INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('717b616f-835c-41d4-bf7d-c13f47f76fe3', '011h', '011h.com', 'https://www.011h.com/', 'https://www.linkedin.com/company/011h/', 'https://app.dealroom.co/companies/011h', 'The new generation building platform with a mission to accelerate the transition to a sustainable building development', 'Barcelona', 'Spain', 2020, 297, 30.263159, 42029983, 4, 20833325, 2025, 'operational', '[{"uuid":"ab402b46-5a85-4152-8bfd-94f58d3b5a55","name":"Lucas Carné Carcas"},{"uuid":"90cb5eae-0878-4b04-b135-85b1a909b9a6","name":"Jose Manuel Villanueva"},{"uuid":"8a7bccfd-da2e-49d7-bc70-4f2b44aa4a4a","name":"Lucas Carne"},{"uuid":"17486200-9fe9-4db8-b034-9845e9b9882a","name":"Josep Barbera"}]', '{}', '2026-11-05T15:54:35.037Z', '011h is a forward-thinking startup focused on revolutionizing the construction industry by making net zero construction—buildings that produce as much energy as they consume—viable, reliable, and scalable. The company primarily serves residential developers and municipal housing authorities in Spain, partnering with notable clients like Aedas Homes, Culmia, and the Barcelona Municipal Institute of Housing (IMHAB).
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('47e36305-25d2-4428-987b-79cc484119c2', '01Health', '01health.ai', 'https://01health.ai', 'https://www.linkedin.com/company/01health/', 'https://app.dealroom.co/companies/01health', 'Platform enabling specialist healthcare through local clinics', 'London', 'United Kingdom', 2022, 55, NULL, 11363632, 1, NULL, NULL, 'operational', '[{"uuid":"2f94f2c2-5372-42e7-884f-96386ddc6b66","name":"Sonia Szamocki"}]', '{}', '2026-11-05T15:54:12.521Z', '01Health is a London healthtech founded by Dr Sonia Szamocki, a former NHS doctor and BCG consultant. It provides an end-to-end platform that enables independent practices, practice groups and dental service organisations to deliver specialist care through local clinics rather than concentrating it in hospitals and major centres. The licensed system bundles clinical oversight, specialist-designed protocols, AI-driven patient acquisition, automated workflows and patient communications; it first powered 01Health''s own brands 32Co (orthodontics) and Aerox Health (dental sleep medicine) and is designed to expand into other specialties. In June 2026 01Health raised a $15 million (€12.9 million) Series A led by Gresham House Ventures, with Balderton Capital, Eka Ventures and Wavemaker360 returning, to commercially launch the standalone platform in the UK and expand in the US. Sources: EU-Startups 10 Jun 2026; 01health.ai.', '["Health Platform","data management","database","software as a service","data security","Medical Data","AI for medical imaging","Venture Capital","recruitment marketing","supply chain management","marketing","SaaS","marketing automation","transportation and fleet management","page builders","Angel","frameworks and libraries","communication and collaboration","development","electronic health records","content management system","risk and compliance","web frameworks","travel and expense management","database management","b2b","Health Diagnostics","email","web servers","software framework","customer service","programming languages","Commission","Breakout stage","audio-video-graphics","web & portal technology","generative ai","programming","cloud infrastructure computing","business intelligence","governance-risk and compliance","e-commerce","javascript libraries","analytics","other audio-video-graphics software","security","Dentistry","operating systems & computing languages","cloud hosting","platform as a service","visualisation software","Health","javascript frameworks","consent management","live chat","applicant tracking systems","healthcare marketing","ui frameworks","accounting and finance","certificates","email marketing","logistics","machine learning","web tools and plugins"]', '["startup","vc_backed","funded"]', 82.72, 1600, 0, 0, 68181791, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:54:12.521Z', 'GBP', '2026-11-05T15:54:12.521Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('63749b2b-0eea-423e-a591-611159b3a19e', '32Co', '32co.com', 'http://32co.com', 'https://www.linkedin.com/company/32co/', 'https://app.dealroom.co/companies/32co', 'Your Guardian Angel for Clear Aligner Orthodontics', 'London', 'United Kingdom', 2021, 42, -34.375, 2272726, 1, NULL, NULL, 'operational', '[{"uuid":"2f94f2c2-5372-42e7-884f-96386ddc6b66","name":"Sonia Szamocki"},{"uuid":"f9c161bf-ec2d-4456-8052-f06a192d3313","name":"Nikhith N"}]', '{}', '2026-11-05T15:54:12.521Z', '32Co is a specialized service provider in the dental industry, focusing on supporting general dentists in delivering high-quality orthodontic treatments. The company operates in the healthcare market, specifically targeting dental professionals who seek to enhance their orthodontic skills and offer clear aligner treatments confidently. By providing direct collaboration with top specialist orthodontists, 32Co ensures that each treatment plan is meticulously crafted and clinically sound. The business model revolves around offering free educational courses tailored to individual needs, with revenue generated from the sale of clear aligners. This approach not only upskills dentists but also guarantees that patients receive the best possible care. The company''s clientele primarily includes general dentists looking to expand their practice capabilities and improve patient outcomes. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('8bf4fc04-9f43-4fc8-8b8c-3daccf05c258', 'ALiCE Biometrics', 'alicebiometrics.com', 'https://www.alicebiometrics.com/', 'https://www.linkedin.com/company/alicebiometrics/', 'https://app.dealroom.co/companies/alice_biometrics', 'Identity Verification | ALiCE Biometrics - Digital Onboarding', 'Vigo', 'Spain', 2019, 19, -17.391304, 1249999, 3, 1908533, 2023, 'operational', '[{"uuid":"7bdea644-ace3-4329-8f30-f6151738f5e9","name":"Daniel Gonzalez-Jimenez"},{"uuid":"5831e432-ea95-47a5-acd4-84f15b7511a7","name":"Esteban Vázquez Fernández"}]', '{}', '2026-11-05T15:55:09.655Z', 'Alice Biometrics is a technology startup that specializes in instant identity verification. The company uses its proprietary Artificial Intelligence (AI) engine to verify the identities of its clients'' customers in less than a second. This process is fully automated and does not require manual reviews. All that is needed for verification is a selfie and an identity document.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2ff45e83-cef4-40da-a14b-8e489f88e23d', 'APlanet', 'aplanet.org', 'https://www.aplanet.org/', 'https://www.linkedin.com/company/aplanetorg/', 'https://app.dealroom.co/companies/aplanet', 'The platform to manage and report your organisation''s ESG, CSR and sustainability', 'Bilbao', 'Spain', 2019, 36, 0, 5566236, 11, 747068, 2023, 'operational', '[{"uuid":"9087221f-4465-4905-80cd-df617c2ff040","name":"Joana Paredes Alves"},{"uuid":"769d07e5-ef2a-4d5b-bfe9-f06696ac3e27","name":"Cyril Pierre"},{"uuid":"2a6ec123-f8fe-42f1-8af9-81f7642691e7","name":"JAVIER LLORDEN"}]', '{}', '2026-11-05T15:55:36.049Z', 'APlanet, legally known as INNOVATIVE CSR TECHNOLOGIES AND CONSULTING, S.L., was founded in Spain in 2019 to address the growing need for efficient sustainability management. The company was established by co-founders Johanna Gallo and Cyril Pierre, who drew upon their collective experiences in both large multinational corporations and various startups. Gallo, an engineer by training, has a background leading projects at major companies like Amazon and launching her own ventures in Spain and India. Pierre''s expertise lies in marketing, having held leadership roles at companies such as Ticketbis, which was acquired by eBay''s StubHub, before co-founding APlanet in 2018. They identified a common challenge across organizations: the cumbersome process of collecting and managing social and environmental data. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('fe067333-f590-46be-b1b1-62db9a93a09d', 'Abiquo', 'abiquo.com', 'http://www.abiquo.com', 'https://www.linkedin.com/company/abiquo/', 'https://app.dealroom.co/companies/abiquo', 'Hybrid cloud management software', 'London', 'United Kingdom', 2006, 11, 0, 22583324, 11, 61237, 2012, 'operational', '[{"uuid":"c4c263e9-d513-4e87-8fb8-3d22a601dcd8","name":"Ramon Sangüesa Solé"},{"uuid":"2117186c-cb52-4d8e-a02b-0aa71444a54f","name":"Xavier Fernandez"}]', '{}', '2026-11-05T15:54:12.521Z', 'Established in 2006, Abiquo provides a hybrid cloud management platform designed to help managed service providers (MSPs) and enterprises streamline and monetize their cloud services. The company was co-founded by Xavier Fernandez and Ian Martin Finlay. Fernandez, who also serves as the company''s CEO, has a background as a project manager and developer for large companies like PepsiCo. Finlay, previously the CIO of an MSP that implemented Abiquo''s platform, invested in the company after recognizing its potential and now leads its focus on delivering client value. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('c3ba6362-137c-4e57-8dee-d0a96751fbfe', 'Accurx', 'accurx.com', 'https://www.accurx.com/', 'https://www.linkedin.com/company/accurx/', 'https://app.dealroom.co/companies/accurx', 'Healthcare communication platform for NHS patients and staff', 'London', 'United Kingdom', 2016, 284, 12.698413, 36621819, 5, 48584831, 2025, 'operational', '[{"uuid":"ca59b394-f72c-4617-acab-ddbcb6536b68","name":"Jacob Haddad"}]', '{}', '2026-11-05T15:54:51.538Z', 'Accurx is a technology startup that operates within the healthcare sector, specifically serving the UK''s National Health Service (NHS). The company has developed a unified communication platform that facilitates efficient interaction among healthcare professionals involved in patient care. This platform addresses the communication challenges posed by outdated systems and isolated communication channels that have traditionally been used in the NHS. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('686b7963-d70e-48b4-9255-663f8b99b2f3', 'Acurable', 'acurable.com', 'http://acurable.com', 'https://www.linkedin.com/company/acurable/', 'https://app.dealroom.co/companies/acurable', 'Wearable acoustic sensors for automated respiratory condition diagnosis', 'London', 'United Kingdom', 2016, 31, -3.125, 12636663, 5, NULL, NULL, 'operational', '[{"uuid":"71c1b303-917f-4eae-b1b6-c3ab2db4b1cb","name":"Stuart Bowyer"},{"uuid":"be63a4d3-479e-4e92-a8d4-6298ba8a0484","name":"Emilio Sanz"},{"uuid":"c0460795-31c6-4f60-9b38-09aca2e6ede4","name":"Anas Imtiaz"},{"uuid":"83b47c43-4c07-41b6-be5c-954dc76afb75","name":"Esther Rodriguez Villegas"},{"uuid":"54ca8e6e-1a4a-41fd-8d99-245e8d876805","name":"Emilio Sanz Pereiras"}]', '{}', '2026-11-05T15:53:55.756Z', 'Acurable is a medical device company with offices in London and Seville that develops wearable sensors for at-home medical diagnosis. The company was founded in 2016 by Professor Esther Rodriguez-Villegas, Emilio Sanz Pereiras, and Dr. Anas Imtiaz, spinning out of Imperial College London. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f3f14ac8-6961-4d9f-aac8-5ccdf695a024', 'Adfin', 'adfin.com', 'https://www.adfin.com', 'https://www.linkedin.com/company/adfin-fs/', 'https://app.dealroom.co/companies/adfin_', 'AI-driven payment solutions offering flexible invoicing, instant settlements, and high conversion rates for high-value transactions', 'London', 'United Kingdom', 2024, 55, 111.53846, 20303027, 3, NULL, NULL, 'operational', '[{"uuid":"171c1874-1f15-4ee4-a600-2cbb4dc27704","name":"Sam Jennings"},{"uuid":"b91e2e8c-ca53-43e0-86b5-fc124635cfef","name":"Andra-Elena Cozma (Gîștescu)"},{"uuid":"e23e2ac5-1125-4faa-afe8-15cd5329d797","name":"Carlos Rey"},{"uuid":"bfba0387-de27-43a1-8a95-dccb3af51609","name":"Tom Pope"},{"uuid":"f79bde9b-30b1-464c-9e5e-5e993a809d75","name":"Ciprian Diaconasu"}]', '{}', '2026-11-05T15:53:18.240Z', 'Adfin is a London fintech founded in 2024 that builds an agentic money-movement platform pairing proprietary payment infrastructure with AI workflows that chase, reconcile and clear invoices for SMEs. Customers include professional services, trades and care firms; the company reports late-payment rates far below the UK SME average. In May 2026 Adfin raised a $18 million / about €15.3 million Series A led by Index Ventures, with Visionaries Club and angels including Stéphane Kurgan and Miro founder Andrey Khusid, bringing total funding to more than $30 million. Sources: The Next Web 12 May 2026; EU-Startups May 2026.', '["database","uk is8 financial services","Venture Capital","web fonts","Core AI","SaaS","javascript graphics","Angel","frameworks and libraries","identity and access management","content management system","Fintech","Payments","Billing","it infrastructure","web frameworks","b2b","Artificial Intelligence","tag management","email","content delivery network","programming languages","Commission","Breakout stage","advertising","miscellaneous","programming","AI Applications","Financial Management Solutions","javascript libraries","intelligence and analytics","advertising networks","analytics","security","web analytics","uk is8 digital and technologies","font scripts","blogs","identity verification","Invoicing","web tools and plugins"]', '["startup","rising_star","vc_backed","funded"]', 92.51, 26000, 1, 1, 81818149, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:53:18.240Z', 'GBP', '2026-11-05T15:53:18.240Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('da26246c-e241-4a0b-9b55-3fbf6cc91bae', 'Adsmurai', 'adsmurai.com', 'http://www.adsmurai.com/', 'https://www.linkedin.com/company/adsmurai/', 'https://app.dealroom.co/companies/adsmurai', 'Technological solutions for ad management on social media', 'Barcelona', 'Spain', 2014, 522, 8.298756, 26724989, 6, 88816631, 2024, 'operational', '[{"uuid":"917536fe-adf0-4d1c-9a02-d0997fc1aad5","name":"Juan Antonio Robles"},{"uuid":"a61d2856-38c5-45fe-a91c-cb297ff21469","name":"Otto Wüst"},{"uuid":"c3e44e23-4c65-4a6b-96e5-25bf02427f12","name":"Marc Elena"}]', '{}', '2026-11-05T15:54:35.037Z', 'Adsmurai provides a comprehensive marketing platform for planning, launching, measuring, and scaling campaigns across all digital channels. The company''s software provides optimized advertising campaign execution on social media, automating and scaling advertising campaigns on all social media platforms.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0bcb8509-8f2a-452d-bbb3-e2160bb38701', 'Adzuna', 'adzuna.co.uk', 'http://www.adzuna.co.uk', 'https://www.linkedin.com/company/adzuna/', 'https://app.dealroom.co/companies/adzuna', 'The UK''s search engine for Jobs', 'London', 'United Kingdom', 2011, 146, -9.876543, 14127272, 8, 21089791, 2025, 'operational', '[{"uuid":"6094ebf3-8001-49f6-8585-0932f6761e6f","name":"Doug Monro"}]', '{}', '2026-11-05T15:53:18.240Z', 'Adzuna is a UK-based job search engine that aims to simplify the job hunting process by aggregating job listings from various sources into one easy-to-navigate platform. The company serves job seekers across various industries and locations within the UK, offering a comprehensive database of job opportunities. Adzuna''s primary clients are individuals looking for employment, ranging from entry-level positions to executive roles.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('15fe3198-701f-4e16-9c70-055dbe28477e', 'Alinia AI', 'alinia.ai', 'https://alinia.ai', 'https://www.linkedin.com/company/alinia-ai/', 'https://app.dealroom.co/companies/alinia_ai', 'Makes it easy for enterprises to control and guide Gen AI applications based on their policies and preferences', 'Barcelona', 'Spain', 2023, 26, 188.88889, 7499997, 2, NULL, NULL, 'operational', '[{"uuid":"45a0904f-7a26-4c72-9c56-2186565422bf","name":"Ariadna (Ari) Font Llitjós, PhD"},{"uuid":"1c23dc89-a9e4-424d-ac15-10e9bace351a","name":"Carlos Muñoz Ferrandis"}]', '{}', '2026-11-05T15:56:04.243Z', 'Alinia.ai specializes in the deployment of Generative AI, specifically Large Language Models (LLMs), into enterprise applications. The company addresses concerns over control and governance, which are critical for reducing reputational risk and ensuring trustworthy adoption. Alinia.ai''s robust alignment platform integrates state-of-the-art evaluation, governance, and optimization techniques to make LLM deployment safer, more effective, and accessible for businesses. The company serves enterprises looking to integrate AI solutions while adhering to ethical, organizational, and legal standards. Operating in the AI and technology market, Alinia.ai''s business model revolves around providing a subscription-based platform that enterprises can use to deploy and manage LLMs. Revenue is generated through subscription fees and possibly additional services related to customization and support. The company''s core values emphasize a growth mindset, diversity of thought, and open communication, aiming to build products that benefit a wide range of users.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('dc21ea81-e14a-4337-978b-b951cf106d4f', 'Amenitiz', 'amenitiz.com', 'https://amenitiz.com', 'https://www.linkedin.com/company/amenitiz/', 'https://app.dealroom.co/companies/amenitiz', 'All-in-one platform for the hospitality industry', 'Barcelona', 'Spain', 2017, 206, -21.969696, 61058309, 5, 12666662, 2024, 'operational', '[{"uuid":"c8944584-89f0-47b1-8fad-2e899c8d4c4f","name":"Emmanuelle Sanchez"},{"uuid":"48353f64-72da-440c-8c3c-9be05c047396","name":"Emmanuelle Guinefolleau"},{"uuid":"d2804443-a8c3-4bf8-9e11-569300ceafd0","name":"Alexandre Guinefolleau"},{"uuid":"1d3f9d14-1e5d-49db-8b08-9a4725ab0801","name":"Frédéric Cadet"},{"uuid":"4315e463-e4c1-4ab5-bb65-41291d246b67","name":"Alexandre Guinefolleau"}]', '{}', '2026-11-05T15:56:04.243Z', 'Amenitiz, a Barcelona-based technology company, provides a centralized operating system for the independent hospitality sector, targeting small to medium-sized hotels, B&Bs, and vacation rentals. Founded in 2017 by Alexandre Guinefolleau (CEO), Emmanuelle Guinefolleau (CRO), and Frédéric Cadet, the company emerged from the founders'' desire to create an all-in-one platform to simplify hotel management. Alexandre Guinefolleau''s background includes studies at the prestigious hotel school in Lausanne, providing foundational industry knowledge, while both he and Frédéric Cadet are graduates of the Le Wagon coding bootcamp, which equipped them with the technical skills to build the platform. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2efedbc2-10c4-4478-8bb6-7333aea6feb3', 'Anaconda BioMed', 'anaconda.bio', 'https://anaconda.bio', 'https://www.linkedin.com/company/anaconda-biomed/', 'https://app.dealroom.co/companies/anaconda_biomed', 'Advanced catheters for safer mechanical thrombectomy in stroke', 'Sant Cugat del Vallès', 'Spain', 2015, 46, 6.976744, 72943797, 7, 57834, 2022, 'operational', '[{"uuid":"b3692755-363e-400e-809f-71ee15ac1650","name":"Dr Inyaki Galve"},{"uuid":"e90cbcda-484d-4f7f-b82e-f7514565804a","name":"Ofir Arad"}]', '{}', '2026-11-05T15:53:12.600Z', 'Anaconda BioMed is a Barcelona medical-device company developing next-generation catheters for mechanical thrombectomy in ischemic stroke. Co-founded by Dr. Marc Ribo and Dr. Ofir Arad, its ANA Funnel Catheter and related ANCD Advanced Thrombectomy System combine covered-funnel and clot-mobilizer approaches intended to improve clot capture while reducing distal emboli and fragmentation versus conventional stentriever and aspiration techniques alone. The company is running the ATHENA pivotal IDE randomized study (about 327 subjects) to support U.S. regulatory progress alongside European commercialization ambitions. In September 2026 Anaconda secured a $56 million (about €49–50 million) equity financing led by Omega Funds, with new capital from FOCO/COFIDES and continued participation from Asabys, Ysios Capital and CDTI, to complete ATHENA, advance the catheter portfolio and pursue global approvals. Sources: GlobeNewswire / BioSpace 23 Sep 2026; Expansión.', '["accelerator","photo galleries","Cardiology and cardiovascular","Venture Capital","web fonts","editors","marketing","marketing automation","page builders","Angel","communication and collaboration","development","content management system","Catheters","software development","DT and LS","web frameworks","EIT Health","Intravenous","b2b","web platform extensions","tag management","email","widgets","web servers","software framework","Horizon Europe","Hard Tech","programming languages","Breakout stage","audio-video-graphics","Manufacturing","website builders","miscellaneous","Spinout","office suites","Hospital","javascript libraries","wordpress plugins","Medical Devices","intelligence and analytics","analytics","stroke","science-based","web analytics","Health","build automation","consent management","stock images providers","Headstart 2018 (EIT Health)","Headstart (EIT Health)","font scripts","blogs","ui frameworks","EIT Ecosystem","Deep Tech","Hardware","email marketing","cookie compliance","web tools and plugins"]', '["startup","spinout","vc_backed","funded"]', 83.03, 560, 1, 1, 244999902, -1114500, 2022, -5193969, 2024, '[{"year":2015,"revenue":null,"ebitda":-65886,"profit":-51244,"rnd":null,"valuation":null,"employees":null},{"year":2016,"revenue":null,"ebitda":-191932,"profit":-147706,"rnd":null,"valuation":null,"employees":null},{"year":2017,"revenue":null,"ebitda":-923786,"profit":-1134943,"rnd":null,"valuation":74999970,"employees":null},{"year":2018,"revenue":25190,"ebitda":-997767,"profit":-1291672,"rnd":null,"valuation":74999970,"employees":null},{"year":2019,"revenue":64127,"ebitda":-1067969,"profit":-1856349,"rnd":null,"valuation":100772687,"employees":null},{"year":2020,"revenue":27525,"ebitda":-830584,"profit":-2491379,"rnd":null,"valuation":100772687,"employees":21},{"year":2021,"revenue":61991,"ebitda":-1112384,"profit":-3095943,"rnd":null,"valuation":100772687,"employees":22},{"year":2022,"revenue":57834,"ebitda":-1114500,"profit":-4377055,"rnd":null,"valuation":100772687,"employees":28},{"year":2023,"revenue":57834,"ebitda":-1114500,"profit":-4904219,"rnd":null,"valuation":100772687,"employees":27},{"year":2024,"revenue":57834,"ebitda":-1114500,"profit":-5193969,"rnd":null,"valuation":100772687,"employees":33},{"year":2025,"revenue":57834,"ebitda":-1114500,"profit":-5193969,"rnd":null,"valuation":83977239,"employees":43},{"year":2026,"revenue":57834,"ebitda":-1114500,"profit":-5193969,"rnd":null,"valuation":244999902,"employees":46}]', '2026-11-05T15:53:12.600Z', 'GBP', '2026-11-05T15:53:12.600Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('8bdaab47-bcc9-4345-941a-f0842f92cf19', 'Ankar Ai', 'ankar.ai', 'https://ankar.ai', 'https://www.linkedin.com/company/ankar-ai/', 'https://app.dealroom.co/companies/ankar_ai', 'Enterprise AI operating system for the patent lifecycle', 'London', 'United Kingdom', 2024, 56, 600, 18151509, 2, NULL, NULL, 'operational', '[{"uuid":"c61c7899-79c1-4f98-a821-578f17fbc813","name":"Tamar Gomez"},{"uuid":"250a01e6-db41-4e15-8a92-f1711cd81f50","name":"Tamar Gomez"},{"uuid":"1c3509b2-acb3-4c23-b4bc-ef906df5ad6d","name":"Wiem Gharbi"}]', '{}', '2026-11-05T15:53:18.240Z', 'Ankar Ai is a European enterprise software company founded by former Palantir engineers Wiem Gharbi and Tamar Gomez that builds an AI operating system for the patent lifecycle used by IP and R&D teams. The platform unifies prior-art and novelty analysis across large patent and scientific corpora, strategic drafting and prosecution support, and a consolidated view of examiner responses, with enterprise security design including early ISO 27001 work and customer-data isolation so outputs stay grounded in verified sources. Customers include Fortune 500 R&D organisations seeking faster, more defensible portfolios. In December 2025 Ankar raised a $20 million Series A led by Atomico, with Index Ventures doubling down and Norrsken VC and Daphni participating, taking total funding to about $24 million to grow engineering, product and go-to-market across Europe and the US. Sources: Tech.eu 17 Dec 2025.', '["data management","database","Venture Capital","recruitment marketing","Core AI","Subscription","SaaS","customer relationship management","human resources","Angel","domain name services","database management","b2b","Artificial Intelligence","tag management","web servers","Intellectual Property","content delivery network","programming languages","Breakout stage","payment processing","Research and Development","AI Applications","business intelligence","javascript libraries","intelligence and analytics","Enterprise Software","analytics","Intellectual Property","Legal","web analytics","uk is8 professional business services","uk is8 digital and technologies","consent management","web design and development services","applicant tracking systems","design","ui frameworks","cookie compliance","Woman Founder"]', '["startup","rising_star","vc_backed","funded"]', 91.73, 13000, 1, 7, 90909055, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:53:18.240Z', 'GBP', '2026-11-05T15:53:18.240Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('215755f5-e753-4dbf-ab62-edaa05f2aceb', 'Anyformat', 'anyformat.ai', 'https://anyformat.ai', 'https://www.linkedin.com/company/anyformat/', 'https://app.dealroom.co/companies/anyformat_ai', 'No-code agentic OCR for unstructured enterprise data', 'Madrid', 'Spain', 2024, 13, NULL, 3183332, 2, NULL, NULL, 'operational', '[{"uuid":"2c666b7b-51c0-4a68-ba67-23e7f478a1fb","name":"Juan Huguet Garcia, PhD."},{"uuid":"25d323ff-785a-4f2c-9c82-535614efa0f5","name":"Diego Perez Sastre"}]', '{}', '2026-11-05T15:53:55.756Z', 'Anyformat is a Madrid-based generative AI company that turns unstructured documents — PDFs, invoices, contracts, audio and similar files — into structured, usable data through a no-code enterprise platform combining computer vision, layout understanding, LLMs and agentic OCR. Founded in 2024 by Juan Huguet (CEO), Diego Pérez (CTO) and Alejandro Fernández (COO), Clarity AI alumni, the product lets non-technical users design classification, parsing and validation workflows with confidence scoring and a focus on European data sovereignty. After a €520,000 pre-seed in October 2024 led by 4Founders Capital and Abac Nest Ventures, Anyformat raised a €3.3 million Seed in late 2025 led by Kibo Ventures, with returning investors, to grow engineering and commercial teams across Europe. Sources: EU-Startups late 2025 / company coverage.', '["accelerator","data security","Venture Capital","SaaS","development","performance","risk and compliance","domain name services","it infrastructure","web frameworks","customer data platforms","b2b","Artificial Intelligence","email","software framework","content delivery network","Commission","web & portal technology","miscellaneous","programming","governance-risk and compliance","e-commerce","javascript libraries","intelligence and analytics","Enterprise Software","real user monitoring","analytics","4YFN 2026","4YFN","security","web analytics","application development & management","javascript frameworks","consent management","Early stage","font scripts","ui frameworks","web tools and plugins"]', '["startup","vc_backed","funded"]', 63, 7500, 0, 0, 16499993, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:53:55.756Z', 'GBP', '2026-11-05T15:53:55.756Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f1ef8051-2438-4921-86d7-45b1ca5918cf', 'ApetEat', 'apeteat.com', 'https://apeteat.com', 'https://www.linkedin.com/company/apeteat/', 'https://app.dealroom.co/companies/apeteat', 'Committed to help all those people who want to take care of themselves on a daily basis', 'Madrid', 'Spain', 2015, 22, 4.7619047, 1366666, 5, 1378532, 2023, 'operational', '[{"uuid":"1c32d793-9a03-4534-b8ec-d40637a6eb6b","name":"David Rebull"},{"uuid":"18f08343-2dd9-463c-8508-ad7d1b98c023","name":"Eduardo Liviano Bernal"}]', '{}', '2026-11-05T15:55:36.049Z', 'ApetEat operates as a digital corporate catering platform, positioning itself as a key partner for companies aiming to enhance employee well-being through nutrition. Founded in 2015 in Madrid, Spain, by Pablo Samaranch Dezcallar, Eduardo Liviano Bernal, and David Samaranch Rebull, the company began operations in September 2016. The founders identified a market opportunity at the intersection of evolving digital consumer habits and a growing consciousness around healthy eating, particularly within the corporate environment where a significant number of weekly meals are consumed. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3776ab93-03cb-407a-b126-885fefa75499', 'Appear Here', 'appearhere.co.uk', 'http://www.appearhere.co.uk', 'https://www.linkedin.com/company/appearhere/', 'https://app.dealroom.co/companies/appear_here', 'List, discover and book short-term retail space around the UK', 'London', 'United Kingdom', 2013, 33, 26.923077, 26818171, 5, 840907, 2022, 'operational', '[{"uuid":"0f12d767-b2b1-47fc-a206-84ed27d95314","name":"Ross Bailey"}]', '{}', '2026-11-05T15:54:12.521Z', 'Appear Here operates as an online marketplace for short-term retail space, often described as the ''Airbnb for retail''. The company was founded in 2012 by Ross Bailey, whose entrepreneurial drive was sparked by observing his parents run their hair salon. The specific idea for the company originated after Bailey launched a pop-up shop called Rock and Rule for the Queen''s Diamond Jubilee. He discovered a significant demand from others who also wanted to rent retail space flexibly, prompting him to use the profits from his pop-up to establish Appear Here.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('9312d39c-5af4-4b94-ba3b-65def9031913', 'Apron', 'getapron.com', 'http://getapron.com', 'https://www.linkedin.com/company/getapron/', 'https://app.dealroom.co/companies/getapron_com', 'Sort, pay and reconcile your invoices in seconds', 'London', 'United Kingdom', 2022, 124, 19.23077, 38257560, 3, 3046130, 2025, 'operational', '[{"uuid":"5c51784b-40b8-41ce-8b1f-6bce4eb097da","name":"Bogdan Uzbekov"}]', '{}', '2026-11-05T15:53:18.240Z', 'Apron is a fintech company that specializes in simplifying invoice management and payment reconciliation for small businesses. Operating primarily in the financial technology sector, Apron serves business owners who need to manage their supplier payments efficiently. The platform allows users to sort, pay, and reconcile invoices in seconds, directly from their bank accounts. By integrating with accounting software like Xero, Apron ensures instant reconciliation, reducing administrative burden and improving cash flow. The business model is based on providing a subscription-based service that offers significant time savings and operational efficiency for its clients. Apron generates revenue through subscription fees and possibly transaction fees, depending on the volume of payments processed. The company aims to transform payments from a barrier to a booster for small businesses, allowing them to focus on growth rather than administrative tasks.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('976ac075-a3b4-486c-a7b9-4bed1ba8330d', 'Aquí tu Reforma', 'aquitureforma.com', 'https://aquitureforma.com', 'https://www.linkedin.com/company/aqui-tu-reforma/', 'https://app.dealroom.co/companies/aqu_tu_reforma', 'Fostering the development and well-being of people and sustainable communities through housing renovation', 'Barcelona', 'Spain', 2018, 210, 9.947644, 7499997, 4, 1946458, 2023, 'operational', '[{"uuid":"431d15ba-729d-467c-8a3f-2d36f7d52f8a","name":"Enric Aparici"},{"uuid":"2b1721e8-3d0d-4253-b83a-62a80fbb4135","name":"Francisco Moran"}]', '{}', '2026-11-05T15:54:35.037Z', 'Aquí tu Reforma is a Spanish company that has developed a franchise model for the home renovation market. The company provides a platform that connects homeowners with a network of franchisees, offering a streamlined and transparent process for residential renovations.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('a0c670e3-900d-4d50-8966-5dbb47c814e0', 'Argent', 'ready.co', 'https://ready.co', NULL, 'https://app.dealroom.co/companies/argent_1', 'Smart wallet for cryptocurrencies and decentralised applications', 'London', 'United Kingdom', 2017, 70, 0, 45604528, 5, 5393937, 2023, 'operational', '[{"uuid":"57412191-62d5-4adb-9511-148e890cbab3","name":"Julien Niset"},{"uuid":"a7259a49-f06d-40e2-a297-a05a81b5bff6","name":"Itamar Lesuisse"},{"uuid":"c0f4419c-bb1c-449c-8fc6-32610db0724b","name":"Gerald Goldstein"}]', '{}', '2026-11-05T15:53:18.240Z', 'Argent.xyz is a digital platform that operates in the cryptocurrency market, providing a user-friendly and secure wallet for buying and trading crypto assets. With over a million users, it is Starknet''s most popular wallet, indicating a strong market presence and wide adoption. The company''s primary clientele includes individuals and businesses interested in dealing with cryptocurrencies, particularly those seeking a seamless and secure trading experience.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('8367e4e0-f88e-4631-b9a2-73f6929659cd', 'Arondite', 'arondite.com', 'https://arondite.com', 'https://www.linkedin.com/company/arondite/', 'https://app.dealroom.co/companies/arondite', 'AI software platform connecting autonomous defense systems', 'London', 'United Kingdom', 2023, 60, 71.42857, 9280299, 2, NULL, NULL, 'operational', '[{"uuid":"78f0ddb6-320e-4645-bc65-1d54a6033e37","name":"Rob Underhill"},{"uuid":"7ce02136-53fc-444e-91df-8ea9e8584fd6","name":"Will Blyth"}]', '{}', '2026-11-05T15:53:18.240Z', 'Arondite is a London-based defense technology company developing an AI software platform, named Cobalt, to integrate and manage autonomous systems from different manufacturers. Founded in 2023 by CEO Will Blyth and CTO Rob Underhill, the company aims to solve the challenge of fragmented, non-communicating defense hardware by providing a unified software layer. This "connective tissue" approach allows human operators to control multiple disparate systems—such as drones, robots, and sensors—through a single interface, enhancing operational control, safety, and human-machine teaming. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('14ce2bf7-14fe-4cd5-8277-b7da97b86644', 'Arthos | Mozart AI', 'getmozart.ai', 'https://getmozart.ai/', 'https://www.linkedin.com/company/mozart-ai-music/', 'https://app.dealroom.co/companies/arthos_mozart_ai', 'Developer of Mozart AI, an AI-powered digital audio workstation for music production', 'London', 'United Kingdom', 2025, 10, NULL, 5098483, 2, NULL, NULL, 'operational', '[{"uuid":"ea117ec3-b231-4ff1-a11d-318af8635659","name":"Immanuel Rajadurai"},{"uuid":"c3663a91-310b-4e16-917b-f75ac8be312e","name":"Sundar Arvind"},{"uuid":"24fbde21-4075-447c-83c3-b1691bd9e86d","name":"Arjun S Khanna"},{"uuid":"c32a60fc-6b47-4b69-9da7-a9ee04551a22","name":"Pascual Merita"}]', '{}', '2026-11-05T15:54:12.521Z', 'London-based Mozart AI, founded in 2025, is a music technology startup that has developed an AI-powered Digital Audio Workstation (DAW). The company aims to assist music artists, producers, and engineers by acting as an "AI Co-Producer," handling technical production tasks while leaving creative control with the artist. The platform uses natural language processing, allowing users to give text or voice commands to generate musical elements like chord patterns, melodies, and drum beats, or to perform technical actions like equalization.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('129df739-69d5-4c6a-bc7a-a2ed50eabe15', 'Artificial Labs', 'artificial.io', 'http://artificial.io', 'https://www.linkedin.com/company/artificiallabs/', 'https://app.dealroom.co/companies/artificial_labs', 'Building the next generation of insurance technology to empower commercial insurers to write better risks, faster', 'London', 'United Kingdom', 2013, 136, 76.623375, 57088842, 8, 2550000, 2024, 'operational', '[{"uuid":"1dd5dcf2-9e8d-4e5a-9fdb-b0f511c9f927","name":"David King"},{"uuid":"b0e2cfb2-8b85-4939-a907-cae0a7964867","name":"David King"},{"uuid":"a0f93c8d-8dfa-4083-83c7-68eb7b1ee893","name":"Johnny Bridges"},{"uuid":"63df820e-ec0c-4bff-82ac-3f78233d1989","name":"Jorge Berebichez"}]', '{}', '2026-11-05T15:55:09.655Z', 'Artificial.io is a leading insurtech company that leverages advanced cloud-based tools and machine learning techniques to enhance the efficiency and profitability of commercial insurers and brokers. The company operates in the commercial insurance market, providing solutions that automate manual tasks, improve risk assessment, and facilitate faster and more efficient placement of commercial and specialty risks. Artificial.io''s core products include a powerful Contract Builder and an Underwriting Platform, which streamline data entry and ensure compliance with digital contracts. The business model revolves around partnering with global insurers and brokers, offering them cutting-edge technology to gain more control over their data and improve performance. Revenue is generated through subscription fees and service charges for the use of their platforms. The company serves a diverse range of clients within the insurance industry, including large insurance firms and specialized brokers. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('bb5131f5-76a1-4ede-9343-df7bcdaf8a8f', 'Asistensi', 'asistensi.com', 'http://asistensi.com', 'https://www.linkedin.com/company/asistensi/', 'https://app.dealroom.co/companies/asistensi', 'Offers an insurance for medical emergencies', 'Madrid', 'Spain', 2019, 94, -4.0816326, 9670451, 3, NULL, NULL, 'operational', '[{"uuid":"5de56e44-4595-4dff-9652-8678327c32e8","name":"Bjorn Pardo"}]', '{}', '2026-11-05T15:55:09.655Z', 'Asistensi is an insurtech company with a specific focus on serving migrants who wish to provide healthcare for their families back home. The company was founded in Madrid, Spain, in November 2019 by Dr. Andrés Simón González-Silén, Dr. Luis Velásquez, and Armando Baquero. The foundation of Asistensi stems from the founders'' prior experience; in 2004, González-Silén and Velásquez established Venemergencia, a pioneer in at-home and digital healthcare in Latin America. This venture provided them with deep insights into the healthcare and insurance sectors. The idea crystallized as they observed the growing migration crisis, particularly from Venezuela, and recognized the need for a solution to support migrants. The two doctors partnered with Baquero, who brought extensive experience from the banking and insurance industries, to create Asistensi.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3ede9d8a-fd47-467c-984a-502ca947e4ea', 'Attio', 'attio.com', 'http://attio.com', 'https://www.linkedin.com/company/attio/', 'https://app.dealroom.co/companies/attio', 'AI-native customer relationship management platform for GTM teams', 'London', 'United Kingdom', 2017, 206, 48.20144, 106338594, 7, 2651514, 2023, 'operational', '[{"uuid":"dbad4f9e-91d6-44ee-8fe4-ef327d328c68","name":"Nicolas Sharp"},{"uuid":"90aa5671-ef83-4683-8268-b953f513d849","name":"Alexander Christie"}]', '{}', '2026-11-05T15:54:12.521Z', 'Attio is a London-based technology company that has developed a customizable and AI-native Customer Relationship Management (CRM) platform. Founded in 2017 by CEO Nicolas Sharp and CTO Alexander Christie, the company aims to provide a flexible, data-driven alternative to traditional CRM systems. The founders'' initial motivation stemmed from personal frustrations with existing CRMs, which they found to be clunky and rigid. Sharp, with a background in business development at a venture capital firm, and Christie, with his technical expertise, first created a verticalized CRM for VCs called Fundstack. Realizing the market was limited, they pivoted to building a more comprehensive, horizontal CRM from the ground up, launching publicly as Attio in 2022 after a three-year development period. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('07046de0-b9d2-4065-a90b-0d2b3a07eced', 'Autentic AI', 'autentic.ai', 'http://autentic.ai', 'https://www.linkedin.com/company/autentic-ai/', 'https://app.dealroom.co/companies/autentic_ai', 'AI-powered market research and consumer insights platform.', 'Barcelona', 'Spain', 2025, 15, NULL, 1249999, 1, NULL, NULL, 'operational', '[{"uuid":"e64cb935-7153-4a5b-918c-8fe9afcec7ee","name":"Aniol Carreras"},{"uuid":"cba5eb98-ad23-45e1-a96f-5f01d7a6aaf9","name":"Alejandro Gorina Minguell"},{"uuid":"57015b44-3c1c-4b98-8f98-cb14027cffe8","name":"Dani Diestre Tomas"},{"uuid":"ca53380f-3875-47b5-aa76-873401c82f7c","name":"Jacob Bamio Cordero"}]', '{}', '2026-11-05T15:55:36.049Z', 'Autentic AI operates an artificial intelligence-powered platform for market and consumer research. The company''s main offering is designed to accelerate the process of gathering consumer insights and conducting expert interviews, reducing research timelines from weeks to a matter of hours. Autentic AI was co-founded by Daniel Diestre. The platform utilizes conversational AI agents for several key functions. These agents are responsible for recruiting and screening study participants, ranging from general consumers to specialized industry experts. They conduct interviews through voice and video, which are designed to be adaptive, asking follow-up questions to probe for deeper insights. Following the interviews, the platform automates the analysis process, which includes transcription, thematic analysis, emotion detection, and the extraction of key quotes and insights. This allows client teams to focus on decision-making rather than data processing. Autentic AI serves two primary client segments: consumer insights teams and consultants/investors. For consumer brands, use cases include concept testing, brand perception tracking, pricing analysis, and understanding customer churn. For consulting and investment firms, the platform is used for pre-deal due diligence, go-to-market strategy validation, and competitive intelligence. The business model appears to be a platform-as-a-service, offering a scalable alternative to traditional, project-based research agencies and focus groups. The company emphasizes its enterprise-grade security and GDPR compliance. Keywords: AI market research, consumer insights, expert interviews, conversational AI, automated research, qualitative data analysis, brand perception, concept testing, pricing strategy, voice of customer, competitive intelligence, due diligence, AI recruitment, video interviews, insight synthesis, Daniel Diestre, market intelligence platform', '["Venture Capital","MLops","SaaS","page builders","frameworks and libraries","AI Data Preparation and Generation","web frameworks","b2b","genAI Applications","Artificial Intelligence","email","web servers","software framework","out of stealth","programming languages","programming","javascript libraries","Enterprise Software","operating systems & computing languages","Marketing","javascript frameworks","Early stage","ui frameworks"]', '["startup","vc_backed","funded"]', 42.29, 2700, 0, 0, 7499997, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:55:36.049Z', 'GBP', '2026-11-05T15:55:36.049Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0dca2248-149e-40a0-a04b-0af8e097d3d5', 'Axitech', 'axitech.co', 'http://axitech.co', 'https://www.linkedin.com/company/axitech/', 'https://app.dealroom.co/companies/axitech', 'Intelligent collision and claims management in the connected vehicle ecosystem, driven by the needs of the customer', 'Leeds', 'United Kingdom', 2015, 20, 17.647058, 3840908, 1, 1136363, 2022, 'operational', '[{"uuid":"8eea76f0-8212-4f3a-bc11-7c27a2431977","name":"Matthew Hodges"}]', '{}', '2026-11-05T15:54:12.521Z', 'Axitech Group Limited, operating as Axitech, is a UK-based technology firm established in 2004 by founder Matt Hodges. The company''s genesis stems from its predecessor, InterResolve, which was founded upon recognizing significant inefficiencies in how collision management and insurance claims were traditionally handled. Axitech''s mission is to modernize this space by orchestrating solutions for companies within the connected vehicle ecosystem, including automotive original equipment manufacturers (OEMs), connected car software providers, and insurance carriers. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0d9bbed6-477e-4a5f-8412-3ff934a83400', 'BASE4 Biosciences', 'base4bio.com', 'https://base4bio.com/', 'https://www.linkedin.com/company/base4-biosciences/', 'https://app.dealroom.co/companies/base4_biosciences', 'AI-driven transcriptomic analysis for preventive medicine.', 'Barcelona', 'Spain', 2025, 12, NULL, 757575, 2, NULL, NULL, 'operational', '[{"uuid":"4cc06472-4c5c-4cf8-9ef4-34eb61c9f0b5","name":"Angel Martinez-Perez"},{"uuid":"57dc2fca-ffb8-4f62-afb4-0de1bd376521","name":"Jose Soria"},{"uuid":"0f98e19c-3faa-4384-9956-f332518b2877","name":"Pol Cervera"}]', '{}', '2026-11-05T15:56:04.243Z', 'BASE4 Biosciences is a precision health company operating between Barcelona and Riyadh, developing a platform for preventive medicine. A spin-out from the Sant Pau Research Institute in Barcelona, the company was co-founded by CEO Pol Cervera and CSO Dr. José Manuel Soria, a molecular biologist. The firm''s focus on women''s health was influenced by the passing of a friend of the founders from a late-diagnosed cancer, highlighting the need for better biological insights based on female-specific data. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('540fc1ab-eb91-4504-b180-c6d274caa150', 'BCOME', 'bcome.biz', 'https://bcome.biz', 'https://www.linkedin.com/company/bcome-impact/', 'https://app.dealroom.co/companies/bcome', 'BCome is the platform for the management of sustainability in the textile and apparel industry', 'Barcelona', 'Spain', 2019, 23, 9.523809, 291667, 2, 174871, 2023, 'operational', '[{"uuid":"64902f8b-66ae-4920-b74c-cd4a2e168fd0","name":"Alba García Betorz"},{"uuid":"697921c3-b6fa-4ad4-ad28-21f50001e094","name":"Anna Cañadell"}]', '{}', '2026-11-05T15:56:04.243Z', 'Bcome.biz is a startup that provides a sustainability platform for fashion businesses. It operates in the sustainability and fashion industry, serving clients who are looking to make their supply chains more responsible and compliant with sustainability regulations. The company''s business model revolves around providing tools and services that help businesses measure and improve their environmental, social, and economic impact.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('af949460-dac4-43f4-9744-bb2cc82addc9', 'BEONPRICE', 'beonx.com', 'https://beonx.com/es/', 'https://www.linkedin.com/company/beonprice/', 'https://app.dealroom.co/companies/beonprice', 'Revenue Managements Solutions', 'Villamayor', 'Spain', 2012, 66, -4.347826, 4916665, 5, 2598472, 2024, 'operational', '[{"uuid":"0cd15cff-feef-4da7-be6e-0c7ec73d8755","name":"Emilio Galán"},{"uuid":"84321821-e91e-4807-8682-588020380224","name":"Rubén Sánchez Martín"}]', '{}', '2026-11-05T15:56:04.243Z', 'BEONPRICE, now operating as Beonx, presents a compelling case in the hospitality technology sector. Founded in 2012 by Rubén Sánchez and Emilio Galán, the company has established itself as a significant player in revenue management systems (RMS). The genesis of the company is rooted in the founders'' combined expertise. Rubén Sánchez brought his experience in hotel management, while Emilio Galán contributed his background in technology and software development. This fusion of hospitality insight and technological acumen has been a core driver of the company''s trajectory.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f23eadd3-a684-4746-a2fd-6cca93446c62', 'BERG Cloud', 'berglondon.com', 'http://berglondon.com/', 'https://www.linkedin.com/company/berg/', 'https://app.dealroom.co/companies/berg_cloud', 'Cloud services platform for connected hardware innovators', 'London', 'United Kingdom', 2005, 46, -2.1276596, 984848, 1, 3636362, 2023, 'operational', NULL, '{}', '2026-11-05T15:53:18.240Z', 'BERG Cloud was a London-based design consultancy and product innovation company that operated from 2005 to 2014. The firm was founded by Matt Webb, Matt Jones, and Jack Schulze. Initially, BERG operated as a design and innovation consultancy, working with major clients like Google, Intel, the BBC, and Dentsu on technology strategy and special projects. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('6e1544e4-906b-4159-b947-32bc4b7040bb', 'BEWE.io', 'bewe.ai', 'https://bewe.ai', 'https://www.linkedin.com/company/miora-io/', 'https://app.dealroom.co/companies/bewe_io', 'AI-powered management software for beauty and wellness businesses', 'Barcelona', 'Spain', 2015, 80, 0, 6363634, 4, 1356780, 2023, 'operational', '[{"uuid":"3e585e36-21ad-49c8-b883-b42e205b3309","name":"Diego Ballesteros"}]', '{}', '2026-11-05T15:54:35.037Z', 'BEWE.io, legally BEWE DIGITAL SOLUTIONS S.L., is a cloud-based ERP and business management software provider for the beauty, wellness, and fitness industries. Founded in 2015 by Diego Ballesteros, Jorge Villabona, and Adriana Avella, the Madrid-based company aims to digitize and professionalize small to medium-sized businesses. Ballesteros, a serial entrepreneur with several startups and exits, serves as the CEO and considers BEWE.io the most ambitious project of his career. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('a6a0c51a-a18d-485b-bb51-7abd58fa6b92', 'Barkibu', 'barkibu.com', 'http://www.barkibu.com', 'https://www.linkedin.com/company/barkibu/', 'https://app.dealroom.co/companies/barkibu', 'Barkibu is creating a new AI-powered healthcare for pets', 'Gondomar', 'Spain', 2013, 81, 6.5789475, 9530299, 8, 1612999, 2023, 'operational', '[{"uuid":"0e58763d-681a-42f0-82f5-10cc22817ac7","name":"Patricia Seoane"},{"uuid":"ea06927e-42c2-4e5b-a175-1148a0a66b8f","name":"Maria Alvarez"},{"uuid":"4110df10-b510-48cb-a4e0-093fba2bd2f3","name":"Enrique Torres Redondo"},{"uuid":"1bd09fee-c576-4c4d-bd7e-320deb285f01","name":"Pablo Pazos Rey"}]', '{}', '2026-11-05T15:55:09.655Z', 'Barkibu is a Spanish insurtech company operating in the pet health sector, providing digital insurance and telehealth services for pet owners. Founded in 2013 by Pablo Pazos, Quique Torres, and Patricia Seoane, the company has transitioned from a veterinary marketplace to a comprehensive pet healthcare provider. Initially, Barkibu connected pet owners with veterinarians for online consultations, operating on a subscription model for both parties. Recognizing the limitations for scalability, the business pivoted to focus on pet insurance and AI-driven telehealth solutions.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('679a9b57-e060-4fb3-8924-9bdcfcec6115', 'Bdeo', 'bdeo.io', 'https://bdeo.io/', 'https://www.linkedin.com/company/bdeo/', 'https://app.dealroom.co/companies/bdeo', 'A visual intelligence solution designed to change the way customers connect with insurance companies', 'Arganda del Rey', 'Spain', 2017, 71, 20.338984, 11249995, 6, 2645585, 2023, 'operational', '[{"uuid":"97b2b6e1-8f8b-4838-94c8-6ccc39aa85ad","name":"Ruth Puente"},{"uuid":"53d23ed0-1a62-4a0f-8374-b3557929ee56","name":"Manuel Moreno"}]', '{}', '2026-11-05T15:56:04.243Z', 'Bdeo is a technology company specializing in visual intelligence solutions for the insurance industry. The company leverages advanced artificial intelligence to streamline the claims appraisal process, making it more efficient and cost-effective. Bdeo''s core product is a video calling technology that allows for the remote collection of documentary evidence, which is then processed autonomously by their powerful visual intelligence engine. This technology helps prevent fraud, reduce costs, and improve the overall quality of service. Bdeo primarily serves insurance companies, providing them with tools to enhance productivity, security, and communication. The company operates in the insurtech market, focusing on innovations that transform traditional insurance processes. Bdeo''s business model revolves around offering software-as-a-service (SaaS) solutions, generating revenue through subscription fees from its clients. The company''s technology significantly reduces the time and cost associated with claims management, thereby increasing profitability for its clients.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4443c850-1b21-4237-81bf-900dcc12647b', 'Beamery', 'beamery.com', 'http://www.beamery.com/', 'https://www.linkedin.com/company/beamery/', 'https://app.dealroom.co/companies/beamery', 'Talent Lifecycle Management platform empowers companies to understand the skills and capabilities they have', 'London', 'United Kingdom', 2012, 186, -21.84874, 168969629, 5, 34893004, 2025, 'operational', '[{"uuid":"daabd5a1-efa1-45db-840e-ce2a17f2f7c2","name":"Sultan Saidov"},{"uuid":"977d16c0-e02a-42cd-ad03-2d8c43fa52e3","name":"Abakar Saidov"},{"uuid":"c46f9398-b0b8-486c-850d-b8bcf440d9de","name":"Michael Paterson"}]', '{}', '2026-11-05T15:53:18.240Z', 'Beamery is a talent lifecycle management platform that helps businesses optimize their workforce by understanding their current skills and future needs. It operates in the human resources technology market, serving a wide range of clients, including some of the world''s largest organizations. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('92bfea9f-ad88-4f8d-b5b9-7e610da4d25e', 'Beauty Pie', 'beautypie.com', 'http://beautypie.com', 'https://www.linkedin.com/company/beauty-pie-ltd/', 'https://app.dealroom.co/companies/beauty_pie', 'Beauty Pie mission is to bring our members the world''s best beauty products at totally transparent factory cost prices', 'London', 'United Kingdom', 2016, 668, -0.8902077, 152636315, 3, 72711025, 2025, 'operational', '[{"uuid":"14131211-2a30-4f8c-a2b6-2683c398ecfc","name":"Marcia Kilgore"}]', '{}', '2026-11-05T15:53:18.240Z', 'Beauty Pie operates as a direct-to-consumer buyers'' club for luxury beauty products. The company''s business model is centered around a membership system, where customers pay a recurring fee to gain access to a wide range of skincare, makeup, and other beauty items at ''factory cost'' prices.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('115ee5c3-6c4c-4a9f-be5e-5ec1def96ebd', 'Behavox', 'behavox.com', 'http://behavox.com', 'https://www.linkedin.com/company/behavox/', 'https://app.dealroom.co/companies/behavox', 'Uses AI and analytics software to detect potential wrongdoing among its customers'' employees', 'London', 'United Kingdom', 2014, 202, -15.12605, 268863529, 7, 33378775, 2025, 'operational', '[{"uuid":"32e50115-a85f-4989-b31e-f22c16eb23cb","name":"Erkin Adylov"},{"uuid":"596d72ce-e9cc-4442-b4ef-582e8f192046","name":"Slav Slavinski"},{"uuid":"367ff298-9984-4a5b-aa86-a0f07f875d80","name":"Roman Zelov"},{"uuid":"1c2b6de4-ec14-42b1-a5b7-fb0cb6726d38","name":"Kiryl Trembovolski"},{"uuid":"00faed5b-1c2d-4d97-90c2-7dea3a16c3c0","name":"Alex Glasman"}]', '{}', '2026-11-05T15:53:18.240Z', 'Behavox operates in the enterprise risk management and compliance market, providing AI-powered solutions to help businesses manage compliance and conduct risks. The company serves large enterprise clients, offering a suite of SaaS-based products that leverage artificial intelligence to analyze data and communications for potential compliance issues. Behavox collaborates with Amazon Web Services (AWS) to ensure its solutions are fast, secure, and scalable, making them accessible globally. The business model is subscription-based, where clients pay for access to the platform and its various features. Revenue is generated through these subscriptions, as well as through additional services such as implementation and support. Behavox''s core product, Behavox Quantum, is a holistic security solution that goes beyond regulatory checkboxes, providing comprehensive compliance, conduct, and archiving solutions. The company has a strong track record of successfully implementing large, complex projects for global clients, ensuring high performance and security while reducing total cost of ownership.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('07d946d4-63d1-43bb-94e6-0a83d2f30045', 'Ben', 'thanksben.com', 'http://www.thanksben.com', 'https://www.linkedin.com/company/thanksben/', 'https://app.dealroom.co/companies/thanks_ben', 'The all-in-one platform for any company to personalize benefits and rewards by marrying a modern software (SaaS) platform with per-employee Mastercards and financial infrastructure', 'London', 'United Kingdom', 2019, 433, 11.025641, 35583319, 3, 2651514, 2022, 'operational', '[{"uuid":"4be4a420-1c15-4558-b4c5-e4cea2bb7be2","name":"David Duckworth"},{"uuid":"88d3b9e4-e13d-4ae5-8d42-2ff7fbde619d","name":"Sebastian Fallert"}]', '{}', '2026-11-05T15:54:51.538Z', 'Ben is a forward-thinking startup revolutionizing the employee benefits landscape. The company offers a comprehensive platform designed to simplify and enhance the management of employee benefits for businesses of all sizes. Ben primarily serves HR departments, benefits providers, and employees, providing them with a seamless and flexible solution to manage and access a wide range of benefits.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f9927ec2-90cd-4d2d-8939-d969236d4d72', 'Beryl', 'beryl.cc', 'http://www.beryl.cc', 'https://www.linkedin.com/company/berylbikes/', 'https://app.dealroom.co/companies/blaze', 'Beryl is the UK''s leading micromobility company and seeks to remove the barriers that exist to cycling in cities', 'London', 'United Kingdom', 2011, 82, -11.827957, 13378789, 7, 12301835, 2025, 'operational', '[{"uuid":"3b4778b7-3d34-4b0f-ba5b-f3f7a8e68068","name":"Emily Brooke MBE"},{"uuid":"d87ccfe2-daba-43c8-a5de-cbc6eee1bdbf","name":"Emily Serov MBE (née Brooke)"},{"uuid":"ef65ab89-1053-4310-862e-de9ff0649b2b","name":"Emily Brooke Mbe"},{"uuid":"a2da41d7-8e01-46f5-8de2-08b878a5474c","name":"Philip Ellis"}]', '{}', '2026-11-05T15:53:18.240Z', 'Beryl is a UK-based company that operates shared, sustainable transport schemes in partnership with local authorities and communities. The company provides a range of micro-mobility options, including bicycles, e-bikes, e-scooters, and cargo bikes, which are available for hire through a user-friendly mobile app.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('614cc21e-567c-4ac8-8a5c-b6b87f33e584', 'Besana', 'besana.energy', 'https://besana.energy', 'https://www.linkedin.com/company/besana-energy/', 'https://app.dealroom.co/companies/besana', 'Provides solar, energy-efficiency and electrification services for residential communities in Spain', 'Madrid', 'Spain', 2022, 23, -84.353745, 14166661, 3, 2444104, 2023, 'operational', '[{"uuid":"aae34652-9841-40c0-82ed-97f8b3a3141e","name":"Manel Pujol Olivares"},{"uuid":"23113c18-3000-4286-8c48-dd3bcb396ff8","name":"Iván Cabezuela"}]', '{}', '2026-11-05T15:54:35.037Z', 'Besana is a Madrid-based clean energy company providing energy services to residential communities and property managers in Spain. It helps homeowners associations reduce their energy costs through electricity bill optimisation, collective self-consumption solar projects, heat pump and insulation upgrades, and EV charging infrastructure. Besana manages the full process, from technical design through installation, financing and ongoing management, so communities can access renewable energy without a large upfront investment. Founded in 2022, the company originally operated under the name Samara before rebranding to Besana. Keywords: solar energy, energy efficiency, heat pumps, EV charging, residential communities, Spain, clean energy.', '["sales","Venture Capital","recruitment marketing","Climate Action (#13)","Solar Energy","marketing","marketing automation","customer relationship management","Angel","identity and access management","Urban Tech","Selling own inventory","Affordable And Clean Energy (#7)","marketing analytics","marketing performance measurement","Residential Solar","Energy","Hard Tech","Sustainable Cities And Communities (#11)","programming languages","Breakout stage","advertising","Clean Energy","security","Sustainable Development Goals","Green Buildings","Climate Tech","Renewable Energy","b2c","Marketplace & ecommerce","applicant tracking systems","affiliate advertising networks","Hardware","identity verification"]', '["startup","vc_backed","funded"]', 60.13, 1900, 0, 0, 37499985, NULL, NULL, -2662622, 2023, '[{"year":2022,"revenue":299571,"ebitda":null,"profit":-509548,"rnd":null,"valuation":22499991,"employees":26},{"year":2023,"revenue":2444104,"ebitda":null,"profit":-2662622,"rnd":null,"valuation":22499991,"employees":136},{"year":2024,"revenue":2444104,"ebitda":null,"profit":-2662622,"rnd":null,"valuation":37499985,"employees":198},{"year":2025,"revenue":2444104,"ebitda":null,"profit":-2662622,"rnd":null,"valuation":37499985,"employees":147},{"year":2026,"revenue":2444104,"ebitda":null,"profit":-2662622,"rnd":null,"valuation":37499985,"employees":23}]', '2026-11-05T15:54:35.037Z', 'GBP', '2026-11-05T15:54:35.037Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3b1e5c16-8886-4446-b142-213ea759599a', 'Better Society Capital', 'bettersocietycapital.com', 'https://bettersocietycapital.com', 'https://www.linkedin.com/company/big-society-capital/', 'https://app.dealroom.co/investors/better_society_capital', 'We improve the lives of people in the UK through investment with a sustainable return', 'London', 'United Kingdom', 2012, 119, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '2026-11-05T15:55:56.052Z', 'Big Society Capital improves the lives of people in the UK by connecting social investment to charities and social enterprises.   We know that investment can help charities and social enterprises achieve more. We believe the greatest chance to improve lives comes when investors and enterprises are both motivated by social mission.   We engage with investors, fund managers, charities and social enterprises to make it easier to use social investment. With our co-investors, we have made over £1bn of new capital available to organisations with a social mission, through investments into fund managers and social banks. We have a special focus on: providing homes for people in need; supporting communities to improve lives; and early action to prevent problems.', '["other","marketing","marketing automation","javascript graphics","content management system","other advertising software","online video platforms","web frameworks","tag management","email","widgets","web servers","programming languages","audio-video-graphics","advertising","javascript libraries","intelligence and analytics","video players","analytics","web analytics","font scripts","social networks","B Corp","charting","email marketing","web tools and plugins"]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:55:56.052Z', 'GBP', '2026-11-05T15:55:56.052Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('eb2fab92-040b-4625-867a-17252c4c4b87', 'Biorce', 'biorce.com', 'https://biorce.com', 'https://www.linkedin.com/company/biorce/', 'https://app.dealroom.co/companies/biorce', 'AI clinical-trial design and operations platform for life-science teams', 'Barcelona', 'Spain', 2024, 209, 1061.1111, 46477254, 3, NULL, NULL, 'operational', '[{"uuid":"9ec835b5-b225-4aa6-8b38-e17890c7d413","name":"Diogo Pisoeiro"},{"uuid":"fb08bdee-db20-49a4-935c-90db5e04ac1b","name":"Diogo Pisoeiro"},{"uuid":"cf85fa83-adf9-45e2-bf40-6bcbe3696ef9","name":"Pedro Coelho"}]', '{}', '2026-11-05T15:53:04.860Z', 'Biorce is a Barcelona HealthTech company founded in 2024 that builds Aika, an AI platform for pharmaceutical companies, biotechs and CROs to design and operate clinical trials. Trained on a proprietary foundation of roughly one million trials, Aika supports protocol development, site selection and feasibility analysis while documenting recommendations for regulatory review and keeping experts in the loop; the company says it can reduce preparation timelines and protocol amendments across therapeutic areas including oncology, neurology and rare diseases. In February 2026 Biorce closed a €43.8 million ($52 million) Series A with DST Global Partners, Norrsken VC, YZR Capital, Mustard Seed Maze and angels, bringing total funding to more than €50.6 million ($60 million). Capital supports US expansion, hiring and new contract, budget and planning modules. Source: EU-Startups 2 Feb 2026.', '["Health Platform","accelerator","data management","Techbio","data security","sales","Biotechnology","Venture Capital","ad exchanges","Core AI","Subscription","SaaS","sales enablement","marketing automation","Angel","frameworks and libraries","development","deployment","testing and qa","system analytics & monitoring","risk and compliance","domain name services","software development","DT and LS","AI Agents","it infrastructure","data warehousing","b2b","Artificial Intelligence","corporate performance management","advanced analytics and data science","web servers","Tech for Biotech and Pharma","software framework","content delivery network","programming languages","Breakout stage","audio-video-graphics","advertising","infrastructure as a service","slush24","Pharmaceutical","web and application servers","miscellaneous","Techbio Drug Discovery","AI Applications","business intelligence","dev tools","javascript libraries","intelligence and analytics","analytics","devops","sales performance management","4YFN 2026","4YFN","issue trackers","science-based","data integration","Clinical Trials","platform as a service","visualisation software","Health","application development & management","insurance software","web design and development services","lead generation","design","healthcare marketing","health platform","big data processing","Drug Development","ui frameworks","certificates","Deep Tech","continuous integration","configuration management","machine learning","Digital Pharma"]', '["startup","rising_star","vc_backed","funded"]', 94.87, 8100, 1, 59, 236363542, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:53:04.860Z', 'GBP', '2026-11-05T15:53:04.860Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('c7077c9f-8fff-49a1-a58e-8d75c3475c9d', 'Biow', 'biow.es', 'http://biow.es', 'https://www.linkedin.com/company/biow/', 'https://app.dealroom.co/companies/biow_1', 'Developing and manufacturing products with a direct effect on exposure and a broad spectrum adjuvant mechanism on cellular function to create regenerative environments', 'Gijón/Xixón', 'Spain', 2015, 103, 7.2916665, 4166665, 1, 1348051, 2023, 'operational', '[{"uuid":"bb9ff259-d084-473c-8df2-ad35744d40e1","name":"Alejandro Loredo"}]', '{}', '2026-11-05T15:55:09.655Z', 'Headquartered in Madrid, Spain, Biow is a biotechnology company established in 2012 that operates within the wellness and electronics sectors. The firm is dedicated to developing and manufacturing cellular regeneration systems aimed at improving health by mitigating oxidative stress. The business model is centered on the direct sale of its patented devices to consumers for both residential and office use. With an estimated annual revenue of $16.1 million, the company generates income through the sale of its core products and maintenance packs. Biow has successfully raised $5.48 million in venture capital funding, with Mundi Ventures being a notable investor. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4a7c3863-9f4a-4966-b5fd-f808895e5108', 'Birdie', 'birdie.care', 'http://www.birdie.care/', 'https://www.linkedin.com/company/birdiecare/', 'https://app.dealroom.co/companies/birdie', 'Empowering care providers with digital products, IoT and machine learning to help deliver better, preventative care for our elders to live healthier and happier at home', 'London', 'United Kingdom', 2017, 154, -8.333333, 41628771, 5, 10500000, 2024, 'operational', '[{"uuid":"01e61396-e5f9-4cfa-88eb-5b384a0761a6","name":"Max Parmentier"},{"uuid":"def1dc40-8193-400b-8816-6964a11522b5","name":"Gwen Le Calvez"},{"uuid":"a82acfdf-c905-4021-9148-e390d97f8d96","name":"Abeed Mohamed"},{"uuid":"e329f47c-a2d8-4309-b770-e3d7cbff6cde","name":"Rajiv Tanna"},{"uuid":"28e5eab5-bafd-49ed-93c1-8e1e1988fb3d","name":"Max Parmentier"}]', '{}', '2026-11-05T15:53:18.240Z', 'Birdie is a comprehensive homecare software platform designed to enhance the quality of care for older generations, enabling them to live healthier and happier lives at home. The company serves homecare agencies by providing a suite of digital tools that streamline care management processes. These tools include electronic Medication Administration Records (eMAR), digital assessments, task and medication schedules, and industry-leading reporting and analytics. Birdie also offers custom-built rostering and finance tools to simplify billing and payroll, reducing administrative burdens for care agencies. The platform''s mobile app ensures care staff have access to the latest care information, even offline, and allows real-time updates to be shared with clients'' loved ones. Birdie''s business model is subscription-based, generating revenue through software licensing fees paid by homecare agencies. The company operates in the homecare market, targeting agencies that aim to deliver high-quality, personalized care efficiently. By leveraging innovative technology, Birdie aims to reinvent the care industry and bring next-generation solutions to the forefront.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('eb836f65-532b-495d-a235-3602a9bd1ad2', 'Blockchain.com', 'blockchain.com', 'www.blockchain.com', 'https://www.linkedin.com/company/blockchain/', 'https://app.dealroom.co/companies/blockchain_com', 'Blockchain.com is connecting the world to the future of finance. The most trusted and fastest growing crypto company, helping millions across the globe', 'London', 'United Kingdom', 2011, 1207, 4.4117646, 454545273, 6, 1136363182, 2021, 'operational', '[{"uuid":"2c5d00b8-c738-402c-95c7-4bc1787c9aa4","name":"Ben Reeves"},{"uuid":"53c7846e-f02e-42a7-aac4-ad7423d5aeec","name":"Nicolas Cary"},{"uuid":"d0fd9fdc-9075-4c63-8860-11016020016c","name":"Peter Smith"}]', '{}', '2026-11-05T15:53:04.860Z', 'Blockchain.com is a leading platform in the cryptocurrency market, providing a comprehensive suite of services for buying, storing, and trading digital assets like Bitcoin, Ethereum, and other top cryptocurrencies. The company serves both individual and institutional clients, offering a fast and reliable exchange that executes trades in microseconds. Blockchain.com operates in the global cryptocurrency market, leveraging its deep liquidity and advanced matching engine to facilitate seamless transactions. The business model revolves around transaction fees, trading spreads, and premium services for advanced users. Revenue is generated through trading fees, wallet services, and API access for institutional clients. The platform integrates with a global banking network, allowing users to deposit and withdraw multiple fiat currencies, including Euros, Dollars, Pounds, and Lira. Blockchain.com also provides an institutional-grade API for programmatic trading and live market data streaming. The company is committed to security and reliability, ensuring that users'' funds and data are protected at all times.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4f1c6e46-3831-42f9-b1bf-be3b4b4642e0', 'Bloom & Wild', 'bloomandwild.com', 'http://www.bloomandwild.com', 'https://www.linkedin.com/company/bloom-&-wild/', 'https://app.dealroom.co/companies/bloom_wild', 'An online flower delivery platform developing a modern approach for sending flowers to loved ones', 'London', 'United Kingdom', 2014, 299, 7.9422383, 126250000, 5, 116569306, 2025, 'operational', '[{"uuid":"a1693d8b-ac0f-43f7-a781-0abb95bdfaa2","name":"Ben Stanway"},{"uuid":"dfb1c339-e48e-4a8a-8bb7-f6c0398be840","name":"Aron Gelbard"}]', '{}', '2026-11-05T15:53:18.240Z', 'Bloom & Wild is a UK-based online florist startup that operates in the e-commerce sector. The company specializes in delivering fresh, designer-quality flowers in bespoke packaging that fits through a standard letterbox. This innovative approach to flower delivery eliminates the need for recipients to be at home to receive their flowers, providing a unique selling point in the competitive online florist market.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('622fbf16-84f5-4cd8-a431-39e7c18637e3', 'Bob', 'bob.io', 'https://bob.io/', 'https://www.linkedin.com/company/bob-bluetooth-baggage-tracking/', 'https://app.dealroom.co/companies/bob', 'Tech service that transports and checks in luggage for passengers', 'Madrid', 'Spain', 2017, 17, 21.428572, 2749999, 3, 37290, 2022, 'operational', '[{"uuid":"648e5793-88b8-4329-8934-9b536631232a","name":"Marc Palatsi"},{"uuid":"9ad881ba-bf92-4f45-8396-155afd515ac6","name":"Felix Campano"}]', '{}', '2026-11-05T15:56:04.243Z', 'Bob.io is a travel service company that specializes in providing a convenient baggage check-in service from home, aimed at enhancing the travel experience for airline passengers. Operating primarily in the travel and transportation market, Bob.io partners with leading airlines to offer a seamless service where customers can have their luggage picked up from their location, checked in, and delivered directly to the destination airport''s baggage reclaim belt. This service is particularly beneficial for frequent flyers, business travelers, and families who seek to avoid the hassle and time-consuming process of airport check-ins and queues.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('02216955-115c-4624-a012-df0d2f8d664f', 'CMR Surgical', 'cmrsurgical.com', 'http://www.cmrsurgical.com/', 'https://www.linkedin.com/company/cmrsurgical/', 'https://app.dealroom.co/companies/cmr_surgical', 'Modular robotic system for minimal access surgery.', 'Cambridge', 'United Kingdom', 2014, 684, 9.090909, 947726894, 7, 52900000, 2024, 'operational', '[{"uuid":"ae2d285a-90ce-4004-ab54-933568edaeb8","name":"Luke Hares"},{"uuid":"588a1885-2f06-422d-aef0-66ed289c99dc","name":"Mark Slack"}]', '{}', '2026-11-05T15:55:56.052Z', 'CMR Surgical is a British medical device company, founded in 2014, that developed the Versius Surgical Robotic System to make minimal access, or keyhole, surgery more accessible to patients globally. The company was founded by Luke Hares, Keith Marshall, Paul Roberts, Mark Slack, and Martin Frost. The founders combined their expertise in surgery, engineering, robotics, and medical device commercialization to create a more versatile and cost-effective robotic solution. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('8de8225c-9fd7-4168-b8a6-1cf9d1e1b012', 'Cabify', 'cabify.com', 'http://cabify.com', 'https://www.linkedin.com/company/cabify/', 'https://app.dealroom.co/companies/cabify', 'Connects private users and companies with the means of transport that best suit their needs. Its main objective is to make cities a better place to live', 'Madrid', 'Spain', 2011, 4856, 12.668214, 369174095, 11, 633333080, 2024, 'operational', '[{"uuid":"b84dcdc0-ddd0-4bf5-90ef-6d35c7416c56","name":"Juan de Antonio"},{"uuid":"b7aea0d6-5f49-46ab-a2cb-224eb28357e7","name":"Vicente Pascual"}]', '{}', '2026-11-05T15:54:35.037Z', 'Cabify is a transportation startup that operates in the ride-hailing market, similar to companies like Uber and Lyft. The company serves a diverse range of clients, including individual consumers and businesses, across eight countries and more than 40 cities in Latin America and Spain. Cabify aims to provide a safer and higher-quality travel experience through its app-based platform, which allows users to book rides with professional drivers and modern vehicles.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('ef36bf4d-5375-40db-a15d-a3b14c9c0e99', 'Cafler', 'cafler.ai', 'https://cafler.ai', 'https://www.linkedin.com/company/cafler/', 'https://app.dealroom.co/companies/cafler', 'The AI-native operating system for the automotive aftermarket.', 'Barcelona', 'Spain', 2021, 60, 36.363636, 20666658, 4, 374132, 2022, 'operational', '[{"uuid":"fa32fe80-20fa-44a4-bcbc-43604dc778b3","name":"Inigo Cavero"},{"uuid":"a5332cae-7a93-4aac-994b-34be337aa705","name":"Ricard Guillem"}]', '{}', '2026-11-05T15:54:35.037Z', 'Cafler is the AI for automotive aftersales. Its platform, Cafler OS, is a workshop management system with AI agents that handle the day-to-day work of independent workshops, workshop networks, dealerships, fleets and service stations: scheduling, customers and vehicles, work orders, quotes, invoicing and parts ordering.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('226638bb-46c4-4863-9775-03c08d6f6750', 'Cala AI', 'cala.ai', 'https://www.cala.ai', 'https://www.linkedin.com/company/cala-ai/', 'https://app.dealroom.co/companies/cala_ai', 'Verified knowledge layer and structured data API for AI agents', 'Barcelona', 'Spain', 2025, 29, NULL, 5833331, 1, NULL, NULL, 'operational', '[{"uuid":"8272ffbe-81e0-4080-be82-c4af7e6867d8","name":"Issey Masuda Mora"},{"uuid":"981714a1-ba98-46b4-88ec-477b47cab85c","name":"Elisenda Bou-Balust"}]', '{}', '2026-11-05T15:53:55.756Z', 'Cala AI is a foundational artificial intelligence infrastructure company that develops explainable data pipelines and knowledge verification systems for enterprise applications. Founded by former Apple Media Knowledge leads, the company was established to address the critical limitations of modern large language models, specifically their propensity to hallucinate, rely on outdated information, and lack proper source attribution. Its core product functions as a specialized knowledge layer that transforms chaotic, unstructured web data into a clean, strictly verified entity graph.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0a94dec7-064c-456d-8397-4678052c5cb5', 'Callosum', 'callosum.com', 'https://www.callosum.com', 'https://www.linkedin.com/company/callosumtechnologies/', 'https://app.dealroom.co/companies/callosum_1', 'Software that unifies heterogeneous AI models and chips', 'London', 'United Kingdom', 2025, 46, NULL, 83522694, 4, NULL, NULL, 'operational', '[{"uuid":"e7b75210-20e4-4421-b308-0486c68ced1e","name":"Jascha Achterberg"},{"uuid":"36e19061-f19b-440a-9b56-b357f78edb0b","name":"Danyal Akarca"}]', '{}', '2026-11-05T15:54:51.538Z', 'Callosum is a London AI infrastructure company building software that unifies heterogeneous models and chips—orchestrating AI workloads across specialised silicon rather than scaling a single model on uniform hardware. Co-founded by neuroscientists Dr. Danyal Akarca and Dr. Jascha Achterberg (Cambridge PhDs; experience spanning Google DeepMind and Intel), Callosum delivers Tailored Inference APIs that route tasks to the best model–chip combination under cost, energy and latency constraints, with compute partnerships including Cerebras and Rebellions. After a $10.25 million Plural-led pre-seed with ARIA support in February 2026, Callosum raised a $100 million (€85.4 million) Seed in August 2026 led by Atomico, with significant participation from Plural, DCVC and the UK Sovereign AI Fund—the fund’s first investment—and was named in the UK’s £1.1 billion AI hardware plan.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('ee0bded7-0786-4e5c-95d5-a583d8c3def5', 'Cambridge Quantum Computing', 'cambridgequantum.com', 'http://www.cambridgequantum.com/', 'https://www.linkedin.com/company/cambridge-quantum-computing-limited/', 'https://app.dealroom.co/companies/cambridge_quantum_computing_limited', 'A pioneer in the research and development of powerful quantum technology', 'London', 'United Kingdom', 2014, 25, -16.666666, 62223308, 11, 2670000, 2023, 'operational', '[{"uuid":"7b602288-4d5d-4c8d-9dc4-d35364d0a00d","name":"Ilyas Khan"},{"uuid":"6e06cbbb-cd43-4eff-bff2-99b249611481","name":"Henrik Dreyer"}]', '{}', '2026-11-05T15:54:12.521Z', 'Cambridge Quantum Computing (CQC) is a pioneering company in the field of quantum software and algorithms. Founded in 2014, CQC focuses on developing advanced quantum computing solutions that enable businesses to leverage the transformative potential of quantum technology. The company serves a diverse range of clients in the chemical, energy, financial, and material science industries, helping them to optimize their operations and solve complex problems that are beyond the reach of classical computing.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('d8f8a059-3a3b-48ce-b72f-c82c22b02990', 'Carwow', 'carwow.co.uk', 'http://www.carwow.co.uk/', 'https://www.linkedin.com/company/carwow/', 'https://app.dealroom.co/companies/carwow', 'Carwow is an online car marketplace that connects customers, automotive brands and car dealers', 'London', 'United Kingdom', 2013, 609, 5, 174081766, 10, 104200000, 2025, 'operational', '[{"uuid":"7016f45c-0264-42f2-8ec0-2c58d067b9ae","name":"David Santoro"},{"uuid":"6c52ef7b-9673-42d0-abc0-08e6b27fc522","name":"Alexandra Margolis"},{"uuid":"b0a577b2-dbf1-4398-9639-d76912144902","name":"James Hind"}]', '{}', '2026-11-05T15:54:12.521Z', 'Carwow is a UK-based online platform that simplifies the process of buying and selling cars. It operates in the automotive retail market, serving a broad range of clients, from individual car owners to car dealerships. The platform''s primary function is to connect buyers and sellers, eliminating the need for haggling and providing a transparent, hassle-free experience. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('edf1f444-8004-4c71-ad6e-8d27a0e50ea2', 'Causaly', 'causaly.com', 'https://www.causaly.com', 'https://www.linkedin.com/company/causaly/', 'https://app.dealroom.co/companies/causaly', 'AI research platform for life sciences R&D', 'London', 'United Kingdom', 2018, 119, -11.851851, 62674217, 5, 22121203, 2023, 'operational', '[{"uuid":"a1f97e62-1bad-4219-8078-f5534ca5ecc9","name":"Yiannis Kiachopoulos"},{"uuid":"275afbee-9f18-4ad9-956b-b1117fe0cac7","name":"Artur Saudabayev"}]', '{}', '2026-11-05T15:53:18.240Z', 'Causaly builds an agentic AI research platform for life sciences R&D. It helps drug discovery and clinical development teams find and interpret biomedical evidence, turning research questions into cited, reviewable answers.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('d5afa912-29d5-44ae-b19d-96eec2cba585', 'Checkout.com', 'checkout.com', 'http://www.checkout.com', 'https://www.linkedin.com/company/checkout/', 'https://app.dealroom.co/companies/checkout_com', 'Offers credit card and alternative payment methods', 'London', 'United Kingdom', 2012, 2485, 11.385029, 1386363082, 4, 568181591, 2026, 'operational', '[{"uuid":"73c1791a-4b26-4520-900a-fc3417299ab6","name":"Guillaume Pousaz"}]', '{}', '2026-11-05T15:53:04.860Z', 'Checkout.com is a financial technology company that provides a high-performance payments platform. The platform is designed for enterprise and scaling businesses, enabling them to process payments, send payouts, and manage card programs efficiently. Headquartered in London, Checkout.com has a global presence with offices in New York, Paris, Dubai, Hong Kong, and other locations across six continents. The company serves a diverse range of clients, including global brands such as Sony, SHEIN, Wise, Patreon, and GE HealthCare.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('edc5dfbc-2665-44c2-998c-8dbd2aeb7db3', 'CitiBox', 'citibox.com', 'http://citibox.com', 'https://www.linkedin.com/company/citibox-sostenibilidad/', 'https://app.dealroom.co/companies/citibox', 'Smart mailboxes for residential e-commerce parcel deliveries', 'Madrid', 'Spain', 2015, 82, 24.242424, 86096935, 9, 54166645, 2023, 'operational', '[{"uuid":"f3fcd76e-340e-4785-b1bb-7c52727be120","name":"David Bernabeu"}]', '{}', '2026-11-05T15:55:09.655Z', 'Citibox is a technology-driven company specializing in smart parcel lockers designed to streamline last-mile delivery in urban environments. The company installs secure, automated parcel boxes directly inside residential buildings, allowing residents to receive packages from any courier or online retailer at any time, even when they are not home. This system eliminates missed deliveries, enhances package security, and provides a fully contactless experience.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('6f985058-99f1-4118-9831-01a44a978c3b', 'Cleo', 'meetcleo.com', 'http://meetcleo.com', 'https://www.linkedin.com/company/cleo-ai/', 'https://app.dealroom.co/companies/cleo', 'AI financial assistant for budgeting and saving', 'London', 'United Kingdom', 2016, 733, 31.362007, 104246625, 6, 303030182, 2026, 'operational', '[{"uuid":"8a9ee26e-0b84-4e66-bc26-30cc9c418b77","name":"Barnaby Hussey-Yeo"}]', '{}', '2026-11-05T15:54:12.521Z', 'Cleo is an AI-powered financial assistant designed to help users, particularly Gen Z and millennials, manage their money through a conversational interface. The company was founded in 2016 by Barney Hussey-Yeo, a data scientist with a master''s degree in Machine Learning. Hussey-Yeo was motivated by his own struggles with money management and his experience at payday loan company Wonga, where he observed that customers were offered credit with little guidance on financial literacy. He began by creating scripts that would analyze his own banking and send him text alerts, an idea that evolved into Cleo. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('cc72abd0-b87a-4dee-88ee-37e88e3c8c17', 'CloudNC', 'cloudnc.com', 'https://cloudnc.com/', 'https://www.linkedin.com/company/cloudnc/', 'https://app.dealroom.co/companies/cloudnc_1', 'AI CAM Assist software that speeds CNC programming for machine shops', 'London', 'United Kingdom', 2015, 105, -7.079646, 61679374, 12, 2955618, 2025, 'operational', '[{"uuid":"019f05b4-a319-4cf7-8599-9122092c4e6d","name":"Theo Saville"}]', '{}', '2026-11-05T15:54:51.538Z', 'CloudNC is a London precision-manufacturing software company whose CAM Assist product uses AI to generate and review CNC machining strategies and toolpaths inside existing CAM workflows (including Autodesk Fusion, Mastercam, Siemens NX, GibbsCAM and SolidCAM), helping machine shops quote and program faster while keeping human review before production. The software is used by more than 1,000 machine shops globally, including hundreds in the US, with named customers such as Lockheed Martin and Major Tool & Machine; CloudNC also runs its own UK factory machining parts for aerospace, space, energy, automotive and defence. In September 2026 CloudNC raised $20 million led by Nimble Ventures, with Calculus Venture Capital, Entrepreneur First and LM Ventures (Lockheed Martin’s VC arm), to expand CAM Assist into new markets, grow go-to-market and support, pursue FedRAMP for US government work, and develop new AI tools including Quote Agent for automated machining estimates. Sources: Tech.eu, 9 Sep 2026; TechCrunch; company announcements.', '["accelerator","data management","social media marketing software","database","data security","corporate learning management systems","human resource management system","Venture Capital","operations","e-commerce platforms","recruitment marketing","Industry 4.0","Robot Autonomy and Motion Control","editors","ad exchanges","mobile application development platforms","business process management","Core AI","Subscription","SaaS","sales enablement","marketing automation","page builders","Angel","frameworks and libraries","communication and collaboration","development","deployment","identity and access management","testing and qa","content management system","UKis Digital and technologies","Selling own inventory","performance","software development","DT and LS","Dual-Use Tech","it infrastructure","web frameworks","source code management","customer data platforms","open source","b2b","web platform extensions","Artificial Intelligence","tag management","Robotics","email","web servers","search engines","Hard Tech","programming languages","Breakout stage","audio-video-graphics","advertising","payment processing","human resource","Manufacturing","website builders","site search","web & portal technology","web and application servers","miscellaneous","programming","network security","AI Applications","cloud infrastructure computing","governance-risk and compliance","e-commerce","Analytics","office suites","Mechanical Solutions","dev tools","javascript libraries","wordpress plugins","intelligence and analytics","containers","Enterprise Software","real user monitoring","analytics","other audio-video-graphics software","devops","online banking","security","Milling","issue trackers","science-based","cad & graphics","Manufacturing and Assembly Robots","uk is8 advanced manufacturing","operating systems & computing languages","cloud hosting","web analytics","platform as a service","uk is8 digital and technologies","application development & management","javascript frameworks","consent management","Industrial Technology","Manufacturing Tech","live chat","font scripts","blogs","applicant tracking systems","human capital management","ui frameworks","charting","certificates","uk is8 defence","Deep Tech","continuous integration","configuration management","cookie compliance","Manufacturing","Industrial Robotics","Machine Learning","containerization","maps","web tools and plugins","web hosting","enablers for robotics","Defence Applications"]', '["startup","vc_backed","funded"]', 68.26, 61000, 1, 3, 90909055, NULL, NULL, -14889963, 2025, '[{"year":2018,"revenue":1136363,"ebitda":null,"profit":null,"rnd":null,"valuation":54000000,"employees":26},{"year":2019,"revenue":5113634,"ebitda":null,"profit":null,"rnd":null,"valuation":54000000,"employees":67},{"year":2020,"revenue":6439391,"ebitda":null,"profit":null,"rnd":null,"valuation":54000000,"employees":59},{"year":2021,"revenue":7007573,"ebitda":null,"profit":null,"rnd":null,"valuation":54000000,"employees":71},{"year":2022,"revenue":2024683,"ebitda":null,"profit":null,"rnd":null,"valuation":204545373,"employees":67},{"year":2023,"revenue":1836806,"ebitda":null,"profit":null,"rnd":null,"valuation":204545373,"employees":127},{"year":2024,"revenue":2351149,"ebitda":null,"profit":null,"rnd":null,"valuation":204545373,"employees":117},{"year":2025,"revenue":2955618,"ebitda":null,"profit":-14889963,"rnd":null,"valuation":204545373,"employees":113},{"year":2026,"revenue":2955618,"ebitda":null,"profit":-14889963,"rnd":null,"valuation":90909055,"employees":105}]', '2026-11-05T15:54:51.538Z', 'GBP', '2026-11-05T15:54:51.538Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2f62bdb7-3b36-43e8-89cc-5abd4a82feae', 'Codat', 'codat.io', 'http://codat.io', 'https://www.linkedin.com/company/codat-limited/', 'https://app.dealroom.co/companies/codat', 'Universal API for small business financial data.', 'London', 'United Kingdom', 2017, 101, -11.403509, 128712073, 7, 11750000, 2024, 'operational', '[{"uuid":"29924de0-8e6e-4a33-afaa-1a24c65707e1","name":"Peter Lord"}]', '{}', '2026-11-05T15:53:18.240Z', 'Codat.io is a leading fintech startup that provides a specialized infrastructure for financial institutions and fintech companies to streamline their data integration processes. The company operates in the financial technology market, serving clients who need to automate the collection and processing of financial information, particularly for underwriting and lending to small businesses.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('e8f86411-2dd4-479e-9806-dd1568aed1c2', 'Codee', 'codee.com', 'http://codee.com', 'https://www.linkedin.com/company/codee-com/', 'https://app.dealroom.co/companies/appentra', 'Codee is a software solution that provides automated code inspection specifically designed to improve the performance of software.  We are an innovative company  whose mission is to accelerate the digitized world empowering businesses to develop fast and to improve the performance of software by processing more instructions and more data', 'A Coruña', 'Spain', 2012, 13, -35, 7247497, 7, 244179, 2024, 'operational', '[{"uuid":"2562358a-d2ad-448f-adf7-f1994bda7cb4","name":"Rosa Vázquez Rogel"},{"uuid":"6b435d2a-2242-48ef-982c-d668138cecf4","name":"Rosa Vázquez Rogel"},{"uuid":"9963725b-0c89-4704-87b9-bb46b16de680","name":"Manuel Arenaz Silva"}]', '{}', '2026-11-05T15:56:04.243Z', 'Codee operates as a specialized, deep-tech entity focused on optimizing software for high-performance computing (HPC). The firm originated in 2012 as Appentra Solutions, a spin-off from the University of A Coruña, Spain, founded by Manuel Arenaz and Rosa Vázquez. Arenaz, who serves as CEO and CTO, leveraged over a decade of his research in advanced compiler technologies and automatic parallelization to address the increasing complexity of programming for high-performance hardware. His background includes a Ph.D. in Computer Science focused on advanced compiler techniques for automatic parallelization for multicore CPUs and GPUs. Vázquez acts as the company''s CFO.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('76300f5d-5264-40b1-8691-51a1a327fe35', 'ComplyAdvantage', 'complyadvantage.com', 'https://complyadvantage.com', 'https://www.linkedin.com/company/complyadvantage', 'https://app.dealroom.co/companies/complyadvantage', 'ComplyAdvantage is the financial industry’s leading source of AI-driven financial crime risk data and detection technology', 'London', 'United Kingdom', 2014, 510, 7.82241, 81969664, 4, 47428878, 2025, 'operational', '[{"uuid":"a66e360c-66b6-4c5d-93b0-ac3b66e3262a","name":"Charles Delingpole"}]', '{}', '2026-11-05T15:53:18.240Z', 'ComplyAdvantage specializes in providing advanced anti-money laundering (AML) data and technology solutions to financial institutions and digital financial service providers. The company operates in the compliance and regulatory technology market, offering tools that automate labor-intensive processes and significantly reduce false positive rates in compliance checks. ComplyAdvantage''s core services include customer screening and monitoring, adverse information and media screening, transaction screening, and transaction monitoring. These services are delivered through API-enabled, cloud-native solutions that easily integrate with existing workflows. The business model is subscription-based, where clients pay for access to the platform and its various features. ComplyAdvantage generates revenue by offering tiered pricing plans based on the volume of transactions and the level of service required. The company serves a diverse client base, including traditional financial institutions and emerging digital financial service providers, helping them meet regulatory requirements and combat financial crime efficiently. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('e93115ae-38b0-422d-84a3-2e37c883cfc6', 'Conduct', 'conduct.ai', 'https://conduct.ai', 'https://www.linkedin.com/company/conduct-ai/', 'https://app.dealroom.co/companies/conduct_2', 'Agentic AI platform modernising enterprise ERP and SAP operations', 'London', 'United Kingdom', 2024, 77, 670, 54545433, 2, NULL, NULL, 'operational', '[{"uuid":"96d5a535-f0cf-4d86-946c-97d72993458f","name":"Henry Thompson"},{"uuid":"85c8ad52-69eb-46f6-a2f4-3a647f4a9129","name":"Philipp Hoefer"},{"uuid":"f727bd4c-2bb3-4103-b368-4389ef010c4d","name":"Jan Philipp Haas"}]', '{}', '2026-11-05T15:53:18.240Z', 'Conduct (conduct.ai) is a London enterprise AI company founded in January 2024 by former Palantir engineers Jan Philipp Haas (CEO), Philipp Hoefer (CPO) and Henry Thompson (CTO). Its agentic platform maps business logic buried in decades of ERP and related system customisation—starting with SAP and expanding across Salesforce, Oracle, MES, WMS and other systems of record—so enterprises can understand, operate and change those systems safely and faster. Customers including Daimler Truck, Heidelberg Materials, Fraport and DHL use Conduct to accelerate transformation workstreams; SAP has named Conduct a strategic AI partner for SAP Cloud ERP transformation, with delivery partners including BCG and NTT DATA Business Solutions. After a September 2025 Seed of about $12 million led by Creandum (with Lucid Capital and Booom), Conduct raised a €51 million ($60 million) Series A in June 2026 co-led by Index Ventures and ICONIQ, with strategic investment from SAP and participation from existing investors, to expand engineering and go-to-market and deepen multi-system coverage. Sources: EU-Startups 17 Jun 2026; FinSMEs.', '["Venture Capital","recruitment marketing","Core AI","Subscription","SaaS","human resources","b2b","Artificial Intelligence","advanced analytics and data science","email","out of stealth","Breakout stage","miscellaneous","AI Applications","cloud infrastructure computing","javascript libraries","intelligence and analytics","Enterprise Software","devops","uk is8 digital and technologies","web design and development services","applicant tracking systems","design","ui frameworks","configuration management","machine learning"]', '["startup","rising_star","vc_backed","funded"]', 93.21, 38000, 1, 24, 272727164, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:53:18.240Z', 'GBP', '2026-11-05T15:53:18.240Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('8b01ec97-a4c8-4a58-9b8c-646a56af2ba9', 'Condukt', 'condukt.co', 'https://condukt.co', 'https://www.linkedin.com/company/condukt/', 'https://app.dealroom.co/companies/condukt', 'Automated business verification and onboarding platform', 'London', 'United Kingdom', 2022, 23, 2200, 10075754, 2, NULL, NULL, 'operational', '[{"uuid":"925eeada-af9b-436e-ac2e-941add911d0d","name":"Bhasker Rao"},{"uuid":"42ac8ee2-4c59-4683-a151-d7414e650135","name":"Paulo Guichard"}]', '{}', '2026-11-05T15:54:51.538Z', 'Condukt is a business verification and data integration platform headquartered in London, United Kingdom. Founded in 2022 by former Revolut employees Paulo Guichard and Bhasker Rao, the company operates in the Business-to-Business (B2B) Software-as-a-Service (SaaS) market. Guichard previously served as head of operations and product owner at Revolut, while Rao was the head of acquiring risk. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('7a0c6d51-7829-44e1-9230-9bbeb06ea8a4', 'Consentio', 'consentio.co', 'http://consentio.co', 'https://www.linkedin.com/company/consentio/', 'https://app.dealroom.co/companies/consentio_trade_finance', 'Consentio is the communication platform for Fruits and Vegetables B2B Commerce', 'Barcelona', 'Spain', 2017, 42, 0, 4991665, 5, 1052152, 2023, 'operational', '[{"uuid":"43947e60-6cac-4ae1-85fd-5e3b80ada2fe","name":"Rafael Duarte"},{"uuid":"ced7eb84-217a-42c6-b54b-af71ade2562b","name":"Vincent Rosso"}]', '{}', '2026-11-05T15:55:09.655Z', 'Consentio is a dynamic startup focused on revolutionizing the fresh produce industry through digital solutions. Founded in 2018 by French entrepreneurs Benoit Vandevivere and Vincent Rosso, the company aims to address inefficiencies in the supply chain that lead to significant food waste. Consentio operates in the fresh produce market, serving producers, wholesalers, and supermarkets.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('35fb228d-b2b6-40ce-b945-e63864efcc3d', 'Credit Benchmark', 'creditbenchmark.com', 'https://www.creditbenchmark.com/', 'https://www.linkedin.com/company/credit-benchmark/', 'https://app.dealroom.co/companies/credit_benchmark', 'Credit Benchmark is a privately owned financial data analytics company offering access to an entirely new source of information: the consensus credit risk views of the world’s leading banks', 'London', 'United Kingdom', 2012, 70, 12.903226, 25757565, 3, 4833331, 2023, 'operational', '[{"uuid":"16ad2206-3635-4a97-b8f4-6835c56b2356","name":"Mark Faulknet"},{"uuid":"8d10e2f3-09d5-4930-9ea0-c62b7a78e7a0","name":"Mark Faulkner"},{"uuid":"9f57aa49-f1fa-42bb-909f-2be52b021cae","name":"Mark Faulkner"},{"uuid":"9aca9590-cd5e-4e05-99db-c170eec31077","name":"Donal Smith"}]', '{}', '2026-11-05T15:53:18.240Z', 'Credit Benchmark aggregates and anonymizes internal credit risk assessments from over 40 leading global financial institutions to provide consensus ratings and analytics. These insights offer an independent perspective on credit risk, which is crucial for risk and investment professionals at banks, insurance companies, asset managers, and other financial firms. The company operates in the financial services market, focusing on credit risk data and analytics. By collecting and publishing these aggregated views, Credit Benchmark helps its clients monitor and manage credit risk within their portfolios, benchmark against industry standards, and gain insights into unrated entities. The business model revolves around providing subscription-based access to its data and analytics platform, generating revenue from financial institutions that rely on this information for risk management and investment decisions.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('c19d0f7e-0137-4f5b-8623-570898d4f248', 'Crescenta', 'crescenta.com', 'http://crescenta.com', 'https://www.linkedin.com/company/crescenta/', 'https://app.dealroom.co/companies/crescenta', 'Crescenta manages private equity funds and promotes selected funds from other managers, providing a streamlined investment experience through a digital advisory service', 'Parla', 'Spain', 2022, 39, 5.4054055, 12916661, 4, NULL, NULL, 'operational', '[{"uuid":"3bd86757-7e01-4e6f-970a-70ebb2052781","name":"Ramiro Iglesias Concepción"},{"uuid":"dabf0503-efae-4cef-a1e4-41f0dd12d9b4","name":"Eduardo Navarro"}]', '{}', '2026-11-05T15:55:36.049Z', 'Crescenta is a digital platform that provides access to private equity investments for both retail and professional investors, with a minimum investment of €10,000. The company primarily focuses on investments in infrastructure, real estate, and energy funds, with a particular emphasis on the U.S. market.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('13fc4691-ea8b-43dd-85d0-657517e0ad10', 'CrowdFarming', 'crowdfarming.com', 'https://www.crowdfarming.com/en', 'https://www.linkedin.com/company/crowdfarming/', 'https://app.dealroom.co/companies/crowdfarming', 'CrowdFarming is Europe''s leading farmer-to-consumer marketplace', 'Madrid', 'Spain', 2017, 164, -5.202312, 12499995, 1, 20645889, 2023, 'operational', '[{"uuid":"3117d197-415c-4a3d-9fb1-6610c726e141","name":"Gonzalo Úrculo"},{"uuid":"d39d509e-5f7c-4c9b-8183-35b14b4a5f93","name":"Moises Grana"},{"uuid":"5c5f5f4d-e3be-4dd7-8c26-421973705fe4","name":"Gabriel Alvarez-Ossorio"},{"uuid":"bee6a27d-6964-4a00-863c-db4918bf975f","name":"Juliette Simonin"}]', '{}', '2026-11-05T15:54:35.037Z', 'CrowdFarming is Europe''s leading farmer-to-consumer marketplace. It provides all the necessary services farmers need to create their own direct sales channel without intermediaries, resulting in better prices for farmers, fresher products for consumers, and a reduced environmental impact. The company counts more than 400k active customers and 300+ organic and in transition farmers.', '["corporate","data security","sales","paas","photo galleries","Venture Capital","web fonts","recruitment marketing","editors","Food Logistics & Delivery","marketing","mobile application development platforms","sales enablement","marketing automation","customer relationship management","frameworks and libraries","communication and collaboration","development","deployment","testing and qa","content management system","digital asse