INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('a52e47df-37b4-4b66-8bcd-841b8f96dcda', 'Crowdcube', 'crowdcube.com', 'http://www.crowdcube.com', 'https://www.linkedin.com/company/crowdcube-limited/', 'https://app.dealroom.co/companies/crowdcube', 'An online crowdfunding service that enables individuals to invest or loan small amounts in small companies in return for equity or an annual return', 'London', 'United Kingdom', 2010, 123, 6.034483, 37739999, 8, 9761263, 2024, 'operational', '[{"uuid":"533a8815-7fe3-40e5-9a8d-133ea0713e11","name":"Darren Westlake"}]', '{}', '2026-11-05T15:54:12.521Z', 'Crowdcube is a leading equity crowdfunding platform for entrepreneurs of start-ups and growing businesses to connect with potential investors. Dedicated to helping UK-based entrepreneurs raise finance to start or grow their business, Crowdcube gives investors real equity in the companies they fund. Crowdcube uses the web-based notion of ‘crowdfunding’ where a community of like minded people pool their money and knowledge together to back an idea, business or person.  Risk Warning: Investing in start-ups and early stage businesses involves risks, including illiquidity, lack of dividends, loss of investment and dilution, and it should be done only as part of a diversified portfolio. Crowdcube is targeted exclusively at investors who are sufficiently sophisticated to understand these risks and make their own investment decisions. You will only be able to invest via Crowdcube once you are registered as sufficiently sophisticated.', '["accelerator","persona