INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('52f4dfaf-1103-4bd2-b18b-ff7c312d8176', 'Cuideo', 'cuideo.com', 'https://cuideo.com/', 'https://www.linkedin.com/company/cuideo/', 'https://app.dealroom.co/companies/cuideo', 'The best solution to find professional home caregivers for the elderly', 'Barcelona', 'Spain', 2015, 616, 7.3170733, 6833331, 5, 2799897, 2023, 'operational', '[{"uuid":"558d7f28-789f-49e6-987d-a2c46e999c56","name":"Guillermo Molina Valiente"},{"uuid":"15f19cb7-cda9-4e7b-90c1-a539c44cc674","name":"Marta Cuesta López"},{"uuid":"7186e633-39ae-4f16-ace1-9f273731fb4a","name":"Alejandro Valdés Gandarillas"},{"uuid":"c3fbde37-07bf-493e-8316-8592f2de00bc","name":"Roberto Valdes"},{"uuid":"a2c34c0c-292d-4cbe-a217-3638518ff76c","name":"Adrià Buzón Lausín"}]', '{}', '2026-11-05T15:55:09.655Z', 'Cuideo specializes in providing personalized home care services for the elderly, ensuring their comfort and quality of life through professional caregivers. The company operates in the home healthcare market, primarily serving elderly individuals and their families who seek reliable and compassionate care solutions. Cuideo''s business model revolves around matching qualified caregivers with clients based on their specific needs and preferences. The company generates revenue through service fees charged for the caregiving services provided. By leveraging a network of vetted caregivers, Cuideo ensures high standards of care and support for its clients.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('e1c2badc-3b33-4e0b-87ae-f1bee1c08ff2', 'CuspAI', 'cusp.ai', 'https://www.cusp.ai/', 'https://www.linkedin.com/company/cusp-ai/', 'https://app.dealroom.co/companies/cuspai', 'AI materials discovery and AI Materials Foundry', 'Cambridge', 'United Kingdom', 2024, 100, 122.22222, 439393764, 3, NULL, NULL, 'operational', '[{"uuid":"5bc9b197-14da-4773-8dd8-441f18c32382","name":"Chad Edwards"},{"uuid":"b4ed3f96-86d5-4486-ab0c-5b4b368855b6","name":"Max Welling"}]', '{}', '2026-11-05T15:55:23.556Z', 'CuspAI is a Cambridge, UK company founded in 2024 by Dr Chad Edwards and Prof Max Welling that builds an AI system for materials discovery—acting as a search engine for materials that do not yet exist across semiconductors, energy, climate, water treatment and carbon capture. Through its AI Materials Foundry, a global network of labs, compute and partners including NVIDIA, Meta, Samsung and Hyundai, customers specify desired properties and CuspAI designs candidate materials. Advisers include Geoffrey Hinton and Yann LeCun. In July 2026 CuspAI closed a $450 million Series B at a $2.6 billion valuation co-led by Kleiner Perkins and NEA, with significant participation from Bezos Expeditions and the UK Sovereign AI Fund, plus Glade Brook, Lux Capital, AMD Ventures, Tru Arrow, StepStone and returning Temasek, Basis Set, Giant Ventures, Phoenix Court and Northzone; disclosed funding now exceeds $650 million. Proceeds fund US, APAC and European expansion of the Foundry. Sources: Tech.eu / Reuters 20 Jul 2026; cusp.ai.', '["data management","database","Biotechnology","NIF Supply Chain Resilience","Venture Capital","AI Material Discovery","Core AI","Subscription","SaaS","Angel","Industry Innovation And Infrastructure (#9)","Generative AI","UKis Digital and technologies","performance","marketing analytics","system analytics & monitoring","domain name services","software development","DT and LS","it infrastructure","web frameworks","Engineering and Manufacturing Equipment","open source","database management","b2b","genAI Applications","Artificial Intelligence","Energy","advanced analytics and data science","web servers","programming languages","Verified Unicorns and $1B Exits","Commission","miscellaneous","programming","Techbio Drug Discovery","AI Applications","business intelligence","javascript libraries","intelligence and analytics","Late stage","analytics","Advanced Materials","Sustainable Development Goals","Climate Tech","science-based","uk is8 advanced manufacturing","operating systems & computing languages","web analytics","data integration","uk is8 digital and technologies","application development & management","NIF defense security and resilience","comp bio and chem","UKis manufacturing","Deep Tech","Hardware","machine learning","operating systems"]', '["startup","unicorn","vc_backed","funded"]', 96.1, 22000, 1, 42, 1969696182, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:55:23.556Z', 'GBP', '2026-11-05T15:55:23.556Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3ebb0fe0-f4c6-4411-be77-5236e45f738f', 'Cutover', 'cutover.com', 'http://cutover.com', 'https://www.linkedin.com/company/cutover/', 'https://app.dealroom.co/companies/cutover_com', 'Platform designed to orchestrate critical enterprise IT change events, enhancing collaboration and reducing risk and cos', 'London', 'United Kingdom', 2013, 142, -2.0689654, 41363620, 5, 27178398, 2025, 'operational', '[{"uuid":"2f583f0e-6b2f-4021-9d66-9d0df7adc92c","name":"Richard Bell"},{"uuid":"cba15afc-f72e-4eba-b9f5-bd9c187b8d0f","name":"Craig Gregory"}]', '{}', '2026-11-05T15:53:18.240Z', 'Cutover is a cloud-based platform specializing in collaborative automation, designed to streamline and orchestrate both manual and automated activities across organizations. The platform serves a diverse range of clients, including financial services, retail, and technology sectors, helping them manage complex workflows and large-scale projects. Cutover operates in the enterprise software market, offering a subscription-based business model that generates revenue through licensing fees. The platform''s key features include automation runbooks, dashboards, analytics, and integrations, which provide real-time visibility and control over operations. By replacing complexity with clarity, Cutover enables teams to coordinate multiple activities, synchronize efforts, and compress timelines, thereby driving operational excellence. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('9d24631e-1537-42e1-8162-d7b49145dfd9', 'Cüimo', 'cuimo.com', 'https://www.cuimo.com/', 'https://www.linkedin.com/company/cuimo/', 'https://app.dealroom.co/companies/c_imo', 'Transforming motorcycle sales by offering a transactional marketplace with services like inspections, transport, and financing', 'Boadilla del Monte', 'Spain', 2020, 66, 40.425533, 7727270, 3, 7083330, 2024, 'operational', '[{"uuid":"c49474a1-aaa9-4640-89c0-72e2301e2152","name":"Enrique Adrién"},{"uuid":"791bb1ab-0849-4a69-af80-7c700495069e","name":"Jaime Álvarez"},{"uuid":"37fd3bce-3905-4f34-a0b1-2eed4598fd09","name":"Alejandro de la Hoz de Miguel"}]', '{}', '2026-11-05T15:54:35.037Z', 'Cüimo es una plataforma de encuentro en la que vendedores y compradores podrán llevar a cabo sus transacciones de forma 100% segura y sin sorpresas. Comprar una moto es un proceso que cuesta tiempo y dinero. Nosotros nos encargamos de todo lo que necesites durante el proceso: transporte, gestoria online, pago seguro, cambio de titular en la DGT, revisión en taller oficial... Cüimo ha nacido para hacerte la vida más fácil.', '["Private Equity","Venture Capital","Motorcycle","Angel","Search, Buy & Rent","Circular Economy","Commission","Breakout stage","Transportation","Responsible Consumption And Production (#12)","b2c","Marketplace & ecommerce","Second Hand"]', '["startup","rising_star","vc_backed","funded"]', 85.77, 220000, 0, 0, 4499998, NULL, NULL, -233080, 2023, '[{"year":2022,"revenue":282473,"ebitda":null,"profit":-72611,"rnd":null,"valuation":1863636,"employees":3},{"year":2023,"revenue":1297396,"ebitda":null,"profit":-233080,"rnd":null,"valuation":4499998,"employees":9},{"year":2024,"revenue":7083330,"ebitda":null,"profit":-233080,"rnd":null,"valuation":4499998,"employees":19},{"year":2025,"revenue":7083330,"ebitda":null,"profit":-233080,"rnd":null,"valuation":4499998,"employees":47},{"year":2026,"revenue":7083330,"ebitda":null,"profit":-233080,"rnd":null,"valuation":4499998,"employees":66}]', '2026-11-05T15:54:35.037Z', 'GBP', '2026-11-05T15:54:35.037Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('c9ef7be3-ec6f-42f4-8555-f2fef56ef1b2', 'DELLI', 'delli.market', 'https://www.delli.market/', 'https://www.linkedin.com/company/delli-market/', 'https://app.dealroom.co/companies/delli', 'DELLI is a platform that helps independent makers manage, sell, and grow across any channel.', 'London', 'United Kingdom', 2021, 86, 2.3809524, 12416662, 3, 3257574, 2023, 'operational', '[{"uuid":"44db1972-f96d-4e7f-a14e-5e52463f3b63","name":"Robyn Simms"},{"uuid":"238b9232-d756-4898-9a0b-5bfb1058ba59","name":"Simon Beckerman"}]', '{}', '2026-11-05T15:54:12.521Z', 'DELLI is a platform that helps independent makers manage, sell, and grow across any channel.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('9a896f94-c955-4b59-867d-dc9f01b16d6f', 'DUX Gaming', 'teamdux.com', 'http://teamdux.com', 'https://www.linkedin.com/company/team-dux-gaming/', 'https://app.dealroom.co/companies/dux_gaming', 'Brings a unique approach in esports idustry', 'Madrid', 'Spain', 2018, 19, 0, 2499999, 1, 507619, 2023, 'operational', '[{"uuid":"7c95520a-5ded-4ea8-bb3e-7a5c87382b7c","name":"Xavi Robles"},{"uuid":"1702aa40-6fde-4bce-9a16-0ddfaca226a7","name":"Jordi Torras"}]', '{}', '2026-11-05T15:56:04.243Z', 'DUX Gaming, established in May 2018, operates at the intersection of traditional sports and the burgeoning esports sector. The company was founded by Jordi Torras and Xavier Robles, who also founded VIZZ Agency, a prominent talent agency for Spanish-speaking content creators. Their vision was to create an esports club focused on sports simulation games, a niche they identified as having significant growth potential due to its accessibility to a mainstream audience familiar with traditional sports like football and basketball. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('a73bc702-a09f-4301-8322-d49aeda6f4a7', 'Daye', 'yourdaye.com', 'https://yourdaye.com/', 'https://www.linkedin.com/company/yourdaye/', 'https://app.dealroom.co/companies/daye', 'Gynaecological health platform for at-home diagnostic testing', 'London', 'United Kingdom', 2017, 119, 16.666666, 16404023, 5, NULL, NULL, 'operational', '[{"uuid":"d6e81202-91e4-443e-a501-8f8e9acfcdd9","name":"Valentina Milanova"}]', '{}', '2026-11-05T15:53:18.240Z', 'Daye is a UK-based gynaecological health company developing products and services to address gaps in medical research and innovation for women''s health. The company was founded in 2017 by Valentina Milanova, who was motivated by her personal struggles with menstrual pain and the lack of effective solutions. Milanova, who previously worked in venture capital at Founders Factory and Techstars, initially envisioned a research-focused NGO before opting for a startup structure to raise funds for clinical trials. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('75c39ebb-ceea-4895-bbb2-550e631194b9', 'Dersu', 'dersu.com', 'https://dersu.com', 'https://www.linkedin.com/company/dersu/', 'https://app.dealroom.co/companies/dersu', 'An App to organize routes in a safer way', 'Jaca', 'Spain', 2021, 15, -6.25, 833333, 1, 795454, 2023, 'operational', NULL, '{}', '2026-11-05T15:56:04.243Z', 'Dersu, a Spanish startup originating from Jaca, was established in May 2021 by co-founders Borja Delgado, Fernando Errekalde, Juan Delgado, and María Renilla. The founding team combined their extensive backgrounds in both the technology and mountaineering sectors to create a digital product focused on enhancing safety and promoting sustainable values in mountain activities. The company''s inception was a response to the exponential growth in hiking and mountain sports, a trend notably amplified since the pandemic, which also saw a rise in related accidents. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('b6806b00-6926-4ec6-9586-160aebdd9fd2', 'Dexory', 'dexory.com', 'https://www.dexory.com', 'https://www.linkedin.com/company/dexory/', 'https://app.dealroom.co/companies/dexory', 'Robotics and AI for real-time warehouse intelligence', 'Wallingford', 'United Kingdom', 2015, 259, 37.765957, 146721355, 12, 3550609, 2025, 'operational', '[{"uuid":"7c572e06-924a-410f-9875-dd69849c6cc7","name":"Oana Andreea Jinga"},{"uuid":"4317da42-ce24-4343-b7df-c12355614c19","name":"Andrei Danescu"},{"uuid":"894b4c39-f9c5-4858-8ae2-594af31c2d28","name":"Adrian Negoita"}]', '{}', '2026-11-05T15:54:51.538Z', 'Dexory is a robotics and data intelligence company providing logistics solutions that use autonomous robots and AI to generate real-time data insights. The company was founded in 2015 as BotsAndUs by Andrei Danescu, Oana Jinga, and Adrian Negoita, three Romanian entrepreneurs who moved to the UK. The founders have backgrounds in engineering and technology, with experience at companies like Google, Jaguar Land Rover, and Just Eat. Originally focused on robotics for retail and travel, the company pivoted to the logistics and warehouse industry during the pandemic. It rebranded to Dexory in November 2022. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('e19e0d70-7e36-405f-ac74-a947955f4c27', 'Digger', 'opentaco.dev', 'https://opentaco.dev', 'https://www.linkedin.com/company/diggerhq/', 'https://app.dealroom.co/companies/digger', 'Open-source IaC orchestration within your existing CI', 'London', 'United Kingdom', 2020, 21, 31.25, 5227271, 2, 848485, 2023, 'operational', '[{"uuid":"91cb68d0-1e5e-42c8-9894-ce55b17eaf64","name":"Mohamed Habib"},{"uuid":"920cfa95-60ed-43bb-a61b-96b14107ba72","name":"Igor Zalutski"}]', '{}', '2026-11-05T15:53:04.860Z', 'Digger is a software company developing open-source tools for Infrastructure as Code (IaC) management, specifically targeting Terraform and OpenTofu automation. Founded in 2020 by Igor Zalutski (CEO), Mohamed Habib (CTO), and Utpal Nadiger, the company aims to simplify and secure infrastructure provisioning and management by integrating directly into a development team''s existing Continuous Integration/Continuous Delivery (CI/CD) pipeline, such as GitHub Actions. The founding team possesses deep experience in the infrastructure space, with backgrounds at companies like Palantir, Amazon, and Fitbit; Utpal Nadiger was also involved in launching OpenTofu, a fork of Terraform. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('89e3d05d-d4d9-4611-a73d-86cba4e98635', 'Drivetribe', 'drivetribe.com', 'http://drivetribe.com', 'https://www.linkedin.com/company/drivetribe/', 'https://app.dealroom.co/companies/drivetribe', 'Social network for motorheads', 'London', 'United Kingdom', 2016, 23, 4.5454545, 9090905, 3, 2469695, 2023, 'operational', '[{"uuid":"644677ec-1c6e-4f76-8f04-cc8ae05e4faf","name":"Richard Hammond"},{"uuid":"bf78ab3b-4d37-4009-b497-46913e66ee0b","name":"Jeremy Clarkson"},{"uuid":"283b6291-c007-46e0-87a9-5dadad6fa639","name":"James May"},{"uuid":"9adaeb18-7d2a-4f73-bf4f-2bb4d591d7ca","name":"Andy Wilman"}]', '{}', '2026-11-05T15:54:51.538Z', 'Drivetribe emerged in late 2016 from the combined vision of former "Top Gear" personalities Jeremy Clarkson, Richard Hammond, and James May, alongside serial entrepreneur Ernesto Schmitt and producer Andy Wilman. The venture was conceived as a digital hub for automotive enthusiasts, a specialized social network where users could form and join communities, or "Tribes," based on their specific motoring interests. This journey began after the founders'' departure from the BBC, creating a parallel digital venture to their new show, "The Grand Tour," on Amazon Prime. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4996a7bc-f92a-4538-b23d-9fd2610deee4', 'Duffel', 'duffel.com', 'https://duffel.com', 'https://www.linkedin.com/company/duffelhq/', 'https://app.dealroom.co/companies/duffel_1', 'Duffel is a travel-industry startup that aims to transform online travel booking', 'London', 'United Kingdom', 2017, 66, 15.789474, 77670437, 5, NULL, NULL, 'operational', '[{"uuid":"ae949a91-0685-4137-91f6-874cc1f0a6b9","name":"Vincent Pastor"},{"uuid":"fad66612-76f5-47a8-9708-579d561c623f","name":"Steve Domin"}]', '{}', '2026-11-05T15:53:18.240Z', 'Duffel is a technology-driven company that operates in the travel industry, providing a suite of application programming interfaces (APIs) that streamline the process of searching, booking, and managing flights. Its services are primarily targeted towards travel sellers, including both traditional travel agencies and non-traditional sellers like Pelikin, who are looking to diversify their revenue streams. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('ab81e00d-7326-478f-92d7-87307b288026', 'Durcal', 'durcal.com', 'https://durcal.com/es/', 'https://www.linkedin.com/company/durcal/', 'https://app.dealroom.co/companies/alpify', 'The app to take care of loved ones and ensure everyone''s safety', 'Barcelona', 'Spain', 2012, 38, 8.571428, 13383707, 9, 2803029, 2023, 'operational', '[{"uuid":"1ad2e469-1f42-470a-affd-38d61b2e7bde","name":"Guillem Viladomat"}]', '{}', '2026-11-05T15:56:04.243Z', 'Durcal is a technology company operating in the eldercare and family safety market, providing a suite of services centered around a GPS tracking application and a complementary smartwatch. Founded in 2014 by Guillem Viladomat and headquartered in Barcelona, Spain, the company aims to enhance the safety and well-being of seniors, enabling them to live more independently while offering peace of mind to their families. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3ce038b3-eef5-47b7-9265-773d1e79597c', 'EDITED', 'edited.com', 'http://www.edited.com/', 'https://www.linkedin.com/company/edited/', 'https://app.dealroom.co/companies/editd', 'AI-powered retail intelligence and analytics platform', 'London', 'United Kingdom', 2009, 193, -9.389671, 37878773, 5, 34242411, 2023, 'operational', '[{"uuid":"370ca892-2c8b-4c68-8298-715961045cd3","name":"GEOFF WATTS"}]', '{}', '2026-11-05T15:53:18.240Z', 'EDITED is a retail intelligence company that provides a data analytics software platform for brands and retailers. It was founded in 2009 by Geoff Watts and Julia Fowler. Fowler, a former fashion designer, and Watts, an entrepreneur, identified a need in the retail sector for real-time data analysis to address forecasting challenges and make more informed, data-driven decisions. The company is headquartered in London, with offices in New York and other locations worldwide.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('a6b599fa-2272-47ab-8829-0af580fa4460', 'EProspects', 'e-prospects.com', 'http://www.e-prospects.com/', 'https://www.linkedin.com/company/eprospects/', 'https://app.dealroom.co/companies/eprospects', 'An intelligent approach to delivering high quality customer leads', 'London', 'United Kingdom', 2007, 17, -15, 7954542, 1, NULL, NULL, 'operational', NULL, '{}', '2026-11-05T15:55:23.556Z', 'eProspects specializes in quality lead generation through the most effective digital channels. The company focuses on providing buyer-ready leads, eliminating the experimentation and risk typically associated with customer acquisition. By leveraging proprietary techniques and platforms, eProspects captures the attention of potential customers at the precise moment they are ready to engage with a product or service. The business operates on a pay-per-lead model, ensuring a cost-effective way to drive valuable, well-qualified leads to clients'' businesses. eProspects serves both B2C (business-to-consumer) and B2B (business-to-business) markets, consistently delivering high-quality leads that drive business growth. The company generates revenue by charging clients for each lead provided, ensuring a steady flow of hot prospects ready to buy. This model supports sustainable growth for businesses by providing a consistent supply of engaged leads, which in turn boosts sales team morale and performance.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('cdf59516-40bb-4732-92e7-fece5a6c33c6', 'Early Health', 'earlyhealth.com', 'http://earlyhealth.com', 'https://www.linkedin.com/company/early-health-limited/', 'https://app.dealroom.co/companies/early_health_2', 'Home devices for screening and early disease detection , enhancing survival rates and promoting healthier lifestyles', 'London', 'United Kingdom', 2022, 37, 54.166668, 6049586, 4, NULL, NULL, 'operational', '[{"uuid":"306de038-5521-463e-bb56-83dacdd95c52","name":"D-J Collins"}]', '{}', '2026-11-05T15:54:51.538Z', 'Early Health operates in the healthcare technology sector, focusing on the early detection of serious illnesses such as cancer, chronic kidney disease, and diabetes. The company serves individuals who seek proactive health monitoring and early diagnosis from the comfort of their homes. Early Health''s business model revolves around the development and sale of user-friendly, aesthetically pleasing medical devices that integrate seamlessly into daily routines. These devices provide critical health insights, enabling users to make timely lifestyle changes and seek prompt medical treatment, thereby improving survival rates and overall health outcomes. The company generates revenue through the direct sale of these devices and potentially through partnerships with healthcare providers and insurers. Early Health leverages cutting-edge technology and data science to create evidence-based solutions, aiming to democratize access to advanced medical diagnostics. The market it operates in includes health-conscious consumers, patients with chronic conditions, and healthcare professionals seeking reliable monitoring tools. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('6616492b-ef80-4a80-86a6-0f0e13bce0c3', 'Ecoalf', 'ecoalf.com', 'http://www.ecoalf.com', 'https://www.linkedin.com/company/ecoalf/', 'https://app.dealroom.co/companies/ecoalf', 'ECOALF is an SME that design and market high quality textile products and accessories made of recycled materials', 'Madrid', 'Spain', 2012, 226, 27.683617, 83333, 2, 38997756, 2024, 'operational', NULL, '{}', '2026-11-05T15:54:35.037Z', 'Ecoalf is a pioneering startup in the sustainable fashion industry, recognized globally for its commitment to environmental responsibility. The company operates primarily in the fashion and accessories market, targeting eco-conscious consumers who prioritize sustainability and ethical production practices. Ecoalf''s business model revolves around creating high-quality, timeless clothing and accessories using innovative and sustainable materials. This includes 100% recycled polyester and vegan padding, which eliminates the need for animal-derived materials like down and feathers.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('c8fdecc2-91ad-488f-88d8-166e57b5b387', 'Electric Playbox', 'electricplaybox.com', 'https://electricplaybox.com/', 'https://www.linkedin.com/company/immersivegamebox/', 'https://app.dealroom.co/companies/electronic_theatre', 'Delivers immersive adventures in interactive digital rooms', 'London', 'United Kingdom', 2018, 129, 14.159292, 19833330, 3, NULL, NULL, 'operational', '[{"uuid":"f5e8fb57-6efc-434d-bb3c-6cb42ce919c7","name":"Will Dean"}]', '{}', '2026-11-05T15:53:18.240Z', 'Immersive Gamebox, formerly known as Electric Playbox, is a social entertainment and gaming company founded in 2018 by Will Dean and David Spindler. Dean, who previously founded the Tough Mudder endurance events, and Spindler, who co-founded Tough Mudder Bootcamp, were inspired to create a social gaming experience that brings people together, moving away from the often isolating nature of virtual reality. The initial idea stemmed from a realization that VR headsets can create barriers to group interaction. The company launched its first venue in London in October 2019 and has since expanded significantly across the US, UK, Europe, and the UAE.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('eac9d595-9ba6-4eb6-a023-c0a834da8252', 'Electric Twin', 'electrictwin.com', 'https://electrictwin.com', 'https://www.linkedin.com/company/electric-twin/', 'https://app.dealroom.co/companies/electric_twin', 'Synthetic population design and real-time interaction tools for data-driven decision making', 'London', 'United Kingdom', 2023, 37, 208.33333, 10606056, 4, NULL, NULL, 'operational', '[{"uuid":"98748c3d-8893-4bf6-a065-e4607f9e4410","name":"Alex Cooper"},{"uuid":"7f7ee880-685a-4091-ae1b-75e7fd901f68","name":"Ben Warner"},{"uuid":"dd5fc8e3-e465-427d-802e-f97e5a08f7ba","name":"Ben W."}]', '{}', '2026-11-05T15:54:51.538Z', 'Electric Twin is a London AI platform founded in 2023 by Dr Ben Warner (former UK government digital and data adviser) and Alex Cooper (former military commander who led mass COVID testing) that builds synthetic audiences so organisations can test messaging, products and strategies in minutes. Combining survey data, LLMs, social science and machine learning, it has run tens of thousands of evaluations across 155 countries, with academic work citing roughly 95% accuracy versus traditional research; customers include The Times and Lebara. In February 2026 Electric Twin announced €12 million ($14 million) total funding including an €8.5 million ($10 million) round led by Atomico with LocalGlobe, Mercuri and Samos Investments plus angels such as Marc Andreessen and Cal Henderson, following a previously undisclosed €3.5 million ($4 million) pre-seed. Sources: EU-Startups / company 12 Feb 2026.', '["data management","database","Venture Capital","Core AI","Subscription","SaaS","marketing automation","page builders","Angel","frameworks and libraries","development","content management system","performance","risk and compliance","DT and LS","Dual-Use Tech","it infrastructure","customer data platforms","database management","uk is8 creative industries","b2b","Artificial Intelligence","content delivery network","programming languages","audio-video-graphics","miscellaneous","programming","AI Applications","governance-risk and compliance","javascript libraries","intelligence and analytics","real user monitoring","analytics","other audio-video-graphics software","security","web analytics","Marketing","uk is8 digital and technologies","application development & management","javascript frameworks","Early stage","Marketing Analytics","Deep Tech","machine learning","web tools and plugins"]', '["startup","rising_star","vc_backed","funded"]', 90.04, 5800, 0, 0, 45454527, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:54:51.538Z', 'GBP', '2026-11-05T15:54:51.538Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0ee80631-e29e-42d1-952d-ba9e10a52326', 'Electronic Theatre Controls', 'etcconnect.com', 'http://etcconnect.com', 'https://www.linkedin.com/company/electronic-theatre-controls/', 'https://app.dealroom.co/companies/electronic_theatre_controls', 'ETC - Theatre, Film, Studio and Architectural Lighting', 'London', 'United Kingdom', 1995, 1392, 7.076923, 2462120, 1, 30923542, 2024, 'operational', NULL, '{}', '2026-11-05T15:53:18.240Z', 'Electronic Theatre Controls (ETC) is a prominent manufacturer of lighting and rigging technology for entertainment and architectural applications. The company was established in 1975 in Madison, Wisconsin, by a group of University of Wisconsin-Madison students: brothers Fred and Bill Foster, Gary Bewick, and James Bradley. Their journey began with a shared belief that they could create a superior microprocessor-based lighting control console for a fraction of the cost of existing systems. This conviction led to the development of their first console, the Mega Cue, in a bedroom, which marked the inception of the company.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2cbf0ed0-532e-4df1-91d0-7371c7d0b4be', 'Elvie', 'elvie.com', 'http://www.elvie.com', 'https://www.linkedin.com/company/elvie/', 'https://app.dealroom.co/companies/elvie', 'Connected health devices for pelvic floor and breastfeeding.', 'Bristol', 'United Kingdom', 2013, 110, -19.117647, 118833624, 9, 44300000, 2023, 'operational', '[{"uuid":"9a2267b2-f888-4174-9493-27e650674075","name":"Alexander Asseily"}]', '{}', '2026-11-05T15:55:56.052Z', 'Elvie is a female-focused tech startup that operates in the health and wellness sector. The company specializes in creating smart technology products designed to empower women by harnessing their unique biology. Its primary offerings include smart breastfeeding solutions and pelvic floor trainers. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('d75521e4-7e59-465a-8dd2-ce1a0f4716b7', 'Emxys', 'emxys.com', 'http://www.emxys.com', 'https://www.linkedin.com/company/emxys/', 'https://app.dealroom.co/companies/emxys', 'An innovation-focused company specialized in the design, development, and manufacturing of advanced electronic instruments, data acquisition, and control systems for Space applications, both scientific and commercial', 'Elx', 'Spain', 2006, 18, 12.5, 1708333, 2, 245881, 2023, 'operational', '[{"uuid":"e57b4637-c990-477d-a24a-19d1383e4b67","name":"Francisco Garcia-De-Quiros"},{"uuid":"a8afad15-6c67-403d-b2d7-a785d3e2c6bd","name":"Jose A Carrasco"}]', '{}', '2026-11-05T15:55:09.655Z', 'Emxys is a technology-driven startup with over a decade of experience in developing advanced electronic systems, particularly for space environments. The company specializes in designing, developing, and manufacturing sophisticated electronic instruments, data acquisition, and control systems. These systems are used in various applications, including scientific research, commercial space ventures, biomedical engineering, and defense.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('b6c74985-8cf8-4d2d-b7a1-5e669583ba51', 'Enginy', 'enginy.ai', 'https://www.enginy.ai/?utm_source=linkedin&utm_medium=organic', 'https://www.linkedin.com/company/genesy-ai/', 'https://app.dealroom.co/companies/enginy', 'AI-powered B2B lead generation and outreach automation.', 'Barcelona', 'Spain', 2023, 92, 33.333332, 4541665, 2, 481211, 2021, 'operational', '[{"uuid":"fd7b83e5-082a-4e26-a281-959e2260ca42","name":"Kai Brandt"},{"uuid":"baa0ca55-8e3d-47a3-b341-49c0388f60c3","name":"Jaume P."},{"uuid":"fcd98fb4-4c30-4667-83d3-8834c8722a72","name":"Kai Brandt López"}]', '{}', '2026-11-05T15:56:04.243Z', 'Enginy, formerly known as Genesy, provides an artificial intelligence-driven platform for B2B lead generation and outreach automation designed for commercial teams. The company operates on a recurring subscription, enterprise software-as-a-service model. The platform enables sales professionals to create targeted lead lists, enhance them with verified company and contact information from over 30 data sources, and automate communication campaigns through email and LinkedIn. It also features an AI sales chatbot to engage and warm up prospects, aiming to make B2B sales more efficient. Founded in Barcelona, Spain, in 2022 by Kai Brandt (CEO) and Jaume Puig, the company also has an office in Madrid. Genesy serves over 150 customers, including notable clients like Canva, GoGlobal, and Taxdown. The company reports that in its first nine months, it integrated its data sources and developed an intelligent workflow system. In February 2024, Genesy raised $490,000 in a pre-seed round. This was followed by a larger seed round of €5 million (approximately $5.1 million) in January 2025, led by Samaipata with participation from existing investors Kfund and Itnig. This funding was intended to facilitate expansion into new markets such as the United States, United Kingdom, Germany, Italy, France, and the Netherlands, and to increase its workforce. Keywords: B2B lead generation, sales automation, AI sales platform, outreach automation, contact data enrichment, email automation, LinkedIn outreach, AI chatbot, sales pipeline, prospect engagement, decision-maker data, CRM quality, predictable revenue, sales productivity, Kai Brandt, Jaume Puig, Samaipata, Kfund, Itnig, sales intelligence', '["sales","Venture Capital","editors","mobile application development platforms","Core AI","Subscription","SaaS","sales enablement","marketing automation","customer relationship management","frameworks and libraries","communication and collaboration","AI Agents","b2b","Artificial Intelligence","team collaboration","programming languages","documentation tools","Breakout stage","AI Applications","customer experience management","Enterprise Software","real user monitoring","issue trackers","web analytics","Marketing","javascript frameworks","live chat","lead generation","CRM & Sales","design","ui frameworks","email marketing"]', '["startup","rising_star","vc_backed","funded"]', 89.75, 66000, 1, 1, 24999990, NULL, NULL, -455686, 2021, '[{"year":2021,"revenue":481211,"ebitda":null,"profit":-455686,"rnd":null,"valuation":null,"employees":null},{"year":2022,"revenue":481211,"ebitda":null,"profit":-455686,"rnd":null,"valuation":null,"employees":null},{"year":2023,"revenue":481211,"ebitda":null,"profit":-455686,"rnd":null,"valuation":null,"employees":3},{"year":2024,"revenue":481211,"ebitda":null,"profit":-455686,"rnd":null,"valuation":2249999,"employees":22},{"year":2025,"revenue":481211,"ebitda":null,"profit":-455686,"rnd":null,"valuation":24999990,"employees":69},{"year":2026,"revenue":481211,"ebitda":null,"profit":-455686,"rnd":null,"valuation":24999990,"employees":92}]', '2026-11-05T15:56:04.243Z', 'GBP', '2026-11-05T15:56:04.243Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('fd117f23-0c2a-4dd0-ac8f-1c1ecb0a894b', 'Equinvest', 'equinvest.es', 'https://www.equinvest.es/', 'https://www.linkedin.com/company/equinvest-spain/', 'https://app.dealroom.co/companies/equinvest_', 'Specialized distributor of equine health and wellness products', 'Villaviciosa de Odón', 'Spain', 1991, 21, 90.90909, NULL, 0, 3662091, 2023, 'operational', NULL, '{}', '2026-11-05T15:53:55.756Z', 'Equinvest, founded in 1991, is a specialized distributor of zoosanitary and pharmacological products for equine care. The company serves veterinarians, trainers, and horse owners, offering a wide range of medications, nutritional supplements, veterinary supplies, and surgical instruments. Its business model centers on the distribution of these products to a client base of over 11,000 in Spain and Portugal. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2601aa91-dee2-4c23-b5c3-544d30d2085d', 'Exoticca', 'exoticca.com', 'http://www.exoticca.com/', 'https://www.linkedin.com/company/exoticca-travel-agency/', 'https://app.dealroom.co/companies/exoticca', 'Specialized in the preparation and online distribution of trips', 'Barcelona', 'Spain', 2013, 493, 1.6494845, 90191631, 9, 166666600, 2023, 'operational', '[{"uuid":"e66e0717-7a57-42d9-b33c-cefc85695175","name":"Jesus Rodriguez Fernandez"}]', '{}', '2026-11-05T15:53:55.756Z', 'Exoticca.com is an online tour operator that specializes in designing affordable, extraordinary vacation packages. The company operates in the travel and tourism market, serving clients who are seeking unique and memorable travel experiences. Their business model is centered around leveraging innovative technology and travel expertise to offer competitive prices for incredible itineraries. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4100ae17-273d-4936-b0a5-a1de0788ae83', 'FRACTTAL', 'fracttal.com', 'https://fracttal.com', 'https://www.linkedin.com/company/fracttal/', 'https://app.dealroom.co/companies/fracttal', 'AI-powered CMMS and EAM for predictive maintenance', 'Madrid', 'Spain', 2015, 255, 20.85308, 38258318, 6, 503310, 2023, 'operational', '[{"uuid":"e05ad03d-95fe-4042-9cfc-3a3e927adbe0","name":"Fabian Mendoza"},{"uuid":"8bd5f7a0-d54b-413e-a146-5aa7c81ff2d9","name":"Gabriel Francisconi Pavão"},{"uuid":"93e48198-bb32-4f07-a0e6-d0ee960c80bf","name":"Christian Struve"}]', '{}', '2026-11-05T15:54:35.037Z', 'Fracttal provides Fracttal One, an AI-powered cloud CMMS/EAM platform for maintenance and physical asset management, combining work-order and preventive planning with IoT and Fracttal Sense sensors for predictive maintenance. Founded in 2014 by CEO Christian Struve and CTO Alejandro Pérez (initially in Chile, now headquartered in Madrid), the SaaS product serves 1,500+ clients in 60+ countries across manufacturing, utilities, healthcare and facilities, including brands such as Coca-Cola, FedEx and Unilever. In January 2026 Fracttal closed a $35 million (€29.8 million) growth round led by Riverwood Capital, with Seaya Ventures, Kayyak Ventures, GoHub and Amador Holdings, to deepen AI capabilities and expand in Brazil, Mexico, Spain and France. Sources: Riverwood / EU-Startups Jan 2026.', '["corporate","accelerator","data management","database","data security","sales","corporate learning management systems","photo galleries","human resource management system","user onboarding","hris management","Venture Capital","operations","e-commerce platforms","web fonts","recruitment marketing","editors","ad exchanges","control systems","marketing","business process management","Core AI","Subscription","SaaS","marketing automation","javascript graphics","customer relationship management","human resources","social sharing","page builders","frameworks and libraries","communication and collaboration","development","deployment","mapping and gis","testing and qa","content management system","other advertising software","job board software","online video platforms","enterprise","performance","marketing analytics","system analytics & monitoring","marketing performance measurement","software development","DT and LS","it infrastructure","web frameworks","source code management","wikis","database management","help desk management","learning management system","b2b","web platform extensions","Artificial Intelligence","tag management","it infrastructure & operations management","team collaboration","widgets","software framework","online review management","customer service","4YFN 2022","api management","content delivery network","programming languages","Neurology","Breakout stage","audio-video-graphics","advertising","customer self-service","web & portal technology","miscellaneous","programming","cloud infrastructure computing","business intelligence","governance-risk and compliance","e-commerce","dev tools","javascript libraries","wordpress plugins","intelligence and analytics","video players","Enterprise Software","real user monitoring","analytics","other audio-video-graphics software","devops","Appliances","4YFN","security","issue trackers","document management systems","operating systems & computing languages","web analytics","data integration","platform as a service","application development & management","javascript frameworks","live chat","communications technology","font scripts","IoT InternetOfThings","file sharing","social networks","blogs","applicant tracking systems","design","big data processing","ui frameworks","certificates","Deep Tech","email marketing","continuous integration","configuration management","containerization","project management","operating systems","captcha","Asset Management","maps","web tools and plugins","web hosting"]', '["startup","vc_backed","funded"]', 90.88, 380000, 1, 14, 159368118, NULL, NULL, -1701549, 2023, '[{"year":2022,"revenue":133391,"ebitda":null,"profit":-736244,"rnd":null,"valuation":24090899,"employees":160},{"year":2023,"revenue":503310,"ebitda":null,"profit":-1701549,"rnd":null,"valuation":36363622,"employees":159},{"year":2024,"revenue":503310,"ebitda":null,"profit":-1701549,"rnd":null,"valuation":36363622,"employees":190},{"year":2025,"revenue":503310,"ebitda":null,"profit":-1701549,"rnd":null,"valuation":36363622,"employees":211},{"year":2026,"revenue":503310,"ebitda":null,"profit":-1701549,"rnd":null,"valuation":159368118,"employees":255}]', '2026-11-05T15:54:35.037Z', 'GBP', '2026-11-05T15:54:35.037Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('1fccadd4-0f9c-43dc-ad18-a1e216fa6d0b', 'Factorial', 'factorial.com', 'https://factorial.com', 'https://www.linkedin.com/company/factorialai/', 'https://app.dealroom.co/companies/factorial', 'AI-powered HR, finance and IT software for SMEs', 'Barcelona', 'Spain', 2016, 3004, 25.90109, 279318070, 6, 75757545, 2025, 'operational', '[{"uuid":"c919d334-c964-4f25-9e17-fbd2536d69cb","name":"Jordi Romero"},{"uuid":"df2fe3bf-c00d-4127-acbe-589a75c210ea","name":"Bernat Farrero"}]', '{}', '2026-11-05T15:54:51.538Z', 'Factorial is a Barcelona-based business management software company for small and mid-sized businesses. Its cloud platform brings HR, finance and IT processes into one system, and its AI agent, One, works on that company data to answer questions, prepare reports, screen candidates, process expenses and handle routine requests.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('6c11220f-280f-4287-ae4e-782e4eb3b9bd', 'FarmDrop', 'farmdrop.co.uk', 'http://farmdrop.co.uk', 'https://www.linkedin.com/company/farmdrop-ltd/', 'https://app.dealroom.co/companies/farmdrop_1', 'Farmdrop - Mind-blowing groceries, delivered.', 'London', 'United Kingdom', 2012, 34, 6.25, 28674241, 7, 11822435, 2020, 'operational', '[{"uuid":"bb7b0b36-c4af-4a85-a6e7-702378367b98","name":"Ben Pugh"}]', '{}', '2026-11-05T15:54:51.538Z', 'Farmdrop was an online grocery delivery service founded in London in 2012 by Ben Pugh, with co-founders Winnie Pugh and Charles Benedict Pugh. The company''s mission was to create a more direct and equitable food supply chain by connecting consumers with local farmers and producers. Pugh, a former City broker for Morgan Stanley with a background that also included sailing and working on the Ocado stock flotation, was motivated by a passion for the environment and a dissatisfaction with the conventional supermarket system. He observed the unfair distribution of value, where producers received a small fraction of the final retail price, and aimed to build a system that provided a better deal for farmers. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('dffc0224-c470-4096-b676-566bca797a00', 'Fermat', 'fermat.app', 'https://fermat.app/', 'https://www.linkedin.com/company/batou-xyz/', 'https://app.dealroom.co/companies/fermat_1', 'Augment your creativity using Generative AI on a collaborative canvas', 'Barcelona', 'Spain', 2018, 18, 5.882353, NULL, 0, 681818, 2023, 'operational', '[{"uuid":"9a52c984-15f6-41c1-a7d0-41d109be1815","name":"Oscar C"},{"uuid":"4930eba8-5743-4ddd-a307-e4f7739254e4","name":"Oriol Roig"},{"uuid":"3c91085c-f377-476d-8578-cd1cd68bb523","name":"Pol Baladas"}]', '{}', '2026-11-05T15:53:55.756Z', 'Fermat operates as an AI-native commerce platform that enables brands to create personalized and optimized shopping experiences. Founded in November 2021 by Rishabh Jain and Shreyas Kumar, both former product and engineering executives at LiveRamp, the company is headquartered in San Francisco. The founders'' journey was influenced by Apple''s App Tracking Transparency (ATT) changes, which limited digital tracking and prompted a need for new ways to engage customers effectively.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('1ad17a33-5f5b-4f3b-a484-f179e1fd6390', 'Firenze', 'firenzeme.com', 'http://firenzeme.com', 'https://www.linkedin.com/company/firenze-group-ltd/', 'https://app.dealroom.co/companies/firenze', 'Firenze enables wealth managers, advisers & investment platforms to complete their proposition with Lombard Loans from £25k without the need to move custody', 'Manchester', 'United Kingdom', 2023, 49, 44.117645, 9249999, 3, NULL, NULL, 'operational', '[{"uuid":"63e4f2e8-210e-4235-bb54-a9cd75eddbfb","name":"David Newman"},{"uuid":"af72313a-6e19-4c7b-b689-02aff8b8309d","name":"Anna Curtis"}]', '{}', '2026-11-05T15:54:51.538Z', 'Firenze provides a platform for investment-backed loans, targeting the wealth management and advisory sectors. The company enables wealth managers, advisers, and investment platforms to offer Lombard loans to their clients.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('d7f04223-6a0a-458d-94b7-41188bbe3914', 'Flatfair', 'flatfair.co.uk', 'https://www.flatfair.co.uk/', 'https://www.linkedin.com/company/flatfair/', 'https://app.dealroom.co/companies/flatfair', 'Flatfair''s innovative products and integrations streamline operations for agents and operators, offering competitive advantages, customer choice, and increased revenue', 'London', 'United Kingdom', 2016, 46, 15, 11073330, 4, NULL, NULL, 'operational', '[{"uuid":"9a4ef997-812a-460e-8589-26ad267f4dc7","name":"Franz Doerr"}]', '{}', '2026-11-05T15:53:18.240Z', 'Flatfair is a technology company focused on revolutionizing the UK residential lettings market by offering no deposit rental solutions. The company serves a diverse clientele including letting agents, tenants, and landlords. Flatfair operates in the property rental market, providing a modern and secure way to rent properties without the traditional deposit system. The business model involves charging a membership fee and earning commissions from transactions facilitated through its platform. By eliminating the need for upfront deposits, Flatfair reduces financial strain on tenants and speeds up the rental process for landlords, making it more efficient and cost-effective for all parties involved.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('c2b4f185-c744-40d6-a614-339a1cddefd7', 'Flipflow', 'flipflow.io', 'https://Flipflow.io', 'https://www.linkedin.com/company/flipflow/', 'https://app.dealroom.co/companies/flipflow_io', 'Developing advanced market analytics to improve businesses of online retail', 'Madrid', 'Spain', 2021, 26, 44.444443, 3520832, 5, 303030, 2023, 'operational', '[{"uuid":"38b85386-709e-47fe-8492-d700a9610471","name":"Ricardo García Zorzo"},{"uuid":"856edf73-2046-4e01-b6d1-50810703c16d","name":"Ricardo García"}]', '{}', '2026-11-05T15:55:36.049Z', 'Flipflow.io is a dynamic startup operating in the e-commerce analytics sector, specifically focusing on Digital Shelf Analytics. The company provides a comprehensive control panel that delivers real-time, accurate, and actionable data to help businesses make informed decisions. Flipflow.io primarily serves brands, manufacturers, and distributors who are navigating the complexities of a globalized market where physical and online sales channels coexist.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('333c50da-527f-4e28-b543-0de466f8193a', 'Form3', 'form3.tech', 'https://form3.tech/', 'https://www.linkedin.com/company/form3-financial-cloud/', 'https://app.dealroom.co/companies/form3', 'Cloud native payments-as-a-service platform that designs, builds, and runs the technology that powers the future of payments', 'London', 'United Kingdom', 2016, 249, 8.733624, 210075674, 9, 20410556, 2025, 'operational', '[{"uuid":"3944da4a-c7d1-478f-8fce-750583348229","name":"Michael Mueller"},{"uuid":"a14a0e17-ee2a-4f43-878a-1fb02d1e3f2d","name":"Mike Walters"}]', '{}', '2026-11-05T15:56:26.553Z', 'Form3 is a fintech startup that is transforming the payments landscape with its innovative technology platform. The company operates in the financial services market, providing a managed, enterprise-grade payment technology platform that integrates with multiple payment schemes. This platform is designed to easily connect with existing payment systems, making it a versatile solution for businesses of all sizes.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('62e7c024-b16f-451a-b1e7-c50433cbd411', 'Fossa Systems', 'fossa.systems', 'https://fossa.systems/', 'https://www.linkedin.com/company/fossa-systems/', 'https://app.dealroom.co/companies/fossa_systems', 'Vertically integrated satellite manufacturing for IoT connectivity.', 'Majadahonda', 'Spain', 2018, 54, 28.571428, 14215903, 5, 832609, 2024, 'operational', '[{"uuid":"6c373e72-9287-430e-a65d-16b68aba702c","name":"Julian Fernandez"}]', '{}', '2026-11-05T15:53:55.756Z', 'Fossa Systems is a Spanish deep-tech company specializing in vertically integrated satellite manufacturing and global, low-power Internet of Things (IoT) connectivity. The company''s genesis traces back to a non-profit project started in 2018 by Julián Fernández, who at 16, launched Spain''s first picosatellite, the FOSSASAT-1, in 2019. This early initiative, which began on Reddit, aimed to democratize space access and was founded on open-source principles. Recognizing significant market demand, Fernández, along with co-founder and CTO Vicente González, officially established Fossa Systems as a private company in Madrid on July 13, 2020. The firm addresses the critical connectivity gap in the 80% of the world lacking terrestrial cellular coverage. It designs, builds, and operates its own constellation of nanosatellites in Low-Earth Orbit (LEO) to provide affordable, direct-to-device communication for industrial assets. Fossa''s business model includes offering connectivity as a Software-as-a-Service (SaaS) and providing dedicated satellites and end-to-end mission solutions for clients in government and business requiring sovereign infrastructure. This vertical integration of satellite design, manufacturing, testing, launch brokerage, and operations is a distinct capability in Europe, allowing for faster and more secure deployments. The company serves a diverse client base across sectors such as agriculture, logistics, energy, utilities, oil and gas, and national security. Its technology enables remote monitoring of assets, from tracking livestock to managing pipeline infrastructure, using low-power wide-area network (LPWAN) technologies like LoRa. Fossa has achieved significant milestones, including launching over 20 satellites since 2022 and securing a €6.3 million Series A funding round in 2024 to expand its planned 80-satellite constellation. The company has also established a collaboration with Microsoft for agricultural IoT applications. Keywords: satellite IoT, nanosatellites, picosatellites, LEO constellation, space technology, LoRaWAN, IoT connectivity, asset tracking, remote monitoring, vertical integration, satellite manufacturing, space systems, signals intelligence, SIGINT, defence, agriculture technology, logistics management, energy monitoring, oil and gas, national security, direct-to-device, M2M communications, NewSpace, aerospace, ground station, LPWAN, deep tech, satellite-as-a-service', '["accelerator","data management","servers","database","ESA","Satellites","Space Tech for Finance","NIF space","data security","Space Upstream","Space","Satellite Components","Venture Capital","web fonts","Open Source","NIF Security of Critical Technologies","Telecom","page builders","frameworks and libraries","communication and collaboration","content management system","4YFN 2024","software development","DT and LS","Dual-Use Tech","web frameworks","b2b","web platform extensions","4YFN 2023","tag management","advanced analytics and data science","widgets","web servers","search engines","software framework","4YFN 2022","programming languages","Commission","Breakout stage","audio-video-graphics","payment processing","error and exception monitoring","Manufacturing","miscellaneous","programming","governance-risk and compliance","e-commerce","office suites","javascript libraries","wordpress plugins","intelligence and analytics","Space DT","analytics","other audio-video-graphics software","4YFN 2026","4YFN","hardware","security","issue trackers","science-based","operating systems & computing languages","web analytics","data integration","Space Tech","consent management","NIF defense security and resilience","communications technology","font scripts","IoT InternetOfThings","ESA SME","blogs","4YFN 2025","Communication and Connectivity Satellites","Deep Tech","Hardware","operating systems","Space Downstream","web tools and plugins","web hosting","Defence Applications"]', '["startup","vc_backed","funded"]', 89.3, 11000, 1, 4, 46249981, NULL, NULL, -490771, 2024, '[{"year":2023,"revenue":164724,"ebitda":null,"profit":-836171,"rnd":null,"valuation":null,"employees":19},{"year":2024,"revenue":832609,"ebitda":null,"profit":-490771,"rnd":null,"valuation":31499987,"employees":31},{"year":2025,"revenue":832609,"ebitda":null,"profit":-490771,"rnd":null,"valuation":31499987,"employees":42},{"year":2026,"revenue":832609,"ebitda":null,"profit":-490771,"rnd":null,"valuation":46249981,"employees":54}]', '2026-11-05T15:53:55.756Z', 'GBP', '2026-11-05T15:53:55.756Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('a2666159-648f-4c14-9891-930bc847d040', 'Fourvenues', 'fourvenues.com', 'https://fourvenues.com', 'https://www.linkedin.com/company/fourvenues/', 'https://app.dealroom.co/companies/fourvenues', 'Develops the app to optimise VIP areas and achieve the maximum number of customers', 'Valencia', 'Spain', 2018, 136, -24.444445, 6249997, 3, 2887051, 2023, 'operational', '[{"uuid":"cd4f6587-d215-459b-ad6c-78b6eb5058d5","name":"Rubén Pérez López"},{"uuid":"2de50d6c-7851-4c01-85d5-0661eb175e26","name":"Alberto Centeno"}]', '{}', '2026-11-05T15:55:36.049Z', 'Fourvenues is a company that provides a comprehensive software solution for the management of events and venues, primarily targeting the nightlife and entertainment industry. The platform offers a range of tools to streamline operations, including online ticket sales, guest list management, VIP and table reservations, and team coordination. By integrating these functions, Fourvenues aims to enhance the efficiency and profitability of nightclubs, concert halls, and other event spaces.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('257af0ef-0b4c-499f-aa46-a17105ca98eb', 'Frekuent', 'frekuent.com', 'https://frekuent.com', 'https://www.linkedin.com/company/frekuent/', 'https://app.dealroom.co/companies/frekuent', 'Micropayment and loyalty payment platform that lets businesses accept payments through multiple channels and methods', 'Barcelona', 'Spain', 2016, 113, NULL, NULL, 0, NULL, NULL, 'operational', NULL, '{}', '2026-11-05T15:55:36.049Z', 'Frekuent is a Barcelona-based payments company that provides cashless and contactless payment solutions for unattended and self-service businesses. Its focus is on helping operators accept card, mobile and app-based payments while building repeat customer relationships through loyalty features.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('d2896c0f-b7ac-42f5-b3ee-92a019f428c4', 'Frenetic', 'frenetic.ai', 'https://frenetic.ai/', 'https://www.linkedin.com/company/frenetic-ai/', 'https://app.dealroom.co/companies/sp_control', 'Using an AI-based technology to design the optimum magnetics', 'Madrid', 'Spain', 2015, 51, -10.526316, 15245733, 7, 1549311, 2023, 'operational', '[{"uuid":"ae7a0604-9273-44e2-971e-9fc6e3af5641","name":"Chema Molina, PhD"},{"uuid":"797854e2-b373-477d-b057-0ceff5b249f7","name":"Chema Molina"}]', '{}', '2026-11-05T15:53:55.756Z', 'Frenetic, operating under Frenetic AI, presents a targeted investment opportunity within the power electronics sector, specifically addressing the niche market of magnetic components. The company was established in 2015 by a team of engineers, including Dr. Jose Maria Molina, Dr. Alfonso Martinez, and Dr. Lucas Nicieza, who identified a critical bottleneck in the design and manufacturing of custom magnetics. Their collective background in research and development within the power electronics field at institutions like Universidad Politécnica de Madrid (UPM) provided the foundational expertise for the venture. The journey began with the creation of an internal tool to expedite their own research, which later evolved into the commercial platform available today. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('32215a83-f537-46a1-86be-2d1a5a508abb', 'Frontier Health AI', 'frontierhealth.ai', 'https://frontierhealth.ai', 'https://www.linkedin.com/company/frontierhealth-ai/', 'https://app.dealroom.co/companies/frontier_health_ai', 'AI co-worker for coordination in healthcare', 'London', 'United Kingdom', 2024, 16, 1500, 12618301, 2, NULL, NULL, 'operational', '[{"uuid":"10e06ca9-721a-478e-8c4b-7fb445a7e8da","name":"Amna Askari"},{"uuid":"c8c268ca-243e-4af8-9052-ac71caed62b6","name":"Rachel Finegold"}]', '{}', '2026-11-05T15:54:51.538Z', 'Frontier Health AI builds supportive AI for healthcare administration teams. Its product Juno acts as an AI teammate that automates repetitive, high-volume coordination work across existing clinical and administrative systems so staff can keep care moving without leaving their current stack.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('1079c719-4d9f-476b-8356-2f510f68c8ed', 'Fuse Energy', 'fuseenergy.com', 'https://www.fuseenergy.com/', 'https://www.linkedin.com/company/fuseenergyhq/', 'https://app.dealroom.co/companies/fuse_energy', 'Vertically integrated renewable energy generation and supply', 'London', 'United Kingdom', 2022, 476, 115.38461, 115151469, 6, 416666500, 2026, 'operational', '[{"uuid":"d62c1e1c-d1b8-44c5-a70a-948bd63a2cf9","name":"Alan Chang"},{"uuid":"b312f8e0-e1fb-4e8a-bf96-c4b281ccfe27","name":"Charles Orr"}]', '{}', '2026-11-05T15:54:12.521Z', 'Fuse Energy is a London-based vertically integrated energy company spanning renewable generation, trading and retail supply to households and businesses. In December 2025 it raised a $70 million Series B led by Balderton Capital and Lowercarbon Capital at a reported $5 billion valuation, and in June 2026 added a further ~$30 million (€25 million) Series B extension led by 20VC and Collaborative Fund with Balderton and Lowercarbon returning. Founded in 2022 by former Revolut executives, Fuse reinvests profits into solar and wind projects while growing its UK customer base and planning expansion into Ireland, Spain and the US.', '["data management","social media marketing software","Venture Capital","operations","network hardware","web fonts","security information and event management","control systems","Energy Management System","Angel","endpoint protection","frameworks and libraries","deployment","Affordable And Clean Energy (#7)","performance","software development","it infrastructure","web frameworks","Smart Grid","b2b","Energy","advanced analytics and data science","widgets","software framework","automotive marketing","Energy Providers","programming languages","Verified Unicorns and $1B Exits","Commission","audio-video-graphics","infrastructure as a service","Manufacturing","content marketing","cloud infrastructure computing","Grid Technology","network management","dev tools","javascript libraries","Verified Thoroughbreds","intelligence and analytics","Late stage","analytics","devops","network management (software)","security","Sustainable Development Goals","Climate Tech","operating systems & computing languages","web analytics","data integration","Renewable Energy","platform as a service","javascript frameworks","communications technology","font scripts","ui frameworks","continuous integration","configuration management","containerization","operating systems","web tools and plugins"]', '["startup","thoroughbred","unicorn","vc_backed","funded"]', 94.46, 630000, 1, 41, 136363582, NULL, NULL, NULL, NULL, '[{"year":2022,"revenue":1515151,"ebitda":null,"profit":null,"rnd":null,"valuation":109848441,"employees":27},{"year":2023,"revenue":68181791,"ebitda":null,"profit":null,"rnd":null,"valuation":109848441,"employees":37},{"year":2024,"revenue":128787827,"ebitda":null,"profit":null,"rnd":null,"valuation":109848441,"employees":81},{"year":2025,"revenue":378787727,"ebitda":null,"profit":null,"rnd":null,"valuation":3787877273,"employees":221},{"year":2026,"revenue":416666500,"ebitda":null,"profit":null,"rnd":null,"valuation":136363582,"employees":476}]', '2026-11-05T15:54:12.521Z', 'GBP', '2026-11-05T15:54:12.521Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('bf058cb1-30f9-4e7f-b86d-12907110ed6c', 'Gaia', 'gaiafamily.com', 'http://gaiafamily.com', 'https://www.linkedin.com/company/gaiafamily/', 'https://app.dealroom.co/companies/gaia_1_8', 'A company supporting plans, payments and protection of IVF journeys, making IVF more accessible for more people', 'London', 'United Kingdom', 2019, 214, 43.62416, 28030292, 3, NULL, NULL, 'operational', '[{"uuid":"d4de3457-78dd-45dd-b29a-6481f1f971ec","name":"Nader Alsalim"}]', '{}', '2026-11-05T15:54:51.538Z', 'Gaia Family is a unique startup that operates in the fertility treatment market, specifically focusing on In Vitro Fertilization (IVF). The company was founded by Nader, who, after experiencing the financial burden of IVF first-hand, aimed to make the process more accessible and less financially risky for others. Gaia Family''s business model is designed to alleviate the financial stress associated with IVF. Instead of paying the full cost of the treatment upfront, clients pay a protection fee to Gaia Family, who then covers the clinic and pharmacy costs. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('6ec8d186-c8b8-41ad-ba43-1fb03246e7a2', 'Galgus', 'galgus.ai', 'https://www.galgus.ai', 'https://www.linkedin.com/company/galgus/', 'https://app.dealroom.co/companies/galgus_maximizing_wireless_performance', 'AI-powered software for WiFi network optimization and analytics', 'Camas', 'Spain', 2013, 12, -62.5, 8124997, 4, 3645674, 2023, 'operational', '[{"uuid":"a665eef9-7c5d-478e-b35e-75f596738f67","name":"Jose Ayub Gonzalez Garrido"}]', '{}', '2026-11-05T15:55:09.655Z', 'Galgus is a Spanish technology company founded in 2013 by Jose Gonzalez (CEO) and Jose Antonio Delgado (CTO). It specializes in developing software that enhances the performance of Wi-Fi networks and provides advanced location and presence analytics. The firm''s core product is the patented Cognitive Hotspot Technology (CHT), a hardware-agnostic software that can be installed on various access points (APs) to make them intelligent. This technology allows APs in a network to communicate with each other, dynamically self-configure, and optimize radio resources in real-time, which can increase Wi-Fi performance by up to 400-500%. CHT operates on a distributed intelligence model, eliminating the need for expensive centralized controllers and creating a more resilient and scalable network. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('089c2b83-dff3-4837-ad9b-59dc0cd6d01d', 'Gamelearn', 'game-learn.com', 'https://www.game-learn.com/', 'https://www.linkedin.com/company/gamestrategies/', 'https://app.dealroom.co/companies/gamelearn', 'A pioneer in corporate training solutions, being the first company to apply and create online serious games in the sector', 'Pozuelo de Alarcón', 'Spain', 2007, 99, -11.607142, 7121209, 3, 6659304, 2023, 'operational', '[{"uuid":"37902aa6-3f52-4330-9cbc-506079ffa3d7","name":"Ibrahim Jabary"}]', '{}', '2026-11-05T15:53:55.756Z', 'Gamelearn operates as a developer of a game-based learning platform tailored for corporate training. The company was established in 2007 by co-founders Ibrahim Jabary, Mai Apraiz, and Eduardo Monfort, who shared a vision of transforming the corporate training landscape. CEO Ibrahim Jabary''s background includes founding a management skills training consultancy in 2002, and he holds degrees in Economics and Psychology, along with an MBA. This prior experience in soft skills training and analytics directly informed Gamelearn''s approach to tackling the low engagement rates of traditional e-learning methods.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('299e81fa-8370-4675-b725-0e48602a3049', 'Geckoboard', 'geckoboard.com', 'https://www.geckoboard.com', 'https://www.linkedin.com/company/geckoboard/', 'https://app.dealroom.co/companies/geckoboard', 'Use Geckoboard to build clear, effective data dashboards for your business that keep teams informed, motivated and aligned around your KPIs', 'London', 'United Kingdom', 2010, 21, -19.23077, 2499999, 3, 2424241, 2023, 'operational', '[{"uuid":"d85c1403-3722-4b08-9529-77cede1fa796","name":"Paul Joyce"},{"uuid":"129cd163-c377-46d9-bff6-1dc610bfe60b","name":"Rob Hudson"}]', '{}', '2026-11-05T15:53:18.240Z', 'Geckoboard operates as a software-as-a-service (SaaS) business, providing a platform for creating real-time key performance indicator (KPI) dashboards. The company was established in 2010 by Paul Joyce, who currently serves as the CEO. Joyce''s background as an ETL developer and data warehouse builder for large financial institutions in London directly informed the company''s creation. He identified a significant disconnect between the data businesses possessed and the employees who needed it to make timely decisions, a problem he aimed to solve with Geckoboard. The journey to Geckoboard involved four years and multiple failed startup attempts before Joyce, inspired by a dashboard screenshot from the software company Panic, developed the initial concept. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('295ff3e3-d8e9-4dde-951c-2ae2a2e2a237', 'Geordie AI', 'geordie.ai', 'https://geordie.ai', 'https://www.linkedin.com/company/geordie-ai/', 'https://app.dealroom.co/companies/geordie_ai', 'Agent-native security platform for governing autonomous AI', 'London', 'United Kingdom', 2025, 68, 2166.6667, 32743399, 3, NULL, NULL, 'operational', '[{"uuid":"1ce466d3-c480-4bd5-947d-4c294576c1e4","name":"Hanah Marie Darley"},{"uuid":"499f6575-b016-4fbd-8ac1-b387f5661a6c","name":"Benji Weber"},{"uuid":"e2938fb7-bd4c-4c2f-be69-116cf06cc22d","name":"Henry Comfort"}]', '{}', '2026-11-05T15:54:12.521Z', 'Geordie AI is a London-based security and governance platform for AI agents, helping enterprises see which agents exist in their environments, what they can access, how they behave and what risks they create. Its runtime remediation suite, Beam, is designed to shape and constrain agent behaviour in real time without blocking deployment. Founded in early 2025 by a team with Darktrace and Snyk backgrounds—including CEO Henry Comfort, Hanah-Marie Darley and CTO Benji Weber—it emerged from stealth in September 2025 with a $6.5 million seed co-led by Ten Eleven Ventures and General Catalyst. In May 2026 Geordie raised a $30 million Series A (€25 million) led by Balderton Capital, with Crosspoint Capital joining and General Catalyst and Ten Eleven Ventures following on, bringing total funding to $36.5 million. Balderton partner James Wise joined the board. Proceeds support platform expansion and US go-to-market. Sources: Tech.eu 29 May 2026; Fortune 28 May 2026; EU-Startups May 2026.', '["Venture Capital","ad exchanges","Core AI","Subscription","SaaS","marketing automation","Security","frameworks and libraries","development","Generative AI","web frameworks","b2b","Artificial Intelligence","AI Security","software framework","Identity Management","Breakout stage","audio-video-graphics","advertising","Cloud & Infrastructure","javascript libraries","Public safety","other audio-video-graphics software","security","issue trackers","uk is8 digital and technologies","javascript frameworks","ui frameworks","email marketing","Woman Founder"]', '["startup","rising_star","vc_backed","funded"]', 93.49, 35000, 0, 0, 136363582, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:54:12.521Z', 'GBP', '2026-11-05T15:54:12.521Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('7e7c9359-e20b-4de0-8cc5-f21a228eb5fa', 'Get Harley', 'getharley.com', 'http://getharley.com', 'https://www.linkedin.com/company/getharley/', 'https://app.dealroom.co/companies/get_harley', 'Platform for skincare consultations', 'London', 'United Kingdom', 2019, 40, -33.333332, 50909071, 4, 7843453, 2024, 'operational', '[{"uuid":"bec6fbbf-337b-46f4-8489-f016472e4496","name":"Charmaine Chow"}]', '{}', '2026-11-05T15:53:18.240Z', 'GetHarley is a pioneering telehealth platform that connects individuals seeking skincare advice with experienced clinicians. The company operates in the burgeoning telehealth market, serving clients who require personalized skincare consultations and treatments. The business model is centered around online consultations, where clients answer a few questions about their skin and availability, and are then matched with a clinician best suited to their needs. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4233dee2-ba8a-4c6d-9691-7523df3e3e89', 'GetYourHero', 'getyourhero.com', 'http://www.getyourhero.com', 'https://www.linkedin.com/company/clintu/', 'https://app.dealroom.co/companies/getyourhero', 'Online app for booking cleaners', 'Barcelona', 'Spain', 2014, 56, 143.47826, 1499999, 2, 3257574, 2023, 'operational', '[{"uuid":"e5e27c61-79ff-42ac-83ba-5a68c843c6db","name":"Alex Espel Ribera"}]', '{}', '2026-11-05T15:54:35.037Z', 'Clintu, a Barcelona-based company founded in 2014 by Alex Espel Ribera, operates as an online marketplace for home and office services. The platform facilitates the connection between clients and a variety of service professionals. Initially focused on cleaning services, Clintu has since expanded its offerings to include moving, painting, plumbing, home renovations, and technological assistance. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('8ca1d4d3-ba4b-418f-b8e0-80b4ee58604b', 'Glasses Direct', 'glassesdirect.co.uk', 'http://www.glassesdirect.co.uk', 'https://www.linkedin.com/company/glasses-direct/', 'https://app.dealroom.co/companies/glasses_direct', 'Online prescription glasses retailer- Sub-Organization of MyOptique Group', 'Blunsdon', 'United Kingdom', 2004, 47, -7.8431373, 10000000, 1, 34616363, 2024, 'operational', NULL, '{}', '2026-11-05T15:53:18.240Z', 'Glasses Direct is an online retailer specializing in affordable eyewear, offering a wide range of stylish frames for both men and women. The company operates in the e-commerce market, targeting cost-conscious consumers who seek quality glasses at competitive prices. Customers can choose from hundreds of frames and benefit from features like free home trials and a straightforward ordering process. The business model is direct-to-consumer, eliminating the middleman to keep costs low. Revenue is generated through the sale of glasses, with additional income from premium lens options and accessories. Glasses Direct stands out with its customer-friendly policies, including free returns within 90 days and comprehensive guides to help customers find the perfect fit. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('95616111-f424-4e3a-809f-07343c495e7e', 'Goin', 'goin.app', 'https://goin.app/', 'https://www.linkedin.com/company/goinapp/', 'https://app.dealroom.co/companies/goin_1', 'Goin is the first app that allows the user to get the most out of their money without having previous knowledge in the field of finance', 'Barcelona', 'Spain', 2017, 41, 0, 6441664, 7, 2042948, 2023, 'operational', '[{"uuid":"12ce5e01-ec63-40b3-98a2-89aed3188c70","name":"Carlos Rodríguez Antón"},{"uuid":"44d46c00-1782-472e-8158-00f477237898","name":"David Riudor"}]', '{}', '2026-11-05T15:56:04.243Z', 'Goin.app is a Spanish startup that aims to revolutionize personal finance by making saving and investing effortless for its users. The company operates in the financial technology (fintech) sector, targeting individuals who find it challenging to save money or who want to optimize their savings and investments without much effort. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0c517214-fffb-48b5-9673-670e47d46259', 'Gpt Advisor Sociedad Limitada', 'finerative.com', 'https://finerative.com', 'https://www.linkedin.com/company/gptadvisor/', 'https://app.dealroom.co/companies/gpt_advisor_sociedad_limitada', 'Generative AI platform enhancing wealth management productivity with privacy and control', 'Valencia', 'Spain', 2023, 18, 50, NULL, 0, NULL, NULL, 'operational', '[{"uuid":"c195dc3a-17de-4c1d-ba7b-e54cc55ca500","name":"Nacho D Az De Argando A"}]', '{}', '2026-11-05T15:56:04.243Z', 'GPTadvisor, founded in 2023, operates within the wealth management sector, leveraging the capabilities of Generative AI to transform how investment data is managed and utilized. The platform is designed to serve wealth managers by converting complex investment product data into conversational insights, thereby eliminating the need for traditional document navigation. This service is particularly beneficial for wealth managers who aim to strengthen relationships with their investors by focusing on strategic objectives rather than administrative tasks. GPTadvisor''s business model likely involves offering its AI-driven platform as a subscription service or through licensing agreements, generating revenue by providing a tool that enhances productivity and engagement. The company positions itself as a key enabler in the wealth management industry, setting a new standard for information management and narrative creation. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('c269fd5f-4d36-45f0-beb1-ce64e7cb7d12', 'Granola', 'granola.ai', 'https://granola.ai/', 'https://www.linkedin.com/company/meetgranola/', 'https://app.dealroom.co/companies/granola_so', 'AI-powered notepad enhancing and transcribing meeting notes', 'London', 'United Kingdom', 2023, 161, 140.29851, 145643881, 4, NULL, NULL, 'operational', '[{"uuid":"62ab2e9e-a06a-4df1-a1ed-1095e68e3510","name":"Christopher Pedregal"},{"uuid":"a65a8e8f-c1f7-4291-bd2c-4890b451964f","name":"Sam Stephenson"}]', '{}', '2026-11-05T15:53:18.240Z', 'Granola is an AI-powered workspace that started as a smart notetaker and evolved into a daily tool for founders and teams. Launched in 2023 by Chris Pedregal (previously founder of Socratic, acquired by Google), Granola gained traction through word of mouth among startups and investors. It combines accurate meeting transcripts with human-editable notes, letting users capture, edit, and query all their conversations and thoughts in one place.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('ddf589a5-a748-4438-9ba5-c3ac4735523c', 'Graphext', 'graphext.com', 'http://graphext.com', 'https://www.linkedin.com/company/graphext/', 'https://app.dealroom.co/companies/graphext', 'Turning data into actionable insights Closing the gap between machine learning & visual analytics', 'Madrid', 'Spain', 2015, 14, -12.5, 11426339, 9, 211281, 2021, 'operational', '[{"uuid":"b197d97a-f5ac-4e23-93bc-3dee81822a22","name":"Miguel Cantón"},{"uuid":"00ce11b9-ee4b-414a-b9bf-7f0832171df4","name":"Victoriano Izquierdo"}]', '{}', '2026-11-05T15:56:04.243Z', 'Graphext is a forward-thinking startup that specializes in data analytics. The company aims to revolutionize the way businesses understand and utilize their data by creating user-friendly, visually appealing products. These tools allow users to explore data freely and uncover valuable insights without needing extensive technical expertise.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('662e33d9-f490-4034-86ea-e4c3b3c14164', 'Graphy', 'graphy.app', 'https://graphy.app', 'https://www.linkedin.com/company/graphyhq/', 'https://app.dealroom.co/companies/graphy', 'Create highly-visual and flexible dashboards with data from hundreds of apps', 'London', 'United Kingdom', 2018, 37, 8.823529, 7660604, 2, 2272726, 2023, 'operational', '[{"uuid":"e770f732-4801-49ac-89f2-ce02e2dca6d9","name":"Roman Sevast"},{"uuid":"a056b621-b483-44e1-8f34-6e605459c868","name":"Roman Sîrbu"},{"uuid":"97549fc6-ab2e-4a63-b212-b5faaee1f8c1","name":"Andrey Vinitsky"}]', '{}', '2026-11-05T15:55:23.556Z', 'Graphy operates as a data analytics and visualization firm, providing a platform designed to simplify how teams and individuals communicate data-driven narratives. The company was established in 2019 in London, United Kingdom, by CEO Andrey Vinitsky and Co-founder Roman Sirbu. Vinitsky, in a blog post, explained that the founding vision was to build a platform that radically improves the way people work with data after experiencing firsthand the productivity loss from grappling with data scattered across multiple services. The company secured $10.5 million in seed funding over two rounds in 2019 from investors including Northzone and Coatue. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('fa04778e-ea58-4608-adfc-023796d9267c', 'Growth Intelligence', 'growthintelligence.com', 'https://growthintelligence.com', 'https://www.linkedin.com/company/growthintelligence', 'https://app.dealroom.co/companies/growth_intelligence', 'Offering a software-as-a-service product to B2B corporations', 'London', 'United Kingdom', 2011, 34, 78.947365, 6285757, 5, 1742424, 2023, 'operational', '[{"uuid":"26399bd9-5df2-4fc9-b0c0-f32d11e19f06","name":"Thomas Gatten"}]', '{}', '2026-11-05T15:56:26.553Z', 'Established in London, United Kingdom, Growth Intelligence was founded in 2013 by Thomas Gatten and Prashant Majmudar to assist B2B corporations in identifying new sales opportunities. Gatten, the CEO, transitioned from a career in journalism to business intelligence, where he manually produced qualitative company reports before partnering with Majmudar, a software and big data engineer, to automate the process. The company operates on a software-as-a-service (SaaS) model, providing a platform that helps businesses discover sales leads. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('98e65dfb-a212-420d-b779-21118c400678', 'Harmonix', 'harmonix.ai', 'https://harmonix.ai', 'https://www.linkedin.com/company/harmonix-official/', 'https://app.dealroom.co/companies/bloobirds', 'Bloobirds | End-to-end prospecting platform for sales development teams', 'Barcelona', 'Spain', 2019, 17, -60.465115, 7916663, 4, 336635, 2023, 'operational', '[{"uuid":"fac462f1-a6e9-4453-b0c4-9b83e8b9e260","name":"Toni Cáliz"},{"uuid":"af8934e5-ff99-4faf-a5e5-63870253f424","name":"Toni Perez Navarro"},{"uuid":"2a6ec123-f8fe-42f1-8af9-81f7642691e7","name":"JAVIER LLORDEN"}]', '{}', '2026-11-05T15:56:04.243Z', 'Bloobirds is a dynamic startup that specializes in enhancing the productivity and efficiency of sales teams and service agents. The company operates in the Customer Relationship Management (CRM) and sales optimization market, providing tools that integrate seamlessly with popular CRM platforms like Salesforce and Dynamics. Bloobirds is particularly beneficial for staffing and recruitment agencies, helping them streamline their processes and improve their overall performance.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('198c7af8-4fd8-4fe2-a50b-d19a215ee8ec', 'Healx', 'healx.ai', 'https://healx.ai', 'https://www.linkedin.com/company/healx/', 'https://app.dealroom.co/companies/healx', 'AI-drug discovery accelerating treatments for rare diseases', 'Cambridge', 'United Kingdom', 2014, 72, 9.090909, 103712080, 7, 249999, 2022, 'operational', '[{"uuid":"2341b208-e0a7-4d58-9d0a-80ab71734889","name":"David Brown"},{"uuid":"c9da4736-22b9-4dcb-a06d-083337fb7ab0","name":"Tim Guilliams"}]', '{}', '2026-11-05T15:54:12.521Z', 'Healx is a pioneering company in the field of AI-driven drug discovery, focusing on developing new treatments for rare diseases. The company leverages advanced artificial intelligence to identify and accelerate the development of effective therapies for conditions that affect a small percentage of the population. Healx primarily serves patients with rare diseases, their families, and healthcare providers who are in dire need of innovative treatment options. Operating within the pharmaceutical and biotechnology markets, Healx collaborates with patient groups, research institutions, and pharmaceutical companies to expand its pipeline of potential treatments. The business model revolves around partnerships and collaborations, where Healx uses its proprietary AI technology to discover and repurpose drugs, thereby reducing the time and cost associated with traditional drug development. Revenue is generated through licensing agreements, milestone payments, and royalties from successfully developed therapies. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('1f991352-9814-4207-886a-94f39cc34496', 'HeyDiga', 'heydiga.com', 'https://heydiga.com', 'https://www.linkedin.com/company/heydigacom/', 'https://app.dealroom.co/companies/heydiga', 'AI voice agents for local business customer conversations', 'Barcelona', 'Spain', 2025, 29, 222.22223, 5416664, 3, NULL, NULL, 'operational', '[{"uuid":"a321e32a-5d8d-431a-a92b-ee302d9cda9e","name":"David Zafra"},{"uuid":"2d5e12bd-2219-4955-8fff-bad2ee1e0db7","name":"Sergio Espeja"}]', '{}', '2026-11-05T15:56:04.243Z', 'HeyDiga is a Barcelona conversational AI company founded by Sergio Espeja (ex-Jobandtalent CTO) and David Zafra that builds voice agents for local businesses—handling phone and WhatsApp customer conversations for restaurants, workshops, clinics, real estate and salons at scale. The platform manages hundreds of thousands of calls monthly for hundreds of businesses, with modular vertical solutions for appointments, no-show reduction and lead recovery under GDPR. After a €1 million seed led by KFund in December 2025 (with Jobandtalent founders among angels), in September 2026 HeyDiga raised €5.5 million led by 6 Degrees Capital, with KFund, Italian Founders Fund, Decelera and angels, to expand its AI conversation layer for local businesses. Sources: StartupMafia 12 Sep 2026.', '["accelerator","data security","photo galleries","Venture Capital","web fonts","SaaS","Angel","frameworks and libraries","development","Generative AI","content management system","it infrastructure","web frameworks","b2b","genAI Ap