INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2468233b-3832-41c6-bc85-1c67a3bcc099', 'Hook', 'hook.co', 'http://hook.co', 'https://www.linkedin.com/company/hook-technology/', 'https://app.dealroom.co/companies/hook_1_6', 'Uses data science to predict customer revenue growth, identify high-value customers, and maximize revenue through retention strategies', 'London', 'United Kingdom', 2020, 74, -2.631579, 10798484, 2, 1666666, 2023, 'operational', '[{"uuid":"a5076bd3-2e88-4f1c-b84d-b8c1b59e7071","name":"Firaas Rashid"}]', '{}', '2026-11-05T15:54:12.521Z', 'Hook.co is a startup that leverages artificial intelligence (AI) to help businesses identify their most valuable customers and strategize on how to retain them and maximize revenue. The company primarily serves Software as a Service (SaaS) companies, operating in the technology market. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('c6e98581-9486-48a9-a7f9-76831a9b95a9', 'Housfy', 'housfy.com', 'https://housfy.com/', 'https://www.linkedin.com/company/housfy/', 'https://app.dealroom.co/companies/housfy', 'The digital alternative to any home service', 'Barcelona', 'Spain', 2016, 344, 14.666667, 43916649, 8, 37499985, 2025, 'operational', '[{"uuid":"cc285131-9d87-4e5b-8674-30a01fee24a2","name":"Miquel A. Mora"},{"uuid":"ee34d183-6f9a-4b52-a1c0-e74319fa36ed","name":"Albert Bosch"},{"uuid":"f4ecd41c-866d-48b7-9646-31ac5429292d","name":"Carlos Blanco"}]', '{}', '2026-11-05T15:54:35.037Z', 'Housfy is a digital platform that has transformed the traditional real estate model in Spain. The company provides a comprehensive ecosystem of home services, enabling individuals to buy and sell properties without the need for traditional real estate agencies, thus eliminating intermediaries and commissions. This model significantly reduces the costs associated with property transactions for consumers.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('5aaa6688-898c-47cb-91ae-4e391181d320', 'HungryPanda', 'hungrypanda.co', 'http://hungrypanda.co', 'https://www.linkedin.com/company/hungrypanda-ltd/', 'https://app.dealroom.co/companies/hungrypanda', 'HungryPanda is the global leader in delivering Chinese food and groceries with the extensive market coverage, highest user traffic as well as annual transaction volumes', 'London', 'United Kingdom', 2016, 684, 3.6363637, 208333250, 4, 159447124, 2025, 'operational', '[{"uuid":"c893aac2-cda6-4ee1-98bd-049bebae6555","name":"Eric DU"},{"uuid":"5cb2c8ad-584f-4792-b9a8-385c5bbcc377","name":"Eric LIU"}]', '{}', '2026-11-05T15:56:26.553Z', 'HungryPanda is a food and grocery delivery platform that specializes in serving Asian communities living abroad. Founded in 2017 by Kelu “Eric” Liu, the company was born from his personal experience as a computer science student at the University of Nottingham, UK. Liu identified a gap in the market, recognizing the difficulty overseas Chinese students and expatriates faced in finding authentic Asian cuisine and navigating English-only platforms. What started as a student project to solve this problem has expanded into a global operation. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('cd1881d4-29da-4c0f-82f3-0286ef490ce9', 'IMU Biosciences', 'imubiosciences.com', 'https://www.imubiosciences.com/', 'https://www.linkedin.com/company/imubiosciences/', 'https://app.dealroom.co/companies/imu_1', 'AI immune-profiling platform CytAtlas for precision medicine', 'London', 'United Kingdom', 2019, 85, 23.188406, 51500000, 4, 2348484, 2023, 'operational', '[{"uuid":"441c6565-bbdc-4f29-ab20-6ed97a07727d","name":"Tom Hayday"},{"uuid":"b16462c8-e0a5-4713-815d-b587b6fa1a44","name":"Anna Cederberg"},{"uuid":"29bd38e1-8c2e-4e1e-8b75-ce854df5b0ac","name":"Mario Cantero"},{"uuid":"3554a648-10da-47a8-89a2-8a45c73e5cef","name":"Adam Laing"}]', '{}', '2026-11-05T15:56:04.243Z', 'IMU Biosciences is a UK biotechnology company founded in 2021 by Dr Adam Laing, Dr Tom Hayday and Mario Cantero that builds CytAtlas, an AI-powered systems immune-profiling platform rooted in research from King’s College London and the Francis Crick Institute. From a small blood sample CytAtlas analyses vast immune datasets to quantify thousands of cell subsets for applications in immuno-oncology, cell therapy, autoimmune disease and transplantation, and IMU participates in the UK MANIFEST cancer-immunotherapy consortium. After an earlier £11.5 million Series A tranche in January 2024 led by Molten Ventures, in June 2026 IMU announced an oversubscribed financing that brought its Series A to over $53 million (about £40 million), co-led by IQ Capital and Molten Ventures with the British Business Bank, Meltwind and existing investors, taking total funding to about $60 million to expand operations, clinical-platform infrastructure and programs in transplantation and cancer immunotherapy. Sources: company/British Business Bank Jun 2026; Fierce Biotech; BioXconomy.', '["Health Platform","data management","database","data security","Biotechnology","Venture Capital","BioTechnology","Core AI","SaaS","Oncology","communication and collaboration","deployment","electronic health records","UKis Digital and technologies","risk and compliance","software development","DT and LS","Immune System","open source","database management","data warehousing","b2b","Precision Medicine","Artificial Intelligence","advanced analytics and data science","rio ai health","uk is8 life sciences","programming languages","Commission","Breakout stage","AI Applications","Spinout","cloud infrastructure computing","governance-risk and compliance","Longevity","javascript libraries","uk rio","devops","science-based","data integration","uk is8 digital and technologies","Health","b2c","application development & management","web design and development services","Cell Therapy","design","big data processing","ui frameworks","certificates","continuous integration","configuration management","Machine Learning","machine learning","Digital Pharma","Woman Founder","rio AI health life sciences"]', '["startup","spinout","vc_backed","funded"]', 86.43, 2000, 1, 2, 240000000, NULL, NULL, NULL, NULL, '[{"year":2023,"revenue":2348484,"ebitda":null,"profit":null,"rnd":null,"valuation":null,"employees":62},{"year":2024,"revenue":2348484,"ebitda":null,"profit":null,"rnd":null,"valuation":69000000,"employees":44},{"year":2025,"revenue":2348484,"ebitda":null,"profit":null,"rnd":null,"valuation":69000000,"employees":69},{"year":2026,"revenue":2348484,"ebitda":null,"profit":null,"rnd":null,"valuation":240000000,"employees":85}]', '2026-11-05T15:56:04.243Z', 'GBP', '2026-11-05T15:56:04.243Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('1d815b13-f0a3-4845-a555-d546aba92e7a', 'Iconic', 'iconicgames.io', 'https://iconicgames.io', 'https://www.linkedin.com/company/iconic-games/', 'https://app.dealroom.co/companies/iconic_ai', 'The world’s first AI-native AAA game factory', 'London', 'United Kingdom', 2023, 31, 14.814815, 12878783, 2, NULL, NULL, 'operational', '[{"uuid":"007a5c9c-6c59-47e1-a882-579349d53232","name":"Andrew Bowell"},{"uuid":"c88483ab-d92d-41b3-813a-cb8595f2e76c","name":"Borja González León"},{"uuid":"90c371c7-8d6a-4d3b-b9b3-3dd06fd4e361","name":"Mikel Bober-Irizar"},{"uuid":"bd3576bd-43d0-4d73-96d5-c0c42296a811","name":"Johnny Venables"},{"uuid":"4a55ecd8-6f23-44f0-9657-47beaae913f8","name":"Martin Connor"}]', '{}', '2026-11-05T15:54:51.538Z', 'Iconic Games is a pioneering studio in the AAA gaming industry, focusing on the integration of advanced AI and generative animation to create immersive gaming experiences. The company serves a diverse clientele, including gaming enthusiasts and industry professionals, by developing high-quality games that push the boundaries of traditional gameplay. Operating in the competitive gaming market, Iconic Games employs a business model centered around game development and sales, leveraging the expertise of a team with extensive backgrounds in top gaming studios and AI research. Revenue is generated through the sale of games and potential partnerships with other industry leaders. The team comprises seasoned professionals with experience at companies like Apple, Sony AI, and Rockstar North, bringing a wealth of knowledge in computer science and machine learning to the table. Iconic Games is poised to make a significant impact in the gaming world by offering products that combine technical excellence with creative storytelling.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('ed3933ff-30ef-40e9-a1ec-590c9032f608', 'Idoven', 'idoven.ai', 'http://idoven.ai', 'https://www.linkedin.com/company/idoven/', 'https://app.dealroom.co/companies/idoven', 'AI-powered platform for rapid, accurate electrocardiogram analysis', 'Majadahonda', 'Spain', 2018, 60, -16.666666, 15553024, 12, 267443, 2023, 'operational', '[{"uuid":"276c0832-4203-406a-9e90-f0ac88c65bae","name":"Manuel Marina Breysse"},{"uuid":"55459753-a11f-467a-9e21-005e4be9b439","name":"José María Lillo Castellano"},{"uuid":"61719c08-5a8b-4965-ae49-642eaf3ee7f5","name":"Inigo juantegui"}]', '{}', '2026-11-05T15:55:23.556Z', 'Idoven is a health technology company focused on preventing cardiovascular disease through early detection and precision medicine. The company was founded in Madrid in 2018 by cardiologist Dr. Manuel Marina Breysse, serial entrepreneur Iñigo Juantegui, and machine learning scientist José María Lillo Castellano. The founding was the culmination of nearly a decade of research in cardiology and machine learning at Spain''s National Center for Cardiovascular Research (CNIC). Dr. Marina''s background as a sports cardiologist for elite Spanish athletes and his research in cardiac arrhythmias, combined with Lillo Castellano''s expertise in machine learning and data analytics, formed the company''s scientific foundation. Juantegui brought extensive entrepreneurial experience, having previously co-founded and sold the successful food delivery startup La Nevera Roja. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('9696e727-aa85-4f83-8ad9-c057aeb4f731', 'Imperia', 'imperiascm.com', 'http://imperiascm.com', 'https://www.linkedin.com/company/imperia-scm/', 'https://app.dealroom.co/companies/imperia_1', 'Focused on the management and optimization of the demand planning and forecasting process', 'Valencia', 'Spain', 2019, 124, 13.761468, 11086367, 4, 379591, 2023, 'operational', '[{"uuid":"e986bacc-28fb-4feb-9442-79b1a7c91fd8","name":"José Tomás Carrascoso"},{"uuid":"d8f133e1-2854-4a16-bd97-b5b438a21951","name":"Sergio Alemany"},{"uuid":"1838ae18-e2c3-4c73-992e-c933b6a97a62","name":"Alvaro Bernabe"}]', '{}', '2026-11-05T15:55:36.049Z', 'Imperia SCM is a software company that offers a comprehensive solution for supply chain management. The company''s software is designed to simplify and optimize demand planning, production, and purchasing processes. The software is user-friendly and designed to be a tool that the entire team will want to use. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('73a38bf9-f07e-4884-b7a3-c757a5588736', 'Inbiomotion', 'inbiomotion.com', 'http://inbiomotion.com', 'https://www.linkedin.com/company/inbiomotion-sl/', 'https://app.dealroom.co/companies/inbiomotion', 'A personalized medicine company developing biomarkers that can predict bone metastasis in cancers', 'Barcelona', 'Spain', 2010, 12, 9.090909, 3678029, 6, 57442, 2023, 'operational', '[{"uuid":"8d2c5551-5dca-4b3e-a08a-c4fc75400d8a","name":"Anna Farriol"},{"uuid":"8bc762ae-777e-47a3-9669-83f3939dfb6f","name":"Anna Bosch Comas"},{"uuid":"1538a74a-dff0-4292-8920-e2dc14c10bf7","name":"Roger Gomis"}]', '{}', '2026-11-05T15:53:12.600Z', 'Inbiomotion SL, a spin-off from the Institució Catalana de Recerca i Estudis Avançats (ICREA) and the Institut d''Investigació Biomèdica (IRB Barcelona), was established in Barcelona, Spain in 2011. The company operates in the biotechnology sector, focusing on the development of a diagnostic test to guide treatment for breast cancer patients. Its foundation is built upon the research of its founder, Dr. Roger Gomis. His work at the IRB Barcelona centered on understanding the mechanisms of cancer metastasis, specifically identifying the MAF (mesenchymal-epithelial transition activating factor) gene''s role in predicting which early-stage breast cancer patients are at a higher risk of relapse and bone metastasis. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2a32131d-51da-4872-a66d-ebfd64ef76ae', 'Indexa Capital', 'indexacapital.com', 'https://indexacapital.com/', 'https://www.linkedin.com/company/indexa-capital/', 'https://app.dealroom.co/companies/indexa_capital', 'Provides investment and portfolio management services', 'Madrid', 'Spain', 2015, 65, 6.557377, 2166666, 3, 1962120, 2023, 'operational', '[{"uuid":"dbcc74b4-9b97-44b6-961e-cbfc8b1a9cd2","name":"François Derbaix"},{"uuid":"f86eaa96-74fd-4e4f-890b-beb501aa33ae","name":"Unai Ansejo"},{"uuid":"9f3e984f-5041-47c7-9f37-19502a390e36","name":"Ramón Blanco"}]', '{}', '2026-11-05T15:55:36.049Z', 'Indexa Capital Group stands as an automated investment manager, established in 2015 by co-founders Unai Ansejo, François Derbaix, and Ramón Blanco. The firm operates primarily in Spain, launching in Belgium in 2020 and France in 2023. The founders brought together a diverse skill set; Ansejo has a Ph.D. in Quantitative Economics and experience as a fund manager, Derbaix is a serial internet entrepreneur with successful exits like Toprural and Rentalia, and Blanco has a background in business and law with an MBA from Harvard, along with experience founding Selfbank. This collective expertise in finance, investment, and digital ventures shaped Indexa''s foundation. The initial idea stemmed from a plan to create a secondary market for startups, which later evolved into the automated investment service after observing the success of robo-advisors in the United States. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('752d085b-1c1d-4bc8-8e2e-f09459aebedb', 'Ineffable Intelligence', 'ineffable.ai', 'https://www.ineffable.ai/', 'https://www.linkedin.com/company/ineffable-intelligence/', 'https://app.dealroom.co/companies/ineffable_intelligence', 'Post-LLM research advancing general artificial intelligence', 'London', 'United Kingdom', 2025, 27, NULL, 833333000, 2, NULL, NULL, 'operational', '[{"uuid":"bed2d4c1-0d21-4e21-aa1e-3c30f4c045a6","name":"Chris Apps"},{"uuid":"6a5760d8-0e13-40d6-a269-7473ebca514b","name":"Alexandre Laterre"},{"uuid":"8250f1b9-5970-412a-a2c1-289d4340195c","name":"Lasse Espeholt"},{"uuid":"276102b6-60d0-403e-947b-775bd5614cbe","name":"Wojciech Czarnecki"},{"uuid":"884d69d5-2b93-49b2-94ea-7a50d5b5b4ee","name":"Junhyuk Oh"}]', '{}', '2026-11-05T15:53:18.240Z', 'Ineffable Intelligence is a London-based artificial intelligence research lab founded in late 2025 by David Silver, the former DeepMind reinforcement-learning lead behind AlphaGo and AlphaZero. Rather than building large language models trained on human-generated text, the company is pursuing reinforcement learning as its core approach, aiming to develop "superlearners" capable of discovering knowledge and skills from their own experience. The lab emerged from stealth in April 2026 with a $1.1 billion seed round, one of the largest in European history, backed by Sequoia Capital, Lightspeed Venture Partners, Nvidia, Google, Index Ventures and the UK''s Sovereign AI Fund, valuing the company at $5.1 billion. Ineffable positions itself within the broader race toward artificial general intelligence, distinguishing its research bet on experience-based learning from the data-centric approaches used by most leading AI labs.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('9f926581-2450-40e5-b36c-06ffdd154673', 'InfiniteWatch', 'infinitewatch.ai', 'https://www.infinitewatch.ai/', 'https://www.linkedin.com/company/infinitewatch-ai/', 'https://app.dealroom.co/companies/infinitewatch', 'AI observability platform for customer interaction intelligence', 'Madrid', 'Spain', 2025, 10, NULL, 3030302, 1, NULL, NULL, 'operational', '[{"uuid":"67304512-00a2-4059-a456-a7b253ebcaf7","name":"Alberto González Lizán"},{"uuid":"f1606be3-9f51-43f8-839c-7c7da64ff358","name":"Pablo Molina Candel"},{"uuid":"bb4f6165-0240-4571-afa7-440b31e50fc3","name":"Inaki Berenguer"}]', '{}', '2026-11-05T15:53:55.756Z', 'InfiniteWatch is an AI-native platform providing customer interaction intelligence, which emerged from stealth in December 2025 with $4 million in pre-seed funding. The funding round was led by Base10 Partners, with participation from Sequoia and A16Z scouts, Kibo Ventures, Kfund, LifeX, and several unicorn founders. The capital is intended to scale the AI observability platform, expand agent capabilities, and accelerate product development and go-to-market efforts. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('106d40e4-e144-4bcd-bff6-9deb628fd4a0', 'Inherent', 'inherentlabs.ai', 'https://inherentlabs.ai/', 'https://www.linkedin.com/company/inherent-laboratories/', 'https://app.dealroom.co/companies/inherent', 'Recursively self-improving AI lab for scientific discovery', 'London', 'United Kingdom', 2025, 18, NULL, 37878773, 1, NULL, NULL, 'operational', '[{"uuid":"cc7672a5-d30f-4908-aaad-0a2449e24eec","name":"Edward Hughes"},{"uuid":"59dead24-c514-4760-a567-80a36e8ec371","name":"Louis Kirsch"},{"uuid":"76d8228e-7da6-4cff-988d-d148bf5bd476","name":"Tantum Collins"},{"uuid":"b407527d-1435-44f5-8aa4-df2b9e53abdb","name":"Kaloyan Aleksiev"}]', '{}', '2026-11-05T15:53:18.240Z', 'Inherent (Inherent Labs) is a London Public Benefit Corporation AI lab building Faraday, a system for human-led scientific curiosity combined with recursively self-improving algorithmic exploration — aiming to write a playbook for AI-native science rather than plug AI into traditional methods alone. Co-founders include Tantum Collins, Edward Hughes and Louis Kirsch (DeepMind alumni; Collins also worked on AI policy at the White House under President Biden) and Kaloyan Aleksiev (Reka AI / Microsoft); Matt Clifford advises. Operating as an independent deep-tech research entity, Inherent directs capital to foundational research, compute and human–machine discovery paradigms rather than immediate SaaS monetisation. Emerging from stealth in May 2026, Inherent raised a $50 million seed co-led by Index Ventures and Radical Ventures. Sources: Tech.eu 29 May 2026; inherentlabs.ai.', '["Venture Capital","recruitment marketing","genAI Model Maker","BioTechnology","Core AI","Subscription","SaaS","human resources","frameworks and libraries","Generative AI","content management system","DT and LS","b2b","genAI Applications","Artificial Intelligence","rio ai health","out of stealth","uk is8 life sciences","content delivery network","programming languages","Breakout stage","infrastructure as a service","web & portal technology","programming","caching","cloud infrastructure computing","Novel AI","Enterprise Software","devops","science-based","operating systems & computing languages","AI Model Maker","platform as a service","uk is8 digital and technologies","Health","javascript frameworks","applicant tracking systems","Deep Tech","configuration management","ai model layer","machine learning","containerization","operating systems"]', '["startup","rising_star","vc_backed","funded"]', 90.98, 21000, 1, 1, 227272636, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:53:18.240Z', 'GBP', '2026-11-05T15:53:18.240Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('8a637f13-c57f-4e06-b8dd-90b14eda8f87', 'Innovamat', 'innovamat.es', 'http://innovamat.es/', 'https://www.linkedin.com/company/innovamat-education/', 'https://app.dealroom.co/companies/innovamat', 'Proposals for manipulative approaches to mathematics, created by experts and professors in didactics. Mathematics in Elementary School and Early Years. The K-12 Math Curriculum that teachers and students love! ', 'Barcelona', 'Spain', 2017, 384, 11.627907, 17274993, 4, 12116028, 2023, 'operational', '[{"uuid":"4107cf4a-eb23-4d79-b641-9e4ae8a5af29","name":"Isaac Sayol Piedra"},{"uuid":"4452d236-1512-4ed3-ad50-d0498c3f687b","name":"Andreu Dotti Boada"}]', '{}', '2026-11-05T15:53:55.756Z', 'Innovamat is an educational technology company that has developed a platform aimed at transforming mathematics education for students from early childhood through secondary school. The firm was established in 2017 by a team with diverse and relevant backgrounds: Isaac Sayol, a mathematician and data scientist; Alex Coba, a computer scientist and entrepreneur; and Cecilia Bosch, a primary school teacher and mathematics specialist. This blend of expertise in mathematics, technology, and pedagogy forms the foundation of the company''s approach. The venture originated from the founders'' shared concern over traditional, memorization-based math teaching methods and a desire to make the subject more engaging and conceptually understandable for students. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('c939a947-2ab3-4281-bce5-e56e4e9dacd6', 'Insurama', 'insurama.com', 'https://insurama.com', 'https://www.linkedin.com/company/insurama/', 'https://app.dealroom.co/companies/insurama', 'Hub of digital products and services for the insurance industry', 'Madrid', 'Spain', 2018, 80, 6.6666665, 12916661, 3, 4202959, 2024, 'operational', '[{"uuid":"724eeadc-5001-44d3-8057-3a68d3ff5e5e","name":"Juancho C"},{"uuid":"951a7840-5daa-4880-82a1-4d92d68e5f41","name":"Sergio Balsa Pardo"}]', '{}', '2026-11-05T15:55:36.049Z', 'Founded in 2018, Insurama operates as a Managing General Agent (MGA) in the insurtech sector, headquartered in Madrid, Spain. The company was established by Sergio Balsa Pardo. Insurama functions as a digital hub for insurance products and services, focusing on the online, end-to-end distribution and management of insurance solutions. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('d8254e80-4df3-472f-a225-c2bc70cc5387', 'Intelex Vision', 'intelexvision.com', 'http://intelexvision.com', 'https://www.linkedin.com/company/intelexvision/', 'https://app.dealroom.co/companies/intelex_vision', 'InteleXVision – Ultra Smart AI Solutions', 'Chatham', 'United Kingdom', 2017, 58, 3.5714285, 8100000, 2, NULL, NULL, 'operational', '[{"uuid":"348973d7-af70-4616-9186-efda687a3b98","name":"Callum Wilson"}]', '{}', '2026-11-05T15:55:36.049Z', 'IntelexVision operates in the security and surveillance industry, providing advanced AI-driven video analytics solutions. Their core product, iSentry, is designed to analyze thousands of CCTV cameras in real-time, delivering actionable insights and video alerts to control room operators through an intuitive online interface. This technology automates the constant monitoring that human operators cannot sustain, allowing them to focus on critical incidents using their intuition and experience. IntelexVision serves clients in sectors requiring extensive surveillance, such as urban security, transportation hubs, and critical infrastructure. The company generates revenue through a subscription-based model, offering its software as a service (SaaS) to organizations seeking to enhance their security operations. By leveraging AI to autonomously monitor and interpret vast amounts of video footage, IntelexVision helps clients mitigate risks and improve response times to potential threats.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4cd5689e-e8a0-4c11-98ed-13280b55b982', 'Iqana', 'iqana.io', 'http://iqana.io', 'https://www.linkedin.com/company/iqana/', 'https://app.dealroom.co/companies/iqana', 'Data-driven crypto solutions leveraging cloud and machine learning for strategic market advantage', 'Barcelona', 'Spain', 2022, 16, 166.66667, 1374999, 2, NULL, NULL, 'operational', '[{"uuid":"fd04f600-1730-42c2-816a-104d19958536","name":"Ignasi Salat Margarit"},{"uuid":"566540fe-fe12-4a07-b86c-ae6a185fa139","name":"Albert Ventura-Traveset"},{"uuid":"9fd79529-753d-4b86-a644-b86d81f1df8c","name":"François Centeno Lemaire"},{"uuid":"54cdab00-5a21-4a1b-a12c-dd6c4864677a","name":"Quim Allard"}]', '{}', '2026-11-05T15:56:04.243Z', 'Iqana operates in the cryptocurrency market, providing data-driven solutions that simplify crypto investments through advanced technology. The company integrates cloud computing, big data, and machine learning to offer strategic advantages in capitalizing on market movements without the need for constant oversight. Iqana serves investors and institutions interested in the thriving crypto ecosystem, utilizing quantitative expertise to enhance decision-making processes. The business model focuses on delivering software solutions that empower clients to navigate the complex crypto landscape effectively. Revenue is generated through the provision of these cutting-edge tools and services, which are designed to optimize investment strategies and ensure compliance with top-tier cybersecurity standards. Iqana''s team brings diverse backgrounds in global strategy, software development, and critical operations management, positioning the company as a trusted partner in the crypto journey. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('27a8978e-3fa9-46f5-862d-c73344d5a8b9', 'Ironhack', 'ironhack.com', 'https://www.ironhack.com/en', 'https://www.linkedin.com/school/ironhack/', 'https://app.dealroom.co/companies/ironhack', 'An international tech school that offers intensive courses and bootcamps', 'Madrid', 'Spain', 2013, 343, -27.33051, 20546962, 4, NULL, NULL, 'operational', '[{"uuid":"03cfa5e3-1aa4-4778-b383-f5769abe7851","name":"Gonzalo Manrique"},{"uuid":"7b439f5b-2096-49f4-8c2e-5e49074183ba","name":"Ariel Quinones"}]', '{}', '2026-11-05T15:55:36.049Z', 'Ironhack operates as a global technology education company, offering intensive bootcamps in high-demand digital skills such as Web Development, UX/UI Design, Data Analytics, and Cybersecurity. Founded in 2013 by Gonzalo Manrique and Ariel Quiñones, the company emerged from their shared vision to bridge the growing technology skills gap they observed after their experiences at Wharton and Harvard Business School, respectively. Their backgrounds in finance and business consulting provided a strategic foundation for building a scalable educational model focused on career transformation.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('ae604132-5bfe-4435-bdfd-33f9ea684208', 'Jitty', 'jitty.com', 'http://jitty.com', 'https://www.linkedin.com/company/jittyhomes/', 'https://app.dealroom.co/companies/jitty', 'Search engine for finding houses', 'London', 'United Kingdom', 2023, 13, -18.75, 4393938, 2, NULL, NULL, 'operational', '[{"uuid":"32ebcb67-82fd-4ad2-81ad-6ad243b0ab11","name":"James Storer"},{"uuid":"aba07764-ae1d-4e23-ba02-d111cbe66fdc","name":"Graham Paterson"},{"uuid":"78e218e6-618b-4852-bf6f-b624c4c60956","name":"Daniel Cooper"}]', '{}', '2026-11-05T15:54:51.538Z', 'Jitty operates an AI-powered property search platform aimed at simplifying the home-buying process for residents in the United Kingdom. The company was established in London in 2023 by Graham Paterson, James Storer, and Daniel Cooper. The founding trio, all former early-stage employees at Deliveroo, were motivated by their own frustrating and stressful home-buying experiences, which they found to be archaic compared to the seamless digital experiences they were accustomed to building for consumer tech products. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('97aa2407-d21f-40f0-b5ce-058438cd5f6e', 'Job&Talent', 'jobandtalent.com', 'http://www.jobandtalent.com', 'https://www.linkedin.com/company/jobandtalent/', 'https://app.dealroom.co/companies/jobandtalent', 'AI-powered workforce platform for essential industries.', 'Madrid', 'Spain', 2009, 4028, 2.7813218, 937272416, 14, 1499999400, 2024, 'operational', '[{"uuid":"693d1e14-c7aa-4c5e-abf6-bdc841dadf71","name":"Felipe Navío García"},{"uuid":"52b7c3c0-4fc4-4b4f-9977-2a1b9712b94d","name":"Juan Urdiales"},{"uuid":"fcdb0d3d-f784-4a91-a1eb-e62f435b3ecc","name":"Felipe Navio"}]', '{}', '2026-11-05T15:53:55.756Z', 'Jobandtalent is a Madrid-based technology company specializing in digital temporary staffing solutions. Founded in 2009, it operates a global “workforce as a service” marketplace that connects companies with pre-screened hourly and temporary workers across sectors such as logistics, manufacturing, retail, and hospitality. The platform leverages advanced machine learning and AI-driven algorithms to efficiently match job seekers with suitable roles, streamlining the recruitment process for both employers and candidates.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('bd22434e-e786-4cd4-9782-8adc30b35dc9', 'Josh Wood Colour', 'joshwoodcolour.com', 'https://joshwoodcolour.com/', 'https://www.linkedin.com/company/josh-wood-colour-limited/', 'https://app.dealroom.co/companies/josh_wood_colour', 'Josh Wood Colour is a European beauty brand', 'London', 'United Kingdom', 2018, 40, 0, 4916665, 1, 5712119, 2023, 'operational', '[{"uuid":"f13f3926-6bfa-44f8-b813-254b1583a3d4","name":"Josh Wood"},{"uuid":"2e710579-4e17-4bb9-a3d3-98b19ee9688f","name":"Jonathan Davies"}]', '{}', '2026-11-05T15:53:18.240Z', 'Josh Wood Colour, founded in 2011 by the renowned hair colourist Josh Wood, is a London-based company that has carved a niche in the beauty industry with its expert-led approach to at-home hair colour. Wood, a prominent figure in the fashion and beauty world with over 30 years of experience, translated his expertise from the salon to a direct-to-consumer model. His journey began with a vision to provide high-quality, personalized hair colour solutions that could be used at home, a venture that was significantly influenced by his extensive work with celebrity clients and major fashion houses like Alexander McQueen.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f7ed0236-f9ff-4beb-81bd-9f47180e4877', 'Jotelulu', 'plenit.com', 'https://plenit.com', 'https://www.linkedin.com/company/jotelulu/', 'https://app.dealroom.co/companies/jotelulu', 'A simple platform, with specific cloud services for SMEs at an affordable price', 'Madrid', 'Spain', 2013, 119, 2.586207, 9833329, 3, 2319373, 2023, 'operational', '[{"uuid":"5a539acf-2cf5-45ad-8bdb-cd8a221ea65e","name":"David Amorín"}]', '{}', '2026-11-05T15:53:55.756Z', 'Cloud platform for IT companies to become cloud service providers, centralizing management and automating processes.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('7af4ba2b-a44f-4caa-b311-c9c304bbd49a', 'Just-Eat.com', 'justeat.com', 'http://justeat.com', 'https://www.linkedin.com/company/just-eat-spain-sl/', 'https://app.dealroom.co/companies/just_eat_com', 'Online food ordering and delivery marketplace intermediary', 'Madrid', 'Spain', 2000, 256, 5.3497944, NULL, 0, 72103663, 2022, 'operational', NULL, '{}', '2026-11-05T15:53:18.240Z', 'Just Eat is a global online food delivery marketplace that acts as an intermediary connecting customers with local restaurants. The company was founded in Kolding, Denmark, in 2001 by five entrepreneurs, including Jesper Buch. The service commercially launched in August 2001. In 2005, the company was relocated to the UK, and in 2006, David Buttress was appointed CEO of Just Eat UK. A significant milestone occurred in 2020 when Just Eat merged with the Dutch company Takeaway.com, founded by Jitse Groen, to form Just Eat Takeaway.com, one of the world''s largest food delivery companies outside of China. The combined entity is headquartered in Amsterdam. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4a9a2f6f-0ebb-4d04-a8df-f11b46e4cb44', 'Kave Home', 'kavehome.com', 'http://kavehome.com', 'https://www.linkedin.com/company/kave-home/', 'https://app.dealroom.co/companies/kave_home', NULL, 'Sils', 'Spain', 2013, 828, 208.95523, NULL, 0, NULL, NULL, 'operational', '[{"uuid":"b90c9ad1-4a94-4285-bb67-b4c5d9f2e37a","name":"Francesc Gelabert"}]', '{}', '2026-11-05T15:55:36.049Z', 'Hemos llegado para revolucionar el sector del diseño, el mueble y la decoración, porque apostamos por darle una vuelta y ser la opción para inconformistas que buscan algo más. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4704ce5b-b1c8-4c4f-b5c3-a8fc4426e79a', 'Knowledge Development', 'kd.tech', 'https://kd.tech', 'https://www.linkedin.com/company/kd-corp/', 'https://app.dealroom.co/companies/kdpof', 'Innovative high-speed optical networking for harsh environments, making gigabit connectivity over fiber optics a reality', 'Tres Cantos', 'Spain', 2010, 205, 0, 41651993, 15, 1127799, 2024, 'operational', '[{"uuid":"173c9b6f-7981-4c53-927d-de3bd0ee1880","name":"Carlos Pardo"}]', '{}', '2026-11-05T15:53:55.756Z', 'KDPOF (KDPOF.com) is a technology startup specializing in high-speed optical networking solutions. The company focuses on providing advanced communication systems for both the automotive industry and fiber-to-the-home (FTTH) applications. KDPOF''s primary clients include automotive manufacturers and telecommunications companies that require robust and high-speed data transmission capabilities.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('de59005d-00c1-45fd-b64a-3ce7b63405ca', 'Koru Kids', 'korukids.co.uk', 'http://www.korukids.co.uk/', 'https://www.linkedin.com/company/korukids/', 'https://app.dealroom.co/companies/koru_kids', 'Platform to match nannies and families', 'London', 'United Kingdom', 2016, 767, 7.1229053, 18177619, 5, 19015144, 2018, 'operational', '[{"uuid":"0b9445eb-953b-4473-b27a-42132a92f7a3","name":"Rachel Carrell"},{"uuid":"92a395b0-9635-4ed5-8751-8672bc92d892","name":"David Easton"}]', '{}', '2026-11-05T15:54:51.538Z', 'Koru Kids operates as a childcare platform in London, designed to address the challenges of finding affordable and flexible childcare. The company was founded in 2016 by Rachel Carrell and David Michael Easton. Carrell''s inspiration came from her personal struggles with the complexities and high costs of childcare in London after having her first child. Her professional background includes serving as the CEO of DrThom.com, an online doctor service, and working at McKinsey. This experience informed her data-driven approach to solving what she identified as a broken and outdated childcare system. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('a4fe60ab-828e-4c81-a039-1163dbe03acb', 'Kraken', 'kraken.tech', 'https://kraken.tech/', 'https://www.linkedin.com/company/krakentech/', 'https://app.dealroom.co/companies/kraken_3', 'Providing a platform for managing and optimizing distributed energy resources in real time', 'London', 'United Kingdom', 2016, 2220, 15.145228, 757575455, 3, 371000000, 2026, 'operational', '[{"uuid":"639ccce0-e6ab-48d7-9f8a-d129fee27494","name":"James Eddison"},{"uuid":"bd8b9dda-6047-4161-84fb-4fb245c5c748","name":"Greg Jackson"}]', '{}', '2026-11-05T15:55:56.052Z', 'KrakenFlex operates in the energy sector, providing a cloud-based Distributed Energy Resources Management System (DERMS) that allows asset owners, energy traders, and electricity retailers to control and optimize their distributed energy resources (DERs) in real-time. The company serves a diverse range of clients, from large-scale storage and generation facilities to residential homes and electric vehicles. KrakenFlex''s software solution integrates with various DERs, enabling clients to participate in both ancillary and wholesale market trading activities. This includes high-demand markets such as Within Day Trading, Frequency Response, the Balancing Mechanism, and Dynamic Containment. The business model is based on providing software-as-a-service (SaaS), generating revenue through subscription fees and possibly transaction-based fees for market activities. KrakenFlex''s platform enhances the financial and physical performance of energy assets, offering sub-second response times and comprehensive monitoring capabilities.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4013ce41-8989-4450-84ee-a4df4321a066', 'LabGenius', 'labgeni.us', 'http://labgeni.us', 'https://www.linkedin.com/company/labgenius/', 'https://app.dealroom.co/companies/labgenius', 'Combining human and machine intelligence to accelerate the discovery of advanced medicines', 'London', 'United Kingdom', 2012, 66, 0, 57892112, 11, 183800, 2025, 'operational', '[{"uuid":"e679d955-e7f7-40a9-8a75-70bd4b96149d","name":"James Field"}]', '{}', '2026-11-05T15:54:51.538Z', 'LabGenius is a pioneering startup in the drug discovery sector, leveraging advanced technologies like machine learning (ML), synthetic biology, and laboratory automation to develop next-generation protein therapeutics. The company operates in the biopharmaceutical market, focusing on creating innovative treatments for various diseases, including inflammatory conditions.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('da3d1c5d-d0e4-4cff-ad1e-fc3c7a7510c2', 'Laiier', 'laiier.io', 'http://laiier.io', 'https://www.linkedin.com/company/laiier/', 'https://app.dealroom.co/companies/laiier', 'Makes wireless connected printed sensors that install like tape and detect leaks, occupancy, and more', 'London', 'United Kingdom', 2021, 19, -9.523809, 3030302, 1, NULL, NULL, 'operational', '[{"uuid":"869f2d16-000b-40ff-9bc0-d7111f2b0348","name":"Isabel Lizardi Vilá"},{"uuid":"1c937d0b-3de6-4278-9e24-1cdcb60176f8","name":"Bibi Nelson"},{"uuid":"1ad4a0fe-65d9-40aa-889c-07a7c6fdb466","name":"Matt Johnson"},{"uuid":"587e578c-6fd5-46c1-985a-89b079bfdd8e","name":"Isabel Lizardi"}]', '{}', '2026-11-05T15:55:09.655Z', 'LAIIER is a forward-thinking startup that specializes in smart building technology, focusing on predictive maintenance through innovative smart surfaces. These surfaces, which can be installed as easily as stickers or tape, are embedded with printed sensors that monitor various aspects of a building''s infrastructure. This technology aims to prevent resource wastage and enhance the overall efficiency of commercial buildings.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('86392806-84b4-4070-9a59-0ee397374dfa', 'Lapse', 'lapse.app', 'https://lapse.app', 'https://www.linkedin.com/company/getlapse/', 'https://app.dealroom.co/companies/lapse', 'Social media platform and photo-sharing app inspired by disposable cameras', 'London', 'United Kingdom', 2021, 36, -2.7027028, 32316654, 3, 1969696, 2023, 'operational', '[{"uuid":"4c0ee8da-2c14-44fa-8870-0f9a22e93b9d","name":"Ben Silvertown"},{"uuid":"3d334f8f-bdaf-4ee0-ab51-6f7320f3ff28","name":"Dan Silvertown"}]', '{}', '2026-11-05T15:53:04.860Z', 'Lapse is a mobile application that aims to bring back the experience of using a disposable camera in a digital format. Users can capture 36 photos on a "roll" and have to wait for them to be "developed" at a surprise time, after which they can be shared with a private group of friends.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f121254a-be0c-4289-a847-219ea771762e', 'Last.app', 'last.app', 'https://www.last.app/', 'https://www.linkedin.com/company/last-app/', 'https://app.dealroom.co/companies/last_app', 'Ecosystem of tools that helps restaurateurs to fully manage their establishment', 'Barcelona', 'Spain', 2019, 66, 8.196721, 5999998, 2, 985790, 2023, 'operational', '[{"uuid":"b431f831-4832-4be1-b72e-1e33fe35bad4","name":"Eric Nikolic"},{"uuid":"bb0f1fa6-a375-41b3-a315-1d9014044bc2","name":"Ivan Nikolic Fraguela"},{"uuid":"72b3725d-c316-4691-b24f-a034b2bab325","name":"Eric Nikolic"}]', '{}', '2026-11-05T15:55:36.049Z', 'Last.app operates in the restaurant management sector, focusing on optimizing delivery operations for dark kitchens. The company provides a comprehensive software solution that allows restaurants to manage their own delivery services efficiently. By leveraging API integration, Last.app enables seamless order routing to the correct location under the appropriate brand name, ensuring accuracy and efficiency in operations. The platform caters to restaurant owners and operators who seek to streamline their delivery processes and enhance customer satisfaction. Last.app''s business model revolves around offering a subscription-based service, generating revenue through software licensing and support. The company serves a niche market of dark kitchens, which are increasingly popular due to the rise of food delivery services. By providing tools for managing orders, promotions, and pricing through a user-friendly interface, Last.app empowers restaurants to maintain control over their delivery operations and improve profitability.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3a76311a-c294-4043-ae8c-6ea348d72d9d', 'Latitude', 'latitude.so', 'https://latitude.so', 'https://www.linkedin.com/company/trylatitude/', 'https://app.dealroom.co/companies/latitude_3', 'Latitude enables collaboration between data teams and decision-makers', 'Barcelona', 'Spain', 2022, 13, -7.142857, NULL, 0, 378788, 2023, 'operational', '[{"uuid":"87be3530-d0a2-4f19-a41d-d17f1220717e","name":"Gerard Clos"},{"uuid":"3e6df53e-10ab-462d-be8d-a18c7b91038a","name":"Cesar Miguelañez"}]', '{}', '2026-11-05T15:56:04.243Z', 'Latitude is a cutting-edge startup that focuses on enhancing collaboration between data teams and decision-makers. The company operates in the data analytics and business intelligence market, providing a platform that simplifies the process of exploring data, making it more accessible and interactive for all stakeholders involved.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('47a63aef-f5ac-4880-b423-089383cc9152', 'Lawhive', 'lawhive.co.uk', 'https://lawhive.co.uk', 'https://www.linkedin.com/company/joinlawhive/', 'https://app.dealroom.co/companies/lawhive', 'A fast-growing online platform for consumers and businesses to get legal help for a fraction of the cost of a local law firm', 'London', 'United Kingdom', 2021, 267, 6.374502, 87954510, 6, 772727, 2023, 'operational', '[{"uuid":"0b857d92-9c4e-486b-9c51-16d04fc66853","name":"Flinn Dolman"},{"uuid":"1966cb91-a725-432d-ba9f-b946f7bcd3cc","name":"Pierre Proner"},{"uuid":"5c3f81cc-f340-45f9-8c9f-4bb4d983c583","name":"Jaime van Oers"},{"uuid":"301538ce-aaea-4968-8204-6e7fe02902f6","name":"Pierre Proner"}]', '{}', '2026-11-05T15:54:12.521Z', 'Lawhive is a UK-based online platform that connects clients with licensed solicitors for half the cost of traditional law firms. The company operates in the legal services market, offering a fast, convenient, and affordable way to get professional legal assistance without leaving home. Clients can apply online, describe their legal issues, and get paired with expert solicitors who handle their cases and manage all necessary documentation. Lawhive''s business model leverages technology to provide efficient legal services, passing the cost savings to clients through fixed affordable prices with no hourly rates or hidden fees. The platform ensures lightning-speed communication, allowing clients to receive responses and support within minutes, accessible from both mobile and desktop devices 24/7. Lawhive serves a diverse range of clients across the UK, providing expert legal help for any type of case. The company generates revenue through its fixed pricing model, ensuring transparency and affordability for its customers. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('b14d8a51-d195-45b9-817a-35ece860d664', 'Lendable', 'lendable.co.uk', 'https://www.lendable.co.uk/', 'https://www.linkedin.com/company/lendable/', 'https://app.dealroom.co/companies/lendable', 'Lendable is a lending platform that makes borrowing money effortless', 'London', 'United Kingdom', 2014, 685, 27.560522, 217424240, 3, 460605876, 2025, 'operational', '[{"uuid":"0371d360-8e51-462b-bc3d-9721d960871a","name":"Jakob Schwarz"},{"uuid":"a7a7e523-8cc3-487a-b921-58b08544f870","name":"Victoria van Lennep"},{"uuid":"2fd69812-3fcd-4aaf-847e-f1f7599b62de","name":"Martin Kissinger"},{"uuid":"629c69e6-251f-4561-9041-87a08abe541b","name":"Paul Pamment"}]', '{}', '2026-11-05T15:54:12.521Z', 'Lendable operates as a UK-based financial technology company, specializing in consumer credit by connecting borrowers with institutional investors. The firm was established in 2014 by Martin Kissinger, Victoria van Lennep, Paul Pamment, and Jakob Schwarz, with a vision to make personal finance more straightforward and efficient through technology. Kissinger, the CEO, brought experience from Rocket Internet, where he was involved in launching a similar consumer finance platform, and both he and van Lennep had financial backgrounds from Goldman Sachs. The company''s model was designed to bypass traditional banking inefficiencies by automating credit decisions and loan processing. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('9360aa5b-10b7-4e32-b1e1-61815e4efbf8', 'Let’s Do This', 'letsdothis.com', 'http://letsdothis.com', 'https://www.linkedin.com/company/lets-do-this/', 'https://app.dealroom.co/companies/let_s_do_this_1', 'Marketplace for endurance events', 'London', 'United Kingdom', 2016, 76, -14.606742, 61791643, 7, 10681814, 2022, 'operational', '[{"uuid":"8d2f2f6c-4bee-43e1-a3e7-fc8da08efd10","name":"Sam Browne"},{"uuid":"5c71e091-9efc-4e24-bbb2-3206fca743eb","name":"Neil Lock"},{"uuid":"8d04d10f-8a36-445b-91f2-83ec1540fcd1","name":"Alex Rose"}]', '{}', '2026-11-05T15:53:18.240Z', 'Let''s Do This is a digital platform that operates in the recreational and competitive events market. The startup primarily serves individuals who are interested in participating in various physical activities such as running, cycling, swimming, climbing, and more. The company''s mission is to inspire more people to experience amazing moments, discover new places, people, and communities. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('9c5a4945-357d-429b-9f98-801a036470f1', 'Life5', 'life5.es', 'https://life5.es/', 'https://www.linkedin.com/company/life5insurance/', 'https://app.dealroom.co/companies/life5', 'Fast and flexible online life insurance to protect loved ones', 'Madrid', 'Spain', 2021, 26, -16.129032, 14166661, 3, 3787877, 2023, 'operational', '[{"uuid":"95d48be1-660b-4981-a856-a49abd2d8c28","name":"Guillermo Alén Iglesias"},{"uuid":"b7fddae5-18de-4a52-99e1-44151e93830e","name":"Yago Montenegro Mendez"},{"uuid":"f466655c-a2c2-4bb6-8093-86f4af465f87","name":"Guillermo Alén Iglesias"},{"uuid":"f54ee208-4715-49d7-90ac-956288758ade","name":"Yago Montenegro"}]', '{}', '2026-11-05T15:55:09.655Z', 'Life5, a Spanish insurtech company headquartered in Madrid, is positioned to modernize the life insurance sector in Europe. Founded in 2021 by Guillermo Alen, Yago Montenegro, and Yago Mendez, the firm was initially known as Getlife before rebranding. The company operates as a Managing General Agent (MGA), partnering with established insurers like AXA and CNP Assurances to offer its products. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('664bb3d3-7efa-4a22-adef-60b20b9ce665', 'Lindus', 'lindustx.com', 'https://www.lindustx.com/', 'https://www.linkedin.com/company/lindustx/', 'https://app.dealroom.co/companies/lindus', 'Accelerates clinical trials for biotech and healthtech pioneers', 'London', 'United Kingdom', 2021, 165, -20.673077, 59590885, 4, 3712120, 2023, 'operational', '[{"uuid":"840dcf2d-7c61-4157-9cec-a12ac00f51cf","name":"Michael Young"},{"uuid":"e592938d-202c-4a01-8d06-78b4773ab2f1","name":"Meri Beckwith"},{"uuid":"5ac96796-22ff-4a80-9b6d-473c5b74ca16","name":"Meri Beckwith"}]', '{}', '2026-11-05T15:54:12.521Z', 'Lindus is a next-generation contract research organization (CRO) purpose-built to give biotech and pharmaceutical sponsors genuine confidence and control over their clinical trials. At the core of its offering is Citrus™, an AI-assisted trial operating system with clinical oversight that connects patient identification across 40 million electronic health records to full-scope trial execution across the US and UK. Rather than managing complexity with more complexity, Lindus is engineered to surface risks early — integrating recruitment, study operations, and clinical data into a single system visible to both sponsors and internal teams in real time. The result is a model where one partner carries one clear line of accountability, from study design through database lock.
