itda":null,"profit":null,"rnd":null,"valuation":27272716,"employees":82},{"year":2020,"revenue":3574507,"ebitda":null,"profit":null,"rnd":null,"valuation":45454527,"employees":93},{"year":2021,"revenue":6147313,"ebitda":null,"profit":null,"rnd":null,"valuation":181818109,"employees":129},{"year":2022,"revenue":9936554,"ebitda":null,"profit":358025,"rnd":null,"valuation":181818109,"employees":188},{"year":2023,"revenue":8466906,"ebitda":null,"profit":628822,"rnd":null,"valuation":181818109,"employees":175},{"year":2024,"revenue":9167136,"ebitda":null,"profit":628822,"rnd":null,"valuation":181818109,"employees":198},{"year":2025,"revenue":9644761,"ebitda":null,"profit":628822,"rnd":null,"valuation":545454327,"employees":207},{"year":2026,"revenue":9644761,"ebitda":null,"profit":628822,"rnd":null,"valuation":545454327,"employees":230}]', '2026-11-05T15:55:36.049Z', 'GBP', '2026-11-05T15:55:36.049Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('b66fb614-7ecb-4acf-aa95-18af9720ccda', 'Livo', 'getlivo.com', 'https://www.getlivo.com/', 'https://www.linkedin.com/company/livoapp/', 'https://app.dealroom.co/companies/livo_2', 'Healthcare staffing platform for talent recruitment and retention', 'Barcelona', 'Spain', 2023, 69, -9.210526, 0, 1, 11355, 2023, 'operational', '[{"uuid":"db4d00fc-46f3-49ac-a440-0d59ec285556","name":"Carlos Manubens Mercadé"},{"uuid":"105badb3-5bc2-4372-a699-b91bacce2106","name":"Adnane Ouahabi"}]', '{}', '2026-11-05T15:56:04.243Z', 'Livo, registered as Livo Health, SL, is a technology company that operates a platform to address staffing shortages in the healthcare sector. Founded in 2023 by Adnane Ouahabi and Carlos Manubens Mercade, the company is headquartered in Barcelona, Spain. Livo serves healthcare facilities such as hospitals and clinics by connecting them with qualified nursing professionals for shifts, substitutions, and permanent positions. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('588d64b4-35ed-482b-8fc8-6682880ed3be', 'Lookiero', 'lookiero.com', 'http://lookiero.com/', 'https://www.linkedin.com/company/lookiero/', 'https://app.dealroom.co/companies/lookiero', 'E-commerce startup that provides online personal shopper services for women', 'Bilbao', 'Spain', 2016, 306, -17.741936, 57128508, 7, 66666640, 2023, 'operational', '[{"uuid":"ffe4cc6a-dcd2-4a3b-97d6-d4818b99217b","name":"Oier Urrutia"}]', '{}', '2026-11-05T15:55:36.049Z', 'Founded in 2015 by Oier Urrutia, Lookiero is an online personal shopping service that has established a significant presence in the European market. The company''s business model is centered around providing a personalized and convenient shopping experience for women.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0f998525-5f9d-4217-a50f-c0c8fb54d090', 'Ludus', 'ludusglobal.com', 'https://ludusglobal.com', 'https://www.linkedin.com/company/ludus-realidad-virtual-para-industria-y-servicios-de-emergencia/', 'https://app.dealroom.co/companies/ludus_2', 'Virtual reality for company training', 'Bilbao', 'Spain', 2011, 76, 4.109589, 4039770, 19, 1420726, 2024, 'operational', '[{"uuid":"da3cbf1e-a086-4be7-9e46-8de72b0a75ee","name":"Mikel Calvo Alonso"},{"uuid":"90a6b36f-95b0-4a85-892b-875d777cfc62","name":"Mikel Cearsolo"}]', '{}', '2026-11-05T15:55:36.049Z', 'Ludus, established in Bilbao, Spain, in 2011, develops a virtual reality platform for health and safety training. The company was founded by engineers from the University of Deusto, including Mikel Cearsolo, who serves as CEO. Cearsolo''s background in Industrial Organization Engineering and his experience in managing innovation projects have shaped the company''s direction. The idea for Ludus emerged in 2013 after the founders encountered a new generation of virtual reality technology at a fair in Amsterdam. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('5cb6b858-2d40-486f-8efd-8d961d41ddaa', 'MAFER AI', 'mafer.ai', 'https://mafer.ai', 'https://www.linkedin.com/company/mafer-ai/', 'https://app.dealroom.co/companies/mafer_ai', 'AI operating system for R&D teams in formulation industries', 'Sant Cugat del Vallès', 'Spain', 2025, 15, NULL, 1666666, 1, NULL, NULL, 'operational', '[{"uuid":"1d862f2e-b4e6-4403-b4ec-4b1b43a35929","name":"Fer Oliver Jané"},{"uuid":"ef02130f-9ec9-422d-8e02-5c37e485c6e2","name":"Marc Montalbo"}]', '{}', '2026-11-05T15:56:04.243Z', 'Mafer AI (MaferOS) is a Barcelona startup building an AI operating system for R&D teams in formulation industries—specialty chemicals, food and beverages, cosmetics, personal care, and fragrances and flavours. Founded in late 2025 by Fernando Oliver Jané (CEO) and Marc Montalbo Burges (CTO), it trains proprietary models on each customer''s historical laboratory data (formulas, chromatograms, regulatory docs) while keeping data isolated, and deploys specialised agents for analysis, regulatory compliance across jurisdictions and formula recommendation via Forward Deployed Engineers. In May 2026 Mafer AI raised €2 million in pre-seed funding from K Fund, 4Founders Capital, Masia and Lavanda Ventures (Puig family), plus angels including Adrián Mato, Manuel Roca, Dídac Lee, Fernando Castiñeiras and Juanjo Mostazo. Selected for the Barcelona Supercomputing Centre AI Factory programme, it reported near €300k committed ARR within six months of launch.', '["Venture Capital","genAI Model Maker","SaaS","Angel","Generative AI","b2b","Artificial Intelligence","Commission","Enterprise Software","4YFN 2026","4YFN","Early stage","ai model layer"]', '["startup","vc_backed","funded"]', 75.75, 6100, 0, 0, 9999996, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:56:04.243Z', 'GBP', '2026-11-05T15:56:04.243Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0644c14d-aa39-4381-9b49-8b7e3d435394', 'MITO — An AI visual myth-making studio', 'mitofilms.ai', 'http://mitofilms.ai', 'https://www.linkedin.com/company/mito-films-ai/', 'https://app.dealroom.co/companies/mito_an_ai_visual_myth_making_studio', 'Visual campaigns crafted through a fusion of AI tools and human creativity, building culturally relevant and memorable brand narratives', 'A Coruña', 'Spain', 2025, 28, NULL, 3409090, 2, NULL, NULL, 'operational', '[{"uuid":"21188940-845a-4ec6-992c-7415a4cf6341","name":"Danny Saltaren"},{"uuid":"de6c105d-62ab-4418-8452-cf66300be3a1","name":"Arantxa B"},{"uuid":"bb4f6165-0240-4571-afa7-440b31e50fc3","name":"Inaki Berenguer"}]', '{}', '2026-11-05T15:53:55.756Z', 'MITO operates as a creative agency specializing in the production of visual campaigns and narrative content. The firm''s core service involves a hybrid approach, combining artificial intelligence tools with human-led strategic vision and emotional storytelling to create what it terms "iconic visual stories."
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3f8a501a-2064-4ef4-b1c4-bfbd2daf4d12', 'MOO', 'moo.com', 'http://www.moo.com', 'https://www.linkedin.com/company/moo-com/', 'https://app.dealroom.co/companies/moo', 'MOO offers high-quality, affordable business cards and branded items like notebooks and water bottles', 'London', 'United Kingdom', 2006, 810, 7.001321, 3787877, 4, 90227237, 2024, 'operational', '[{"uuid":"4857b46a-68ac-41ca-9846-620abb0fadcb","name":"Richard Moross"}]', '{}', '2026-11-05T15:53:18.240Z', 'Moo is a leading online print and design company, founded in 2006 with a vision to revolutionize the print industry. Initially focused on providing high-quality, affordable business cards, Moo has since expanded its offerings to include a wide range of branded products, from notebooks and stickers to packaging and promotional items like water bottles.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f8db5679-edcb-47a0-b8ee-ba0e8e35188e', 'Manglai', 'manglai.io', 'https://www.manglai.io/', 'https://www.linkedin.com/company/manglai/', 'https://app.dealroom.co/companies/manglai', 'Manglai: AI-driven, reducing carbon footprints. Empowering global businesses for a sustainable future', 'Barcelona', 'Spain', 2023, 35, 75, 1249999, 2, NULL, NULL, 'operational', '[{"uuid":"f1f8bb66-878a-47d4-bd8f-b4c5fdbb380d","name":"Jordi López Ramírez"},{"uuid":"1de662c3-7f39-4baa-8b21-07bd50757705","name":"Jaume Fontal"},{"uuid":"5b6fae2a-587a-498f-8650-4342f513b01f","name":"Jesús C."},{"uuid":"33583da7-98fd-40cc-89da-81e3fb1d0ddb","name":"Andres Cester"}]', '{}', '2026-11-05T15:55:36.049Z', 'Manglai, founded in 2023, operates an AI-powered platform designed to assist businesses in managing their carbon footprint. The company is headquartered in Barcelona, Spain, and was established by co-founders Andres Cester, Jaume Fontal, Jesus C, and Jordi Lopez Ramirez. The founding team brings relevant experience to the venture; for instance, Jaume Fontal, the Chief Product and Technology Officer (CPTO), previously served as Director of Technology and Product at Colvin and spent over a decade at Softonic. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('56d698b8-a82c-4200-807d-1b4f358c2a46', 'Mantic', 'mantic.com', 'https://www.mantic.com/', 'https://www.linkedin.com/company/mantic-ai/', 'https://app.dealroom.co/companies/mantic', 'AI for superhuman forecasting of global events', 'London', 'United Kingdom', 2024, 23, NULL, 21909387, 2, NULL, NULL, 'operational', '[{"uuid":"1c374ffd-86a8-4eee-ba63-bf6a9629c316","name":"Ben Day"},{"uuid":"ad627c29-909e-4ca7-8b6f-87888df3729e","name":"Toby Shevlane"}]', '{}', '2026-11-05T15:54:12.521Z', 'Mantic is a London-based AI forecasting company building systems that predict geopolitical, business, policy, technology and cultural events with superhuman accuracy. Co-founded in 2024 by Toby Shevlane (former Google DeepMind senior research scientist) and Ben Day (former Head of Research at Foresight Data Machines; PhD machine learning, Cambridge), the company specialises frontier models for medium-term (1 week–1 year) judgemental forecasting and sells foresight tools — horizon scan, probabilistic forecast and monitoring — to executives, investors, strategists, risk teams and policymakers. Mantic outperformed human forecasters in the Metaculus Cup and raised a $25 million seed round in September 2026 led by Radical Ventures with M12, Balderton Capital and others.', '["Venture Capital","b2b","out of stealth","Breakout stage","Enterprise Software"]', '["startup","vc_backed","funded"]', 84.34, 14000, 0, 0, 68181791, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:54:12.521Z', 'GBP', '2026-11-05T15:54:12.521Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('69533550-d97f-41c8-80f4-d78cd8c52f57', 'Marker', 'marker.page', 'https://marker.page/', 'https://www.linkedin.com/company/writewithmarker/', 'https://app.dealroom.co/companies/marker_3', 'AI-powered word processor with advanced writing tools', 'London', 'United Kingdom', 2025, 12, 140, 9848481, 1, NULL, NULL, 'operational', '[{"uuid":"0d4a95cb-4ceb-4807-b053-6d8027ebfb81","name":"Jon Steinback"},{"uuid":"e4c34c39-5006-4a34-872d-2b8b99975b92","name":"Ryan Bowman"}]', '{}', '2026-11-05T15:53:18.240Z', 'Marker (marker.page) is a London AI writing company building a reimagined word processor that writes with authors rather than for them—supporting ideation, drafting, revision and collaboration so blogs, Substacks, memos and long-form work stay craft-led instead of AI-slop automation. Co-founded by Jon Steinback (ex-DeepMind brand and creative lead) and Ryan Bowman (platforms for writers inside literary and talent agencies), it emerged from stealth targeting professional and creative writers who want AI that preserves authorial control. In July 2026 Marker raised a $13 million seed led by Index Ventures with LocalGlobe and angels including Writely/Google Docs co-founder Steve Newman, Slack co-founder Cal Henderson and Hugging Face’s Thomas Wolf. Sources: Tech.eu 9 Jul 2026; Index Ventures.', '["Venture Capital","Core AI","SaaS","Angel","Generative AI","b2b","genAI Applications","Artificial Intelligence","Enterprise Software","uk is8 digital and technologies","Early stage"]', '["startup","rising_star","vc_backed","funded"]', 85.49, 8300, 0, 0, 59090885, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:53:18.240Z', 'GBP', '2026-11-05T15:53:18.240Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3284bf17-a3e6-4ebb-8798-673ca91245cc', 'Marvel', 'marvelapp.com', 'http://marvelapp.com', 'https://www.linkedin.com/company/marvel-app/', 'https://app.dealroom.co/companies/marvel', 'Mobile and web prototyping without coding', 'London', 'United Kingdom', 2013, 32, -3.030303, 5840149, 4, 57121, 2023, 'operational', '[{"uuid":"d1da796f-d86d-4f25-8847-20376424be16","name":"Jonathan Siao"},{"uuid":"06509b34-e7dd-4f15-b95c-0a46e7a110a4","name":"Dustin McCaffree"},{"uuid":"00274f7e-546d-4c9f-8233-8fbdc115d021","name":"Brendan Moore"},{"uuid":"d9cf1825-3154-471d-a111-aec704a8ce4f","name":"Murat Mutlu"}]', '{}', '2026-11-05T15:53:18.240Z', 'Marvel Prototyping LTD, operating as Marvel, is a London-based company founded in 2013 by Murat Mutlu, Brendan Moore, and Jonathan Siao. The company provides a cloud-based design platform that centralizes the entire design process, from initial ideas to developer handoff. The concept for Marvel originated from CEO Murat Mutlu''s own frustrations with the prototyping process while working as a product designer. What began as a side project quickly evolved into a full-fledged business, officially launching in November 2013. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('fbbe6e3c-30f0-4b7e-9bc3-fd36cbb47a11', 'Mascoteros', 'garudaku138.com', 'https://garudaku138.com', 'https://www.linkedin.com/company/mascoteros/', 'https://app.dealroom.co/companies/mascoteros', 'Mascoteros is the first Spanish marketplace in the world of pets', 'Barcelona', 'Spain', 2016, 11, -8.333333, 2358332, 3, 1106060, 2023, 'operational', '[{"uuid":"160ae424-431e-4583-a921-2d2105a0856f","name":"Eduardo Sánchez"},{"uuid":"f1d22051-a5c2-4f9f-aa4f-55f52e72c419","name":"Carlos Rodríguez"},{"uuid":"22d873d4-e291-4368-a8d5-9e150ec43f6a","name":"Alberto Pérez del Águila"},{"uuid":"2598ddc4-c617-4541-93df-d8ab00481317","name":"Thaís Almeida Baptista"}]', '{}', '2026-11-05T15:53:55.756Z', 'Mascoteros is a Barcelona-based entity in the pet care sector, operating primarily in Spain and Portugal. The company was established in 2015 by venture builder Antai and media group Atresmedia. The founding team included Alberto Pérez, Thaís Almeida Baptsita, Eduardo Sánchez, and the veterinarian Carlos Rodríguez, who initially approached Atresmedia''s incubator to develop his content blog into a broader platform. One of the founders, Demis Torres Baro, served as CEO, bringing experience from KPMG, Nestlé, and Rakuten Spain. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('c34103a4-5d4b-4b10-a0bd-ecbc2a19c71d', 'Master Me Up', 'mastermeup.com', 'http://mastermeup.com', 'https://www.linkedin.com/school/mastermeup/', 'https://app.dealroom.co/companies/master_me_up', 'Intensive training programs enhancing leadership skills through practical implementation for founders and managers', 'Barcelona', 'Spain', 2018, 15, 0, NULL, 0, NULL, NULL, 'operational', '[{"uuid":"0afc05fb-f443-45d7-b0cd-f8cbd836297c","name":"Lucas Sanchez"},{"uuid":"1152b09e-f136-4df2-9861-2bcad1098aca","name":"Tomas Pando"}]', '{}', '2026-11-05T15:56:04.243Z', 'Master Me Up es una comunidad online de aprendizaje online para founders y managers. Mediante programas online enfocados en implementación mejorarás tus habilidades como líder para llevar tu empresa al siguiente nivel.', '["service provider","Marketing","Early stage"]', '["funded"]', NULL, 3500, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:56:04.243Z', 'GBP', '2026-11-05T15:56:04.243Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3efadf0d-659e-4e84-95a7-35447ef0d227', 'Matillion', 'matillion.com', 'http://matillion.com', 'https://www.linkedin.com/company/matillion-limited/', 'https://app.dealroom.co/companies/matillion_com', 'Makes data transformation software for cloud data warehouses', 'Salford', 'United Kingdom', 2011, 479, 2.7896996, 234378696, 7, 70434820, 2025, 'operational', '[{"uuid":"7dcc18b1-d412-40b9-99ce-f75adf86ee84","name":"Peter McCord"},{"uuid":"b3d54328-21ce-4dc7-9338-60e392796eb0","name":"Matthew Scullion"},{"uuid":"96a65265-eed5-4e04-a158-9ce75fe13653","name":"Ed Thompson"}]', '{}', '2026-11-05T15:54:12.521Z', 'Matillion is a data management platform that provides solutions for data teams to build, manage, and orchestrate data pipelines. The company operates in the data management and analytics market, serving a wide range of clients from various industries. Its primary focus is on enhancing productivity for data teams, both coders and non-coders, by offering tools to move, transform, and orchestrate data pipelines swiftly and efficiently.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3d51b505-0962-4e29-9217-ada903e1f294', 'Medlumics', 'medlumics.com', 'http://medlumics.com', 'https://www.linkedin.com/company/medlumics/', 'https://app.dealroom.co/companies/medlumics', 'A pre-commercial, medical device company that designs and manufactures catheter-based systems for the treatment of supra-ventricular tachycardias', 'Madrid', 'Spain', 2009, 11, -54.166668, 63808459, 8, 599180, 2019, 'operational', NULL, '{}', '2026-11-05T15:53:12.600Z', 'MedLumics, founded in 2011, is a medical device startup focused on improving human living standards through advanced technology. The company operates in the biophotonics sector, which combines biology, medical science, physics, and photonic technology (the use of light to study and manipulate biological materials). MedLumics aims to transform scientific and technological advances in biophotonics into innovative, high-quality solutions for the global market.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0cbdb1ec-e710-4cf1-960f-f0521b729aff', 'Memgraph', 'memgraph.com', 'https://memgraph.com/', 'https://www.linkedin.com/company/memgraph/', 'https://app.dealroom.co/companies/memgraph', 'Memgraph is a high-performance, in-memory graph database that powers real-time AI context and graph analytics at scale.', 'Sevenoaks', 'United Kingdom', 2016, 107, 224.24243, 8790909, 4, NULL, NULL, 'operational', '[{"uuid":"67f08808-3b6f-41f5-9055-dd20c8d9145f","name":"Marko Budiselić"},{"uuid":"8d03f9bb-f0cf-4c09-8cb2-cf9d59db80cf","name":"Dominik Tomicevic"}]', '{}', '2026-11-05T15:55:09.655Z', 'Memgraph is a high-performance, in-memory graph database that powers real-time AI context and graph analytics at scale.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('a80ec65d-9ffc-4c29-b6a3-318483871e10', 'Memrise', 'memrise.com', 'http://www.memrise.com', 'https://www.linkedin.com/company/memrise/', 'https://app.dealroom.co/companies/memrise', 'Language learning system combining cognitive science, tech and entertaining content', 'London', 'United Kingdom', 2010, 48, -22.580645, 16498478, 6, 7663769, 2023, 'operational', '[{"uuid":"b5421b81-9adf-4323-aa40-31b4fef4265c","name":"Ben Whately"},{"uuid":"5f3a5b57-a099-493c-b36e-79825ac7c420","name":"Edward Cooke"}]', '{}', '2026-11-05T15:54:12.521Z', 'Memrise is a language learning platform that leverages memory techniques and machine learning to help users become multilingual. Founded on the principles of serious research, Memrise aims to radically change the ability of normal people to learn new languages. The platform serves a diverse client base of over 65 million learners in 189 countries, ranging from casual learners to serious polyglots. Operating in the online education market, Memrise offers a freemium business model where users can access basic features for free and pay for premium features. Revenue is generated through subscription fees for premium content and features, which include advanced learning tools, offline access, and personalized learning plans. The company''s core product is its mobile and web application, which provides interactive language courses, memory-enhancing techniques, and progress tracking. Memrise''s commitment to continuous improvement is evident in its regular updates and new feature rollouts, ensuring that users have access to the latest advancements in language learning technology.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('1423a6ac-5099-413b-9c8b-81b4af726e8c', 'Mimo', 'mimohq.com', 'http://mimohq.com', 'https://www.linkedin.com/company/joinmimo/', 'https://app.dealroom.co/companies/mimo_6', 'Automatically process all business transactions', 'London', 'United Kingdom', 2023, 50, -5.6603775, 18496659, 2, NULL, NULL, 'operational', '[{"uuid":"026e7267-b6f1-4c92-a781-c4ae6eb55415","name":"Alexander Gernandt Segerby"},{"uuid":"cd04217f-f930-4ee6-8b62-e33594f0eaec","name":"Andreas Meisingseth"},{"uuid":"b51c07b4-b512-44a5-846f-02d26b80c099","name":"Henrik Grim"}]', '{}', '2026-11-05T15:55:23.556Z', 'Mimo is a startup focused on simplifying B2B (business-to-business) transactions, primarily targeting small and medium-sized businesses (SMBs). The company operates in the financial technology (fintech) market, providing tools that help businesses manage their cash flow more effectively. Mimo addresses common issues such as late payments and large supplier bills, which are frequent pain points for SMBs. By automating the transaction process, Mimo allows businesses to pay and get paid with just one click, freeing up time and resources for more critical business activities.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('078b960c-8b74-4716-8b88-de3148e4a982', 'Minoryx Therapeutics', 'minoryx.com', 'http://minoryx.com', 'https://www.linkedin.com/company/minoryx-therapeutics/', 'https://app.dealroom.co/companies/minoryx_therapeutics', 'Clinical stage biotech company focusing on the development of novel therapies for orphan CNS diseases with high unmet medical needs', 'Mataró', 'Spain', 2011, 32, 0, 103576474, 10, 4342355, 2023, 'operational', '[{"uuid":"ef992f15-fa8f-44a1-8001-31c1345c187b","name":"Marc Martinell"}]', '{}', '2026-11-05T15:53:12.600Z', 'Minoryx Therapeutics is a biotechnology startup dedicated to discovering and developing innovative treatments for severe, rare diseases of the central nervous system (CNS). These conditions, often referred to as orphan diseases, have high unmet medical needs, meaning there are few or no effective treatments available. The company is headquartered in Gosselies, Charleroi, Belgium.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('6af54edd-6321-4219-ac61-785fd46599fe', 'Minube', 'minube.com', 'https://www.minube.com/', 'https://www.linkedin.com/company/minube-com/', 'https://app.dealroom.co/companies/minube', 'A leading social travel platform that helps you find your next destination', 'Las Rozas de Madrid', 'Spain', 2007, 22, -4.347826, 2083332, 3, 1742424, 2023, 'operational', '[{"uuid":"8db62a57-19ae-43d3-8b48-49d5b8433529","name":"Pedro Jareño Algobia"},{"uuid":"b4650154-0e8b-45af-a9e7-8b24a8912259","name":"Gonzalo Moreno de León"},{"uuid":"bb14fd90-c6ce-463d-bd44-bfbda7168275","name":"Raul Jimenez Algobia"}]', '{}', '2026-11-05T15:53:55.756Z', 'Minube operates as a social travel platform designed to assist users throughout their entire travel journey, from inspiration and planning to in-trip guidance and post-trip memory sharing. Founded in 2006 by brothers Raúl Jiménez and Pedro Algobia in Madrid, Spain, the company emerged during the global financial crisis. Raúl Jiménez, serving as CEO, and his team aimed to create a platform that addresses common traveler pain points by leveraging community-generated content.
