INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2fbe118a-387b-4404-a481-d4f980cd8f3f', 'Moniepoint', 'moniepoint.com', 'http://moniepoint.com', 'https://www.linkedin.com/company/moniepoint-inc/', 'https://app.dealroom.co/companies/teamapt', 'All-in-one financial services ecosystem for African businesses.', 'London', 'United Kingdom', 2015, 5881, 51.143665, 197424163, 8, 262499895, 2024, 'operational', '[{"uuid":"cb0c3d08-c0c5-4bde-a827-8a310baf56ff","name":"Felix Ike"},{"uuid":"cc57f252-cbcc-4791-a861-c5af489b5239","name":"Tosin Eniolorunda"}]', '{}', '2026-11-05T15:55:56.052Z', 'Moniepoint is a rapidly growing fintech company that provides comprehensive financial solutions for businesses and individuals in emerging markets. The company offers an all-in-one platform that combines payments, banking, and business management tools to empower entrepreneurs and drive economic growth.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('b8d72472-4b36-4d3c-bedd-67835b7e9cb1', 'Moshi | Mind Candy', 'mindcandy.com', 'http://www.mindcandy.com', 'https://www.linkedin.com/company/mind-candy/', 'https://app.dealroom.co/companies/mind_candy', 'A multi brand entertainment company with online games at it''s heart', 'London', 'United Kingdom', 2004, 40, 73.91304, 32132563, 11, 2720000, 2024, 'operational', NULL, '{}', '2026-11-05T15:53:18.240Z', 'Mind Candy operates in the digital health and wellness market, focusing on children''s sleep and mindfulness through its flagship product, the Moshi Sleep app. The app provides audio-only content, including original stories, meditations, and music, designed to help children fall asleep and teach them mindfulness. The target clients are parents and professionals working with children, such as educators and healthcare providers. The business model is subscription-based, generating revenue through monthly or annual fees for access to its growing library of content. The app features contributions from notable personalities and experts in sleep science, enhancing its credibility and appeal. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3c32591e-1476-4259-9f7f-d17772d456da', 'Motorway', 'motorway.co.uk', 'http://motorway.co.uk', 'https://www.linkedin.com/company/motorway-online-ltd./', 'https://app.dealroom.co/companies/motorway', 'The next-generation used car marketplace', 'London', 'United Kingdom', 2017, 471, 6.561086, 230739336, 5, 78000000, 2025, 'operational', '[{"uuid":"067ecfc6-960e-428e-b394-5134daca18ad","name":"Tom Leathes"},{"uuid":"a1258c89-5ef7-4e39-900d-abf1eb52e7ee","name":"Alex Buttle"},{"uuid":"99af44cd-f1ae-45bd-9309-c9ef81e15454","name":"Harry Jones"}]', '{}', '2026-11-05T15:53:18.240Z', 'Motorway is a UK-based online marketplace that facilitates the sale of privately owned used cars to a network of professional car dealers. The platform is designed to help private sellers achieve a higher price than they might get from part-exchange or other car-buying services, by creating a competitive environment where dealers bid for the vehicles.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('7f4d48dd-94d2-4b1e-8901-7e4735ae04b7', 'Multiverse', 'multiverse.io', 'https://www.multiverse.io', 'https://www.linkedin.com/company/joinmultiverse/', 'https://app.dealroom.co/companies/multiverse', 'AI, data and tech apprenticeships and upskilling programmes for employers and workers', 'London', 'United Kingdom', 2016, 1287, 4.2105265, 369365236, 9, 79600000, 2025, 'operational', '[{"uuid":"7eabff19-36b7-473c-9465-919ab7128a91","name":"Euan Blair"}]', '{}', '2026-11-05T15:53:18.240Z', 'Multiverse is a mission-driven tech startup that aims to revolutionize workforce development through professional apprenticeships. The company focuses on reskilling and upskilling individuals by providing on-the-job training programs that prepare them for high-paying jobs and career advancement. Multiverse operates primarily in the United States and the United Kingdom, with headquarters in New York and London.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0f6f7884-4ba1-49c6-b41d-829b57ebf57e', 'Murphy AI', 'getmurphy.ai', 'http://getmurphy.ai', 'https://www.linkedin.com/company/murphy-ai/', 'https://app.dealroom.co/companies/murphy_ai', 'AI-powered autonomous agents for omnichannel debt collection', 'Barcelona', 'Spain', 2024, 54, NULL, 11363632, 1, NULL, NULL, 'operational', '[{"uuid":"f50664ff-9827-4310-affe-1af01cf4839b","name":"Marc Sánchez Garcia"},{"uuid":"6696c0e0-734f-49b2-9385-92ea2d4ed3d1","name":"Borja Fauria"}]', '{}', '2026-11-05T15:55:23.556Z', 'Murphy AI is a Barcelona-based financial technology company developing an AI-native platform for debt servicing. Founded in 2024 by Borja Sole and Marc Sanchez, the company aims to replace traditional call-center operations with fully autonomous agents. The founding idea originated from CEO Borja Sole''s previous experience as a CFO, where he faced challenges with inefficient debt collection processes, which led him to partner with CTO Marc Sanchez. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('aba6e7a0-83dc-4f02-8c56-efab4c619200', 'Nested', 'nested.com', 'http://nested.com', 'https://www.linkedin.com/company/nested-uk/', 'https://app.dealroom.co/companies/nested', 'Platform for homeowners to sell their homes within 90 days', 'London', 'United Kingdom', 2015, 111, 9.9009905, 69666664, 6, 3106059, 2023, 'operational', '[{"uuid":"45d01549-9c3f-4723-8a10-cf76dd390a3f","name":"Matt Robinson"},{"uuid":"d8d1b86f-c34d-465c-a21b-495ce700191f","name":"Tomaso Brezzi"},{"uuid":"90632a06-3f44-40a6-8cc1-964cea6b12cc","name":"Jordi Montoyo"},{"uuid":"78194333-d465-4868-8a3e-8d83bad12c35","name":"James Turford"},{"uuid":"a303cdcf-8ec7-4680-9c5c-a911b229d807","name":"Phil Cowans"}]', '{}', '2026-11-05T15:54:12.521Z', 'Nested is a UK-based online estate agent that modernizes the home moving process. The company offers a service that allows customers to receive a cash advance to purchase a new home before their old one is sold, addressing a common problem for homeowners looking to move.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3ceb4659-1eec-43ad-90b6-00f9017bfa7d', 'NeuralTrust', 'neuraltrust.ai', 'https://neuraltrust.ai', 'https://www.linkedin.com/company/neuraltrust/', 'https://app.dealroom.co/companies/neuraltrust', 'Security and governance platform for enterprise AI agents', 'Barcelona', 'Spain', 2022, 36, 100, 16939708, 3, 67864, 2024, 'operational', '[{"uuid":"7aa8fc75-4729-4717-add9-5af8892b4c7c","name":"Alejandro Domingo"},{"uuid":"1fb60729-694d-4a15-89f2-aa0344ab09c1","name":"Joan Vendrell Farreny"},{"uuid":"66e0d7f3-a62e-457f-9012-39cca9a897d5","name":"Victor García"}]', '{}', '2026-11-05T15:53:55.756Z', 'NeuralTrust is a Barcelona AI-security company that helps enterprises discover, secure and govern AI agents and LLM applications. Founded in 2022 by CEO Joan Vendrell Farreny and CTO Victor Garcia (with COO Alejandro Domingo), NeuralTrust’s platform combines TrustGate (an agent gateway that brokers model and tool traffic), TrustGuard (runtime detection that stops prompt injection, data leakage and tool hijacks) and TrustLens (posture management that inventories agents and tracks behaviour). Customers and partners cited in public materials include AirEuropa, Abanca, Iberia and Banc Sabadell; the company has also been named in Gartner Market Guides and KuppingerCole’s Generative AI Defense Leadership Compass. In June 2026 NeuralTrust raised a $20 million seed—described by the company as Europe’s largest cybersecurity seed—led by Alstin Capital, with VentureFriends, Seaya, Kibo Ventures, Banc Sabadell, EA Ventures Plug and Play Fund and Finaves (IESE), alongside public support from the European Innovation Council and Spain’s AEI, to deepen product integration, expand engineering and grow across Europe from Barcelona and London. Sources: NeuralTrust / PR Newswire 17 Jun 2026; Tech.eu; neuraltrust.ai.', '["data management","Venture Capital","Big Data","Supply Chain Software","Core AI","Subscription","SaaS","sales enablement","Security","frameworks and libraries","development","deployment","Forecasting Tool","Generative AI","testing and qa","Big Data and Analytics","eu apply ai","domain name services","software development","AI Agents","it infrastructure","Inventory Management","open source","b2b","4YFN 2023","Artificial Intelligence","AI Security","software framework","Horizon Europe","Interoperability","programming languages","Breakout stage","audio-video-graphics","web & portal technology","generative ai","Cybersecurity","business intelligence","governance-risk and compliance","javascript libraries","Retailers","Natural Language Processing","Enterprise Software","other audio-video-graphics software","4YFN 2026","4YFN","Responsible Consumption And Production (#12)","security","Sustainable Development Goals","Climate Tech","EIC","4YFN 2025","continuous integration","Machine Learning","web tools and plugins"]', '["startup","rising_star","vc_backed","funded"]', 91.35, 51000, 1, 5, 90909055, NULL, NULL, 421, 2024, '[{"year":2023,"revenue":31688,"ebitda":null,"profit":13152,"rnd":null,"valuation":null,"employees":null},{"year":2024,"revenue":67864,"ebitda":null,"profit":421,"rnd":null,"valuation":null,"employees":8},{"year":2025,"revenue":67864,"ebitda":null,"profit":421,"rnd":null,"valuation":null,"employees":18},{"year":2026,"revenue":67864,"ebitda":null,"profit":421,"rnd":null,"valuation":90909055,"employees":36}]', '2026-11-05T15:53:55.756Z', 'GBP', '2026-11-05T15:53:55.756Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('bb2d3ea2-2a9f-4e87-a906-4d9626bd9775', 'Nivoda', 'nivoda.com', 'https://nivoda.com', 'https://www.linkedin.com/company/nivoda/', 'https://app.dealroom.co/companies/nivoda', 'B2B marketplace for diamonds, gemstones, and jewelry', 'London', 'United Kingdom', 2017, 415, -2.5821595, 69696942, 3, 196896891, 2025, 'operational', '[{"uuid":"2b0ab6f6-0fca-4211-a1af-cba8d93a2cf2","name":"David Sutton"},{"uuid":"5bf700dd-31d7-43c7-85f2-6de8f06397d1","name":"Andre Woons"}]', '{}', '2026-11-05T15:55:23.556Z', 'Nivoda operates a business-to-business (B2B) marketplace designed to streamline the global trade of diamonds and jewelry. The company was founded in 2017 by CEO David Sutton, a serial entrepreneur with a background in the diamond industry, and CTO Andre Woons, a software developer. The idea stemmed from Sutton''s firsthand experience with the inefficiencies of the traditional diamond supply chain, including complex logistics and negotiations with numerous manufacturers. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('badcf0cb-5757-4910-b853-095c6ed86e86', 'Noda', 'noda.ai', 'https://noda.ai/', 'https://www.linkedin.com/company/nodabuildings/', 'https://app.dealroom.co/companies/noda_4', 'IoT made easy. Sensor solutions for smart buildings', 'London', 'United Kingdom', 2018, 81, -8.988764, 94939357, 5, 8379736, 2024, 'operational', '[{"uuid":"7e05e5c1-b6af-48c1-b5ec-c10595b4e04a","name":"William Cowell de Gruchy"}]', '{}', '2026-11-05T15:55:23.556Z', 'Noda is a technology company transforming how buildings operate through intelligent automation and data-driven insights. Combining artificial intelligence (AI) with Internet of Things (IoT) sensors, Noda provides a connected platform that helps organizations make their buildings more efficient, sustainable, and people-centric.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('b81b0c3f-987b-4635-9406-30c294d53532', 'Noxus', 'noxus.ai', 'https://www.noxus.ai/', 'https://www.linkedin.com/company/noxus-ai/', 'https://app.dealroom.co/companies/noxus_1', 'Full-stack platform to build, deploy, and govern AI “co-workers” that automate high-stakes resolution workflows with auditability, compliance, and scalability', 'London', 'United Kingdom', 2023, 34, 126.666664, 1136363, 2, NULL, NULL, 'operational', '[{"uuid":"f519b27a-2a54-4014-9f27-0c24bec5c72e","name":"Jorge Pessoa"},{"uuid":"74681dc4-3430-4992-9d46-d84cd2009779","name":"João Pedro Almeida"},{"uuid":"c30eb31c-db34-4d7e-889a-d442bed462b8","name":"Gonçalo Ferreira"},{"uuid":"662fe884-d2aa-4a84-a8cf-70a7aaeffb2c","name":"Miguel Ribeiro"}]', '{}', '2026-11-05T15:54:35.037Z', 'Noxus offers a no-code platform designed for enterprises to develop, implement, and manage AI-driven solutions for critical operations. The company''s primary offering is a full-stack engine that enables business teams to create and deploy AI-powered "co-workers." These virtual employees are designed to automate complex workflows, such as extracting codes from clinical records for billing and claims submission. The platform includes a workflow builder that allows users to construct, test, and share AI-powered tools and workflows without requiring extensive coding knowledge. This approach aims to make AI capabilities more accessible across large organizations.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('c4751ff0-e7d5-4a00-ada9-5c61f357fc25', 'Nuna', 'holanuna.com', 'http://holanuna.com', 'https://www.linkedin.com/company/discovernuna/', 'https://app.dealroom.co/companies/nuna', 'Builds tools for mental healthcare experts & help users discover the right experts based on their needs', 'Barcelona', 'Spain', 2020, 11, -21.428572, 0, 2, 718939, 2023, 'operational', '[{"uuid":"a97c9e35-9485-4717-883f-5988dcd4dd01","name":"Fredrik Wallgren"},{"uuid":"3bc59104-85c9-4902-9c51-5c56b7908576","name":"Vignesh Anand"}]', '{}', '2026-11-05T15:56:04.243Z', 'Holanuna.com, commonly known as Nuna, is a digital platform that provides easy and affordable access to mental health services. The company operates in the healthcare sector, specifically in the mental health and wellness industry. It serves a broad range of clients, including individuals, couples, and children, by connecting them with certified psychologists, coaches, and therapists from various countries, cultures, and specializations. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('68932201-dd34-4ca0-83b6-19d6eb2baddc', 'Octopus Energy', 'octopusenergy.group', 'https://octopusenergy.group/', 'https://www.linkedin.com/company/octopusenergy/', 'https://app.dealroom.co/companies/octopus_energy', 'Renewable energy supplier with proprietary grid management technology.', 'London', 'United Kingdom', 2015, 5751, 26.395605, 2171211372, 10, 13700000000, 2025, 'operational', '[{"uuid":"639ccce0-e6ab-48d7-9f8a-d129fee27494","name":"James Eddison"},{"uuid":"e8586290-ec05-4460-a116-e2c3ce78ae0a","name":"Pete Miller"},{"uuid":"cda1f436-ca0d-44d0-aceb-79bcf3075a6b","name":"Stuart Jackson"},{"uuid":"dc7b672a-917b-4c63-8ccc-cb615495189c","name":"Greg Jackson"}]', '{}', '2026-11-05T15:55:56.052Z', 'Octopus Energy Group is a British energy technology company founded in 2015 by Greg Jackson with backing from Octopus Group. Jackson, a serial entrepreneur who had previously founded companies like the e-commerce firm C360, started Octopus Energy to disrupt the traditional energy market with a focus on customer service, fair pricing, and renewable energy. His interest in the energy sector was partly fueled by personal experiences with energy supply being cut off during his childhood and frequent bill increases as an adult.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('14da02f4-d957-4e2a-9109-c1c7f64b5c31', 'Odilo', 'letmino.ai', 'https://letmino.ai', 'https://www.linkedin.com/company/odilotid/', 'https://app.dealroom.co/companies/odilo', 'Learning platform enabling organizations to create personalized digital education ecosystems with multimodal content', 'Madrid', 'Spain', 2011, 180, -48.275864, 64060580, 6, 12526855, 2023, 'operational', '[{"uuid":"2d3064c0-5b28-4ddc-9fb9-5d996fb188a7","name":"Rodrigo Rodriguez"}]', '{}', '2026-11-05T15:53:55.756Z', 'Odilo is a Spanish startup that operates in the digital content and e-learning sector. The company provides a comprehensive platform that allows governments, schools, startups, businesses, libraries, and cultural organizations to manage, distribute, and consume digital content. This includes a wide variety of digital titles from various content providers, making it a versatile tool for learning and development.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4bc71366-1b31-480f-92a9-2c296bb40e69', 'Omnia', 'useomnia.com', 'https://useomnia.com', 'https://www.linkedin.com/company/useomnia/', 'https://app.dealroom.co/companies/omnia_5', 'AI-driven platform optimizing brand visibility by identifying high-impact, low-competition topics for SEO and marketing experts', 'Madrid', 'Spain', 2024, 23, 27.777779, 3141665, 2, NULL, NULL, 'operational', '[{"uuid":"905d83d6-1952-4885-8f7e-e0cfefe72edb","name":"Daniel Espejo"}]', '{}', '2026-11-05T15:56:04.243Z', 'Omnia is a Madrid agentic AI-search visibility platform founded in 2025 by Daniel Espejo (CEO; formerly Klarna) and Miguel Fernández (CTO; GitHub/Fastly) that helps brands discover high-demand topics in AI assistants, monitor positioning versus competitors, see which sources engines cite, and launch agents that create and place AI-optimised content. It targets ChatGPT, Perplexity, Google AI Overviews and similar surfaces; early adopters cited include Personio, ElevenLabs, Embat, Trade Republic, Pleo and HappyRobot plus agencies such as MIO group. In October 2025 Omnia raised €3.5 million pre-Seed led by Visionaries Club with KFund and Baobab Ventures, plus angels Carles Reina, Paulo Rodriguez and Hugo Arévalo, to expand topic intelligence, source coverage, agentic placement and international go-to-market. Sources: EU-Startups 16 Oct 2025.', '["Venture Capital","Subscription","SaaS","Angel","Artificial Intelligence","out of stealth","Commission","Enterprise Software","b2c","Early stage"]', '["startup","vc_backed","funded"]', 83.1, 40000, 0, 0, 17499993, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:56:04.243Z', 'GBP', '2026-11-05T15:56:04.243Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('8de65b1e-f7dc-4365-91c7-2e69426ba22d', 'Ona Therapeutics', 'ona-therapeutics.com', 'https://ona-therapeutics.com', 'https://www.linkedin.com/company/ona-therapeutics/', 'https://app.dealroom.co/companies/ona_therapeutics', 'Specializes in the discovery and development of therapeutic biologics targeting the lipid metabolism in order to treat advanced cancer', 'Barcelona', 'Spain', 2019, 43, 22.857143, 100204505, 5, 11340, 2020, 'operational', '[{"uuid":"60f62dd4-ac8e-42b1-aabd-75914c4590fd","name":"Salvador Benitah"},{"uuid":"824fa9b0-37da-435a-abe1-c104395a9a2c","name":"Valerie Vanhooren"}]', '{}', '2026-11-05T15:53:12.600Z', 'ONA Therapeutics is a startup operating in the biotechnology sector, specifically focusing on the development of therapeutic solutions for cancer treatment. The company''s primary clientele includes healthcare providers and patients seeking advanced cancer treatments. ONA Therapeutics operates in a highly specialized market, where the demand for innovative and effective cancer therapies is consistently high.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('7e2c09bd-d423-4a3b-91cd-6d8a752a29a7', 'OneTwoTrip', 'onetwotrip.com', 'http://www.onetwotrip.com', 'https://www.linkedin.com/company/onetwotrip/', 'https://app.dealroom.co/companies/onetwotrip', 'Its users with the ability to compare and buy cheap tickets from more than 800 airlines around the world, including budget airlines that fly to destinations all over the globe', 'London', 'United Kingdom', 2011, 202, -6.0465117, 36613622, 7, 55783220, 2024, 'operational', NULL, '{}', '2026-11-05T15:54:51.538Z', 'OneTwoTrip operates as an online travel agency (OTA), providing a comprehensive platform for booking travel services. The company was established in 2011 by Peter Kutis, a co-founder of a similar venture, Anywayanyday. Initially focusing on flight ticketing, the platform has since expanded its offerings significantly.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('e9f39385-ec00-4142-9ecb-424d0b6512d2', 'Ontruck', 'ontruck.com', 'http://ontruck.com', 'https://www.linkedin.com/company/ontruck-ai/', 'https://app.dealroom.co/companies/ontruck', 'Ontruck is the leading digital transportation company offering the most efficient and low-carbon solution to move freight. We ship thousands of pallets through our connected network of over 4,000 carriers and cross-docks each day', 'Madrid', 'Spain', 2016, 31, -18.421053, 43749982, 4, 13416661, 2021, 'operational', '[{"uuid":"3dcfb7b9-fdff-4809-972f-15a0c7d903a3","name":"Antonio Lu"},{"uuid":"b9a24c97-b7e7-4b81-82c0-cc3d3c7a98db","name":"Samuel Fuentes"},{"uuid":"61719c08-5a8b-4965-ae49-642eaf3ee7f5","name":"Inigo juantegui"}]', '{}', '2026-11-05T15:54:51.538Z', 'Ontruck is a digital logistics company specializing in road freight transport, providing fast and sustainable solutions for businesses. Operating primarily in the logistics sector, Ontruck serves a diverse range of clients including large logistic centers like Amazon, El Corte, and Carrefour. The company leverages technology to offer same-day or next-day deliveries, real-time shipment tracking, and instant pricing comparisons, allowing clients to choose the best options for their needs. Ontruck''s business model focuses on optimizing palletized road transport operations, enabling parcel companies to enhance efficiency and sustainability. Revenue is generated through service fees for freight transport, with a strong emphasis on reducing CO2 emissions and promoting eco-friendly logistics solutions.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('9f5c1c17-b499-4574-a9fd-87d654e6ef87', 'Open Cosmos', 'open-cosmos.com', 'https://www.open-cosmos.com/', 'https://www.linkedin.com/company/opencosmos/', 'https://app.dealroom.co/companies/open_cosmos', 'End-to-end small satellite missions, connectivity and Earth-observation intelligence', 'Harwell', 'United Kingdom', 2015, 319, 70.588234, 336333201, 10, 29700000, 2024, 'operational', '[{"uuid":"def2aabc-03b8-4281-8571-9750891b999e","name":"Jordi Barrera Ars"},{"uuid":"30c37b81-db19-4b09-97f0-abc98809a253","name":"Aleix Megias Homar"},{"uuid":"97eb0946-cc57-4a41-a281-f44f6e5228c2","name":"Rafael Jorda Siquier"}]', '{}', '2026-11-05T15:55:56.052Z', 'Open Cosmos is a Harwell (UK) space company that designs, manufactures, launches and operates small satellites and turns orbital data into actionable intelligence for governments, agencies and enterprises. Founded in 2015 by Rafel Jordà Siquier (CEO) with Aleix Megias Homar (COO), it offers OpenOrbit end-to-end missions, OpenConstellation shared satellite infrastructure, ConnectedCosmos broadband/IoT space communications and DataCosmos AI-powered Earth-observation analytics, with four European factories able to build about one satellite a day and nearly 400 employees across the UK, Spain, Portugal and Greece. In September 2026 Open Cosmos secured €300 million led by European investors including ETF Partners, Lightrock, BCI, ICF and Entrepreneurs First, with Convex, NSSIF, Phoenix Court (LocalGlobe/Latitude) and Claret Capital Partners, to expand manufac