INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('6e938082-d8a1-49b8-bb00-736958d617e6', 'Opply', 'opply.com', 'https://www.opply.com/', 'https://www.linkedin.com/company/opply/', 'https://app.dealroom.co/companies/opply', 'AI-powered supply chain platform for F&B ingredients', 'London', 'United Kingdom', 2021, 46, 31.428572, 8712118, 2, NULL, NULL, 'operational', '[{"uuid":"03dcc5a9-77c8-4a26-bae2-e2774e70821e","name":"Helen M"},{"uuid":"c74ba743-bc92-46bb-a34c-25c62a1c091f","name":"Martin Postel"}]', '{}', '2026-11-05T15:53:18.240Z', 'Opply provides an AI-driven platform that streamlines ingredient sourcing, ordering, and payment for the food and beverage industry. Founded in London in 2021 by CEO Helen Murphy and CTO Martin Postel, the company aims to simplify the complex supply chain process for small and medium-sized enterprises (SMEs). The founders'' experience, including Murphy''s background in consumer goods at Procter & Gamble and Bain and Postel''s PhD in AI in Manufacturing, shaped Opply''s mission to address the challenges they observed in the market. 
