INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('be47d618-f555-446e-b528-4e68dea27d62', 'Paddle', 'paddle.com', 'https://paddle.com/', 'https://www.linkedin.com/company/paddle/', 'https://app.dealroom.co/companies/paddle', 'The only complete payments infrastructure provider for SaaS companies', 'London', 'United Kingdom', 2012, 438, 12.307693, 220725672, 7, 97000000, 2025, 'operational', '[{"uuid":"7d8ec571-d6eb-4867-ad16-272dcc027def","name":"Harrison Rose"},{"uuid":"8022f4f7-1786-4819-beb0-0fb14d0a5204","name":"Christian Owens"}]', '{}', '2026-11-05T15:56:26.553Z', 'Paddle is a comprehensive platform designed to simplify the complexities of software sales, particularly for SaaS (Software as a Service) companies. It provides a suite of tools that help software developers manage billing, payments, tax compliance, and customer support, allowing them to focus on product development rather than administrative tasks. Paddle operates in the global software market, serving clients ranging from small startups to large enterprises.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('fe3f9d67-d8e3-490d-9125-35c9a0ad5212', 'Pandabikes', 'pandabikes.es', 'https://pandabikes.es', 'https://www.linkedin.com/company/pandago/', 'https://app.dealroom.co/companies/pandabikes', 'The first sustainable electric mobility marketplace', 'Madrid', 'Spain', 2020, 39, 25.806452, 3916665, 1, 1760443, 2023, 'operational', '[{"uuid":"7bc27480-c181-412b-bd6b-bf9925a5c6b3","name":"Francisco Acosta"},{"uuid":"e96ad9c4-f3b7-456f-92bd-3f719dd510d0","name":"Andres Soler"}]', '{}', '2026-11-05T15:53:55.756Z', 'Pandago, operating as Pandabikes.es, is a specialized B2B platform focused on accelerating the adoption of sustainable urban mobility for companies across Spain. Founded in Madrid in 2021 by Francisco Acosta, Andrés Soler, and Mariano Galán, the company provides comprehensive electric vehicle renting and fleet management solutions. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2a7317a1-34a6-42dc-878e-ab6c10b57ccb', 'PassEntry', 'passentry.com', 'http://passentry.com', 'https://www.linkedin.com/company/passentry/', 'https://app.dealroom.co/companies/passentry', 'PassEntry - Your Digital NFC Pass', 'London', 'United Kingdom', 2019, 29, -6.451613, 5799392, 5, NULL, NULL, 'operational', '[{"uuid":"1208c254-5c38-43fd-ae0b-3857f4ffd52e","name":"Josh Shepherd"},{"uuid":"3ffc486d-e6a7-4547-a808-b31c931decac","name":"Nico Cary"}]', '{}', '2026-11-05T15:55:36.049Z', 'PassEntry is an innovative startup that leverages Near Field Communication (NFC) technology to streamline access and tracking for various applications. The company offers a digital pass system that replaces traditional plastic membership cards, event tickets, and contractor timesheets with a more efficient and eco-friendly solution. By using NFC, PassEntry ensures frictionless entry and real-time logging, making it ideal for membership clubs, events, workplaces, and educational institutions.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('56f3da8c-dca5-46b1-9610-523145e80fe2', 'Passionfruit', 'usepassionfruit.com', 'https://www.usepassionfruit.com', 'https://www.linkedin.com/company/usepassionfruit/', 'https://app.dealroom.co/companies/passionfruit_', 'The freelancing platform for Gen Z marketers', 'London', 'United Kingdom', 2021, 97, 6.5934067, 10075754, 3, 378788, 2022, 'operational', '[{"uuid":"d28d5863-44f8-4ba3-a0fc-595b7e67fb1b","name":"Joshua Jooste"},{"uuid":"7ca38ddc-6d2c-4c54-89e5-98ea24acb6d0","name":"Issah Abdul-Moomin"},{"uuid":"b74fbf1b-f387-4e59-b676-bb605a6f8b41","name":"Raffi Salama"}]', '{}', '2026-11-05T15:54:35.037Z', 'Passionfruit is a marketing startup that connects businesses with pre-vetted marketing specialists. The company operates in the digital marketing industry, serving clients across various sectors. Its primary clientele includes businesses seeking to enhance their marketing efforts without the stress and time constraints of traditional hiring processes. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('ce8ff517-aae9-41da-8f5c-4d66a769956d', 'Patients Know Best', 'patientsknowbest.com', 'https://www.patientsknowbest.com/', 'https://www.linkedin.com/company/patients-know-best/', 'https://app.dealroom.co/companies/patients_know_best', 'Health records software for patients and medical organisations', 'Cambridge', 'United Kingdom', 2008, 98, 7.6923075, 17391874, 9, 10984844, 2023, 'operational', '[{"uuid":"9ef83f09-37e3-4409-89e2-1e1dd6672149","name":"Ian Bastow"},{"uuid":"0c7384fa-ce0a-4371-9ae0-65738de73e37","name":"Mohammad Al-Ubaydli"}]', '{}', '2026-11-05T15:54:12.521Z', 'Patients Know Best is a social enterprise and technology platform that consolidates patient data from various health and social care providers into a single, secure personal health record. The platform serves patients, healthcare providers, and social care organizations, primarily in the United Kingdom. By enabling patients to share their medical records with family, carers, and healthcare professionals, the platform aims to improve the quality and efficiency of care. Patients Know Best operates in the healthcare technology market, focusing on patient empowerment and data integration. The company generates revenue through subscription fees from healthcare providers and organizations that use its platform. Founded by Dr. Mohammad Al Ubaydli, the company leverages a granular consent model to ensure data privacy and security, allowing patients to control who can access their information. This approach has led to more coordinated and patient-centered care for over 5.2 million citizens in the U.K. alone.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('72279f7d-bde1-4427-9d2e-9667ef3f5cce', 'Payflow', 'payflow.es', 'https://www.payflow.es/', 'https://www.linkedin.com/company/payflow-es/', 'https://app.dealroom.co/companies/payflow', 'An innovative application that allows colleagues to charge when they need it, with one click', 'Alcobendas', 'Spain', 2020, 84, -6.6666665, 24753020, 9, 5833331, 2025, 'operational', '[{"uuid":"c9460729-5492-4940-ba43-c50a71a6b8bc","name":"Avinash Sukhwani"},{"uuid":"adcfd421-d1df-4155-a1e2-0beb7a75e29e","name":"Benoit Menardo"}]', '{}', '2026-11-05T15:54:35.037Z', 'Payflow is a comprehensive financial wellness application operating in the Spanish market. The startup primarily serves employers and their employees, providing a platform that allows workers to access their earned wages at any point during the month. This gives employees the flexibility to manage their finances according to their needs, rather than being restricted to traditional monthly pay cycles. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('23c4eb9c-523c-4158-9c90-29c817776ce1', 'Peanut', 'peanut-app.io', 'http://peanut-app.io', 'https://www.linkedin.com/company/peanut-app/', 'https://app.dealroom.co/companies/peanut', 'Social connection platform for women''s life stages', 'London', 'United Kingdom', 2016, 46, 6.976744, 12882571, 4, NULL, NULL, 'operational', '[{"uuid":"99ed7003-ebb2-469f-81cc-30aa186f5b51","name":"Michelle Kennedy"}]', '{}', '2026-11-05T15:53:18.240Z', 'Peanut App Ltd. operates an online social network exclusively for women, focusing on life stages such as fertility, pregnancy, motherhood, and menopause. The company was co-founded in London, UK, in 2017 by Michelle Kennedy, who serves as CEO, and Greg Orlowski. Kennedy, formerly the deputy CEO of the dating app Badoo and an inaugural board member of Bumble, drew from her professional background and personal experience of feeling isolated as a new mother to create the platform. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('652b74a8-a39e-4039-b609-3268b2f63f8d', 'PeoplePerHour', 'peopleperhour.com', 'http://www.peopleperhour.com', 'https://www.linkedin.com/company/peopleperhour/', 'https://app.dealroom.co/companies/peopleperhour', 'Marketplace connecting small businesses and freelance employees', 'London', 'United Kingdom', 2007, 4117, 5.7810893, 6224241, 4, NULL, NULL, 'operational', '[{"uuid":"55cd9ee6-8dd1-47fe-aacf-c8012270b2a0","name":"Xenios Thrasyvoulou"}]', '{}', '2026-11-05T15:53:18.240Z', 'PeoplePerHour is an online platform that connects businesses with freelancers for a wide range of projects. Operating in the global freelance market, it serves small to medium-sized enterprises (SMEs) and individual entrepreneurs who require specialized skills on a project-by-project basis. The platform allows clients to post projects and receive bids from freelancers, ensuring competitive pricing and a broad selection of talent. PeoplePerHour generates revenue through service fees charged to freelancers and clients for using the platform. The business model is designed to provide cost-effective solutions by leveraging the gig economy, where freelancers offer services in areas such as web development, graphic design, content writing, and digital marketing. The platform''s key features include a business cost calculator, success stories for inspiration, and a comprehensive guide to hiring freelancers. By facilitating the hiring process and offering a secure environment for transactions, PeoplePerHour aims to streamline business operations and help clients achieve their project goals efficiently.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('e084d6f2-ee73-4ce6-b2ac-04309e1af1b3', 'Perk', 'perk.com', 'https://www.perk.com/', 'https://www.linkedin.com/company/perk/', 'https://app.dealroom.co/companies/perk_3', 'Formerly TravelPerk. Integrated business‐platform streamlining corporate travel booking, expense processing and spend control', 'Barcelona', 'Spain', 2015, 2241, 11.160714, 493408894, 10, 272727164, 2025, 'operational', '[{"uuid":"6661a321-aba3-4cf0-9c8b-f627cc18e509","name":"Avi Meir"},{"uuid":"68a48ce2-6815-4aa9-8261-ce505c9a60e9","name":"Javier Suarez"},{"uuid":"9820e0f9-d89b-4673-89ec-6ed1074f8e0e","name":"Ron Levin"}]', '{}', '2026-11-05T15:53:04.860Z', 'Perk (formerly TravelPerk) is a Barcelona-founded business travel and spend platform that unifies booking, expenses, invoices, events and corporate cards with AI-driven policy controls for finance and operations teams, serving more than 12,000 companies from dual hubs in Boston and London. After a Series E in January 2025 and the Yokoy acquisition to deepen spend management, in June 2026 Perk closed a $300 million private credit facility—debt, not equity—led by Neuberger Specialty Finance with Blue Owl Capital, Hercules Capital and Liquidity, upsizing and replacing a prior $134 million line on improved terms, to fund product, AI and a US launch of its integrated spend platform after crossing about $300 million annualised revenue. Sources: TNW 4 Jun 2026; Fintech Global; Tech.eu June 2026 top deals.', '["corporate","data management","social media marketing software","databas