INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2f8a14ba-0a87-4083-9111-f97454a3dce7', 'Plain', 'plain.com', 'http://plain.com', 'https://www.linkedin.com/company/plainsupport/', 'https://app.dealroom.co/companies/plain_1_1', 'Plain is an API-first customer service platform for modern companies', 'London', 'United Kingdom', 2020, 58, 34.88372, 16628781, 2, 1022727, 2023, 'operational', '[{"uuid":"2b277ef3-a792-44a7-8b3f-dc5cabf299ca","name":"Matt Vagni"},{"uuid":"4ea688fa-6509-4610-a8f1-f761e9ee4391","name":"Simon Rohrbach"}]', '{}', '2026-11-05T15:53:18.240Z', 'Plain operates a customer support platform specifically engineered for business-to-business (B2B) companies. Founded in 2020 by Simon Rohrbach and Matt Vagni, the London-based company aims to streamline customer interactions by unifying them into a single, powerful inbox. The founders'' experience at Deliveroo, where they helped scale the company significantly, informed their approach to building systems for high-growth businesses. Rohrbach led a 40-person design team, while Vagni was instrumental in building design systems and internal tools. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('5073f707-722a-458d-a4d1-99f08a15ba8e', 'Pompeii', 'pompeiibrand.com', 'https://www.pompeiibrand.com/', 'https://www.linkedin.com/company/pompeiibrand/', 'https://app.dealroom.co/companies/pompeii', 'Pompeii is a Madrid based footwear startup', 'Madrid', 'Spain', 2014, 83, 18.571428, 833333, 1, 4289830, 2022, 'operational', '[{"uuid":"bcda2378-79f8-4a5d-97d8-1765ab3086d4","name":"Jorge Vidri Salgado"},{"uuid":"3415f58a-1f25-4aea-a4c6-2971564a73cd","name":"Cosme Sans"},{"uuid":"65b3be24-cf31-4103-a206-8410fd6feac2","name":"Nacho Salgado"}]', '{}', '2026-11-05T15:54:35.037Z', 'Pompeii Brand is a sustainable fashion company that specializes in eco-friendly clothing and footwear. The company targets environmentally conscious consumers who prioritize sustainability in their purchasing decisions. Operating in the fashion retail market, Pompeii Brand employs a direct-to-consumer business model, selling its products through its online store and physical retail locations. Revenue is generated through the sale of high-quality, stylish apparel and shoes that are designed with sustainability in mind. The company emphasizes the use of eco-friendly materials and ethical manufacturing processes to minimize its environmental impact. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('cec4ddcd-38f3-4a34-9935-1f7782195586', 'Primer', 'primer.io', 'https://primer.io', 'https://www.linkedin.com/company/primerapi/', 'https://app.dealroom.co/companies/primer_co', 'Payment infrastructure for merchants to orchestrate checkout, routing and reconciliation across providers', 'London', 'United Kingdom', 2019, 310, 31.355932, 75757545, 2, 14018831, 2025, 'operational', '[{"uuid":"8d014496-fcc8-4f59-8f9c-7a785b41c1b7","name":"Gabriel Le Roux"},{"uuid":"b7c6a6ef-7b05-41f7-af92-a616f84c02f7","name":"Paul Anthony"}]', '{}', '2026-11-05T15:54:12.521Z', 'Primer is a London payments infrastructure company founded in 2020 by former Braintree and PayPal leaders that gives finance and payments teams a unified platform across checkout to payout, recording hundreds of data points per transaction so merchants can orchestrate processors, improve authorisation rates and run AI on complete payment context. Customers include GetYourGuide, Dialpad and Printful; the company processes billions of transactions a year and reports roughly a fifth of revenue from the US with ARR doubling year-on-year. Its Primer Companion AI agent helps merchants answer payment queries and is expanding toward autonomous optimisation within merchant-defined parameters. In May 2026 Primer raised a €86.2 million ($100 million) Series C led by Sofina with Peak XV Partners and existing backers Balderton, Accel, ICONIQ, Tencent and Speedinvest, bringing total funding to about €146.6 million ($170 million) to scale AI capabilities and US growth. Sources: EU-Startups / company 20 May 2026.', '["data management","static site generator","uk is8 financial services","software as a service","data security","sales","accounting","chat","human resource management system","Venture Capital","e-commerce platforms","web fonts","recruitment marketing","marketing","Core AI","Subscription","SaaS","sales enablement","marketing automation","customer relationship management","human resources","Angel","frameworks and libraries","communication and collaboration","development","event management","content management system","Fintech","storage","Payments","enterprise","risk and compliance","AI Agents","payroll management and benefits administration","it infrastructure","web frameworks","source code management","open source","data warehousing","b2b","Artificial Intelligence","tag management","No-Code and Low-Code Software","team collaboration","widgets","search engines","enterprise mobility management","software framework","api management","content delivery network","programming languages","documentation tools","payment processing","software","enterprise resource planning","web & portal technology","web conferencing","miscellaneous","programming","AI Applications","cloud infrastructure computing","governance-risk and compliance","e-commerce","dev tools","javascript libraries","intelligence and analytics","containers","Late stage","real user monitoring","analytics","inventory and order management","devops","API","online banking","security","issue trackers","Payment Orchestration","operating systems & computing languages","cloud hosting","web analytics","platform as a service","uk is8 digital and technologies","application development & management","javascript frameworks","fraud detection and prevention","Other Payment Infrastructure","multichannel retail software","Payment Processing","live chat","communications technology","font scripts","lead generation","Embedded Payments","applicant tracking systems","tools","producti