INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('38ef4409-85ad-4523-8341-86d418edf20e', 'Prodigy Finance', 'prodigyfinance.com', 'http://prodigyfinance.com', 'https://www.linkedin.com/company/prodigy-finance/', 'https://app.dealroom.co/companies/prodigy_finance', 'Crowdsourced funding for talented international students', 'London', 'United Kingdom', 2007, 163, -23.474178, 39772711, 2, 19100000, 2024, 'operational', '[{"uuid":"9fcac6bf-db04-4521-b9a7-1516b80a2824","name":"Cameron Stevens"}]', '{}', '2026-11-05T15:53:18.240Z', 'Prodigy Finance operates as a fintech platform focused on providing education loans to international postgraduate students. The company was founded in 2007 by three INSEAD MBA graduates, Cameron Stevens, Miha Zerko, and Ryan Steele, who identified a critical funding gap for students from emerging markets wishing to attend top-tier universities globally. The initial idea stemmed from founder Cameron Stevens'' own difficulties in financing his degree as an international student. The concept was developed during their MBA program and gained initial recognition at the 2006 International Venture Capital Investment Competition at INSEAD.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('b828dd4c-4309-4a37-8d63-9b7544526eb6', 'Prosper', 'letsprosper.io', 'http://letsprosper.io', 'https://www.linkedin.com/company/prosperyouth/', 'https://app.dealroom.co/companies/prosper_10', 'Safe MasterCard prepaid debit card with a mobile banking app for young people aged under 18', 'London', 'United Kingdom', 2012, 27, -6.8965516, 8375754, 2, NULL, NULL, 'operational', NULL, '{}', '2026-11-05T15:53:18.240Z', 'A whitelabel platform that enables businesses to create and launch their own youth banking solutions and card schemes. The end-to-end solution is designed for rapid deployment, allowing companies to get a youth card program operational within a couple of months.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('df489fcf-5a86-4998-b818-be869ce12e4a', 'Qargo', 'qargo.com', 'https://qargo.com', 'https://www.linkedin.com/company/qargo-tms/', 'https://app.dealroom.co/companies/qargo_tms', 'Intelligent cloud TMS for European road freight', 'London', 'United Kingdom', 2020, 225, 73.07692, 38607485, 3, NULL, NULL, 'operational', '[{"uuid":"3f61e3f6-34b1-4566-b3e2-2a92bd48d728","name":"Adriaan Coppens"},{"uuid":"766d92ca-e252-463d-8c81-b22a211e91e8","name":"Sander De Wilde"},{"uuid":"d09b7b7b-520f-450d-b5ca-5481df1e3bc5","name":"Joeri De Turck"}]', '{}', '2026-11-05T15:54:12.521Z', 'Qargo is a Ghent-based cloud Transport Management System (TMS) founded in 2020 by Adriaan Coppens that helps carriers, freight forwarders and 3PLs digitise the full road-transport cycle from order entry and planning to load building, invoicing and reporting. Qargo Intelligence, its AI layer, automates repetitive admin and optimisation so customers can cut empty running and reclaim planner time; press cites invoicing through the platform rising from about €479 million to more than €2.1 billion a year and the customer base expanding from roughly 100 to over 400 after Series A. In December 2025 Qargo raised €28 million ($33 million) Series B led by Sofina with returning Balderton Capital, taking total investment to €46 million ($54 million), to scale the team, markets and agentic AI product while remaining independent. Sources: EU-Startups 11 Dec 2025.', '["data management","data security","Venture Capital","recruitment marketing","editors","ad exchanges","marketing automation","frameworks and libraries","testing and qa","performance","system analytics & monitoring","software development","it infrastructure","wikis","open source","travel and expense management","database management","b2b","web platform extensions","Artificial Intelligence","tag management","team collaboration","web servers","programming languages","Commission","Breakout stage","audio-video-graphics","advertising","generative ai","web and application servers","cloud infrastructure computing","business intelligence","governance-risk and compliance","account-based marketing","dev tools","javascript libraries","intelligence and analytics","analytics","other audio-video-graphics software","devops","Mobility","Transportation","security","operating systems & computing languages","cloud hosting","web analytics","platform as a service","uk is8 digital and technologies","application development & management","consent management","web design and development services","applicant tracking systems","design","ui frameworks","accounting and finance","certificates","continuous integration","machine learning","operating systems","web tools and plugins","web hosting"]', '["startup","rising_star","vc_backed","funded"]', 94.58, 61000, 1, 27, 141644943, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:54:12.521Z', 'GBP', '2026-11-05T15:54:12.521Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('b7303e1c-4475-4947-af31-aca08365ab43', 'Qida', 'qida.es', 'https://qida.es', 'https://www.linkedin.com/company/qida-atencion-domiciliaria-home-care/', 'https://app.dealroom.co/companies/qida', 'Tech-enabled home eldercare and caregiver platform across Spain', 'Sabadell', 'Spain', 2018, 603, 18.467583, 49916647, 6, 31666654, 2025, 'operational', '[{"uuid":"4dfa9b0a-8359-405e-a122-9d6771489f25","name":"Oriol Fuertes Cabassa"},{"uuid":"1cedb54c-b579-4920-a3da-403de245855f","name":"Lluís Guitart Moya"}]', '{}', '2026-11-05T15:53:55.756Z', 'Qida (Caring Well, S.L.) is a Sabadell HealthTech and social-impact company founded in 2018 by Oriol Fuertes Cabassa (CEO), Anna Montañés and Guillem Garcia that provides integrated home care for dependent and chronically ill seniors in Spain. The model combines a digital caregiver marketplace and matching platform with proactive monitoring, public-system partnerships, specialised insurance products and an acquisition strategy that has absorbed multiple regional home-care providers; press cites hundreds of staff, thousands of caregivers ("Qiders") and B-Corp status. In November 2025 Qida raised €37 million led by Quadrille Capital with Asabys Partners, the Cofides-managed Social Impact Fund (FIS), Institut Català de Finances, Endeavor Catalyst and returning Kibo Ventures, Creas and Ship2B—described as Spain''s largest eldercare round—bringing total funding cited to about €57 million across four rounds. Capital funds city expansion, technology and team growth toward serving 100,000 seniors and ~€100 million revenue by 2027. Sources: EU-Startups 4 Nov 2025.', '["Health Platform","data management","database","elderly care","accounting","Home Healthcare","help desk software","human resource management system","hris management","Venture Capital","e-commerce platforms","web fonts","recruitment marketing","editors","visual and user generated content marketing","it service management","marketing","enterprise content management","customer relationship management","human resources","social sharing","page builders","frameworks and libraries","communication and collaboration","development","testing and qa","content management system","storage","other advertising software","online video platforms","marketing analytics","system analytics & monitoring","payroll management and benefits administration","it infrastructure","web frameworks","source code management","open source","web platform extensions","unified communications","tag management","demand side platforms","team collaboration","widgets","web servers","Digital Care","search engines","software framework","customer service","Hard Tech","content delivery network","programming languages","audio-video-graphics","advertising","payment processing","Tech for Medical Professionals","web and application servers","miscellaneous","programming","Silver Economy","cloud infrastructure computing","contact center solutions","business intelligence","e-commerce","dev tools","javascript libraries","wordpress plugins","intelligence and analytics","video players","customer experience management","education management","Late stage","real user monitoring","analytics","marketing data providers","devops","issue trackers","operating systems & computing languages","cloud hosting","web analytics","platform as a service","Health","b2c","javascript frameworks","consent management","live chat","communications technology","font scripts","web design and development services","payroll processing","file sharing","soci