INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('02978c71-1214-4968-b288-2e79939d66c4', 'Quartz', 'myquartz.ai', 'https://myquartz.ai', 'https://www.linkedin.com/company/quartzwealth/', 'https://app.dealroom.co/companies/quartz_6', 'Personal finance app with an AI banker for everyday investors', 'London', 'United Kingdom', 2025, 14, 40, 2750000, 1, NULL, NULL, 'operational', '[{"uuid":"14a0d66c-b1e9-481e-80b1-85122a82632c","name":"Mateus Mesquita Alves"},{"uuid":"7148d6bc-38f7-46b1-b5ad-b15e3e8007d2","name":"André Silva"}]', '{}', '2026-11-05T15:56:04.243Z', 'Quartz is a London fintech founded in 2025 by former Revolut Head of Global Expansion André Silva (CEO) and former N26 Investment Product Lead Mateus Mesquita Alves, building a personal finance platform that consolidates pensions, ISAs, savings and investments in one app and pairs them with personalised guidance.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('9b09a172-e8b9-44ba-a360-bda36aa8d7f6', 'Quibim', 'quibim.ai', 'https://quibim.ai', 'https://www.linkedin.com/company/quibim/', 'https://app.dealroom.co/companies/quibim', 'Producer of whole body radiological image analysis based on Artificial Intelligence', 'Valencia', 'Spain', 2015, 116, 3.5714285, 50695434, 8, 1612669, 2023, 'operational', '[{"uuid":"fdb1739d-58a5-4fd4-a6c2-d88ee883940e","name":"Luis Marti-Bonmati"},{"uuid":"51984df8-3a38-46d8-b179-9496146d168b","name":"Angel Alberich-Bayarri T"}]', '{}', '2026-11-05T15:56:04.243Z', 'Quibim operates in the healthcare technology sector, specializing in advanced medical imaging solutions. The company serves a diverse range of clients, including hospitals, research institutions, and radiology departments. Quibim''s core offering is an AI-driven ecosystem that provides specialized imaging suites for different body parts, enabling comprehensive and precise analysis. This technology generates objective and quantifiable clinical data, facilitating better diagnosis and treatment planning. The business model is primarily B2B, generating revenue through the sale of its imaging software solutions and associated services. Quibim''s market is global, targeting healthcare providers looking to enhance their imaging capabilities with cutting-edge AI technology. The company differentiates itself by offering a holistic imaging solution that covers the entire body, unlike competitors who may focus on specific areas. 
