INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('05616157-1f4d-4217-a638-6b3b974e80dd', 'ROLI', 'roli.com', 'https://roli.com/', 'https://www.linkedin.com/company/roli/', 'https://app.dealroom.co/companies/roli', 'Reinventing the musical instrument', 'London', 'United Kingdom', 2009, 216, -10.743802, 33668168, 8, 8376925, 2024, 'operational', '[{"uuid":"53fa6ab6-cd4f-4a3d-bd56-8a51a1a3ed65","name":"Corey Harrower"},{"uuid":"5b7d8b0a-da9d-4e42-b51f-dcdbca66be59","name":"Roland Lamb"}]', '{}', '2026-11-05T15:53:18.240Z', 'ROLI is a pioneering company in the music technology industry, specializing in the development of innovative musical instruments and software designed to enhance creative expression and music learning. The company serves a diverse range of clients, including professional musicians, music educators, and hobbyists, by offering products that make the process of music creation more inspiring and effective. ROLI operates in the global market, with a particular focus on expanding its community of creators in regions such as Australia and New Zealand. The business model revolves around the sale of hardware products like the Seaboard RISE 2 and Seaboard BLOCK M, as well as software solutions such as Equator2 and ROLI Studio. Revenue is generated through direct sales on their website, partnerships with music retailers, and software subscriptions. 
