INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('e07833e3-8c7f-4576-a5da-04d6c9859db4', 'Red Points', 'redpoints.com', 'http://www.redpoints.com/', 'https://www.linkedin.com/company/redpoints/', 'https://app.dealroom.co/companies/red_points_bag', 'The most widely used solution to recover digital revenue', 'Barcelona', 'Spain', 2011, 324, -2.9940119, 65201489, 8, 27844057, 2023, 'operational', '[{"uuid":"96a06e12-bdac-4fec-bd51-4c1074d0eac5","name":"Rachid Sguiar"}]', '{}', '2026-11-05T15:55:23.556Z', 'Red Points was founded in 2011 by Josep Coll, an intellectual property lawyer, with the vision of creating a technology-driven solution to combat online brand abuse. In 2012, David Casellas joined as a co-founder, bringing his expertise to help shape the company''s direction.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2a795625-e68b-4bc3-adb4-9f593b977a9f', 'Relevant Traffic', 'relevantgroup.media', 'https://relevantgroup.media', 'https://www.linkedin.com/company/relevant-traffic/', 'https://app.dealroom.co/companies/relevant_traffic', 'Digital Marketing Consultancy specialised in acquisition and based in Spain, Mexico and most of LatAm markets', 'Madrid', 'Spain', 2001, 41, -24.074074, 8579542, 3, 4856672, 2024, 'operational', '[{"uuid":"b8de431a-265e-4c14-8c1f-38f28d33f913","name":"Michael Kleindl"}]', '{}', '2026-11-05T15:54:35.037Z', 'Relevant Traffic is a leading consultancy on digital marketing specialised on direct response and with a customized service for each project.  The mission is to maximize the customer''s ROI (return on investment) and brand-awareness through online marketing, offering services for Online Strategy, Paid Media, SEO, Web-Analytics, Optimisation and Usability Consulting, Social Media Strategy, Online Reputation Management, Community Management, Display and Customized Trainings.  The staff is constituted by professionals, with deep expertise on the market and multi-channel campaigns, certified by the main search engines and natives for international services.   The client portfolio includes global and european enterprises, related to e-commerce to travel agencies, airlines, main hotel chains, and IT and telco, fashion, banking and insurance companies.  Part of Plenummedia Group since May 2013.', '["database","sales","Venture Capital","web fonts","marketing","Subscription","marketing