INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2426608b-a737-478d-9ff4-fe6f3b584bde', 'Remuner', 'remuner.com', 'https://www.remuner.com/', 'https://www.linkedin.com/company/remuner/', 'https://app.dealroom.co/companies/remuner', 'AI-powered sales compensation and variable pay automation', 'Barcelona', 'Spain', 2023, 22, 10, 6333331, 3, NULL, NULL, 'operational', '[{"uuid":"13d2db0d-e22c-4ea4-9acb-5065b7725e15","name":"Matias Haro"},{"uuid":"5e8b5139-03ea-4c37-8586-20a1c1aa0da3","name":"Iván Ruz Ruz"},{"uuid":"5a44765f-31d4-415d-8baa-44fcca52d247","name":"Sergio Gonzalez Gaspar"},{"uuid":"7f469eff-f4e2-44be-9e93-a13beaefd1ad","name":"Sergio Gonzalez"}]', '{}', '2026-11-05T15:54:35.037Z', 'Remuner is a Barcelona-based sales compensation platform that automates variable pay from plan design to payout, giving commercial teams no-code plan design, commission automation and an AI Compensation Manager for personalised goal guidance. Founded by CEO Sergio González and team, the product connects to core customer systems and is used by European organisations in pharma, telecom, industry, real estate and digital services, including Europastry, Fluidra, Redpin, MasOrange, Alfasigma, Theydo and CoverManager. In September 2025 Remuner raised a $6.5 million Seed round led by Seaya, with significant participation from Pear VC and continued backing from existing investors; Beatriz González (Seaya) and Pepe Agell (Pear VC) joined the board. Proceeds fund international expansion and further AI product development across major European markets. Sources: Tech.eu