INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('5c403feb-78bf-472f-ae46-c2bcccf92e9f', 'Research Grid (R.grid)', 'rgrid.tech', 'https://rgrid.tech/', 'https://www.linkedin.com/company/rgrid/', 'https://app.dealroom.co/companies/r_grid', 'AI-powered automation engine for admin-free clinical trials', 'Norwich', 'United Kingdom', 2018, 36, 20, 10593356, 4, 340909, 2023, 'operational', '[{"uuid":"e96bd21f-234c-4739-83fd-d6bd20b40ef9","name":"Amber Michelle H"}]', '{}', '2026-11-05T15:54:51.538Z', 'Research Grid (R.grid) is a technology company that has developed an AI-native automation engine to streamline clinical trials. Founded in 2020 by Dr. Amber Hill, a former medical researcher with a PhD in biomedical neuroscience and a background in AI research technology, the company aims to make clinical trials faster and more successful by automating administrative tasks. Dr. Hill identified the problem of researchers being burdened with excessive back-office paperwork and set out to create a solution that eliminates manual administration from patient sourcing to trial management. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('d2a41dfa-2e50-40af-9768-d06bb631232e', 'Resource Guru', 'resourceguruapp.com', 'http://resourceguruapp.com', 'https://www.linkedin.com/company/resource-guru/', 'https://app.dealroom.co/companies/resource_guru', 'Cloud-based team scheduling software', 'London', 'United Kingdom', 2011, 29, 7.4074073, 850000, 2, 1969696, 2023, 'operational', '[{"uuid":"496fd677-6c05-42cd-862c-1fcd3624bbbf","name":"Chandni Chugh"},{"uuid":"f9530729-6c24-4295-9ab9-3bbcfe068c09","name":"Percy Stilwell"},{"uuid":"ff7ee5ab-9c5d-46b8-be4d-8e9cbad958e1","name":"Percy Stilwell"},{"uuid":"c7767be2-d866-4fd9-a20b-6cba9e5f9160","name":"Andrew Rogoff"}]', '{}', '2026-11-05T15:53:18.240Z', 'Resource Guru is a software company specializing in resource scheduling and project management solutions. The platform is designed to help businesses efficiently allocate their resources, including team members, equipment, and facilities, by providing real-time availability and scheduling features. Resource Guru serves a diverse range of clients, from small businesses to large enterprises, across various industries such as marketing, IT, and consulting. The company operates in the SaaS (Software as a Service) market, offering subscription-based access to its platform. Revenue is generated through tiered subscription plans, which vary based on the number of users and features required. The business model focuses on providing a scalable and user-friendly solution that enhances productivity and project management efficiency. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('bab26999-7eeb-4d42-ad8c-804d1da7b288', 'Revolut', 'revolut.com', 'https://revolut.com/', 'https://www.linkedin.com/company/revolut/', 'https://app.dealroom.co/companies/revolut', 'Digital banking platform for global money management', 'London', 'United Kingdom', 2015, 20814, 38.86183, 2816968570, 11, 7100000000, 2026, 'operational', '[{"uuid":"bc03a52f-7ed2-4917-a517-a3c8f6cf03ca","name":"Vlad Yatsenko"},{"uuid":"c9175cc7-a44d-4479-b284-1fd58bfb4f00","name":"Nikolay Storonsky"}]', '{}', '2026-11-05T15:53:04.860Z', 'Revolut is a London-based financial technology company that runs a global banking and money app for individuals and businesses. In one mobile app, personal customers can hold multi-currency accounts, spend with debit and credit cards, send money abroad, exchange currencies, save, budget, invest in stocks, ETFs and crypto, and take out insurance and loans where available. It also offers accounts for children and teens and a separate crypto exchange, Revolut X.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('1b393146-6130-496d-89bf-2b23e581bb68', 'Ricall', 'ricallmusic.com', 'https://www.ricallmusic.com', NULL, 'https://app.dealroom.co/companies/ricall', 'Crowdsourced exchange for (1) licensing music for use in videos and (2) selling and distributing digital downloads', 'London', 'United Kingdom', 1998, 11, 0, 11545452, 5, NULL, NULL, 'operational', NULL, '{}', '2026-11-05T15:54:12.521Z', 'Established in 2000, Ricall operates as a music supervision company, offering a comprehensive suite of services that includes music research, rights clearance, bespoke compositions, and re-record services. The firm caters to a wide array of clients, from global advertising agencies and major brands to independent filmmakers, assisting them in finding the perfect soundtrack for their projects. Ricall''s business model revolves around creating, sourcing, and clearing music for various productions like major advertising campaigns, social media content, films, and trailers. They have worked with notable brands such as Samsung, Jet2, M&S, Coca-Cola, and Volkswagen. 
