INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('078ff2fb-6f53-4a38-a7a8-03df63227df7', 'Sava', 'sava.health', 'http://sava.health', 'https://www.linkedin.com/company/savahealth/', 'https://app.dealroom.co/companies/sava_3', 'Minimally invasive continuous glucose monitors', 'London', 'United Kingdom', 2019, 171, 52.67857, 47727254, 6, NULL, NULL, 'operational', '[{"uuid":"ec8d9aac-ca7c-465f-9130-dc04dac10251","name":"Rafaël Michali"},{"uuid":"1d072b34-2c32-4815-8825-1b33a2a9b528","name":"Renato Circi"}]', '{}', '2026-11-05T15:54:12.521Z', 'Sava Technologies Ltd. is a London-based health technology company working to shift healthcare from a reactive to a preventative and data-driven model. Founded in 2019 by bioengineers Renato Circi and Rafaël Michali, the company emerged from their work at Imperial College London. Both founders were passionate about personal health monitoring and recognized the limited access individuals have to their own molecular health data. Their research in the lab that invented modern glucose strip technology provided them with a deep understanding of the potential and limitations of existing biosensing technologies.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f0cb334c-4d67-4d60-b528-8c50846ad779', 'Savana', 'savanamed.com', 'http://savanamed.com', 'https://www.linkedin.com/company/savanamed/', 'https://app.dealroom.co/companies/medsavana', 'Savana is a unique company at leveraging AI to generate global and deep Real World Evidence, thus enabling a data-driven healthcare', 'Madrid', 'Spain', 2014, 152, 8.571428, 38284833, 5, 937788, 2023, 'operational', '[{"uuid":"14ba0c12-a3c4-4bf9-8c8c-6a5fd9005465","name":"Nacho HM"},{"uuid":"5e1583a4-05a0-4bea-80c2-eb1a4457da65","name":"Alberto Giménez Ramón-Borja"},{"uuid":"8f977237-1869-4d66-8e76-b38b2eb53b5c","name":"Ignacio Medrano"},{"uuid":"26991252-e38c-444e-86b3-351c147b9704","name":"Jorge Tello Guijarro"}]', '{}', '2026-11-05T15:54:35.037Z', 'Savana is a healthcare technology company that specializes in transforming unstructured clinical records into structured Big Data using advanced Artificial Intelligence (AI). The company serves a diverse range of clients including private practices, small medical institutions, primary care centers, and larger healthcare organizations. Operating in the health informatics market, Savana''s core business model revolves around providing AI-driven solutions that unlock the clinical value embedded within electronic health records (EHRs). By converting free-text clinical notes into actionable data, Savana enables healthcare providers to generate clinical research hypotheses, conduct observational studies, predict clinical events, and understand epidemiological behaviors. The company generates revenue through subscription-based models and customized solutions tailored to the specific needs of its clients. Savana''s innovative technology supports decision-making in real-life cases, offering a significant advantage in the rapidly evolving field of health science.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('df9a5b98-46d6-4c68-a0c0-907d0f831171', 'Scarlet', 'scarlet.cc', 'http://scarlet.cc', 'https://www.linkedin.com/company/scarlet-comply/', 'https://app.dealroom.co/companies/scarlet1', 'EU & UK certification for AI medical devices', 'London', 'United Kingdom', 2020, 103, 58.46154, 58636343, 4, 1590908, 2023, 'operational', '[{"uuid":"a8f780d6-5e5c-48d5-b33b-474c29bb5eaa","name":"James Dewar"},{"uuid":"80397276-6e85-4478-a8cc-621c85cfcd02","name":"Jamie Cox"}]', '{}', '2026-11-05T15:54:51.538Z', 'Scarlet is a startup that operates in the healthcare technology sector, specifically focusing on the certification of Software Medical Devices. The company has identified a gap in the market where the current regulatory environment is not adequately equipped to handle the rapidly evolving field of health and medicine software. To address this, Scarlet has developed a framework that enables both manufacturers and regulators to build and monitor software products in a scalable and continuous manner. 
