INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('48bab6e9-5ef8-41ac-80da-4338767fd8a2', 'Seabery', 'seaberyat.com', 'https://seaberyat.com', 'https://www.linkedin.com/company/seabery/', 'https://app.dealroom.co/companies/seabery', 'The worldwide leading company in the development of educational solutions with Augmented Reality technology', 'Huelva', 'Spain', 2008, 136, -3.5460992, 916666, 2, 14076022, 2024, 'operational', '[{"uuid":"a9c0dfb8-08b0-44f3-a48c-c718cd39d9d8","name":"Basilio Marquínez"},{"uuid":"699d7487-dfbb-49b4-a5dd-a55ed3d61f18","name":"Basilio Marquinez"}]', '{}', '2026-11-05T15:54:35.037Z', 'Seabery is a pioneering company in the field of Augmented Reality (AR) technology, specializing in welding training solutions. The company offers a comprehensive AR-based platform designed to enhance the learning process for both beginner students and professional welders. Seabery''s solutions feature a wide catalog of welding joints based on real practices and the development of customized joints, making the training dynamic and flexible. This allows instructors to manage multiple courses and students of varying skill levels, learning paces, and locations effectively.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('eaa2af6d-b5bd-436a-9f3a-c705f7fc843f', 'Seamflow', 'seamflow.com', 'https://seamflow.com', 'https://www.linkedin.com/company/seamflow/', 'https://app.dealroom.co/companies/seamflow', 'AI-powered workflows for testing, inspection, and certification.', 'London', 'United Kingdom', 2024, 21, NULL, 3409090, 1, NULL, NULL, 'operational', '[{"uuid":"a6e4d74d-27f1-46b4-92d8-1462ea5b4eeb","name":"Konstantin Klingler"},{"uuid":"332cca8e-0e9a-453c-87cb-f350aefc0063","name":"Yusuf Kırçova"}]', '{}', '2026-11-05T15:55:23.556Z', 'Seamflow is a London-based software company developing an AI-native operating system for the Testing, Inspection, and Certification (TIC) industry. Founded in 2024 by CEO Konstantin Klingler and CTO Yusufhan Kircova, the company aims to resolve bottlenecks in regulatory compliance and product certification processes that hinder innovation. Both founders, in their mid-twenties, experienced these certification constraints firsthand in regulated industries. Klingler, a Forbes 30 Under 30 honoree and Schwarzman Scholar, previously co-founded the book delivery startup Lobu in Vienna and has experience in venture capital and startups across the US, Asia, and Europe. Kircova previously developed manufacturing software at Bosch and ERP systems at SAP and conducted research in machine learning and computer vision at University College London and Johns Hopkins. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4cd35390-2508-41a5-b453-cf48be8a6fcb', 'Secret Escapes', 'secretescapes.com', 'http://www.secretescapes.com/', 'https://www.linkedin.com/company/secret-escapes/', 'https://app.dealroom.co/companies/secret_escapes', 'Exclusive, members-only discounted offers for hotels and luxury holidays', 'London', 'United Kingdom', 2010, 529, -5.8718863, 220030281, 8, 190778000, 2024, 'operational', '[{"uuid":"67fc3588-f914-4040-bad0-a9bd6a17b6ef","name":"Alex Saint"},{"uuid":"b2ade9f4-e89f-4809-b869-8f3447614ae5","name":"Tom Valentine"}]', '{}', '2026-11-05T15:53:18.240Z', 'Secret Escapes is a UK-based startup that specializes in offering luxury travel experiences at significantly reduced prices. The company operates an online platform where members can access exclusive deals on high-end hotels and holiday packages. Membership is free, and users can save up to 70% on curated travel options. The platform serves over 20 million members primarily in the UK but also caters to international clients.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('9e0aeab7-744a-42e4-9c52-e1c6eb9d2ecb', 'SeedLegals', 'seedlegals.com', 'https://seedlegals.com/', 'https://www.linkedin.com/company/seedlegals/', 'https://app.dealroom.co/companies/seedlegals', 'Simple way for startups and investors to complete legals needed to raise investment and distribute equity', 'London', 'United Kingdom', 2016, 135, -11.184211, 3757574, 2, 29696958, 2023, 'operational', '[{"uuid":"bb6b990b-926d-46e4-a476-8d98d5e33c24","name":"Anthony Drogon"},{"uuid":"9a124db9-d27d-41a6-9b36-9ec6cc407e47","name":"Laurent Laffy"},{"uuid":"3a15de39-ab36-40f9-b001-55d25ad362b2","name":"Anthony Rose"}]', '{}', '2026-11-05T15:53:18.240Z', 'SeedLegals operates as a legal technology platform designed to automate the legal processes required by startups, primarily focusing on fundraising, cap table management, and team incentivization.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('ff6ece07-d076-4def-a6d4-1e7c753e5f51', 'Seedtag', 'seedtag.com', 'http://seedtag.com/', 'https://www.linkedin.com/company/seedtag/', 'https://app.dealroom.co/companies/seedtag', 'Contextual advertising technology that leverages the power of machine learning to provide human-like understanding of the content', 'Madrid', 'Spain', 2014, 718, -10.807453, 250083233, 6, 149999940, 2023, 'operational', '[{"uuid":"95a5053b-b1d8-43a5-9c28-8f883ea72cab","name":"Albert Nieto"},{"uuid":"fe3b51dd-6e47-4651-8aaf-3c937b15f81e","name":"Jorge Poyatos"}]', '{}', '2026-11-05T15:55:36.049Z', 'Seedtag is a digital advertising startup that operates in the privacy-first era. The company offers solutions to advertisers and publishers, helping them engage with their audiences in a more meaningful and effective way. Seedtag''s primary service is its contextual advertising technology, named Liz, which uses artificial intelligence to place ads in the right context, at the right time, and to the right mindset of the audience. This technology helps advertisers elevate their advertising strategy and connect with their audience more effectively.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f7971cb4-5ee4-4192-8472-748f1dbfcccf', 'Selina Finance', 'selinafinance.co.uk', 'http://selinafinance.co.uk', 'https://www.linkedin.com/company/selina-finance-limited/', 'https://app.dealroom.co/companies/selina_finance_1', 'Flexible home equity lines of credit (HELOCs).', 'London', 'United Kingdom', 2019, 112, 23.076923, 39272716, 2, 18650964, 2025, 'operational', '[{"uuid":"851aaa53-d666-415f-9824-56f5b0f89b41","name":"Leonard Benning"},{"uuid":"8d742f8e-2a2e-4d39-8403-cd79fe6506ff","name":"Hubert Fenwick"}]', '{}', '2026-11-05T15:55:56.052Z', 'Selina Finance is a fintech lender that introduced the U.K.''s first Home Equity Line of Credit (HELOC). Founded in 2019 by Hubert Fenwick, Andrea Olivari, and Leonard Benning, the company aims to provide homeowners with a flexible and affordable way to access the equity in their properties. The concept was born after Fenwick observed the widespread use of HELOCs in the U.S. and identified a gap in the U.K. market where homeowners lacked similar accessible options to fund significant purchases or consolidate debt. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('aa498a0d-0c42-4e2a-b16a-e0a6687d64dc', 'Shakers', 'shakersworks.com', 'https://www.shakersworks.com/', 'https://www.linkedin.com/company/shakersworks/', 'https://app.dealroom.co/companies/shakers', 'Workforce orchestration for tech freelancers and hybrid AI teams', 'Madrid', 'Spain', 2020, 202, 26.25, 17083326, 3, 5393937, 2023, 'operational', '[{"uuid":"d16c759b-d146-4457-8f03-baa1985f39bb","name":"Nico de Luis"},{"uuid":"57d50564-5679-492d-90fa-f6fcf15ebf60","name":"Nico de Luis"},{"uuid":"12becc25-2407-47c4-8e32-9317c1c5a051","name":"Héctor Mata"},{"uuid":"52767584-69d5-443d-bf9a-9af15a516aa2","name":"Adrian De Pedro"},{"uuid":"ae38c355-cfdb-43be-ab77-d7ee28938456","name":"Jaime Castillo"}]', '{}', '2026-11-05T15:56:04.243Z', 'Shakers is a Madrid workforce-orchestration platform founded in 2021 by Héctor Mata (CEO), Nico de Luis (COO), Adrián de Pedro (CPO) and Jaime Castillo (CRO) that connects companies with specialised tech freelancers and autonomous AI agents for complex projects. The product combines AI matchmaking and pre-vetting (Shakers Verified) with a Freelancer OS of embedded services so businesses can assemble hybrid teams quickly; press cites 450+ client companies including Microsoft, Inditex and Telefónica and a community of more than 10,000 freelancers, with strong recurring and cross-European revenue. In May 2025 Shakers raised €14 million Series A led by Partech with KFund, Brighteye Ventures, Athos Capital and Wayra to expand across Europe, grow the team and deepen AI agent integrations toward orchestrating over 10,000 hybrid projects by 2027. Sources: Partech / EU-Startups 13 May 2025.', '["corporate","accelerator","data management","database","logging","Venture Capital","Jobs Recruitment","editors","ad exchanges","SaaS","marketing automation","customer relationship management","Angel","frameworks and libraries","communication and collaboration","development","deployment","content management system","4YFN 2024","storage","online video platforms","performance","system analytics & monitoring","software development","it infrastructure","web frameworks","source code management","b2b","tag management","team collaboration","web servers","content delivery network","programming languages","Commission","Breakout stage","audio-video-graphics","advertising","payment processing","B2b Online Marketplace","site search","web and application servers","miscellaneous","cloud infrastructure computing","e-commerce","dev tools","javascript libraries","intelligence and analytics","video players","Enterprise Software","real user monitoring","analytics","devops","4YFN","issue trackers","Freelancers","operating systems & computing languages","cloud hosting","web analytics","data integration","platform as a service","javascript frameworks","consent management","Marketplace & ecommerce","blogs","4YFN 2025","design","Decent Work And Economic Growth (#8)","ui frameworks","continuous integration","configuration management","cookie compliance","Human Resources","containerization","operating systems","web tools and plugins"]', '["startup","rising_star","vc_backed","funded"]', 88.62, 66000, 1, 10, 69999972, NULL, NULL, NULL, NULL, '[{"year":2023,"revenue":5393937,"ebitda":null,"profit":null,"rnd":null,"valuation":29999988,"employees":null},{"year":2024,"revenue":5393937,"ebitda":null,"profit":null,"rnd":null,"valuation":29999988,"employees":91},{"year":2025,"revenue":5393937,"ebitda":null,"profit":null,"rnd":null,"valuation":69999972,"employees":160},{"year":2026,"revenue":5393937,"ebitda":null,"profit":null,"rnd":null,"valuation":69999972,"employees":202}]', '2026-11-05T15:56:04.243Z', 'GBP', '2026-11-05T15:56:04.243Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0098bd56-59d1-4a28-9eaf-ce2115fa8343', 'Shalion', 'shalion.com', 'http://shalion.com', 'https://www.linkedin.com/company/shalion/', 'https://app.dealroom.co/companies/shalion', 'Digital shelf solutions for brands and retailers', 'Barcelona', 'Spain', 2019, 143, 7.518797, 4591665, 2, 1116119, 2023, 'operational', '[{"uuid":"e379c480-1302-42c6-b595-b8fc2044aa7b","name":"German Loewe"},{"uuid":"1ff10a08-0dc2-4d87-b001-070c7d4cd839","name":"Valeria Bellani"}]', '{}', '2026-11-05T15:54:35.037Z', 'Shalion.com is a digital platform that provides brands with comprehensive visibility and control over their online retail presence, also known as the Digital Shelf. The company operates in the rapidly growing eCommerce market, serving global brands and eRetailers. Shalion''s business model revolves around providing tools and services that allow brands to optimize their product information across hundreds of retailers, apps, and locations. This includes monitoring and controlling product availability, content, pricing, promotions, ratings, and reviews. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('251d9709-6a88-482e-a501-dbf650580511', 'Sherpa.ai', 'sherpa.ai', 'https://sherpa.ai/', 'https://www.linkedin.com/company/sherpa-ai/', 'https://app.dealroom.co/companies/sherpa_ai', 'Researching and building Artificial Intelligence-based technology and products', 'Erandio', 'Spain', 2012, 18, NULL, 49370025, 11, 8585, 2022, 'operational', '[{"uuid":"30f02503-71fc-4ef2-9dd3-7be21b1b55d1","name":"Xabi Uribe-Etxebarria"}]', '{}', '2026-11-05T15:55:09.655Z', 'Sherpa.ai is a pioneering startup specializing in Privacy Preserving Artificial Intelligence (AI). The company offers an enterprise-grade, privacy-compliant solution designed to facilitate data collaborations without compromising privacy. Sherpa.ai''s flagship product is its Federated Learning platform, which allows organizations to build and train AI models using sensitive data from various sources—such as business units, customers, or partners—without actually sharing the data. This ensures that privacy is maintained and regulatory compliance is achieved.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('d5b3bb92-8c09-4e7b-a9cf-1ad0e150b965', 'Smol products', 'smolproducts.com', 'https://smolproducts.com', 'https://www.linkedin.com/company/smolproducts/', 'https://app.dealroom.co/companies/smolproducts', 'Producing high performance, eco-friendly laundry capsules and dishwash tablets', 'London', 'United Kingdom', 2018, 141, 12.8, 32000000, 2, 44700000, 2025, 'operational', '[{"uuid":"c76fb96f-4dfc-4a64-8bd9-616395752899","name":"Paula Quazi"},{"uuid":"f89d50f8-26ae-4183-96ea-0e4010a5a5c0","name":"Nick Green"}]', '{}', '2026-11-05T15:54:12.521Z', 'Smol products, established in 2018 by co-founders Paula Quazi and Nick Green, operates as a direct-to-consumer challenger in the home care market. The company''s inception was driven by the founders'' shared experience within the consumer goods industry, notably at Unilever, where they identified a gap for affordably priced, eco-conscious cleaning solutions. Quazi''s background in life sciences and extensive experience in product development, combined with Green''s commercial expertise, provided the foundation for a business model that bypasses traditional retail channels. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('b8bdd4d5-dad0-4987-aadc-955be185064c', 'Sofar Sounds', 'sofarsounds.com', 'http://www.sofarsounds.com', 'https://www.linkedin.com/company/sofarsounds/', 'https://app.dealroom.co/companies/sofar_sounds', 'Global music community, hosting secret events', 'London', 'United Kingdom', 2009, 745, 6.2767477, 34765138, 5, 9615845, 2024, 'operational', '[{"uuid":"dfb4dd4b-965a-4bb7-b840-15594187909f","name":"Rafe Offer"},{"uuid":"ef43488b-f852-4dca-89b5-b2900656ee6a","name":"Rastiningdyah T. Sryantoro"}]', '{}', '2026-11-05T15:53:18.240Z', 'Sofar Sounds operates as a global music community that bridges the gap between artists and audiences through distinctive live music events and artist services. Originating from a living room in London, the company has expanded organically to host events in 78 countries. Sofar Sounds is renowned for its non-traditional approach to live music, organizing secret concerts in unconventional venues such as living rooms, galleries, breweries, and rooftops. These unique settings provide a platform for artist discovery and foster a sense of community and connection among attendees. The company also offers artist services aimed at helping performers manage their fan relationships and build sustainable careers. Sofar Sounds generates revenue through ticket sales for its live events and by providing various services to artists. The company serves a diverse clientele, including music enthusiasts seeking unique concert experiences and artists looking to grow their fan base and sustain their creative endeavors.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('52b8ae4b-10e2-456d-b54d-3ceda663e42e', 'SolveAI', 'solve.ai', 'https://solve.ai/', 'https://www.linkedin.com/company/solve-ai/', 'https://app.dealroom.co/companies/solveai', 'AI platform for building production-ready enterprise applications', 'London', 'United Kingdom', 2025, 23, 2200, 37878773, 2, NULL, NULL, 'operational', '[{"uuid":"a377d801-121a-4b8a-bdc0-338c91f192e4","name":"Steve Basher"}]', '{}', '2026-11-05T15:55:23.556Z', 'SolveAI is a London platform that lets non-technical employees build production-ready, IT-compliant enterprise software through AI-powered conversations. Founded in July 2025 by Steve Basher, a former Palantir engineer, it turns natural-language requests into full-stack applications that deploy on a company’s existing infrastructure and connect securely to systems such as Salesforce, SAP, ServiceNow, Snowflake and GitHub. The workflow starts with a written proposal and technical specification that teams can iterate before specialised agents handle UX, frontend and backend development; forward-deployed engineers help ensure reliable integration. Emerging from stealth in February 2026, SolveAI disclosed a $5 million Accel-led pre-seed and a $45 million Series A led by GV (Google Ventures), with Northzone, Mantis VC and NeverLift, to expand engineering across North America and Europe and deepen partnerships in manufacturing, retail and financial services. Sources: Tech.eu 25 Feb 2026; solve.ai.', '["Venture Capital","Core AI","Subscription","SaaS","sales enablement","customer relationship management","Angel","performance","AI Agents","b2b","genAI Applications","Artificial Intelligence","No-Code and Low-Code Software","advanced analytics and data science","content delivery network","Breakout stage","Conversational AI","web & portal technology","miscellaneous","programming","javascript libraries","Natural Language Processing","intelligence and analytics","Enterprise Software","analytics","security","web analytics","Automation Solutions","uk is8 digital and technologies","application development & management","Software Development","Machine Learning","machine learning","web tools and plugins"]', '["startup","rising_star","vc_backed","funded"]', 92.95, 5500, 0, 0, 204545373, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:55:23.556Z', 'GBP', '2026-11-05T15:55:23.556Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('5f0796d0-989c-4824-9c89-ed14735702ca', 'Sona', 'sona.ai', 'https://www.sona.ai/', 'https://www.linkedin.com/company/getsona/', 'https://app.dealroom.co/companies/sona_1_2', 'The modern app designed for the new era of frontline work, offering powerful productivity tools within a sleek, intuitive, and user-friendly interface', 'London', 'United Kingdom', 2021, 253, 48.82353, 61893915, 4, 3333332, 2023, 'operational', '[{"uuid":"3f0c84d4-7862-4ae8-b7c6-c2ccec8ebd94","name":"Steffen Wulff Petersen"},{"uuid":"910d6e46-f948-45cf-9f3d-da8816e597de","name":"Ben Dixon"},{"uuid":"3ff860f4-bece-4294-98de-8b807668e50a","name":"Oli Johnson"},{"uuid":"d7af3346-0587-4dd4-8f78-ffa80edcc152","name":"Steffen Wulff Petersen"}]', '{}', '2026-11-05T15:55:23.556Z', 'Sona is a workforce management platform specifically designed for businesses with frontline employees, a segment that constitutes 80% of the global workforce. The company primarily targets sectors such as hospitality (specifically hotel groups), retail, and logistics, offering a software solution to streamline operations for this demographic.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2ef6d28d-c488-414d-a724-f3c853bdc5e9', 'Sourceful', 'sourceful.com', 'https://www.sourceful.com', 'https://www.linkedin.com/company/sourceful-com/', 'https://app.dealroom.co/companies/sourceful', 'Our sourcing and supply chain platform specialises in finding the most sustainable auxiliary goods that accompany your company''s core products', 'Manchester', 'United Kingdom', 2020, 65, 51.162792, 24393930, 3, 10227269, 2023, 'operational', '[{"uuid":"fda2e612-0b1b-414c-aaf7-abfd40209799","name":"Sharon C."},{"uuid":"f3dd1ad5-5175-4224-a432-5862f732e3da","name":"Wing Chan"}]', '{}', '2026-11-05T15:53:18.240Z', 'Sourceful is a forward-thinking startup that leverages the power of artificial intelligence (AI) to revolutionize the packaging industry. The company primarily serves climate-conscious brands that are looking to switch to more sustainable packaging solutions. Sourceful operates in the packaging market, which is a critical component of supply chains across various industries, including food and beverage, e-commerce, and subscription services.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('585da5a7-3367-440d-9773-741256d0d655', 'Splice Bio', 'splice.bio', 'https://splice.bio', 'https://www.linkedin.com/company/splicebio/', 'https://app.dealroom.co/companies/proteodesign', 'A biotech company based on intein technologies developed in the Muir Lab at Princeton University', 'Barcelona', 'Spain', 2012, 57, 7.5471697, 145356002, 5, 137695, 2023, 'operational', '[{"uuid":"daa38438-03aa-4b22-9bd4-29679c441433","name":"Silvia Frutos"},{"uuid":"aaf8b43b-2905-4c69-a741-20e3fb978408","name":"Miquel Vila- Perelló"}]', '{}', '2026-11-05T15:53:12.600Z', 'Splice Bio is a biotechnology company that specializes in the development of gene therapies for genetic diseases. The company''s approach is centered around its proprietary Protein Splicing platform, which is designed to overcome the size limitations of adeno-associated virus (AAV) vectors. This platform enables the delivery of large genes that would otherwise not fit into a single AAV, thereby expanding the range of diseases that can be targeted with gene therapy.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3dc38d3a-9505-44cf-8a15-22fd3e2f5c57', 'Spotahome', 'spotahome.com', 'https://www.spotahome.com', 'https://www.linkedin.com/company/spotahome/', 'https://app.dealroom.co/companies/spotahome', 'The easiest way to find and book mid to-long term residential rentals online', 'Madrid', 'Spain', 2014, 167, -5.6497173, 80825725, 13, 12499995, 2025, 'operational', '[{"uuid":"dc3a0f6f-bc50-4582-ad73-66bd10739ea7","name":"Alejandro Artacho"}]', '{}', '2026-11-05T15:54:35.037Z', 'Spotahome is a digital platform that simplifies the process of renting mid to long-term housing entirely online. The company operates in the European rental market, catering to a diverse range of clients including students, professionals, and expatriates looking for rooms, studios, apartments, and other types of housing. Spotahome''s primary markets include major cities such as Barcelona, Berlin, Brussels, Dublin, Florence, Lisbon, London, Madrid, Milan, Paris, Porto, Rome, Valencia, and Vienna.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('fb80e2d6-d8b3-412d-bfeb-cfc37f5b5f59', 'Statement', 'statementpayments.com', 'https://www.statementpayments.com/', 'https://www.linkedin.com/company/tuzapayments/', 'https://app.dealroom.co/companies/statement_', 'Payment provider comparison marketplace for small businesses', 'London', 'United Kingdom', 2023, 27, 3.8461537, 5500000, 2, NULL, NULL, 'operational', '[{"uuid":"eff8a083-d6a9-442a-a499-4adeb363d897","name":"Olivia Stannah"},{"uuid":"570df136-6505-4c13-9730-0c8060cab841","name":"Ed Hardy"}]', '{}', '2026-11-05T15:55:23.556Z', 'Statement, which rebranded to Tuza, is a UK-based platform focused on changing payment processing for small to medium-sized businesses (SMBs). The company was founded by Ed Hardy and Liv Passey. In June 2023, while operating as Statement, the company raised £1.5 million in a pre-seed funding round led by Northzone, with participation from angel investors. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('be1d9aba-2c3f-462e-8e6a-6b39a5fac402', 'Stream', 'stream.co', 'http://stream.co', 'https://www.linkedin.com/company/wagestream/', 'https://app.dealroom.co/companies/stream_22', 'Building Financial Resilience for your Workforce', 'Stroud', 'United Kingdom', 2018, 306, 6.25, 166371147, 6, 84300000, 2026, 'operational', '[{"uuid":"6c649ace-7d24-4ed5-a933-7497cbf30c48","name":"Reuben Alexander Saxon"},{"uuid":"cc3daa49-4083-4375-a746-9c2871a34a87","name":"Josh Vernon"},{"uuid":"e52505cf-deb8-4116-8266-537fe1526a90","name":"Peter Briffett"},{"uuid":"01a3c9f8-238c-4b4a-a614-38391424b273","name":"Portman Wills"},{"uuid":"8c8ee0f9-4ba2-4430-9905-1adb9cc83dd4","name":"Serge Kotlyarov"}]', '{}', '2026-11-05T15:54:12.521Z', 'Wagestream, founded in 2018 and headquartered in London, operates a financial wellbeing platform offered by employers to their staff. The company primarily serves sectors with a large proportion of frontline workers, including retail, hospitality, and healthcare, with notable clients such as Asda, Bupa, and the NHS.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('01a7aa8b-eff5-49b2-9149-ccdcbd87891c', 'Submer Technologies', 'submer.com', 'https://submer.com', 'https://www.linkedin.com/company/submer/', 'https://app.dealroom.co/companies/submer_technologies', 'Immersion Cooling Solution for Data Centers', 'Rubí', 'Spain', 2015, 194, 33.793102, 82707873, 6, 124999950, 2025, 'operational', '[{"uuid":"0233aa18-ffde-4a95-95e5-d2ef30358257","name":"POL VALLS"},{"uuid":"6dfa738d-31a6-45cc-aa4c-6fe39c0c28ca","name":"Pol Valls Soler"},{"uuid":"d406b2ba-dd90-4344-8e6a-22a56f190d1d","name":"Daniel Pope"}]', '{}', '2026-11-05T15:55:09.655Z', 'Submer is a pioneering company in the data center industry, specializing in advanced cooling solutions. The company offers a range of products designed to enhance the efficiency and sustainability of data centers. Their flagship products include the SmartPodX, SmartPodXL, and MicroPod, all of which utilize immersion cooling technology. This technology involves submerging electronic components in a special liquid coolant to dissipate heat more effectively than traditional air cooling methods.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('073db290-7ffe-4ad8-8422-a318a8a569f2', 'Sunhero', 'sunhero.com', 'https://sunhero.com', 'https://www.linkedin.com/company/sunhero/', 'https://app.dealroom.co/companies/sunhero', 'Sunhero''s mission is to provide easy and affordable access to high quality residential rooftop solar', 'Barcelona', 'Spain', 2021, 12, -20, 11249995, 2, NULL, NULL, 'operational', '[{"uuid":"e626b106-64e9-47dd-9a19-5402839a5098","name":"Stefan Braun"},{"uuid":"9d95003c-21c0-48ff-926c-7a056dfa9d82","name":"Christopher Cederskog"}]', '{}', '2026-11-05T15:55:36.049Z', 'Sunhero is a solar energy company that provides comprehensive solar panel installation services. The company primarily serves homeowners across the country, operating in the renewable energy market. Sunhero''s business model is centered around making solar energy accessible and affordable for all. They offer tailored quotes and studies within 24 hours, and once an agreement is formalized, they guarantee installation within a month. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('953aa895-960b-46a6-a146-08220d4a7001', 'Supercede', 'supercede.com', 'https://supercede.com/', 'https://www.linkedin.com/company/supercedehq/', 'https://app.dealroom.co/companies/riskbook', 'A hyperconnected reinsurance marketplace, radically improving the placement experience for brokers and underwriters', 'London', 'United Kingdom', 2019, 31, -8.823529, 16363632, 4, 2121211, 2023, 'operational', '[{"uuid":"25182024-125d-40e9-85e6-45deb69df4f1","name":"Jerad Leigh"},{"uuid":"b2153811-252d-40f7-9ea9-3c52395cd33c","name":"Jezen Thomas"},{"uuid":"9fb10d20-5eca-4bc9-8caf-c7fb8c476746","name":"Ben Rose"}]', '{}', '2026-11-05T15:55:09.655Z', 'Supercede is a global reinsurance platform that provides digital tools for cedents, brokers, and underwriters. The platform is designed to streamline and optimize the reinsurance lifecycle, from data preparation to deal management and submission.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('376f2a4f-2539-43d9-a3c6-c2e3b00b6574', 'Supersolid', 'supersolid.com', 'http://supersolid.com', 'https://www.linkedin.com/company/supersolid/', 'https://app.dealroom.co/companies/supersolid', 'Supersolid is a mobile games studio based in London, UK.', 'London', 'United Kingdom', 2012, 46, -2.1276596, 3030302, 3, NULL, NULL, 'operational', '[{"uuid":"eca4bed9-2903-49fa-b1e4-3daf973f1294","name":"Michelle Chuang"},{"uuid":"3e813292-c353-4d40-a74b-009c76bb0544","name":"Tommy Chuang"},{"uuid":"143cb5f0-a5e0-494a-ac29-30908a75904a","name":"Edward Chin"},{"uuid":"70d57957-ffa8-4acb-944e-e2aa4a1ea2f0","name":"Kenneth Fejer"}]', '{}', '2026-11-05T15:53:18.240Z', 'Supersolid is a London-based independent mobile games studio founded in 2012 by Kenneth Fejer, Michelle Chuang, Tommy Chuang, and Ed Chin. The founding team brought together extensive experience from prominent gaming companies like EA and Playfish, where they had worked on successful social and mobile games. This background in creating engaging online experiences shaped Supersolid''s direction from its inception.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f7b13448-fc43-43eb-bd42-57a84eb842bd', 'Swap', 'swap-commerce.com', 'http://swap-commerce.com', 'https://www.linkedin.com/company/sw-ap/', 'https://app.dealroom.co/companies/swap_7', 'Unified software platform streamlining logistics, compliance, returns and inventory for cross-border ecommerce', 'London', 'United Kingdom', 2021, 382, 66.08696, 114931772, 4, 20833325, 2025, 'operational', '[{"uuid":"3dbce04c-631f-4b59-96d0-639b8d2463f9","name":"Zach Bailet"},{"uuid":"cc4c62da-b869-4b4a-8ed9-a7a9b4e4e16f","name":"Sam Atkinson"}]', '{}', '2026-11-05T15:53:04.860Z', 'Swap-Commerce.com is a pioneering startup that redefines the returns process for online retailers by offering a unique blend of returns management and flexible financing solutions. The company operates in the e-commerce market, serving small to medium-sized online stores that seek to improve their returns and exchanges experience while managing cash flow more effectively.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('854b7994-cd71-4a5f-ae80-33f22b41bc00', 'Swoon', 'swooneditions.com', 'http://www.swooneditions.com', 'https://www.linkedin.com/company/swoon-editions/', 'https://app.dealroom.co/companies/swoon_editions', 'Direct-to-consumer, data-driven, handcrafted designer furniture', 'London', 'United Kingdom', 2012, 64, 14.285714, 21515149, 4, 10585017, 2025, 'operational', '[{"uuid":"afa763e0-0642-4b5d-9d18-e533b67ae0a5","name":"Brian H"},{"uuid":"eebaee82-6b8f-4f10-9dfb-b74559346e3c","name":"Debbie Williamson"},{"uuid":"eda382ef-ada3-4e4b-8638-a7d643f3a8c1","name":"Brian Harrison"}]', '{}', '2026-11-05T15:53:18.240Z', 'Swoon is a London-based, direct-to-consumer furniture brand founded in 2012 by Debbie Williamson and Brian Harrison. Williamson, with a background in digital product development and advertising, and Harrison, a former CEO of kgb deals, identified a gap in the market for beautifully designed, affordable furniture. The idea originated from Williamson''s personal experience of finding high-quality furniture to be prohibitively expensive. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('d34ab566-7392-44cd-b7bd-786b54cc0c53', 'Sylvera', 'sylvera.com', 'http://sylvera.com', 'https://www.linkedin.com/company/sylveracarbon/', 'https://app.dealroom.co/companies/sylvera', 'Carbon data and intelligence platform for net-zero investments', 'London', 'United Kingdom', 2020, 151, -0.65789473, 73787849, 4, 5129000, 2025, 'operational', '[{"uuid":"2d3cc5cd-cee6-4565-a726-745c659a0b9f","name":"Allister Furey."}]', '{}', '2026-11-05T15:53:18.240Z', 'Sylvera is a carbon data provider that develops machine learning-based tools to track and evaluate carbon offset projects. Founded in London in 2020 by CEO Dr. Allister Furey and Samuel Gill, the company aims to bring transparency to the voluntary carbon markets. The founding was a meeting of minds, with Furey, a serial entrepreneur with a Ph.D. in machine learning and a decade in the renewables sector, providing the technological expertise, and Gill contributing domain knowledge as a corporate lawyer focused on ESG and carbon markets. Their shared vision was that for carbon markets to be effective tools against climate change, they required an independent and accurate source of data free from conflicts of interest. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2edf6753-ac10-4675-beff-339d29a7cce8', 'Symbe', 'symbe.co', 'http://symbe.co', 'https://www.linkedin.com/company/symbe/', 'https://app.dealroom.co/companies/symbe', 'An AI-powered platform that automates and standardizes the creation of business cases, enabling value-selling at scale', 'London', 'United Kingdom', 2023, 20, 11.111111, 5739558, 3, NULL, NULL, 'operational', '[{"uuid":"aea3b575-30fb-4e88-9127-cf260ad313b1","name":"Martin Blinder"},{"uuid":"22aff58a-2eb9-48a8-80e0-f57eef73309d","name":"Thomas Laurbjerg"},{"uuid":"6ccca238-f927-4988-9407-83a8d1e81231","name":"Thomas Laurbjerg"},{"uuid":"28c1c460-da57-4e3f-9632-d59ce2276b93","name":"Xavier Wilders"}]', '{}', '2026-11-05T15:56:04.243Z', 'Symbe.co is an innovative startup that operates in the business solutions market, specifically focusing on sales and customer relationship management. The company offers a Collaborative Business Case platform designed to automate the creation of business cases and proposals. This platform aims to match the quality of the best sales representatives, thereby enhancing efficiency and effectiveness in sales processes.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('509bb058-848a-4938-9cc3-d5c9b99ff29b', 'Synthesized', 'synthesized.io', 'https://synthesized.io', 'https://www.linkedin.com/company/synthesized/', 'https://app.dealroom.co/companies/synthesized', 'AI-native synthetic test-data infrastructure for enterprise QA', 'London', 'United Kingdom', 2020, 59, 34.090908, 36452657, 8, 2499999, 2023, 'operational', '[{"uuid":"e3de32a0-712d-4b81-b964-3534e39c9a2f","name":"Nicolai Baldin"},{"uuid":"46fb490b-b572-4edb-bdf6-3d5ddc9541fe","name":"Denis Borovikov"}]', '{}', '2026-11-05T15:55:09.655Z', 'Synthesized is a London (and New York) AI software-testing company that generates privacy-compliant synthetic datasets mirroring production statistics so regulated finance, insurance and healthcare teams can automate QA without exposing sensitive data. Founded by Nicolai Baldin and Denis Borovikov, the B2B SaaS platform covers masking, subsetting and generation with integrations across Snowflake, Oracle, SAP and Salesforce, serving clients including Deutsche Bank and UBS. In September 2025 Synthesized raised a $20 million Series A (over €17 million) led by Redalpine, with IQ Capital, Mercia Ventures, UBS, Seedcamp and Deutsche Bank, to expand in North America and Europe and grow the team. Sources: Fortune 24 Sep 2025; EU-Startups Sep 2025; IQ Capital.', '["accelerator","data management","data security","Venture Capital","operations","web fonts","recruitment marketing","editors","mobile application development platforms","business process management","Core AI","Subscri