INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0640bba0-086b-4716-ac20-39a49d1c8d4e', 'THEKER', 'theker.ai', 'https://theker.ai', 'https://www.linkedin.com/company/theker/', 'https://app.dealroom.co/companies/theker_robotics', 'A company specialized in robotics, deep learning, and computer vision', 'Barcelona', 'Spain', 2022, 73, 204.16667, 81893907, 4, 63, 2023, 'operational', '[{"uuid":"b26578c8-9ac8-4275-b33d-1d736c525579","name":"Carla Gómez Cano"},{"uuid":"680e5704-a632-4cda-97a1-fb09fb95a9c2","name":"Carla Gomez Cano"}]', '{}', '2026-11-05T15:53:55.756Z', 'THEKER is a Barcelona AI-robotics company founded by Carla Gómez Cano and Jiaqiang Ye Zhu that builds AI-native generalist robots for industrial production—adapting in real time to mixed SKUs and variable environments without manual reprogramming—for manufacturing, logistics and related operators across Europe. In June 2026 THEKER raised €73 million ($85 million) Series A led by CRV, with Samsung, LVMH, Cathay Innovation, 20VC, Henkel Ventures, Korelya and Bright Pixel Capital (Sonae) plus existing investors, less than a year after Spain’s largest seed round, to scale deployments, deepen its AI/robotics stack and grow engineering and field teams. Sources: EU-Startups 11 Jun 2026.', '["accelerator","data management","database","Deep Learning","Venture Capital","editors","Angel","communication and collaboration","4YFN 2024","DT and LS","b2b","4YFN 2023","Artificial Intelligence","Robotics","team collaboration","EIT Supernovas","Horizon Europe","programming languages","Commission","audio-video-graphics","Manufacturing","programming","Spinout","dev tools","intelligence and analytics","Late stage","4YFN","science-based","cad & graphics","operating systems & computing languages","design","EIT Ecosystem","Deep Tech","Hardware","Machine Learning","machine learning","Woman Founder","Computer Vision"]', '["startup","rising_star","spinout","vc_backed","funded"]', 93.98, 4800, 0, 0, 386363482, NULL, NULL, 12651, 2023, '[{"year":2022,"revenue":2500,"ebitda":null,"profit":-34,"rnd":null,"valuation":null,"employees":null},{"year":2023,"revenue":63,"ebitda":null,"profit":12651,"rnd":null,"valuation":null,"employees":null},{"year":2024,"revenue":63,"ebitda":null,"profit":12651,"rnd":null,"valuation":null,"employees":10},{"year":2025,"revenue":63,"ebitda":null,"profit":12651,"rnd":null,"valuation":89999964,"employees":24},{"year":2026,"revenue":63,"ebitda":null,"profit":12651,"rnd":null,"valuation":386363482,"employees":73}]', '2026-11-05T15:53:55.756Z', 'GBP', '2026-11-05T15:53:55.756Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('7ccf9002-98b0-4230-92ff-8b97ca12104a', 'TOQIO', 'toqio.co', 'https://toqio.co/', 'https://www.linkedin.com/company/toqiofintech/', 'https://app.dealroom.co/companies/toqio', 'Enables organizations to develop their fintech solution as an app or on the web', 'London', 'United Kingdom', 2019, 27, -25, 23787869, 3, 1329209, 2025, 'operational', '[{"uuid":"28a60e4c-4151-4437-aa2a-fd6a5e20ac21","name":"Eduardo Garcia"},{"uuid":"05cdbb46-e869-4a78-8180-5cbf99acca50","name":"Jose Nistal"},{"uuid":"ca989369-0cd0-4b1d-8350-31f2e74fda2b","name":"Michael Galvin"}]', '{}', '2026-11-05T15:54:35.037Z', 'TOQIO, established in 2019 by co-founders Eduardo Martinez Garcia and Michael Galvin, operates as a Software-as-a-Service (SaaS) platform specializing in embedded finance. The company is headquartered in London, with additional offices in Madrid and Nairobi. The founders, Martinez (CEO) and Galvin (CCO), previously collaborated on Geniac, a SaaS platform for business administration that was later acquired by Grant Thornton, providing them with foundational experience in the sector. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('14619986-2ea2-463d-8f31-4d0b3029d57e', 'Tangent', 'jointangent.com', 'https://www.jointangent.com', 'https://www.linkedin.com/company/jointangent/', 'https://app.dealroom.co/companies/tangent_1_1', 'Tangent, a platform facilitating connections between jobseekers from low socioeconomic backgrounds and tech industry professionals, enables mentoring and employee referrals', 'London', 'United Kingdom', 2022, 257, -4.4609666, 1010302, 4, NULL, NULL, 'operational', '[{"uuid":"65fbc3fd-007d-4d6d-a1cf-f95e1bcb76ed","name":"Gary Izunwa"},{"uuid":"20d00d14-8acc-42ed-9c78-0327fa27d0c1","name":"Joe Adams"}]', '{}', '2026-11-05T15:54:51.538Z', 'Tangent is a unique startup that aims to bridge the gap between aspiring Business Development Representatives (BDRs) from diverse backgrounds and top tech companies. The company operates in the recruitment and career development market, focusing specifically on the tech sales sector. Tangent''s primary clients are individuals who are either in university or have spent their careers in other fields, such as retail, and are now looking to transition into tech sales roles.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('365e971b-ed0f-418f-a012-279924c90304', 'Tappx', 'tappx.com', 'https://www.tappx.com/', 'https://www.linkedin.com/company/tappx/', 'https://app.dealroom.co/companies/tappx', 'Adtech solutions for Mobile & OTT / CTV', 'Barcelona', 'Spain', 2013, 57, 0, 541666, 6, 15692583, 2023, 'operational', '[{"uuid":"4add9c45-2978-4db9-bc5a-6253e9cdbf15","name":"Francisco Morante"},{"uuid":"92d65ddd-d02f-42be-83c2-6a61c285446d","name":"Daniel Reina"},{"uuid":"d3e6ada6-77f0-49e2-b2f7-7fb7d07de162","name":"Antonio Hervás Vílchez"}]', '{}', '2026-11-05T15:53:55.756Z', 'Tappx operates in the digital advertising industry, providing advanced technology solutions to ensure brand safety and effective ad targeting. The company offers instant access to premium ad inventory, which is carefully curated and controlled to provide a safe environment for advertisers. Tappx serves a diverse range of clients, including advertisers and publishers, helping them reach their target audience at the right time and location using the appropriate format. The business model revolves around providing high-quality, contextually relevant audiovisual ads that enhance campaign performance. Tappx generates revenue through private marketplace (PMP) deals and other monetization strategies that leverage their premium inventory and targeting capabilities. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('c7a83cfc-610c-438f-bb11-158fc65b8c79', 'Tem', 'tem.energy', 'http://tem.energy', 'https://www.linkedin.com/company/temmarketplace/', 'https://app.dealroom.co/companies/tem_', 'Reimagining how renewable energy is bought and sold', 'London', 'United Kingdom', 2021, 139, 21.929825, 69895280, 4, 1590908, 2023, 'operational', '[{"uuid":"c949695f-31f6-4c7f-80ca-5018b6c84cc4","name":"Jason Stocks"},{"uuid":"d7b44f60-4760-49f0-800e-b28c529eddba","name":"Joe Mcdonald"},{"uuid":"b3c0e638-bb42-480e-aa25-827e1b1bea2d","name":"Ross Mackay"},{"uuid":"08b77379-ba03-4858-87ef-3023d7bb9a4e","name":"Bartlomiej Szostek"}]', '{}', '2026-11-05T15:54:51.538Z', 'TEM Energy specializes in providing renewable energy solutions tailored for UK businesses, particularly in the food manufacturing, brewing, and educational sectors. The company operates in the renewable energy market, focusing on wind, solar, hydro, biogas, and biomass generators. TEM Energy''s business model involves partnering with renewable energy generators to offer businesses a reliable and clean power supply, thereby reducing their energy costs and environmental footprint. The company generates revenue through direct energy transactions and long-term energy contracts with its clients. By facilitating access to renewable energy, TEM Energy helps businesses in the UK save money and contribute to environmental sustainability. The company also provides valuable insights and support to ensure a seamless transition to renewable energy sources. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('8a8b425c-aaf1-4c7f-9f8c-6b26d45b2c70', 'Tessl', 'tessl.io', 'https://www.tessl.io/', 'https://www.linkedin.com/company/tesslio/', 'https://app.dealroom.co/companies/tessl', 'Reimagining software development for the AI era, and helping shape a new paradigm called AI Native Development', 'London', 'United Kingdom', 2024, 61, 19.607843, 94696932, 2, NULL, NULL, 'operational', '[{"uuid":"fd8eb929-435c-43c1-8a01-f63f60c346e0","name":"Guy Podjarny"}]', '{}', '2026-11-05T15:53:18.240Z', 'Tessl is pioneering a new approach to software development tailored for the AI era, known as AI Native Development. This innovative platform is designed to streamline and enhance the software creation process by integrating artificial intelligence at its core. Tessl primarily serves tech companies and developers looking to leverage AI to improve their software solutions. Operating in the rapidly evolving AI and software development market, Tessl''s business model focuses on providing a subscription-based platform that offers tools and resources for AI-driven software development. Revenue is generated through subscription fees and premium service offerings, catering to businesses aiming to stay competitive in the digital transformation landscape.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('36592efa-2611-4d9e-9e4b-7b2e3f9b0b49', 'The Business of Fashion', 'businessoffashion.com', 'http://www.businessoffashion.com/', 'https://www.linkedin.com/company/the-business-of-fashion/', 'https://app.dealroom.co/companies/the_business_of_fashion', 'Daily resource for fashion creatives, executives and entrepreneurs on breaking news and fashion business intelligence', 'London', 'United Kingdom', 2007, 2045, 17.79954, 1590908, 3, 18515164, 2024, 'operational', '[{"uuid":"c3492579-31db-4e45-a8e7-a917283df2be","name":"sky redme"},{"uuid":"c1ead011-7699-4b09-8eb9-821e7b816178","name":"Imran Amed"}]', '{}', '2026-11-05T15:53:18.240Z', 'The Business of Fashion is an online resource for the fashion industry, offering in-depth analysis and intelligence.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f9726791-d6ec-4108-bd5a-f2034b6c473d', 'The Cambridge Satchel Company', 'cambridgesatchel.com', 'http://www.cambridgesatchel.com/', 'https://www.linkedin.com/company/cambridge-satchel/', 'https://app.dealroom.co/companies/the_cambridge_satchel_company', 'Hand-made leather satchels and accessories', 'London', 'United Kingdom', 2008, 46, 9.523809, 15909085, 2, 6338533, 2020, 'operational', '[{"uuid":"e65bdce3-af22-488d-a571-e277f45570de","name":"Julie Deane"}]', '{}', '2026-11-05T15:53:18.240Z', 'The Cambridge Satchel Company, founded in 2008 by Julie Deane and her mother Freda Thomas, emerged from a personal mission to fund school fees, starting with a modest £600 budget at a kitchen table. This bootstrapped origin story is central to the brand''s identity, which champions traditional British craftsmanship. The company''s growth trajectory was significantly impacted by early adoption from fashion bloggers and a feature in a 2012 Google Chrome advertisement, which catapulted the brand to international recognition and boosted sales dramatically. A key milestone was the opening of its first physical store in Covent Garden in 2013, marking a significant step from a purely online retailer to a high-street presence. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('bcc0a9e9-7626-4949-8a53-b663e2843628', 'The Power MBA', 'thepowermba.com', 'https://global.thepowermba.com/rmk-nl/', 'https://www.linkedin.com/school/thepowermba/', 'https://app.dealroom.co/companies/the_power_mba_1', 'Provider of an online business program intended to bring knowledge to people who are eager to learn', 'Madrid', 'Spain', 2017, 300, 0, NULL, 0, 8532827, 2023, 'operational', '[{"uuid":"ba44db75-940b-4f25-a243-15db35eb7e6a","name":"Hugo Arévalo Álvarez-Arenas"},{"uuid":"c417552c-dc60-4d0d-8b97-e8ae7ea87ca8","name":"Kike Corral"},{"uuid":"a5caf62f-2a1d-44f0-838b-d4010f9b5892","name":"Borja Guinea"},{"uuid":"f55ecb71-1181-4837-b568-555152149dee","name":"Rafael Corral"}]', '{}', '2026-11-05T15:55:36.049Z', 'The Power MBA, which has evolved into The Power Business School, was established in Spain in 2017 by founders Borja Adanero, Rafael Gozalo, Hugo Arévalo, and Kike Corral. The venture originated from co-founder Rafael Gozalo''s experience with a traditional MBA, which he felt was costly and could be delivered more accessibly. Joined by his former consulting colleagues Adanero and Corral, and later Arévalo, they set out to disrupt the conventional education model. Their mission was to make high-level business education accessible to a global audience, irrespective of financial or time constraints.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('66092948-65b1-4101-9404-fe9fac00cfb7', 'Those Beyond', 'thosebeyond.io', 'http://thosebeyond.io', 'https://www.linkedin.com/company/those-beyond/', 'https://app.dealroom.co/companies/those_beyond', 'Building new worlds that reimagine fictional experiences. Currently in development, Fates is an immersive, narrative-driven, web3 experience following the next step in human survival', 'London', 'United Kingdom', 2021, 16, 6.6666665, 7290803, 3, 738636, 2023, 'operational', '[{"uuid":"9b755db8-52d7-40a4-83cf-b6fde926a67f","name":"Fox Rogers"},{"uuid":"6428e541-ec7f-43bf-8ad4-6b0a07bdc55b","name":"Matt Hyde"},{"uuid":"35a007fe-d0c5-40a8-ba92-ef618d26ba9c","name":"Mark Warrick"}]', '{}', '2026-11-05T15:55:36.049Z', 'Cauldron is an innovative startup that blends design and technology to create engaging game experiences with applications in finance, education, and other sectors. The company operates as an independent studio, having secured backing from notable investors such as Draper Esprit and Backed. Cauldron''s primary focus is on developing immersive, experience-rich products that encourage players to adopt real-life habits or collaboratively solve complex problems.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('cb6ebcd7-a982-48d7-a8b6-c1cc1423e261', 'Tilt', 'tilt.app', 'https://www.tilt.app/', 'https://www.linkedin.com/company/tilt-app/', 'https://app.dealroom.co/companies/tilt_', 'Creates a category-defining shopping experience for digital natives', 'London', 'United Kingdom', 2021, 73, 4.285714, 41806046, 4, 833333, 2023, 'operational', '[{"uuid":"57424374-f1e5-467e-8b58-fcf4b8c76a18","name":"Neil Shah"},{"uuid":"fdeafda2-ff51-405a-928c-46e0e1c0fcd7","name":"Abhi Thanendran"}]', '{}', '2026-11-05T15:54:12.521Z', 'An app-based live streaming platform for multi-category fashion products, allowing users to discover emerging fashion, unlock rare collectibles, and shop through videos and live streams with friends.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2011e9dd-8861-4119-a09c-914dc8705d1c', 'Tiney', 'tiney.co', 'https://www.tiney.co', 'https://www.linkedin.com/company/tiney-co/', 'https://app.dealroom.co/companies/tiney', 'Offers a simple way for families to find exceptional local childcare', 'London', 'United Kingdom', 2018, 167, 7.051282, 16261000, 5, 8257572, 2023, 'operational', '[{"uuid":"f0a702d5-4518-4417-af43-e0ae11b5e99d","name":"Edd Read"},{"uuid":"106f5706-ad9c-4f47-805f-ca98a5c6b7bb","name":"John Newbold"},{"uuid":"641859c8-3b64-4a44-b28a-e2d9d567be3b","name":"Brett Wigdortz"}]', '{}', '2026-11-05T15:53:18.240Z', 'Tiney operates as a technology-enabled childminder agency in the United Kingdom, positioning itself as a solution to the nation''s childcare crisis. Founded in 2018 by Brett Wigdortz OBE, Edd Read, and John Newbold, the company was established to address the declining number of childminders and the lack of accessible, high-quality early years education. Wigdortz, the founder of the educational charity Teach First, drew upon his 15 years of experience in tackling educational inequality and his personal challenges as a parent seeking childcare to shape Tiney''s mission. He teamed up with tech entrepreneurs Edd Read, co-founder of Graze.com, and John Newbold, to build a platform that supports micro-entrepreneurs in establishing Ofsted-registered childcare settings within their own homes. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4e405dd3-944c-4b6b-bc17-a36005f46719', 'Tinybird', 'tinybird.co', 'https://www.tinybird.co/', 'https://www.linkedin.com/company/tinybird-co/', 'https://app.dealroom.co/companies/tinybird_1', 'Helping data teams deliver real-time answers at scale through analytical API endpoints built in minutes', 'Madrid', 'Spain', 2019, 51, -10.526316, 53030282, 3, 82708, 2019, 'operational', '[{"uuid":"b812558a-e4f0-42a3-b269-0c925530960d","name":"Javier Álvarez Medina"},{"uuid":"976bca48-5fc8-482d-b94c-1d29b7d8acc2","name":"Javi Santana"},{"uuid":"da978328-62e7-428c-88be-5447bc4be0a3","name":"Jorge Gomez Sancha"},{"uuid":"83c04f86-a63f-4bbd-aed5-a240c4cf4a2d","name":"Jorge GÃ³mez Sancha"}]', '{}', '2026-11-05T15:54:12.521Z', 'Tinybird is a real-time data analytics platform that provides a comprehensive suite of services to its clients. It operates in the data analytics market, serving clients who need to manage and analyze large volumes of data in real time. Its clients range from engineering directors like Damian Grech at FanDuel, to software teams looking to build data products.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('07f3045a-8f37-4269-b3dc-534d8d4a8112', 'Togetherall', 'togetherall.com', 'https://togetherall.com', 'https://www.linkedin.com/company/together-all/', 'https://app.dealroom.co/companies/togetherall', 'Clinically moderated peer-to-peer online mental health community.', 'London', 'United Kingdom', 2007, 69, 2.9850745, 7575755, 2, 6012307, 2025, 'operational', NULL, '{}', '2026-11-05T15:55:56.052Z', 'Togetherall is a digital mental health service centered on a peer-to-peer support community that operates 24/7 and is clinically moderated. Founded in 2007 as Big White Wall, the company''s goal was to provide a safe, anonymous online space where individuals could discuss their mental well-being without fear of stigma. The name was changed to Togetherall in August 2020 to better reflect the platform''s inclusive community. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('a17939df-433f-49f8-9553-1f7ebe1655cf', 'Toothfairy', 'toothfairyapp.co.uk', 'https://www.toothfairyapp.co.uk/', 'https://www.linkedin.com/company/tooth-fairy-app/', 'https://app.dealroom.co/companies/toothfairy', 'Toothfairy connects patients to dentists on-demand via video, with the app being officially approved by the NHS', 'London', 'United Kingdom', 2019, 29, 7.4074073, 10300000, 2, 2272726, 2023, 'operational', '[{"uuid":"de8291ed-2850-49fe-a9be-38dbc7bafa47","name":"Dr. Deepak Singh Aulak"},{"uuid":"ddbb56d2-3410-4c89-8982-a37ed001354c","name":"Dr Kian Singh Dhinsa"}]', '{}', '2026-11-05T15:55:36.049Z', 'Toothfairy is a pioneering startup in the teledentistry sector, offering immediate access to dental care through a user-friendly mobile app. The company addresses a critical gap in the dental care market, exacerbated by the COVID-19 pandemic, which resulted in over 19 million missed dental appointments. Toothfairy serves individuals experiencing dental emergencies, pain, discomfort, or those seeking dental advice and cosmetic treatments such as teeth straightening and whitening.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('8a57436e-2c2e-4fba-b703-bc6d8c3fcc4c', 'Top Doctors', 'topdoctors.es', 'http://www.topdoctors.es/', 'https://www.linkedin.com/company/top-doctors-europe/', 'https://app.dealroom.co/companies/top_doctors', 'Providing excellent medical care to its patients', 'Esplugues de Llobregat', 'Spain', 2013, 545, 12.603306, 13681813, 5, 18106053, 2023, 'operational', '[{"uuid":"e70eb469-c63b-45f2-8823-864ee4500575","name":"Alberto E. Porciani"},{"uuid":"f44586ae-a4e6-4725-a092-69f69df3f530","name":"Alberto E. Porciani"},{"uuid":"5e30e4f5-2472-461f-b55d-2eb624a8088d","name":"Lorena Bassas Vivó"}]', '{}', '2026-11-05T15:55:36.049Z', 'TopDoctors.es operates as a premier online platform that connects patients with highly qualified medical specialists across various fields. Serving a diverse clientele, including individuals seeking specialized medical advice and treatments, the company operates within the healthcare sector, specifically focusing on telemedicine and in-person consultations. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('cdc1bc15-bfb6-4a3b-a777-abe92fd7d946', 'Tranxfer', 'tranxfer.com', 'http://www.tranxfer.com/home/', 'https://www.linkedin.com/company/tranxfer/', 'https://app.dealroom.co/companies/tranxfer', 'Tranxfer | Safe file delivery', 'Barcelona', 'Spain', 2013, 29, 3.5714285, 833333, 1, 687761, 2023, 'operational', '[{"uuid":"316a6bdd-a730-4ca4-b247-7d95c9e23887","name":"Miguel Planas"}]', '{}', '2026-11-05T15:56:04.243Z', 'Based in Barcelona, Tranxfer is a cybersecurity firm established in 2013 by Miguel Planas Arruti. The company originated from a specific development project for a major Spanish bank before officially launching its product to the market in 2017. Tranxfer was created within the Iris Venture Builder, a venture capital firm co-founded by Planas that specializes in technology startups in cybersecurity and artificial intelligence. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('1b8796d7-e598-4e94-9c55-e27535f7cc7e', 'TreasurySpring', 'treasuryspring.com', 'treasuryspring.com', 'https://www.linkedin.com/company/treasuryspring/', 'https://app.dealroom.co/companies/spring_treasury', 'Regulated cash investment platform for fixed-term funds.', 'London', 'United Kingdom', 2016, 96, 5.4945054, 26125755, 6, 12002268, 2025, 'operational', '[{"uuid":"dd9fbe64-c370-46c0-89ae-5b83d7b1b1a2","name":"Matthew Longhurst"},{"uuid":"7ebe8868-0024-4843-8257-f2110f35d2c5","name":"James Skillen"},{"uuid":"3feb029b-3cdd-48e8-aba0-701f888485a9","name":"Kevin Cook"}]', '{}', '2026-11-05T15:54:12.521Z', 'TreasurySpring operates a financial technology platform that provides access to the wholesale money markets for institutional clients. Founded in London in 2016 by Kevin Cook, Matthew Longhurst, and James Skillen, the company was established to modernize cash investment infrastructure. The founders'' collective experience in hedge funds, fixed income, and asset management, particularly during the 2008 financial crisis, highlighted the need for more robust and accessible solutions for corporate cash management. The firm''s core offering is its regulated digital platform, which allows companies to invest excess cash into a variety of short-term, fixed-income products. Clients include a wide range of organizations, from FTSE 100 corporations and multinationals to startups, charities, and fund managers. For these entities, the platform offers a way to diversify holdings, manage risk, and increase returns on cash balances that might otherwise be held in low-yield bank accounts. The platform also serves institutional borrowers, such as governments, banks, and investment-grade corporations, by providing them with a flexible, low-cost source of funding from a diverse network of non-bank investors. The business model appears to be based on transactional fees linked to the volume and value of investments facilitated through the platform. TreasurySpring''s main product is the Fixed-Term Fund (FTF), a financial instrument it designed and first issued in 2018. FTFs function similarly to term deposits but provide direct, single-name exposure to high-quality issuers like governments or investment-grade banks and corporations for a set period, typically from one week to one year. The platform offers over 600 such products in multiple currencies, including secured options backed by collateral and unsecured options. This structure provides transparency and avoids the maturity transformation and co-mingling of assets common in traditional money market funds, thereby reducing certain risks for the investor. The company has raised approximately $43.5 million in funding, including a $29 million Series B round in June 2023 to fuel product development and international expansion. Keywords: cash investment platform, Fixed-Term Funds, FTFs, money markets, corporate treasury, cash management, institutional finance, short-term funding, fixed income, fintech, asset management, investment grade assets, government securities, secured bank assets, risk diversification, wholesale funding, digital investment, financial technology, corporate finance, liquidity management', '["database","uk is8 financial services","photo galleries","Venture Capital","web fonts","recruitment marketing","editors","marketing","marketing automation","javascript graphics","page builders","CFO Tech","Angel","frameworks and libraries","communication and collaboration","Wealth Management","content management system","Fintech","storage","online video platforms","software development","it infrastructure","web frameworks","b2b","web platform extensions","tag management","email","team collaboration","widgets","web servers","Cash Management","search engines","content delivery network","programming languages","Commission","Breakout stage","audio-video-graphics","advertising","website builders","web conferencing","web and application servers","miscellaneous","programming","cloud infrastructure computing","Financial Management Solutions","javascript libraries","wordpress plugins","intelligence and analytics","video players","analytics","security","operating systems & computing languages","cloud hosting","web analytics","Treasury Management","platform as a service","javascript frameworks","Marketplace & ecommerce","font scripts","blogs","applicant tracking systems","design","affiliate advertising networks","ui frameworks","email marketing","cookie compliance","Capital Market","captcha","maps","web tools and plugins","web hosting"]', '["startup","vc_backed","funded"]', 82.81, 8100, 1, 4, 90000000, NULL, NULL, -1015000, 2025, '[{"year":2021,"revenue":992424,"ebitda":null,"profit":null,"rnd":null,"valuation":45454527,"employees":19},{"year":2022,"revenue":1818181,"ebitda":null,"profit":null,"rnd":null,"valuation":45454527,"employees":27},{"year":2023,"revenue":2651514,"ebitda":null,"profit":null,"rnd":null,"valuation":90000000,"employees":50},{"year":2024,"revenue":12412874,"ebitda":null,"profit":null,"rnd":null,"valuation":90000000,"employees":66},{"year":2025,"revenue":12002268,"ebitda":null,"profit":-1015000,"rnd":null,"valuation":90000000,"employees":91},{"year":2026,"revenue":12002268,"ebitda":null,"profit":-1015000,"rnd":null,"valuation":90000000,"employees":96}]', '2026-11-05T15:54:12.521Z', 'GBP', '2026-11-05T15:54:12.521Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('35a6d833-5a94-4ebb-804a-3d8f44fc015b', 'Trucksters', 'trucksters.io', 'http://trucksters.io', 'https://www.linkedin.com/company/trucksters', 'https://app.dealroom.co/companies/trucksters', 'Offering a FTL long-distance transportation service through an innovative relay system based on artificial intelligence', 'Madrid', 'Spain', 2018, 79, -2.4691358, 40439378, 7, 12830640, 2023, 'operational', '[{"uuid":"871a8a8d-077a-40da-aaa9-13664bbf296d","name":"Gabor Balogh"},{"uuid":"a86a0f8d-af23-4b65-9d55-141118dfba79","name":"Ramon castro"},{"uuid":"56c1c6cd-f5af-4cbf-94e5-ba10af331bd7","name":"Luis Bardají Izard"}]', '{}', '2026-11-05T15:53:55.756Z', 'Founded in 2018 by Luis Bardají, Gabor Balogh, and Ramón Castro, Trucksters is a long-haul trucking operator aiming to enhance the efficiency and professional standards of the global road freight industry.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('6c1aa961-9675-45e5-b84d-bd1bbff19c02', 'TrueLayer', 'truelayer.com', 'https://truelayer.com/', 'https://www.linkedin.com/company/truelayer/', 'https://app.dealroom.co/companies/truelayer', 'Platform allows easily integrate next-generation payments and financial data into any app', 'London', 'United Kingdom', 2016, 280, 1.0830325, 277128261, 13, 28205712, 2025, 'operational', '[{"uuid":"e7fd89a9-bb93-4a90-8eb0-45fb62187de2","name":"Francesco Simoneschi"},{"uuid":"e47fccec-2dad-407a-83fe-ca560705a025","name":"Luca Martinetti"}]', '{}', '2026-11-05T15:55:23.556Z', 'TrueLayer is a leading open banking platform that facilitates seamless financial data integration and payments for businesses. Operating primarily in the fintech sector, TrueLayer serves a diverse range of clients including financial institutions, technology companies, and online marketplaces. The company leverages open banking regulations to provide secure and efficient access to financial data, enabling businesses to offer enhanced services such as instant bank payments, account verification, and data-driven insights.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f40797e4-5d4a-4da7-aeb8-02d03dea0738', 'Trueflag', 'trueflag.ai', 'https://trueflag.ai', 'https://www.linkedin.com/company/trueflag/', 'https://app.dealroom.co/companies/trueflag', 'Multimodal and multilingual SaaS designed to automate the detection and verification of disinformation in online content', 'Colmenar Viejo', 'Spain', 2024, 14, 16.666666, 1000000, 1, NULL, NULL, 'operational', '[{"uuid":"c7a78900-02f7-4d9c-8743-b59a416bd68f","name":"Ana Pastor"},{"uuid":"76301352-06ca-4693-a456-b611ee32aca7","name":"Tomás Pastor"},{"uuid":"3bb30e59-b627-4197-befc-525a7c9d2b0a","name":"Ruben Miguez Perez"},{"uuid":"123a0394-1091-4a0e-8b5b-47ec23cbc59b","name":"Ruben Miguez"}]', '{}', '2026-11-05T15:56:04.243Z', 'Trueflag.ai operates in the digital information sector, focusing on the detection and verification of disinformation across various online platforms. The company offers a Software as a Service (SaaS) solution that is both multimodal and multilingual, designed to automate the identification of fake news before it reaches mainstream media. Trueflag.ai serves clients who are concerned with the impact of misinformation, including businesses, governments, and individuals. The service monitors suspicious sources across platforms like Telegram, TikTok, Facebook, YouTube, podcasts, and blogs, providing real-time alerts to its users. The business model is subscription-based, generating revenue through service subscriptions from clients who require continuous monitoring and verification of online content. Trueflag.ai addresses a critical need in the market, especially with increasing regulations on disinformation by entities such as the EU Digital Service Acts. The platform''s ability to provide targeted advertising based on user preferences also adds a layer of value for its clients. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('721d6968-74ff-441c-b102-7e5a82be4434', 'TuLotero', 'tulotero.es', 'http://tulotero.es', 'https://www.linkedin.com/company/tulotero/', 'https://app.dealroom.co/companies/tulotero', 'An app for national and other lottery playing', 'Madrid', 'Spain', 2013, 91, 56.896553, NULL, 0, 8366686, 2023, 'operational', NULL, '{}', '2026-11-05T15:55:36.049Z', 'TuLotero operates as an application-based platform for purchasing official state lottery tickets and managing bets. The company was conceptualized when its founders identified a market gap for a convenient, digital method to buy lottery tickets, an idea that arose when they found it impossible to purchase a ticket quickly and easily one Saturday night. While some sources indicate a founding year of 2013 or 2015, others point to its initial conceptualization in 2010. The Madrid-based company was founded by Eduardo Villanueva Bayona, who serves as CEO, and Rebeca Cámara, the Co-Founder and VP of Global Marketing. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('9c3c19f7-bc43-49e9-91f8-b0dce69dcb5c', 'Tucuvi', 'tucuvi.com', 'https://tucuvi.com', 'https://www.linkedin.com/company/tucuvi/', 'https://app.dealroom.co/companies/tucuvi', 'Certified voice AI for clinical care management', 'Madrid', 'Spain', 2019, 81, 55.76923, 21497264, 7, 339232, 2023, 'operational', '[{"uuid":"ec20d0db-9b48-42dd-a7f5-87986303428c","name":"Marcos Rubio Rubio"},{"uuid":"6fe6fc58-a771-4736-8876-fc24230f829f","name":"María González Manso"}]', '{}', '2026-11-05T15:54:35.037Z', 'Tucuvi is a Madrid-based HealthTech company building certified voice AI for clinical care management. Its platform uses AI agents such as LOLA to run secure phone conversations with patients, automate nursing follow-up and care-coordination workflows, and escalate to clinicians when needed, with Class IIb Software as a Medical Device approval in Europe. Founded in 2019, Tucuvi works with dozens of healthcare organisations on post-surgical follow-up, chronic-disease management, preoperative assessments and related pathways. In January 2026 it raised a €17 million ($20 million) Series A led by Cathay Innovation and KFund (Leadwind), with Frontline Ventures, Seaya Ventures and Shilling, to scale in Europe and the US. Sources: EU-Startups 9 Jan 2026.', '["Health Platform","accelerator","data management","database","elderly care","Health It","Voice Recognition","Venture Capital","web fonts","Core AI","SaaS","customer relationship management","page builders","Good Health And Well-Being (#3)","frameworks and libraries","electronic health records","content management system","enterprise","DT and LS","AI Agents","EIT Health","b2b","web platform extensions","Artificial Intelligence","tag management","web servers","EIT Supernovas","remote health monitoring","search engines","4YFN 2022","Horizon Europe","programming languages","Commission","Breakout stage","audio-video-graphics","error and exception monitoring","programming","caching","Silver Economy","AI Applications","javascript libraries","wordpress plugins","Medical Devices","intelligence and analytics","Enterprise Software","analytics","other audio-video-graphics software","Remote Monitoring","4YFN","Sustainable Development Goals","science-based","operating systems & computing languages","web analytics","EIC","Health","consent management","Physician Support Tools","Virtual Assistant","font scripts","cache tools","Health Office Tools","blogs","Tech for Patients","health platform","Caregiving","EIT Ecosystem","Deep Tech","Woman Founder","operating systems","web tools and plugins"]', '["startup","vc_backed","funded"]', 92.57, 6900, 1, 3, 24999990, NULL, NULL, -54217, 2023, '[{"year":2022,"revenue":111103,"ebitda":null,"profit":-324997,"rnd":null,"valuation":3999998,"employees":16},{"year":2023,"revenue":339232,"ebitda":null,"profit":-54217,"rnd":null,"valuation":3999998,"employees":31},{"year":2024,"revenue":339232,"ebitda":null,"profit":-54217,"rnd":null,"valuation":3999998,"employees":41},{"year":2025,"revenue":339232,"ebitda":null,"profit":-54217,"rnd":null,"valuation":3999998,"employees":52},{"year":2026,"revenue":339232,"ebitda":null,"profit":-54217,"rnd":null,"valuation":24999990,"employees":81}]', '2026-11-05T15:54:35.037Z', 'GBP', '2026-11-05T15:54:35.037Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('b7edd708-0b21-481d-a534-e4817618962d', 'Tuza', 'tuza.co.uk', 'http://tuza.co.uk', 'https://www.linkedin.com/company/trytuza/', 'https://app.dealroom.co/companies/tuza', 'AI agentic workflows for banking automation.', 'London', 'United Kingdom', 2023, 31, 34.782608, 1500000, 1, NULL, NULL, 'operational', '[{"uuid":"eff8a083-d6a9-442a-a499-4adeb363d897","name":"Olivia Stannah"},{"uuid":"570df136-6505-4c13-9730-0c8060cab841","name":"Ed Hardy"}]', '{}', '2026-11-05T15:55:23.556Z', 'Tuza is a financial technology company that began by targeting the payments processing sector for small and medium-sized businesses (SMBs) and is now expanding into broader banking automation. The company was founded in 2023 as ''Statement'' by CEO Ed Hardy and CTO Olivia Stannah. Hardy, an Oxford and Cambridge graduate, previously worked in the payments industry at Worldpay, while Stannah holds degrees in Economics and Computer Science and has a background in software engineering at major banks and payment startups. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('e6c17721-a3f4-41e6-8329-55baf8a789cb', 'Twinco Capital', 'twincocapital.com', 'https://www.twincocapital.com', 'https://www.linkedin.com/company/twincocapital/', 'https://app.dealroom.co/companies/twinco_capital', 'Fair funding global trade, from purchase order to final invoice payment', 'Alcobendas', 'Spain', 2016, 52, 10.638298, 24356051, 5, 1256628, 2023, 'operational', '[{"uuid":"162b248c-606a-455e-8c62-6d963a7185ce","name":"Sandra Nolasco"},{"uuid":"db5e9c69-07eb-48f4-8a9a-35669f75aecb","name":"Carmen Marin, CFA"}]', '{}', '2026-11-05T15:55:09.655Z', 'Twinco Capital is a supply chain finance company that provides a new model for funding suppliers. The company offers a platform that allows suppliers to receive early payment for their invoices, which helps them to manage their cash flow and reduce their risk of non-payment. Twinco Capital''s platform is designed to be easy to use and to provide a high level of transparency to both suppliers and buyers.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('5eac1b5a-0a94-44f7-a16b-e1d785016687', 'Typeform', 'typeform.com', 'http://www.typeform.com/', 'https://www.linkedin.com/company/typeform-/', 'https://app.dealroom.co/companies/typeform', 'Engaging conversational forms, surveys, and quizzes for businesses.', 'Barcelona', 'Spain', 2012, 920, 9.263658, 141651458, 6, 69166639, 2024, 'operational', '[{"uuid":"b541a37d-4534-4155-b098-567371f007a7","name":"David Okuniev"},{"uuid":"4553b209-5966-482d-90b5-94768f389855","name":"Robert Muñoz"}]', '{}', '2026-11-05T15:53:18.240Z', 'Typeform is a dynamic startup that specializes in creating user-friendly online forms and surveys. The company operates in the software-as-a-service (SaaS) market, providing tools that help businesses and organizations collect and analyze data efficiently. Typeform''s products include form builders, survey makers, quiz creators, and interactive video conversations through their VideoAsk tool. These products are designed to be engaging and easy to use, which helps clients get better response rates and more meaningful data.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('84a495b0-2655-462f-af6d-3938aecd5ee2', 'Ultromics', 'ultromics.com', 'http://www.ultromics.com/', 'https://www.linkedin.com/company/ultromics/', 'https://app.dealroom.co/companies/ultromics', 'AI-powered echocardiogram analysis for heart failure detection.', 'Oxford', 'United Kingdom', 2017, 83, 16.90141, 86666640, 10, 3480000, 2025, 'operational', '[{"uuid":"518cb9e0-0027-4c7e-b839-931fad305401","name":"Ross Upton, PhD"},{"uuid":"2d68f28e-a495-4268-88f9-76a17b4ebcdb","name":"Ross Upton"}]', '{}', '2026-11-05T15:55:56.052Z', 'Ultromics is a health technology company that provides artificial intelligence (AI)-driven solutions for cardiovascular disease diagnostics. It was founded in 2017 as a spin-out from the University of Oxford by Ross Upton and Professor Paul Leeson. The company''s creation stemmed from Upton''s PhD research in cardiovascular medicine, where, as a trained sonographer, he identified the subjective and time-consuming nature of echocardiography as a major bottleneck in heart disease detection. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('30919972-10ab-49d9-9cda-fb5c21806124', 'Uncapped', 'weareuncapped.com', 'https://weareuncapped.com/', 'https://www.linkedin.com/company/weareuncapped/', 'https://app.dealroom.co/companies/uncapped', 'Revenue-based finance provider that allows founders to raise growth capital without giving up control of their business', 'London', 'United Kingdom', 2019, 78, -1.2658228, 96039362, 4, 12649345, 2025, 'operational', '[{"uuid":"09199666-eceb-47b6-8ec8-b30e869d49bb","name":"Piotr Pisarz"},{"uuid":"f47d4565-77cb-4511-a14a-dacd6cc5013f","name":"Asher Ismail"}]', '{}', '2026-11-05T15:55:36.049Z', 'Uncapped is a financial technology startup that provides flexible funding solutions to online businesses. It operates in the financial services market, specifically targeting online businesses in need of capital to accelerate growth. The company offers no-interest, no-equity funding ranging from £100k to £10m, which means businesses can access funds without giving up a share of their company or paying interest. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('99cc7f88-6aae-4db6-9eb7-f75d24f717dd', 'Unfabled', 'unfabled.co', 'https://unfabled.co/', 'https://www.linkedin.com/company/unfabled/', 'https://app.dealroom.co/companies/unfabled', 'Wellness platform offering curated, sustainable health and hygiene products for women’s life-stages', 'London', 'United Kingdom', 2021, 10, -23.076923, 2499999, 5, NULL, NULL, 'operational', '[{"uuid":"78181924-ebac-4d13-84ce-ca872f4dc147","name":"Hannah Samano"}]', '{}', '2026-11-05T15:54:51.538Z', 'Launched in February 2021, Unfabled is the first marketplace for menstrual wellness. We curate sustainable and ethical brands for period care, period symptoms, and for self-care at any time of the month. We call it cycle care.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('250eb943-7f62-4a4e-bdfd-3e37a7fa43ef', 'Urban Jungle', 'myurbanjungle.com', 'https://myurbanjungle.com/', 'https://www.linkedin.com/company/urban-jungle-insurance/', 'https://app.dealroom.co/companies/urban_jungle', 'Offers simple, fair and affordable insurance, unlocked using the latest technology', 'London', 'United Kingdom', 2017, 90, -3.2258065, 43560000, 7, NULL, NULL, 'operational', '[{"uuid":"a3687288-50f4-4855-8897-aeff1a8b650f","name":"James Williams"},{"uuid":"3c188127-deeb-429a-bf81-91e555a3b36a","name":"Jimmy Williams"},{"uuid":"088b7a30-d80e-4c0f-a7e5-609a6d30bb9f","name":"Greg Smyth"}]', '{}', '2026-11-05T15:55:09.655Z', 'Urban Jungle provides insurance solutions designed to meet the needs of a new generation. The company offers straightforward, transparent, and equitable coverage options. Operating in the insurance market, Urban Jungle serves clients who seek confidence in their financial future. The business model focuses on delivering value through clear and fair insurance products, generating revenue from policy premiums. As a certified B Corp, Urban Jungle is committed to high standards of social and environmental performance, accountability, and transparency.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('6a165323-7d03-4463-a1ac-3052fca51dce', 'Urbanitae', 'urbanitae.com', 'http://urbanitae.com/', 'https://www.linkedin.com/company/urbanitae/', 'https://app.dealroom.co/companies/urbanitae', 'The meeting point between the small investor and the best real estate developers', 'Madrid', 'Spain', 2017, 124, 24, 9999996, 4, 8450194, 2024, 'operational', '[{"uuid":"58c2bac7-f7e5-4ae6-96fa-1dca5168ac6e","name":"Diego Bestard"},{"uuid":"dabf0503-efae-4cef-a1e4-41f0dd12d9b4","name":"Eduardo Navarro"}]', '{}', '2026-11-05T15:55:36.049Z', 'Urbanitae is a real estate crowdfunding platform that allows small investors to participate in large-scale real estate projects, a market traditionally dominated by institutional investors. The company operates primarily in the Spanish market, where it holds a significant market share, and has recently expanded its operations to Portugal. Its business model is based on a B2C approach, connecting individual investors with real estate developers seeking funding for their projects. Urbanitae''s revenue is likely generated through fees charged to both investors and developers for successful funding campaigns.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('b1c22675-2516-4556-a788-28789c2dd17b', 'Vertice', 'vertice.one', 'http://vertice.one', 'https://www.linkedin.com/company/verticeone/', 'https://app.dealroom.co/companies/vertice_1', 'The SaaS purchasing platform that gives finance leaders cost control, efficiency and flexibility', 'London', 'United Kingdom', 2021, 577, 38.369305, 77628757, 3, 9591146, 2024, 'operational', '[{"uuid":"f817416f-5882-4f9f-a02a-989b111598b3","name":"Eldar Tuvey"},{"uuid":"81d6053c-4b15-4d90-a7f4-e540c17dbe4e","name":"Roy Tuvey"}]', '{}', '2026-11-05T15:56:26.553Z', 'Vertice.One is a financial technology startup that provides a platform for finance leaders to optimize their Software as a Service (SaaS) and cloud spending. The company operates in the financial technology market, serving businesses of all sizes that use SaaS and cloud services. Vertice.One''s business model revolves around providing visibility into clients'' SaaS and cloud spending, offering advanced forecasting, and controlling usage through intelligent workflows. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('230fe501-ffac-4fea-92c2-f7501b02e6c8', 'Voicemod', 'voicemod.net', 'http://www.voicemod.net', 'https://www.linkedin.com/company/voicemod/', 'https://app.dealroom.co/companies/voicemod', 'A simple online voice modifier and transformer', 'Valencia', 'Spain', 2014, 113, 1.8018018, 17464614, 9, 8641578, 2022, 'operational', '[{"uuid":"240655d7-28f3-49f0-89b5-d789c68db6e2","name":"Carlos Garcia Gomez"},{"uuid":"4a89743b-4719-4452-9ad8-6f866f3625c2","name":"Fernando Bosch"},{"uuid":"997e0082-6c75-4b8b-a2cc-c465a7ae6fe3","name":"Jaime Criado"},{"uuid":"37492a5e-859a-4dd7-bb1d-ab11fd8b3cbb","name":"Jaime Bosch Criado"},{"uuid":"8ebecda6-1c16-4df9-a6d2-e5044468d5cf","name":"Juan Bosch"}]', '{}', '2026-11-05T15:56:04.243Z', 'Voicemod operates in the digital entertainment market, providing a real-time voice changer and soundboard application primarily for PC users. The company targets gamers, content creators, and online communities, offering tools to modify and enhance voice interactions during gameplay and streaming. Voicemod''s business model revolves around a freemium approach, where users can access basic features for free while premium features are available through subscription or one-time purchases. The platform supports popular games like Apex Legends and Call of Duty Warzone, allowing users to surprise and entertain their peers with diverse voice effects and sound clips. By integrating with various gaming and communication applications, Voicemod enhances user engagement and interaction, making it a popular choice among gaming enthusiasts. The company generates revenue through premium subscriptions, in-app purchases, and partnerships with gaming platforms. Voicemod''s offerings cater to a growing demand for personalized and immersive digital experiences, positioning it as a key player in the voice modulation segment.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('27076bf2-90b3-4516-9abe-53622853c486', 'Voy', 'joinvoy.com', 'http://joinvoy.com', 'https://www.linkedin.com/company/joinvoy/', 'https://app.dealroom.co/companies/voy_5', 'Aims to improve the daily lives of men by encouraging men to take control of their happiness and health and talk openly', 'London', 'United Kingdom', 2018, 510, -12.969283, 55593929, 6, 227363187, 2025, 'operational', '[{"uuid":"8f8a9e95-c4cb-4638-ae3a-d89df950f2e3","name":"Saloni Paliwal"},{"uuid":"ecb0a38c-5453-4fe1-baa3-8cd3f72ae0ee","name":"Parth Chopra"},{"uuid":"1e966dfa-8746-4996-90e9-b386b2b83e32","name":"George Pallis"},{"uuid":"0a3153d6-d3ba-4329-944d-362036466157","name":"Michalis Gkontas"}]', '{}', '2026-11-05T15:55:36.049Z', 'Voy  (formerly Manual.co) offers a comprehensive weight loss program that integrates personalised coaching and medication to help individuals achieve sustainable weight loss. The program is designed for those who have struggled with traditional diet and exercise methods, providing a tailored approach that addresses both physical and emotional aspects of eating. Clients begin their journey with an online assessment to determine the most suitable treatment plan, followed by discreet delivery of prescribed medication and regular coaching sessions to track progress and reshape habits. The business primarily serves individuals seeking long-term weight management solutions, leveraging a subscription-based model to generate revenue. By focusing on personalized care and continuous support, Voy aims to enhance client outcomes, with participants reportedly losing five times more weight compared to diet and exercise alone. The program also addresses emotional eating, offering strategies to manage it effectively. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('8903b2fe-d187-4f34-9430-84687bfdb331', 'Wayve', 'wayve.ai', 'https://wayve.ai', 'https://www.linkedin.com/company/wayve-technologies/', 'https://app.dealroom.co/companies/wayve_1', 'Mapless, hardware-agnostic AI driving software for OEMs', 'London', 'United Kingdom', 2017, 1065, 34.13098, 1945447417, 10, NULL, NULL, 'operational', '[{"uuid":"1c652400-5d64-478f-9b6c-a7872ec04fed","name":"Alex Kendall"}]', '{}', '2026-11-05T15:54:12.521Z', 'Wayve is a London embodied-AI company founded in 2017 that builds end-to-end autonomous-driving software (AV2.0 / AI Driver) for automakers and fleets without relying on HD maps or city-by-city engineering. Its foundation models run on onboard compute and sensors and have demonstrated zero-shot driving across more than 500 cities in Europe, North America and Japan. In February 2026 Wayve raised a $1.2 billion Series D at an $8.6 billion post-money valuation—led by Eclipse, Balderton and SoftBank Vision Fund 2, with Microsoft, NVIDIA, Uber, Mercedes-Benz, Nissan, Stellantis and institutional backers including Ontario Teachers’, Baillie Gifford and the British Business Bank—taking total capital secured to about $1.5 billion including milestone-linked Uber robotaxi funding, to scale commercial robotaxi trials from 2026 and supervised autonomy in consumer vehicles from 2027. Sources: Wayve press 25 Feb 2026; NYT.', '["corporate","accelerator","data management","social media marketing software","static site generator","database","online community software","logging",