","video players","containers","Late stage","real user monitoring","analytics","other audio-video-graphics software","devops","site and cart abandonment","Transportation","security","issue trackers","science-based","local marketing","document management systems","cad & graphics","operating systems & computing languages","cloud hosting","web analytics","automotive website design and development services","data integration","rio drones and autonomous systems","configure price quote","platform as a service","visualisation software","uk is8 digital and technologies","Autonomous & Sensor Tech","build automation","application development & management","javascript frameworks","Industrial Technology","live chat","font scripts","referral marketing","lead generation","file sharing","applicant tracking systems","design","tools","affiliate advertising networks","ui frameworks","charting","certificates","Deep Tech","continuous integration","configuration management","ai model layer","Machine Learning","machine learning","identity verification","containerization","project management","Autonomous & Sensor Tech","operating systems","captcha","data management platforms","web tools and plugins","web hosting"]', '["startup","unicorn","vc_backed","funded"]', 97.49, 130000, 1, 88, 6515148909, -22910689, 2022, -46969678, 2024, '[{"year":2021,"revenue":null,"ebitda":-11667062,"profit":-10177144,"rnd":null,"valuation":75757545,"employees":113},{"year":2022,"revenue":null,"ebitda":-22910689,"profit":-19682446,"rnd":null,"valuation":909090545,"employees":184},{"year":2023,"revenue":null,"ebitda":-22910689,"profit":-34824518,"rnd":null,"valuation":909090545,"employees":223},{"year":2024,"revenue":null,"ebitda":-22910689,"profit":-46969678,"rnd":null,"valuation":2272726364,"employees":395},{"year":2025,"revenue":null,"ebitda":-22910689,"profit":-46969678,"rnd":null,"valuation":2272726364,"employees":794},{"year":2026,"revenue":null,"ebitda":-22910689,"profit":-46969678,"rnd":null,"valuation":6