INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('fcca2a2e-3a1f-456e-aafb-82601566d6db', 'Wonder', 'wonderstudios.com', 'https://www.wonderstudios.com', 'https://www.linkedin.com/company/wearewonderstudios/', 'https://app.dealroom.co/companies/wonderstudios', 'AI-native creative studio for filmmaking and storytelling', 'London', 'United Kingdom', 2025, 62, 3000, 11363632, 2, NULL, NULL, 'operational', '[{"uuid":"d313bfb9-ebab-46c9-ae76-d0bc8ce85aaa","name":"Yigit Kirca"},{"uuid":"4dddca30-0792-44d7-b258-375e050edd36","name":"Justin Hackney"},{"uuid":"e1b8484e-4c46-4d2e-aa9d-ebbe0bd46442","name":"Xavier Collins"}]', '{}', '2026-11-05T15:54:51.538Z', 'Wonder Studios is a London AI-native creative studio founded in 2025 by Xavier Collins (CEO; formerly Lumiere Ventures) and Justin Hackney that builds tools and productions for AI filmmakers, traditional creatives and technologists. Its browser-based platform automates parts of VFX workflows—including animation, lighting and composition of CG characters into live-action—aiming to cut high-end production cost per minute dramatically while exporting into professional pipelines. The studio develops original IP and incubates talent; projects have included an AI music video for Lewis Capaldi with DeepMind, YouTube and Universal Music Group, the Beyond the Loop anthology, and commercial/documentary work with partners such as Campfire Studios. After a $3 million (€2.6 million) April 2025 pre-seed led by LocalGlobe and Blackbird (with OpenAI, Google DeepMind and ElevenLabs executives among angels), in October 2025 Wonder raised a $12 million seed led by Atomico with LocalGlobe, Blackbird and Adobe Ventures to double engineering and accelerate IP and original content. Sources: TechCrunch 23 Oct 2025; Atomico; Sifted; company.', '["social media marketing software","database","software as a service","Media","Deep Learning","Venture Capital","Film Production","Core AI","Content production","javascript graphics","page builders","Angel","frameworks and libraries","development","identity and access management","Generative AI","testing and qa","software development","web frameworks","travel and expense management","uk is8 creative industries","b2b","Artificial Intelligence","tag management","web servers","Video Content","api management","programming languages","Entertainment","Breakout stage","audio-video-graphics","payment processing","content marketing","web & portal technology","generative ai","programming","Analytics","javascript libraries","intelligence and analytics","analytics","other audio-video-graphics software","operating systems & computing languages","web analytics","platform as a service","uk is8 digital and technologies","javascript frameworks","consent management","Digital Entertainment","web design and development services","design","ui frameworks","accounting and finance","Machine Learning","operating systems"]', '["startup","vc_backed","funded"]', 56.78, 29000, 1, 3, 54545433, NULL, NULL, NULL, NULL, NULL, '2026-11-05T15:54:51.538Z', 'GBP', '2026-11-05T15:54:51.538Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('451e9926-5226-40fa-9651-1027b328626f', 'Workflow', 'workflow.design', 'http://workflow.design', 'https://www.linkedin.com/company/workflow-design/', 'https://app.dealroom.co/companies/workflow_design', 'A platform designed to organize and work together on assets like design, web, video, and more', 'London', 'United Kingdom', 2022, 19, -17.391304, 2543767, 2, NULL, NULL, 'operational', '[{"uuid":"5d505a92-7c05-458d-b901-11c47c55c338","name":"Will Taylor"},{"uuid":"f3b3062d-2c0c-42dc-ae8e-1d451ce47867","name":"Allis Yao"}]', '{}', '2026-11-05T15:53:18.240Z', 'Workflow is a minimalist collaboration platform designed to streamline creative work for teams involved in design, web development, video production, and more. It offers features such as fast feedback and approval processes, allowing reviewers to provide input on live websites, Figma designs, images, videos, PDFs, and text documents. The platform facilitates efficient communication by enabling users to share work, assign tasks, set due dates, and monitor project progress through an intuitive interface. Workflow aims to reduce the complexity of creative project management, enhancing productivity and collaboration among team members. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('4650f5d6-9c20-4656-b8d4-d72d729a5df9', 'Worldover', 'worldover.io', 'https://www.worldover.io/', 'https://www.linkedin.com/company/worldover-io/', 'https://app.dealroom.co/companies/worldover', 'AI-powered compliance and lifecycle management for cosmetics', 'London', 'United Kingdom', 2022, 31, 47.61905, 3000000, 1, NULL, NULL, 'operational', '[{"uuid":"fb0ebbb6-745c-4204-ab93-810c0388f66d","name":"Edward Alun-Jones"}]', '{}', '2026-11-05T15:53:18.240Z', 'Worldover is a London-based software company founded in 2022 by CEO Edward Alun-Jones and CTO Chris Gudde. The company provides an AI-driven operating system designed to streamline operations for the beauty and chemicals industries. Its target clients include cosmetics brands, contract manufacturers, and ingredient suppliers. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('5bc8ef38-505e-4ae1-a9c8-50e7dfc2e120', 'Worldsensing', 'worldsensing.com', 'http://worldsensing.com', 'https://www.linkedin.com/company/worldsensing', 'https://app.dealroom.co/companies/worldsensing', 'Sensing solutions for smart cities and industries with critical assets in remote locations', 'Barcelona', 'Spain', 2008, 127, 0.7936508, 21877596, 14, 12651510, 2023, 'operational', '[{"uuid":"2839c6f8-c8ef-4c9e-8566-63ae08382bdb","name":"Xavier Vilajosana"},{"uuid":"ec4a0997-f8bf-49b3-b0ea-6c7df26c6228","name":"Ignasi Vilajosana"}]', '{}', '2026-11-05T15:53:55.756Z', 'Worldsensing is a technology company specializing in IoT (Internet of Things) wireless monitoring solutions for critical infrastructures. The company focuses on enhancing safety and efficiency in industries such as construction, mining, rail, and civil infrastructure. By providing data loggers and sensors, Worldsensing enables continuous monitoring of structural integrity for large-scale projects like bridges, tunnels, and tailings dams. This helps prevent incidents and ensures safer operations.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('a8bd46ca-19ae-4782-b8ed-7101bb764565', 'Wrisk', 'wrisk.co', 'http://wrisk.co', 'https://www.linkedin.com/company/wrisk/', 'https://app.dealroom.co/companies/wrisk', 'Enables its customers to understand and control risk of insurance', 'London', 'United Kingdom', 2016, 94, 0, 23675454, 9, 15287610, 2025, 'operational', '[{"uuid":"2376244d-e0ad-43a2-8e67-d37aaf036707","name":"Darius Kumana"}]', '{}', '2026-11-05T15:55:09.655Z', 'Wrisk operates in the insurance technology sector, providing a platform that allows brands to co-create, launch, and manage customized insurance products. The company focuses on simplifying the consumer insurance experience by offering intuitive, transparent, and customer-centric solutions. Wrisk serves a diverse range of clients, including automotive manufacturers and other global brands looking to innovate their insurance offerings. The company operates primarily in the UK and the USA, with a subsidiary headquartered in Hartford, Connecticut. Wrisk''s business model revolves around partnerships with brands to deliver tailored insurance products, generating revenue through these collaborations. The platform is designed to be omnichannel ready, ensuring accessibility from any device, and aims to build customer loyalty through engaging and simplified insurance experiences.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('3142c5db-1510-480c-adcd-855cdbd5c3ac', 'Wuolah', 'wuolah.com', 'https://www.wuolah.com/', 'https://www.linkedin.com/company/wuolah/', 'https://app.dealroom.co/companies/wuolah_com', 'Platform for learning with notes', 'Seville', 'Spain', 2015, 57, -3.3898306, 5507248, 4, 479048, 2021, 'operational', '[{"uuid":"6bb0c929-0f61-41d5-9fdd-3713af012751","name":"Francisco Javier Ruiz Fernández"},{"uuid":"4ecc7d1e-65b6-403d-9c55-4c44adbe310d","name":"Francisco José Martínez Benítez"},{"uuid":"0439d840-2dd7-4b30-a4a6-8aeb03e63eb8","name":"Jaime Quintero Rodríguez"}]', '{}', '2026-11-05T15:54:35.037Z', 'Wuolah operates as an online platform where university students can access and share study materials. The company was established in 2015 in Seville, Spain, by a group of four university friends: Enrique Ruiz Galan, Jaime Quintero, Luis Lopez Rodriguez, and Francisco Jose Martinez Benitez. The founders, while studying, identified a gap in the market for a centralized, course-specific platform for study notes, as existing options were too generalized. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('e2fb4237-cdc4-4363-b176-e85755cf1c0a', 'XRF', 'xrf.ai', 'https://xrf.ai', 'https://www.linkedin.com/company/xrealityfactory/', 'https://app.dealroom.co/companies/xrf', 'Key support for decision-makers in complex scenarios like emergency response, and security for critical industries', 'Las Palmas de Gran Canaria', 'Spain', 2023, 51, 15.909091, 1916666, 1, NULL, NULL, 'operational', '[{"uuid":"173d2b92-84c9-423d-94f8-a51e8ca44d33","name":"Gustavo Medina"},{"uuid":"f0a49de1-0bb4-43c6-8347-ca9eda07ae9e","name":"Antonio Jose Antoniojotasl Sanchez Lopez"}]', '{}', '2026-11-05T15:56:04.243Z', 'A Spanish technology company that has developed a platform combining artificial intelligence and extended reality to aid decision-making in complex and critical environments, such as emergency response, security, and defense.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('173e6a6e-c134-44fe-b5da-da58f91f971c', 'Yonder', 'yonder.com', 'https://www.yonder.com/', 'https://www.linkedin.com/company/yondercard/', 'https://app.dealroom.co/companies/yonder_3', 'A credit card to earn points anywhere in the world, and use them on experiences', 'London', 'United Kingdom', 2020, 121, 18.62745, 56750000, 5, NULL, NULL, 'operational', '[{"uuid":"8c66707e-5677-4606-a6b9-00a248e5c4c1","name":"Harry Jell"},{"uuid":"e2654237-6656-4eb1-b906-2e0feda320b6","name":"Theso Jivajirajah"},{"uuid":"bc854768-1c67-40d5-b9fe-d8341e289fdc","name":"Tim Chong"}]', '{}', '2026-11-05T15:55:23.556Z', 'Yonder is a financial services company that offers a credit card with a rewards program targeted at individuals in London. The company''s business model is centered on interchange fees from merchants when customers use their Yonder card for purchases. It also likely generates revenue from interest on outstanding balances and potentially annual fees, although the latter is not explicitly stated in the provided information.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('38d1f645-3e0a-438e-8227-dcddc08994ae', 'ZENOS', 'zenosinteractive.com', 'https://zenosinteractive.com', 'https://www.linkedin.com/company/zenosinteractive/', 'https://app.dealroom.co/companies/virtex_xr', 'Has envisioned virtual stadiums and a 3D viewing experience from the moment consumer VR arrived', 'London', 'United Kingdom', 2020, 39, -9.302325, 2424241, 4, 2348484, 2023, 'operational', '[{"uuid":"cc2ee31f-0a86-416e-8c4b-bb4e8ef88f2d","name":"Christoph Ortlepp"},{"uuid":"8de5d278-0749-4e45-92f1-d4566391628b","name":"Tim Mcguinness"}]', '{}', '2026-11-05T15:55:36.049Z', 'Virtex Stadium is an innovative startup that aims to revolutionize the way people experience esports by leveraging virtual reality (VR) technology. The company provides a unique platform where users can watch live esports competitions in a fully immersive 3D environment. By creating a virtual stadium, Virtex allows fans to feel as if they are physically present at the event, offering a level of engagement and excitement that traditional viewing methods cannot match.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('6633f395-43a3-4f45-b067-e31df6fb48bd', 'ZOE', 'zoe.com', 'http://zoe.com', 'https://www.linkedin.com/company/joinzoe/', 'https://app.dealroom.co/companies/zoe', 'AI-powered personalized nutrition program using at-home testing', 'London', 'United Kingdom', 2017, 424, 2.1686747, 80578758, 9, 34070000, 2025, 'operational', '[{"uuid":"48251b2d-84f4-4288-97ae-95023821f37b","name":"George Hadjigeorgiou"},{"uuid":"f916fa57-9683-4158-89a6-63dfe3e5ae08","name":"Tim Spector"},{"uuid":"db2f5e90-29ee-4430-970b-f43a52035103","name":"Jonathan Wolf"}]', '{}', '2026-11-05T15:54:12.521Z', 'ZOE is a health science company that provides a personalized nutrition program based on scientific research and artificial intelligence. Co-founded in 2017 by Tim Spector, Jonathan Wolf, and George Hadjigeorgiou, the company''s mission is to improve long-term health by helping individuals understand their unique biological responses to food. The concept originated from Spector''s research on twins, which demonstrated that even genetically identical individuals have different metabolic responses to the same foods, largely due to their unique gut microbiomes.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('d22d181e-2ec1-4414-bdcd-e02092cfdd1e', 'Zapp', 'justzapp.com', 'https://justzapp.com', 'https://www.linkedin.com/company/zappquickcommerce/', 'https://app.dealroom.co/companies/zapp_1_1', 'Building the future of convenience with a full stack approach to on-demand essential items, 24/7, delivered in minutes', 'London', 'United Kingdom', 2020, 381, 1.8716577, 227272636, 3, 39463234, 2023, 'operational', '[{"uuid":"84972018-6a8e-468a-997f-c54f405769de","name":"Navid Hadzaad"},{"uuid":"24f8add6-fc9e-4590-8ffc-6a6d0d3e3506","name":"Joe Falter"}]', '{}', '2026-11-05T15:54:51.538Z', 'Zapp operates as an on-demand, premium convenience retail platform, positioning itself in the quick-commerce sector. Founded in 2020 by Joe Falter and Navid Hadzaad, the company is headquartered in London and strategically targets ''mega-cities,'' beginning with a dense operational focus in London before expanding to other urban centers like Manchester and Amsterdam. The founders brought relevant experience to the venture; Hadzaad had been a product leader at Amazon and worked at Rocket Internet, while Falter previously led the on-demand services business at Jumia Group. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('f7eed705-a404-4b97-b713-b4ce392d408e', 'Zego', 'zego.com', 'https://www.zego.com/', 'https://www.linkedin.com/company/zegocover/', 'https://app.dealroom.co/companies/zego_com', 'Global insurtech business providing flexible commercial insurance for businesses & professionals', 'London', 'United Kingdom', 2016, 398, 15.028902, 180243870, 7, 50870000, 2024, 'operational', '[{"uuid":"6eab4c30-6837-4338-83df-732b7b0a8df7","name":"Sten Saar"},{"uuid":"c07e1742-e16b-4ba0-964f-29438f0b76d5","name":"Harry Franks"}]', '{}', '2026-11-05T15:53:04.860Z', 'Zego, a commercial motor insurance provider, was established in 2016 by Sten Saar and Harry Franks, with Stuart Kelly joining as a third co-founder. The founders'' backgrounds are rooted in the gig economy and technology sectors; Saar and Franks previously worked at Deliveroo, where they identified a critical need for more flexible insurance options for delivery drivers. This firsthand experience with the limitations of traditional annual insurance policies for gig workers directly shaped Zego''s mission.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2fd0270e-5718-44d9-aa8d-6297a6a8e2e4', 'Zopa', 'zopa.com', 'http://www.zopa.com', 'https://www.linkedin.com/company/zopabank/', 'https://app.dealroom.co/companies/zopa', 'The first ever peer-to-peer lending company to give people access to simpler, better-value loans and investments', 'London', 'United Kingdom', 2005, 1055, 12.955032, 725106021, 15, 377100000, 2025, 'operational', '[{"uuid":"a4fcc32a-ac6b-48f1-b907-07c66f15a3ce","name":"Richard Duvall"}]', '{}', '2026-11-05T15:54:12.521Z', 'Zopa is a pioneering financial services company that operates in the peer-to-peer (P2P) lending market, providing a range of products including personal loans, savings accounts, credit cards, and car finance. Established in 2005, Zopa was the first company to introduce P2P lending, allowing individuals to lend money directly to borrowers, bypassing traditional banks. This innovative approach has enabled Zopa to offer better value loans and investments by leveraging technology to streamline the lending process.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('0dd8f629-55be-48b6-b972-f08baed2866a', 'Zynap', 'zynap.com', 'https://zynap.com', 'https://www.linkedin.com/company/zynap-ai/', 'https://app.dealroom.co/companies/zynap', 'AI-powered SaaS platform that replicates cybercriminal tactics to predict, detect, and neutralize threats before they strike, offering comprehensive cybersecurity solutions', 'Barcelona', 'Spain', 2024, 39, 225, 9749996, 2, NULL, NULL, 'operational', '[{"uuid":"0ecc4662-773c-4df5-a2a5-2573978786e4","name":"Daniel Solis."}]', '{}', '2026-11-05T15:53:55.756Z', 'Zynap specializes in providing strategic human capital management solutions, focusing on talent management, succession planning, and leadership development. Since 2000, the company has been serving both private and public sectors, helping blue-chip organizations optimize their workforce. Zynap''s flagship product, Talent Studio, is known for its flexibility and configurability, allowing organizations to effectively manage their human resources. The company operates in the enterprise sector, targeting large organizations that require sophisticated talent management solutions. Zynap generates revenue through software licensing and service fees, offering a comprehensive suite of tools designed to enhance organizational performance by ensuring the right people are in the right roles at the right time. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('b8548b9c-d101-45b2-b786-0bb32d959dba', 'cord', 'cord.com', 'https://cord.com', NULL, 'https://app.dealroom.co/companies/cord_com', 'Comment, mention, and annotate on any SaaS tool with Cord', 'London', 'United Kingdom', 2020, 48, 0, 24213632, 3, NULL, NULL, 'operational', '[{"uuid":"60eb1945-ebfb-4986-9f88-b7344246b21b","name":"Nimrod Priell"}]', '{}', '2026-11-05T15:53:18.240Z', 'Cord operates a hiring platform focused on the technology sector, designed to facilitate direct communication between job seekers and companies. The company was founded in the autumn of 2016 by two friends, Ben Henley-Smith and another individual named Will, who aimed to simplify the job search process. They started the company without prior investment or startup experience, initially creating a basic messaging system for people and companies to connect. The platform operates on a business model that provides companies with direct access to active candidates through a flexible rolling monthly subscription, eliminating hiring fees.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('2ee1aeb2-13fa-4bd8-8172-f946b9f54173', 'eSave', 'esave.es', 'https://esave.es/', 'https://www.linkedin.com/company/e-save-spain/', 'https://app.dealroom.co/companies/esave_', 'A leading company in process automation and optical character recognition (OCR)', 'San Sebastián de los Reyes', 'Spain', 2018, 42, -8.695652, 3499999, 2, 689054, 2023, 'operational', '[{"uuid":"992e482a-89a1-4126-b0b4-a693ad384911","name":"Sergio Martinez de Tejada Ayuso"},{"uuid":"56e74b45-8f8f-4efb-8629-658e2d0e1059","name":"Pablo Manzano Martín"}]', '{}', '2026-11-05T15:54:35.037Z', 'eSave is a company that has developed a platform for automating sales processes, with a particular focus on companies in the energy sector. The company''s technology is based on an OCR (Optical Character Recognition) reader that uses a proprietary algorithm to automatically process and extract data from any electricity bill, either in digital format or a photograph.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('61ca2e33-0b20-46f9-92d4-995098ab1380', 'fintonic', 'fintonic.com', 'http://fintonic.com', 'https://www.linkedin.com/company/fintonic/', 'https://app.dealroom.co/companies/fintonic', 'Personal finance app for loans, insurance, and savings', 'Madrid', 'Spain', 2011, 110, 7.8431373, 50166647, 8, 1245581, 2023, 'operational', '[{"uuid":"8bf5eda0-236f-4571-a6c0-a56344ffa9db","name":"Lupina Iturriaga"},{"uuid":"b7098b57-7005-490b-a242-5abe2b3851f4","name":"Marcos Icardo"},{"uuid":"bca647ed-4285-4389-aa1e-69c91eb8d528","name":"Sergio Chalbaud"}]', '{}', '2026-11-05T15:55:36.049Z', 'Fintonic is a Spanish fintech company founded in 2012 by Lupina Iturriaga, Sergio Chalbaud, and Marcos Icardo. The founders utilized their backgrounds in finance and banking to develop a personal finance application. The platform operates as a financial aggregator, allowing users to connect their various bank accounts and cards to gain a consolidated view of their finances. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('1c3e1562-4b56-4651-b553-1c10ca9ba020', 'floLIVE', 'flolive.net', 'https://flolive.net/', 'https://www.linkedin.com/company/flo-live/', 'https://app.dealroom.co/companies/flo_live', 'Operates a self-developed, cloud-based connectivity enablement platform designed and built especially for IoT', 'London', 'United Kingdom', 2015, 178, 3.488372, 66818155, 4, 11632622, 2024, 'operational', '[{"uuid":"6e67fb58-d62c-4c19-8086-d0a0ca9a2962","name":"Arik Aberjel"},{"uuid":"1cb0971f-ee23-4a3b-981a-e52d1af198ea","name":"Jeegar Swaly"}]', '{}', '2026-11-05T15:56:26.553Z', 'The world is experiencing a significant transformation. The Internet of Things (IoT) industry is revolutionizing life as we know it, enabling manufacturers to monitor and exchange production status in real time. Serving as a powerful tool to address global connectivity and challenges like climate change and improving health care, IoT is shaping the future. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('1485ed9a-c86f-47b1-a390-8c554f3d12b5', 'flyboard', 'flyboard.ai', 'http://flyboard.ai', 'https://www.linkedin.com/company/getflyboard/', 'https://app.dealroom.co/companies/flyboard', 'AI voice agents for automated customer engagement', 'Sant Cugat del Vallès', 'Spain', 2024, 14, NULL, 1583333, 1, NULL, NULL, 'operational', '[{"uuid":"8c7d6d93-e4c7-49c1-b352-a9cff41a4aaa","name":"Jaime Farres Rocabert"},{"uuid":"ce643f3b-5467-4b6c-b7f5-951d1e6d658f","name":"Edu Álvarez de Toledo"},{"uuid":"20c86824-8142-4165-b5e9-bcf76827db45","name":"Maximilian Zoller"},{"uuid":"45fbd4d9-1d46-4255-8017-50e25350f62f","name":"Maximilian Zoller"}]', '{}', '2026-11-05T15:56:04.243Z', 'Flyboard AI develops real-time, multilingual AI voice agents designed to automate sales and customer support. The company was founded in 2024 and is headquartered in Barcelona, Spain. It operates under the legal name Evoltio Labs SL. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('a3acf714-75e7-4f5f-b5c6-3429037b0f14', 'goodays.co', 'goodays.co', 'http://goodays.co', 'https://www.linkedin.com/company/goodays/', 'https://app.dealroom.co/companies/goodays_co', 'Transform your customer feedback into actionable insights with our user-friendly customer interaction management platform', 'London', 'United Kingdom', 2012, 79, -8.139535, NULL, 0, NULL, NULL, 'operational', '[{"uuid":"10088ab0-be45-4a3c-84e8-296f3ed20a67","name":"Thibaut Carlier"},{"uuid":"ff21c851-e7d6-4a73-8b32-fcbeba16cabb","name":"Nicolas HAMMER"}]', '{}', '2026-11-05T15:56:26.553Z', 'Goodays is a customer interaction management platform designed to transform customer feedback into actionable insights. The company serves a wide range of clients, including leading brands like Carrefour and Fashion Brand Jules, focusing on improving customer experience (CX) and Net Promoter Score (NPS). Operating in the customer experience management market, Goodays offers a user-friendly platform that facilitates better, deeper, and more frequent interactions between businesses and their customers. The business model revolves around a subscription-based service, where clients pay for access to the platform and its features. Goodays makes money by providing tools that help businesses rally their entire teams around customer centricity, empowering frontline employees with the knowledge and drive to enhance customer experiences. By simplifying complex metrics and focusing on actionable insights, Goodays ensures that businesses can see immediate impacts from day one. The platform is designed to be an everyday essential, making it easier for companies to engage with their customers and drive loyalty.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('eab907b2-517b-4f90-b44f-ceb38ce815c8', 'hiya!', 'sayhiya.co.uk', 'http://sayhiya.co.uk', 'https://www.linkedin.com/company/sayhiya/', 'https://app.dealroom.co/companies/hiya__1', 'Tech & appliances, without the hassle', 'Manchester', 'United Kingdom', 2017, 11, -42.105263, 26136358, 2, NULL, NULL, 'operational', '[{"uuid":"2e7a5da4-8791-43ce-9b58-a1521c1f97bc","name":"Graham Clarke"}]', '{}', '2026-11-05T15:54:12.521Z', 'SayHiya.co.uk operates in the consumer electronics rental market, specializing in affordable weekly TV rentals. The company targets individuals who may have concerns about their credit history, offering a unique service that does not require a credit check for approval. Instead, SayHiya.co.uk reviews recent credit history without focusing on the credit score itself. This approach allows a broader range of customers to access high-quality TVs without the burden of long-term financial commitments or the risk of incurring debt. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('dcabc63c-0966-4f50-85e0-1abe567f7627', 'incident.io', 'incident.io', 'https://incident.io/', 'https://www.linkedin.com/company/incident-io/', 'https://app.dealroom.co/companies/incident_io', 'A Slack-powered incident management platform helping high-growth companies declare, collaborate, communicate around and learn from events that disturb their normal course of business', 'London', 'United Kingdom', 2020, 225, 37.19512, 72272698, 3, 15282589, 2025, 'operational', '[{"uuid":"053642db-304c-465a-81fa-68eb398bb0b4","name":"Stephen Whitworth"},{"uuid":"83739e42-fe8e-45bb-885d-d5a3209a6b1e","name":"Christopher Evansss"},{"uuid":"e9ac1e63-e79d-4253-a7c5-534d09a259f3","name":"Pete Hamilton"},{"uuid":"69a8caf2-d29a-47b6-9518-17818b3b553c","name":"Stephen Whitworth"}]', '{}', '2026-11-05T15:53:18.240Z', 'Incident.io is a startup that operates in the tech industry, offering a platform designed to streamline and simplify incident management within organizations. The company''s primary target market includes businesses that utilize Slack for internal communication, as the platform integrates seamlessly with this tool. Incident.io also integrates with other popular tools such as Jira, Statuspage, and PagerDuty, making it a versatile addition to any company''s tech stack.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('8927d74e-6e6f-406c-b221-d7de28239f8f', 'ollo', 'askollo.com', 'https://askollo.com', 'https://www.linkedin.com/company/itsollo/', 'https://app.dealroom.co/companies/ollo_8', 'AI agent platform co-built with business teams.', 'London', 'United Kingdom', 2021, 24, 4.347826, 4517877, 3, 1742424, 2023, 'operational', '[{"uuid":"b3f30848-03dd-4997-931d-ded4bb328267","name":"Husayn Kassai"}]', '{}', '2026-11-05T15:55:23.556Z', 'ollo is an agentic AI platform built for teams, combining software with a hands-on deployment service. The platform has three parts: Ask for enterprise search across an organisation''s connected tools and data, Assist for building AI agents grounded in company knowledge, and Auto for workflow automation. Rather than selling software for customers to figure out alone, ollo deploys the platform into a client''s environment, trains their teams to use and build with it, and stays on as an ongoing AI partner through weekly co-build sprints so the capability remains in-house. It is model-agnostic, working with models including Anthropic''s Claude and OpenAI''s GPT, and integrates with tools such as Slack, Notion, SharePoint, Google Drive and Salesforce. The company was previously known as Quench.AI (and earlier NewMN) before rebranding to ollo, and is SOC 2 and ISO 27001 certified.', '["corporate","database","human resource management system","Venture Capital","Core AI","Subscription","SaaS","Angel","Education","Generative AI","Knowledge Management","b2b","Artificial Intelligence","tag management","content delivery network","programming languages","miscellaneous","AI Applications","intelligence and analytics","Enterprise Software","security","issue trackers","Learning Tools and Resources","web analytics","uk is8 digital and technologies","b2c","consent management","Early stage","human capital management","cookie compliance","Machine Learning","identity verification"]', '["startup","vc_backed","funded"]', 72.81, 2500, 0, 0, 22727264, NULL, NULL, NULL, NULL, '[{"year":2023,"revenue":1742424,"ebitda":null,"profit":null,"rnd":null,"valuation":22727264,"employees":27},{"year":2024,"revenue":1742424,"ebitda":null,"profit":null,"rnd":null,"valuation":22727264,"employees":26},{"year":2025,"revenue":1742424,"ebitda":null,"profit":null,"rnd":null,"valuation":22727264,"employees":23},{"year":2026,"revenue":1742424,"ebitda":null,"profit":null,"rnd":null,"valuation":22727264,"employees":24}]', '2026-11-05T15:55:23.556Z', 'GBP', '2026-11-05T15:55:23.556Z');
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, rounds_fetched_at) VALUES ('d4cc0a67-3070-4e9b-b5d2-c7178d1fb32a', 'supernova3d.com', 'supernova3d.com', 'http://supernova3d.com', 'https://www.linkedin.com/company/supernovavlm/', 'https://app.dealroom.co/companies/supernova3d_com', 'Viscous lithography manufacturing for industrial-grade components.', 'Barcelona', 'Spain', 2024, 38, 46.153847, 848485, 1, NULL, NULL, 'operational', '[{"uuid":"d74c996f-b412-406c-b27c-5324ba20ff0f","name":"Marta Mico"},{"uuid":"9d2e0c7c-50b6-4870-8345-9f39d02415b6","name":"Marta Micó Martínez"},{"uuid":"ab8ef2c9-c153-473d-bf68-9963996d95ca","name":"Ross Farrow"},{"uuid":"bca636dc-1efd-4ff9-927f-8be37b289e8d","name":"Roger Antunez"}]', '{}', '2026-11-05T15:56:04.243Z', 'Supernova is an additive manufacturing company that spun out of BCN3D in the fourth quarter of 2023, becoming a new, independent entity incorporated in the US. The company was established to commercialize the Viscous Lithography Manufacturing (VLM) technology developed by BCN3D. Supernova is headquartered in Austin, Texas, with a site in Barcelona, Spain. 
